INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_001', 'zenlish_practice', 'Maggie Williams, the purchasing manager, currently _____ requested supplies at the end of each week.', 'ordered', 'orders', 'order', 'ordering', 'B', 'Giải thích: "Orders" là động từ ở thì hiện tại đơn, phù hợp với chủ ngữ "Maggie Williams" (người quản lý mua hàng), một chủ ngữ ngôi thứ ba số ít. Câu này nói rằng Maggie Williams hiện tại đặt hàng các vật tư yêu cầu vào cuối mỗi tuần.\n(A) ordered (v. past tense): "ordered" là động từ ở thì quá khứ, không phù hợp với ngữ cảnh của câu khi câu đang nói về hành động hiện tại.\n(C) order (v. base form): "order" là động từ nguyên mẫu, không phù hợp với ngữ pháp của câu khi chủ ngữ là ngôi thứ ba số ít.\n(D) ordering (v. present participle): "ordering" là hiện tại phân từ, không phù hợp với cấu trúc của câu khi cần một động từ chia theo ngôi thứ ba số ít.', 'Maggie Williams, người quản lý mua hàng, hiện tại đặt hàng các vật tư yêu cầu vào cuối mỗi tuần.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_002', 'zenlish_practice', 'Even though assigned tasks are somewhat complex, we will have to complete them before we _____ for the day.', 'leave', 'leaves', 'will leave', 'have left', 'A', 'Giải thích: Trong mệnh đề thời gian với before / after / when / while / until, ta dùng hiện tại đơn để nói về tương lai. → before we leave (không dùng will leave). we là chủ ngữ số nhiều → dùng leave, không thêm -s.\n(B) leaves: chia cho ngôi thứ ba số ít → sai với we\n(C) will leave: không dùng trong mệnh đề thời gian\n(D) have left: hiện tại hoàn thành → không phù hợp ngữ cảnh', 'Mặc dù các nhiệm vụ được giao có phần phức tạp, chúng tôi sẽ phải hoàn thành chúng trước khi rời khỏi công việc trong ngày.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_003', 'zenlish_practice', 'Attendees will have a chance to watch artist Marta Langdon as she _____ methods of landscape painting at a workshop on Monday.', 'demonstrating', 'demonstrated', 'demonstration', 'demonstrates', 'D', 'Giải thích: Trong câu này, cần một động từ ở thì hiện tại đơn để mô tả hành động của nghệ sĩ Marta Langdon sẽ diễn ra tại workshop vào thứ Hai. "Demonstrates" là thì hiện tại đơn phù hợp, nghĩa là "trình bày," để chỉ rằng Marta Langdon sẽ trình bày các phương pháp vẽ tranh phong cảnh trong workshop.\n(A) demonstrating (present participle): "Demonstrating" có nghĩa là "đang trình bày." Lý do không chọn là vì dạng hiện tại phân từ không phù hợp trong ngữ cảnh này khi cần một động từ chính để mô tả hành động trong tương lai.\n(B) demonstrated (past simple): "Demonstrated" có nghĩa là "đã trình bày." Lý do không chọn là vì thì quá khứ không phù hợp khi mô tả một hành động sẽ xảy ra trong tương lai.\n(C) demonstration (noun): "Demonstration" có nghĩa là "sự trình bày" hoặc "buổi trình diễn." Lý do không chọn là vì đây là danh từ, không phải động từ, và không phù hợp khi câu cần một động từ.', 'Người tham dự sẽ có cơ hội xem nghệ sĩ Marta Langdon khi cô ấy trình bày các phương pháp vẽ tranh phong cảnh tại một workshop vào thứ Hai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_004', 'zenlish_practice', 'Membership at the exclusive sports club _____ benefits ranging from the use of all sports equipment to discounted rates at the club''s restaurant and bar.', 'includes', 'to include', 'have included', 'including', 'A', 'Giải thích: Trong câu này, "includes" là động từ ở ngôi thứ ba số ít, phù hợp với chủ ngữ "Membership," để chỉ việc mà thành viên được hưởng. "Includes" có nghĩa là "bao gồm," mô tả các quyền lợi mà việc làm thành viên tại câu lạc bộ thể thao cao cấp mang lại.\n(B) to include (infinitive): "To include" là dạng nguyên mẫu của động từ, không phù hợp với cấu trúc câu cần động từ chính để chỉ ra việc bao gồm các quyền lợi.\n(C) have included (present perfect): "Have included" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh mô tả một đặc điểm hoặc thuộc tính chung của việc làm thành viên.\n(D) including (present participle): "Including" là dạng hiện tại phân từ, không phải động từ chính của câu mà là một phần mở rộng để giải thích thêm, không phù hợp với cấu trúc cần một động từ chính.', 'Việc làm thành viên tại câu lạc bộ thể thao cao cấp bao gồm các quyền lợi từ việc sử dụng toàn bộ thiết bị thể thao cho đến các mức giá giảm tại nhà hàng và quầy bar của câu lạc bộ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_005', 'zenlish_practice', 'Please mark the appropriate box to indicate if the person named above _____ any of the certificates listed below.', 'holding', 'held', 'holds', 'hold', 'C', 'Giải thích: Đây là câu điều kiện loại 0 nên sau vế "If" cần mệnh đề ở thì hiện tại đơn. "The person named above" là chủ ngữ số ít → holds.\n(A) holding: V-ing → không dùng làm động từ chính trong mệnh đề này\n(B) held: quá khứ đơn → không phù hợp vì không nói về quá khứ\n(D) hold: nguyên mẫu → chỉ dùng với chủ ngữ số nhiều hoặc I/you/we/they', 'Vui lòng đánh dấu vào ô thích hợp để chỉ rõ xem nếu người được nêu tên trên có sở hữu bất kỳ chứng chỉ nào được liệt kê dưới đây không.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_006', 'zenlish_practice', 'Most of the companies surveyed _____ their growth to marketing and sales strategies.', 'attributes', 'attributed', 'attributing', 'attribution', 'B', 'Giải thích: Cần động từ chính cho chủ ngữ "Most of the companies surveyed" - hầu hết các công ty được khảo sát". "Attributed" là dạng quá khứ của động từ "attribute," nghĩa là quy cho hoặc cho rằng".\n(A) attributes (verb, present): "Attributes" là động từ dạng hiện tại, chia theo chủ ngữ số ít, không phù hợp trong ngữ cảnh vì "the companies" là chủ ngữ số nhiều\n(C) attributing (verb, gerund/participle): "Attributing" là dạng hiện tại phân từ, không phù hợp khi câu cần dạng quá khứ của động từ.\n(D) attribution (noun): "Attribution" là danh từ, không phù hợp khi câu cần một động từ.', 'Hầu hết các công ty được khảo sát đã quy sự tăng trưởng của họ cho các chiến lược marketing và bán hàng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_007', 'zenlish_practice', 'Trains for Gruyville ______ at 9:00 A.M. Monday through Friday.', 'depart', 'is departed', 'departs', 'is departing', 'A', 'Giải thích: "Depart" là dạng động từ phù hợp với chủ ngữ số nhiều "Trains" (Các chuyến tàu). Đối với động từ, khi chủ ngữ là số nhiều, động từ cũng phải ở dạng số nhiều.\n(B) is departed: Không đúng vì "is departed" không phù hợp về mặt ngữ pháp và nghĩa.\n(C) departs: Không đúng vì "departs" là dạng số ít, không phù hợp với chủ ngữ số nhiều.\n(D) is departing: Không đúng vì "is departing" cũng là dạng số ít, và không phù hợp với cấu trúc câu hiện tại.', 'Các chuyến tàu đến Gruyville khởi hành vào lúc 9:00 sáng từ thứ Hai đến thứ Sáu.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_008', 'zenlish_practice', 'This week only, spend over $200 and your order ______ for free overnight shipping.', 'qualification', 'qualifies', 'qualify', 'qualifying', 'B', 'Giải thích: "Qualifies" là động từ phù hợp với ngữ cảnh của câu, thể hiện rằng đơn hàng đáp ứng điều kiện để được giao hàng miễn phí. Các đáp án còn lại không phù hợp với ngữ cảnh hoặc cấu trúc câu.\n(A) qualification: Không đúng vì "qualification" là danh từ, không phù hợp với cấu trúc câu này.\n(C) qualify: Không đúng vì "qualify" là động từ ở dạng nguyên mẫu, không phù hợp với ngữ cảnh câu.\n(D) qualifying: Không đúng vì "qualifying" là dạng hiện tại phân từ, không phù hợp với cấu trúc câu.', 'Chỉ trong tuần này, chi tiêu trên $200 và đơn hàng của bạn đủ điều kiện để được giao hàng miễn phí qua đêm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_009', 'zenlish_practice', 'Maggie Williams, the purchasing manager, currently ______ requested supplies at the end of each week.', 'ordered', 'orders', 'order', 'ordering', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn "orders" để diễn tả hành động lặp đi lặp lại hoặc thói quen của Maggie Williams trong hiện tại. Đây là cách diễn tả hành động thường xuyên xảy ra.\n(A) ordered: Không đúng vì đây là thì quá khứ đơn, không phù hợp với ngữ cảnh hiện tại.\n(C) order: Không đúng vì thiếu hình thức động từ phù hợp với chủ ngữ.\n(D) ordering: Không đúng vì không phù hợp với cách dùng thì hiện tại đơn để chỉ hành động thường xuyên.', 'Maggie Williams, trưởng phòng mua sắm, hiện tại đặt hàng các vật tư yêu cầu vào cuối mỗi tuần.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0006_q_010', 'zenlish_practice', 'I ____ a book every morning.', 'read', 'have read', 'has read', 'readed', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động lặp đi lặp lại hoặc thói quen hằng ngày. "Read" là động từ ở dạng nguyên mẫu, phù hợp với ngôi thứ nhất "I" trong câu.\n(B) have read (v.): "have read" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh vì câu này muốn diễn tả thói quen hàng ngày, không phải hành động đã hoàn thành.\n(C) has read (v.): "has read" cũng là thì hiện tại hoàn thành nhưng đi kèm với chủ ngữ số ít ở ngôi thứ ba, không phù hợp với chủ ngữ "I" trong câu này.\n(D) readed (v.): "readed" không tồn tại trong tiếng Anh vì "read" có dạng quá khứ là "read" (phát âm là /rɛd/), không phải "readed."', 'Tôi đọc sách mỗi buổi sáng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_001', 'zenlish_practice', 'A good supervisor ____ encouragement to employees.', 'gave', 'is giving', 'given', 'gives', 'D', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động thường xuyên xảy ra hoặc một sự thật chung. "Gives" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "A good supervisor."\n(A) gave (v.): "gave" là thì quá khứ của "give," không phù hợp với ngữ cảnh của câu vì câu này cần diễn tả một hành động thường xuyên, không phải hành động đã xảy ra trong quá khứ.\n(B) is giving (v.): "is giving" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh vì câu này không diễn tả hành động đang xảy ra tại thời điểm nói.\n(C) given (v./adj.): "given" là dạng quá khứ phân từ của "give" hoặc có thể được dùng như một tính từ, nhưng không phù hợp với vị trí của động từ chính trong câu này.', 'Một người giám sát tốt đưa ra sự khích lệ cho nhân viên.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_002', 'zenlish_practice', 'He usually ____ coffee but now he is drinking tea.', 'to drink', 'drinks', 'drunk', 'is drinking', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả thói quen thường xuyên của chủ ngữ "He," và sau đó sử dụng thì hiện tại tiếp diễn "is drinking" để diễn tả hành động đang xảy ra tại thời điểm nói. "Drinks" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "He."\n(A) to drink (infinitive): "to drink" là động từ nguyên mẫu có "to," không phù hợp với ngữ cảnh của câu này.\n(C) drunk (v.): "drunk" là quá khứ phân từ của "drink," không phù hợp với cấu trúc câu này.\n(D) is drinking (v.): "is drinking" là thì hiện tại tiếp diễn, nhưng ở đây câu đầu tiên cần sử dụng thì hiện tại đơn để diễn tả thói quen.', 'Anh ấy thường uống cà phê nhưng bây giờ anh ấy đang uống trà.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_003', 'zenlish_practice', 'She ____ from London to Edinburgh every year.', 'flies', 'fly', 'flys', 'flying', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động lặp đi lặp lại hàng năm. "Flies" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "She."\n(B) fly (v.): "fly" là động từ nguyên mẫu, không phù hợp với chủ ngữ ngôi thứ ba số ít "She."\n(C) flys (v.): "flys" không tồn tại trong tiếng Anh.\n(D) flying (v./gerund): "flying" là danh động từ hoặc phân từ hiện tại, không phù hợp với vị trí của động từ chính trong câu này.', 'Cô ấy bay từ London đến Edinburgh mỗi năm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_004', 'zenlish_practice', 'He usually ____ to work at 7:30.', 'goes', 'will go', 'went', 'has gone', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một thói quen hàng ngày. "Goes" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "He."\n(B) will go (v.): "will go" là thì tương lai đơn, không phù hợp với câu này vì câu cần diễn tả một hành động thường xuyên.\n(C) went (v.): "went" là thì quá khứ đơn của "go," không phù hợp vì câu đang nói về một thói quen hiện tại.\n(D) has gone (v.): "has gone" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh cần diễn tả một hành động lặp đi lặp lại hàng ngày.', 'Anh ấy thường đi làm lúc 7:30.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_005', 'zenlish_practice', 'The public library usually ____ no fees for local residents to borrow books.', 'will charge', 'charging', 'to charge', 'charges', 'D', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một sự thật chung hoặc quy tắc thường xuyên áp dụng. "Charges" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "The public library."\n(A) will charge (v.): "will charge" là thì tương lai đơn, không phù hợp với ngữ cảnh khi câu muốn diễn tả một quy tắc chung hiện tại.\n(B) charging (gerund/participle): "charging" là danh động từ hoặc phân từ hiện tại, không phù hợp với vị trí của động từ chính trong câu này.\n(C) to charge (infinitive): "to charge" là động từ nguyên mẫu có "to," không phù hợp với ngữ cảnh câu.', 'Thư viện công cộng thường không thu phí cư dân địa phương khi mượn sách.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_006', 'zenlish_practice', 'I ____ care whether you go or not.', 'don’t', 'doesn’t', 'am not', 'wasn’t', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple), và chủ ngữ "I" đi kèm với "don''t" (viết tắt của "do not") để diễn tả phủ định. "Don’t care" có nghĩa là "không quan tâm."\n(B) doesn’t (v.): "doesn’t" là dạng phủ định dành cho chủ ngữ ngôi thứ ba số ít, không phù hợp với chủ ngữ "I."\n(C) am not (v.): "am not" là dạng phủ định của "am," nhưng không phù hợp với động từ "care" trong câu này.\n(D) wasn’t (v.): "wasn’t" là dạng phủ định của "was" ở thì quá khứ, không phù hợp vì câu đang sử dụng thì hiện tại.', 'Tôi không quan tâm liệu bạn đi hay không.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_007', 'zenlish_practice', 'Bread ____ usually made from wheat.', 'are', 'is', 'to do', 'be', 'B', 'Giải thích: Trong câu này, "Bread" là danh từ không đếm được và được coi là số ít, vì vậy động từ "is" (thì hiện tại đơn ngôi thứ ba số ít) được sử dụng để diễn tả sự thật rằng bánh mì thường được làm từ lúa mì.\n(A) are (v.): "are" là dạng động từ to be cho danh từ số nhiều, không phù hợp với danh từ số ít "Bread."\n(C) to do (v.): "to do" là động từ nguyên mẫu, không phù hợp với cấu trúc câu này.\n(D) be (v.): "be" là động từ nguyên mẫu, không phù hợp với ngữ pháp trong câu này.', 'Bánh mì thường được làm từ lúa mì.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_008', 'zenlish_practice', 'He usually ____ the 8.10 bus.', 'catch', 'catches', 'do not catch', 'is not catch', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một thói quen thường xuyên. "Catches" là dạng động từ ngôi thứ ba số ít của "catch," phù hợp với chủ ngữ "He."\n(A) catch (v.): "catch" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "He."\n(C) do not catch (v.): "do not" không đi với chủ ngữ ngôi thứ ba số ít "he".\n(D) is not catch (v.): "is not catch" không đúng ngữ pháp, vì "is" cần đi kèm với một phân từ hiện tại hoặc danh từ, không phải động từ nguyên mẫu "catch."', 'Anh ấy thường bắt chuyến xe buýt 8.10.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_009', 'zenlish_practice', 'She ____ the floor every week.', 'wash', 'washes', 'washing', 'don’t wash', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động lặp đi lặp lại hàng tuần. "Washes" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "She."\n(A) wash (v.): "wash" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "She."\n(C) washing (v./gerund): "washing" là danh động từ hoặc phân từ hiện tại, không phù hợp với vị trí của động từ chính trong câu này.\n(D) don’t wash (v.): "don’t" không đi với chủ ngữ ngôi thứ ba số ít "she".', 'Cô ấy lau sàn mỗi tuần.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0007_q_010', 'zenlish_practice', 'John ____ tennis once or twice a week.', 'often play', 'is often playing', 'will often play', 'often plays', 'D', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động thường xuyên xảy ra. "Plays" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "John." Từ "often" bổ nghĩa cho động từ để diễn tả tần suất.\n(A) often play (v.): "play" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "John."\n(B) is often playing (v.): "is often playing" là thì hiện tại tiếp diễn, không phù hợp với câu này khi muốn diễn tả một thói quen thường xuyên.\n(C) will often play (v.): "will often play" là thì tương lai đơn, không phù hợp vì câu đang nói về một thói quen hiện tại.', 'John thường chơi tennis một hoặc hai lần mỗi tuần.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_001', 'zenlish_practice', 'It usually ____ one hour to get to the City Hall.', 'will take', 'takes', 'took', 'taken', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một sự thật chung hoặc một hành động thường xuyên xảy ra. "Takes" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "It."\n(A) will take (v.): "will take" là thì tương lai đơn, không phù hợp với câu này khi muốn diễn tả một sự thật hiện tại.\n(C) took (v.): "took" là thì quá khứ của "take," không phù hợp vì câu này muốn diễn tả một sự thật hoặc thói quen hiện tại.\n(D) taken (v.): "taken" là quá khứ phân từ của "take," không phù hợp với cấu trúc câu này.', 'Thường mất một giờ để đến Tòa thị chính.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_002', 'zenlish_practice', 'Barbara usually __________ dinner for her husband after work.', 'cooks', 'are cooking', 'is cooking', 'cooked', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động thường xuyên hoặc thói quen. "Cooks" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "Barbara."\n(B) are cooking (v.): "are cooking" là thì hiện tại tiếp diễn ở ngôi thứ hai hoặc ngôi thứ ba số nhiều, không phù hợp với chủ ngữ số ít "Barbara."\n(C) is cooking (v.): "is cooking" là thì hiện tại tiếp diễn, không phù hợp với câu này vì câu muốn diễn tả thói quen thường xuyên.\n(D) cooked (v.): "cooked" là thì quá khứ của "cook," không phù hợp vì câu này đang nói về thói quen hiện tại.', 'Barbara thường nấu bữa tối cho chồng sau khi tan làm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_003', 'zenlish_practice', 'He never ____ to what you say. He is always thinking about something else.', 'listens', 'listened', 'listening', 'will listen', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một thói quen hoặc hành vi thường xuyên. "Listens" là động từ ở dạng ngôi thứ ba số ít, phù hợp với chủ ngữ "He."\n(B) listened (v.): "listened" là thì quá khứ của "listen," không phù hợp vì câu này đang nói về thói quen hiện tại.\n(C) listening (v./gerund): "listening" là danh động từ hoặc phân từ hiện tại, không phù hợp với vị trí của động từ chính trong câu này.\n(D) will listen (v.): "will listen" là thì tương lai đơn, không phù hợp với ngữ cảnh của câu này khi nói về một thói quen hiện tại.', 'Anh ấy không bao giờ lắng nghe những gì bạn nói. Anh ấy luôn nghĩ về điều gì đó khác.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_004', 'zenlish_practice', 'Every month, we ____ a monthly business meeting.', 'will have', 'have', 'having', 'has', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động lặp đi lặp lại hàng tháng. "Have" là động từ nguyên mẫu, phù hợp với chủ ngữ "we."\n(A) will have (v.): "will have" là thì tương lai đơn, không phù hợp vì câu này đang nói về một thói quen hiện tại.\n(C) having (v./gerund): "having" là danh động từ hoặc phân từ hiện tại, không phù hợp với vị trí của động từ chính trong câu này.\n(D) has (v.): "has" là động từ ngôi thứ ba số ít, không phù hợp với chủ ngữ số nhiều "we."', 'Mỗi tháng, chúng tôi có một cuộc họp kinh doanh hàng tháng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_005', 'zenlish_practice', 'Nurses ____ after patients in hospitals.', 'are looking', 'looks', 'will look', 'look', 'D', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động thường xuyên hoặc nhiệm vụ chung của y tá. "Look" là động từ nguyên mẫu, phù hợp với chủ ngữ số nhiều "Nurses."\n(A) are looking (v.): "are looking" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu này vì câu đang diễn tả một nhiệm vụ thường xuyên, không phải một hành động đang diễn ra tại thời điểm nói.\n(B) looks (v.): "looks" là động từ ngôi thứ ba số ít, không phù hợp với chủ ngữ số nhiều "Nurses."\n(C) will look (v.): "will look" là thì tương lai đơn, không phù hợp vì câu này muốn diễn tả một hành động thường xuyên hiện tại.', 'Các y tá chăm sóc bệnh nhân trong bệnh viện.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_006', 'zenlish_practice', 'They ____ exercises every morning.', 'does', 'did not', 'do', 'doing', 'C', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một thói quen hoặc hành động lặp đi lặp lại hàng ngày. "Do" là động từ nguyên mẫu, phù hợp với chủ ngữ số nhiều "They."\n(A) does (v.): "does" là động từ ngôi thứ ba số ít, không phù hợp với chủ ngữ số nhiều "They."\n(B) did not (v.): "did not" là dạng phủ định của thì quá khứ đơn, không phù hợp với ngữ cảnh hiện tại của câu này.\n(D) doing (v./gerund): "doing" là danh động từ hoặc phân từ hiện tại, không phù hợp với vị trí của động từ chính trong câu này.', 'Họ tập thể dục mỗi buổi sáng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_007', 'zenlish_practice', 'The Thames river ____ through London.', 'flows', 'is flow', 'flew', 'flow', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một sự thật hiển nhiên. "Flows" là động từ ngôi thứ ba số ít, phù hợp với chủ ngữ "The Thames river."\n(B) is flow (v.): "is flow" không đúng ngữ pháp, vì "is" cần đi kèm với một phân từ hiện tại hoặc một danh từ, không phải động từ nguyên mẫu "flow."\n(C) flew (v.): "flew" là thì quá khứ của "fly," không phù hợp trong ngữ cảnh này vì "flew" không có nghĩa là "chảy."\n(D) flow (v.): "flow" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "The Thames river."', 'Sông Thames chảy qua London.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_008', 'zenlish_practice', 'The department heads frequently ____ with the overseas marketing team.', 'to meet', 'will meet', 'meet', 'meeting', 'C', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động thường xuyên hoặc thói quen. "Meet" là động từ nguyên mẫu, phù hợp với chủ ngữ "The department heads."\n(A) to meet (infinitive): "to meet" là động từ nguyên mẫu có "to," không phù hợp với cấu trúc câu này.\n(B) will meet (v.): "will meet" là thì tương lai đơn, không phù hợp vì câu đang diễn tả một thói quen hiện tại.\n(D) meeting (v./gerund): "meeting" là danh động từ hoặc phân từ hiện tại, không phù hợp với vị trí của động từ chính trong câu này.', 'Các trưởng bộ phận thường xuyên gặp gỡ với đội tiếp thị ở nước ngoài.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_009', 'zenlish_practice', 'It ________ almost every day in Manchester.', 'rain', 'rains', 'raines', 'rained', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động thường xuyên xảy ra. "Rains" là động từ ngôi thứ ba số ít, phù hợp với chủ ngữ "It."\n(A) rain (v.): "rain" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "It."\n(C) raines (v.): "raines" không tồn tại trong tiếng Anh và không đúng chính tả.\n(D) rained (v.): "rained" là thì quá khứ của "rain," không phù hợp vì câu này đang nói về một hành động thường xuyên hiện tại.', 'Ở Manchester trời mưa gần như mỗi ngày.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0008_q_010', 'zenlish_practice', 'How many languages ________ John speak?', 'do', 'does', 'did', 'will', 'B', 'Giải thích: Trong câu hỏi với chủ ngữ "John," sử dụng "does" ở thì hiện tại đơn (present simple) là phù hợp để hỏi về khả năng hoặc thói quen. "Does John speak?" là dạng đúng ngữ pháp.\n(A) do (v.): "do" phù hợp với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít (I, we), không phù hợp với chủ ngữ ngôi thứ ba số ít "John."\n(C) did (v.): "did" là thì quá khứ đơn, không phù hợp với ngữ cảnh hiện tại của câu hỏi này.\n(D) will (v.): "will" là dạng tương lai đơn, không phù hợp với câu hỏi về khả năng hiện tại.', 'John nói được bao nhiêu ngôn ngữ?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_001', 'zenlish_practice', 'My parents normally __________ breakfast at 7:00 a.m.', 'eat', 'are eating', 'is eating', 'eaten', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một thói quen hoặc hành động thường xuyên. "Eat" là động từ nguyên mẫu, phù hợp với chủ ngữ số nhiều "My parents."\n(B) are eating (v.): "are eating" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu này vì câu đang nói về một thói quen, không phải hành động đang diễn ra.\n(C) is eating (v.): "is eating" là dạng hiện tại tiếp diễn, nhưng "is" không phù hợp với chủ ngữ số nhiều "My parents."\n(D) eaten (v.): "eaten" là quá khứ phân từ của "eat," không phù hợp với cấu trúc câu này.', 'Bố mẹ tôi thường ăn sáng lúc 7:00 sáng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_002', 'zenlish_practice', 'Martin ________ in a small flat. He and his wife always ________ up early to water flowers.', 'is living, get', 'lives, get', 'lives, gets', 'is living, gets', 'B', 'Giải thích: Câu đầu sử dụng thì hiện tại đơn (present simple) với chủ ngữ "Martin," nên động từ "lives" (ngôi thứ ba số ít) là phù hợp. Câu thứ hai có chủ ngữ "He and his wife," là số nhiều, nên động từ "get" là đúng.\n(A) is living, get: "is living" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh câu này vì câu đang nói về một sự thật hoặc thói quen.\n(C) lives, gets: "gets" là động từ ngôi thứ ba số ít, không phù hợp với chủ ngữ số nhiều "He and his wife."\n(D) is living, gets: "is living" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu đầu tiên.', 'Martin sống trong một căn hộ nhỏ. Anh ấy và vợ anh ấy luôn dậy sớm để tưới hoa.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_003', 'zenlish_practice', 'Mr. and Mrs. Parsons __________ to work together every day.', 'drive', 'drives', 'are driving', 'driven', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một thói quen hoặc hành động thường xuyên. "Drive" là động từ nguyên mẫu, phù hợp với chủ ngữ số nhiều "Mr. and Mrs. Parsons."\n(B) drives (v.): "drives" là động từ ngôi thứ ba số ít, không phù hợp với chủ ngữ số nhiều "Mr. and Mrs. Parsons."\n(C) are driving (v.): "are driving" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu này vì câu đang nói về một thói quen.\n(D) driven (v.): "driven" là quá khứ phân từ của "drive," không phù hợp với cấu trúc câu này.', 'Ông và bà Parsons lái xe đi làm cùng nhau mỗi ngày.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_004', 'zenlish_practice', 'John ________ very hard in class, but I don’t think he’ll pass the course.', 'try', 'trys', 'tries', 'has tried', 'C', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động thường xuyên. "Tries" là dạng động từ ngôi thứ ba số ít của "try," phù hợp với chủ ngữ "John."\n(A) try (v.): "try" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "John."\n(B) trys (v.): "trys" không tồn tại trong tiếng Anh và không đúng chính tả.\n(D) has tried (v.): "has tried" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh câu này khi muốn diễn tả một hành động thường xuyên.', 'John rất cố gắng trong lớp, nhưng tôi không nghĩ rằng anh ấy sẽ qua được khóa học.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_005', 'zenlish_practice', 'My mother ________ eggs for breakfast every morning.', 'is frying', 'is fry', 'fries', 'fried', 'C', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một thói quen hoặc hành động thường xuyên. "Fries" là dạng động từ ngôi thứ ba số ít của "fry," phù hợp với chủ ngữ "My mother."\n(A) is frying (v.): "is frying" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu này vì câu đang nói về một thói quen, không phải hành động đang diễn ra tại thời điểm nói.\n(B) is fry (v.): "is fry" không đúng ngữ pháp, vì "is" cần đi kèm với một phân từ hiện tại hoặc danh từ, không phải động từ nguyên mẫu "fry."\n(D) fried (v.): "fried" là thì quá khứ của "fry," không phù hợp vì câu này đang nói về một thói quen hiện tại.', 'Mẹ tôi rán trứng cho bữa sáng mỗi buổi sáng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_006', 'zenlish_practice', 'My life is so boring — I just ________ TV every night.', 'watch', 'watchies', 'watches', 'watched', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một thói quen hoặc hành động thường xuyên. "Watch" là động từ nguyên mẫu, phù hợp với chủ ngữ "I."\n(B) watchies (v.): "watchies" không tồn tại trong tiếng Anh và không đúng chính tả.\n(C) watches (v.): "watches" là động từ ngôi thứ ba số ít, không phù hợp với chủ ngữ "I."\n(D) watched (v.): "watched" là thì quá khứ của "watch," không phù hợp vì câu này đang nói về một thói quen hiện tại.', 'Cuộc sống của tôi thật nhàm chán — tôi chỉ xem TV mỗi đêm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_007', 'zenlish_practice', 'My teacher ________ long hair.', 'have', 'has', 'have had', 'had', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một sự thật hiện tại. "Has" là động từ ngôi thứ ba số ít của "have," phù hợp với chủ ngữ "My teacher."\n(A) have (v.): "have" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "My teacher."\n(C) have had (v.): "have had" là thì hiện tại hoàn thành, không phù hợp vì câu này muốn diễn tả một sự thật hiện tại đơn giản.\n(D) had (v.): "had" là thì quá khứ của "have," không phù hợp vì câu này đang nói về hiện tại.', 'Giáo viên của tôi có tóc dài.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_008', 'zenlish_practice', 'The bank ________ at four o’clock.', 'closes', 'will close', 'is close', 'closed', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một sự kiện hoặc hành động thường xuyên xảy ra. "Closes" là động từ ngôi thứ ba số ít, phù hợp với chủ ngữ "The bank."\n(B) will close (v.): "will close" là thì tương lai đơn, không phù hợp vì câu này đang nói về một sự thật thường xuyên hiện tại.\n(C) is close (adj.): "is close" có nghĩa là "gần," không phù hợp với ngữ cảnh khi câu cần một động từ, không phải tính từ.\n(D) closed (v.): "closed" là thì quá khứ của "close," không phù hợp vì câu này đang nói về hiện tại.', 'Ngân hàng đóng cửa lúc bốn giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_009', 'zenlish_practice', 'He will take the dog out for a walk as soon as he ________ dinner.', 'finish', 'finishes', 'will finish', 'shall have finished', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) trong mệnh đề phụ "as soon as" để diễn tả một hành động sẽ xảy ra ngay sau khi hành động khác kết thúc. "Finishes" là động từ ngôi thứ ba số ít, phù hợp với chủ ngữ "he."\n(A) finish (v.): "finish" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "he."\n(C) will finish (v.): "will finish" không phù hợp vì mệnh đề phụ "as soon as" thường không dùng thì tương lai.\n(D) shall have finished (v.): "shall have finished" là thì tương lai hoàn thành, không phù hợp với cấu trúc mệnh đề phụ trong câu này.', 'Anh ấy sẽ đưa chó đi dạo ngay khi anh ấy ăn tối xong.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0009_q_010', 'zenlish_practice', 'Helen is so smart that she ________ every exam without even trying.', 'pass', 'passes', 'is passes', 'passed', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một sự thật hoặc hành động thường xuyên. "Passes" là động từ ngôi thứ ba số ít, phù hợp với chủ ngữ "Helen."\n(A) pass (v.): "pass" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "Helen."\n(C) is passes (v.): "is passes" không đúng ngữ pháp, vì "is" cần đi kèm với một phân từ hiện tại hoặc một tính từ, không phải động từ "passes."\n(D) passed (v.): "passed" là thì quá khứ của "pass," không phù hợp vì câu này đang nói về hiện tại.', 'Helen thông minh đến mức cô ấy vượt qua mọi kỳ thi mà không cần cố gắng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_001', 'zenlish_practice', 'Let me explain what you need to do. First ________ the dishes and ___________ the floors. Then you ________ the dinner.', 'are washing / are sweep / prepare', 'are clean / vacuum / make', 'wash / vacuum / prepare', 'put / clean / cooking', 'C', 'Giải thích: Câu này yêu cầu sử dụng động từ nguyên mẫu để chỉ dẫn các hành động cần thực hiện theo thứ tự. "Wash" (rửa), "vacuum" (hút bụi), và "prepare" (chuẩn bị) đều là những động từ nguyên mẫu, phù hợp với ngữ cảnh của câu.\n(A) are washing / are sweep / prepare: Các động từ "are washing" và "are sweep" không phù hợp vì chúng là dạng hiện tại tiếp diễn, trong khi câu yêu cầu dạng động từ nguyên mẫu.\n(B) are clean / vacuum / make: "are clean" không đúng ngữ pháp, và "make" không phù hợp với ngữ cảnh của việc chuẩn bị bữa tối.\n(D) put / clean / cooking: "put" và "cooking" không phù hợp với ngữ cảnh và không đúng dạng động từ cần thiết.', 'Để tôi giải thích những gì bạn cần làm. Đầu tiên, rửa bát và hút bụi sàn. Sau đó, bạn chuẩn bị bữa tối.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_002', 'zenlish_practice', 'He usually _______ to bed early. He _________ till midnight.', 'doesn''t go / stays up', 'goes / stays up', 'not to go / doesn''t stay up', 'is going / isn''t staying up', 'A', 'Giải thích: Câu đầu tiên sử dụng "doesn''t go" (thì hiện tại đơn phủ định) để diễn tả một thói quen thường xuyên của chủ ngữ "He." Câu thứ hai sử dụng "stays up" để diễn tả hành động "thức khuya" đến nửa đêm. Cấu trúc này phù hợp với ngữ cảnh của câu.\n(B) goes / stays up: "goes" diễn tả hành động đi ngủ sớm, không phù hợp với ý nghĩa câu đầu tiên.\n(C) not to go / doesn''t stay up: "not to go" không đúng ngữ pháp và không phù hợp với cấu trúc câu.\n(D) is going / isn''t staying up: Đây là thì hiện tại tiếp diễn, không phù hợp với việc mô tả một thói quen hoặc hành động thường xuyên.', 'Anh ấy thường không đi ngủ sớm. Anh ấy thức đến nửa đêm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_003', 'zenlish_practice', 'When does he __________ his room?', 'tidying', 'tidies', 'tidy', 'does tidy', 'C', 'Giải thích: Câu hỏi này sử dụng động từ "tidy" ở dạng nguyên mẫu sau "does" để đặt câu hỏi trong thì hiện tại đơn (present simple). "Tidy" có nghĩa là "dọn dẹp," phù hợp với ngữ cảnh của câu hỏi.\n(A) tidying (v.): "tidying" là dạng danh động từ hoặc phân từ hiện tại, không phù hợp với cấu trúc câu hỏi.\n(B) tidies (v.): "tidies" là dạng động từ ngôi thứ ba số ít, không phù hợp vì sau "does" cần sử dụng động từ nguyên mẫu.\n(D) does tidy (v.): "does tidy" không đúng ngữ pháp, vì không cần lặp lại "does" trong cấu trúc này.', 'Khi nào anh ấy dọn dẹp phòng của mình?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_004', 'zenlish_practice', 'I ___________ it would be a good idea to stay with them one more night.', 'think', 'thought', 'am thinking', 'would think', 'B', 'Giải thích: Câu này diễn tả một suy nghĩ hoặc quyết định đã xảy ra trong quá khứ, vì vậy động từ "thought" (thì quá khứ của "think") là phù hợp.\n(A) think (v.): "think" là thì hiện tại, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) am thinking (v.): "am thinking" là thì hiện tại tiếp diễn, không phù hợp với câu này vì câu đang nói về một suy nghĩ trong quá khứ.\n(D) would think (v.): "would think" là dạng động từ điều kiện, không phù hợp với ngữ cảnh của câu.', 'Tôi đã nghĩ rằng sẽ là một ý tưởng tốt nếu ở lại với họ thêm một đêm nữa.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_005', 'zenlish_practice', 'He __________do his homework every day.', 'doesn''t', 'don''t', 'isn''t', 'is', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) với phủ định để diễn tả rằng anh ấy không làm bài tập hàng ngày. "Doesn''t" là dạng phủ định của "does," phù hợp với chủ ngữ ngôi thứ ba số ít "He."\n(B) don''t (v.): "don''t" là dạng phủ định dùng cho các chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp với "He."\n(C) isn''t (v.): "isn''t" là dạng phủ định của "is," không phù hợp với động từ "do" trong câu này.\n(D) is (v.): "is" là động từ "to be," không phù hợp với cấu trúc cần thiết để phủ định động từ "do."', 'Anh ấy không làm bài tập về nhà mỗi ngày.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_006', 'zenlish_practice', 'Sara says she’s 17 but I ________ her.', 'don’t believe', 'didn’t believe', 'won’t believe', 'wouldn’t believe', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả việc không tin tưởng vào lời nói của Sara ở thời điểm hiện tại. "Don''t believe" là dạng phủ định của "believe," phù hợp với ngữ cảnh của câu.\n(B) didn’t believe (v.): "didn’t believe" là thì quá khứ đơn, không phù hợp vì câu này đang nói về một sự kiện hiện tại.\n(C) won’t believe (v.): "won’t believe" là thì tương lai đơn, không phù hợp với ngữ cảnh của câu hiện tại.\n(D) wouldn’t believe (v.): "wouldn’t believe" là dạng điều kiện, không phù hợp với ngữ cảnh của câu này.', 'Sara nói cô ấy 17 tuổi nhưng tôi không tin cô ấy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_007', 'zenlish_practice', 'He is not a vegetarian but he _____________ meat.', 'is eating', 'never eat', 'always eats', 'occasionally eats', 'D', 'Giải thích: "Occasionally eats" diễn tả hành động ăn thịt một cách thỉnh thoảng, phù hợp với ý nghĩa của câu. "He is not a vegetarian but he occasionally eats meat" cho thấy rằng mặc dù anh ấy không phải là người ăn chay, anh ấy chỉ ăn thịt thỉnh thoảng.\n(A) is eating (v.): "is eating" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh diễn tả thói quen hoặc hành động thỉnh thoảng.\n(B) never eat (v.): "never eat" không đúng ngữ pháp vì "eat" không phù hợp với chủ ngữ ngôi thứ ba số ít "He."\n(C) always eats (v.): "always eats" không phù hợp với ngữ cảnh vì từ "always" chỉ hành động xảy ra thường xuyên, không đúng với ý nghĩa "thỉnh thoảng" của câu.', 'Anh ấy không phải là người ăn chay nhưng anh ấy thỉnh thoảng ăn thịt.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_008', 'zenlish_practice', 'My parents ________ work on Saturdays.', 'isn''t', 'doesn''t', 'don''t', 'wasn''t', 'C', 'Giải thích: Câu này sử dụng "don''t" (dạng phủ định của "do") để phù hợp với chủ ngữ số nhiều "My parents" trong thì hiện tại đơn (present simple). "My parents don''t work on Saturdays" có nghĩa là bố mẹ tôi không làm việc vào các ngày thứ Bảy.\n(A) isn''t (v.): "isn''t" là dạng phủ định của "is," không phù hợp với chủ ngữ số nhiều "My parents."\n(B) doesn''t (v.): "doesn''t" là dạng phủ định của "does," không phù hợp với chủ ngữ số nhiều "My parents."\n(D) wasn''t (v.): "wasn''t" là dạng phủ định của "was," không phù hợp với thì hiện tại đơn và chủ ngữ số nhiều.', 'Bố mẹ tôi không làm việc vào các ngày thứ Bảy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_009', 'zenlish_practice', 'John ________ tennis once or twice a week.', 'usually play', 'is usually playing', 'usually plays', 'have usually played', 'C', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một thói quen hoặc hành động thường xuyên. "Usually plays" là dạng đúng, trong đó "plays" là động từ ngôi thứ ba số ít, phù hợp với chủ ngữ "John."\n(A) usually play (v.): "play" là động từ nguyên mẫu, không phù hợp với ngôi thứ ba số ít "John."\n(B) is usually playing (v.): "is usually playing" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu muốn diễn tả thói quen.\n(D) have usually played (v.): "have usually played" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh diễn tả thói quen.', 'John thường chơi tennis một hoặc hai lần mỗi tuần.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0010_q_010', 'zenlish_practice', 'He _____ his parents twice a week.', 'visits', 'visiting', 'is visiting', 'visited', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) để diễn tả một hành động lặp lại theo tần suất. "visits" là dạng đúng, động từ được chia ở ngôi thứ ba số ít, phù hợp với chủ ngữ "He."\n(B) visiting (v-ing.): "V-ing" không phải là động từ chính của câu\n(C) is visiting (be + V-ing): "is visiting" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu muốn diễn tả thói quen.\n(D) visited (v-ed): "visited" là động từ ở thì quá khứ đơn, không phù hợp với ngữ cảnh của hành động ở hiện tại', 'Anh ấy thăm bố mẹ hai lần một tuần.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_001', 'zenlish_practice', 'The city is ________ its public transportation system in preparation for two international sporting events.', 'improve', 'improved', 'improving', 'improvement', 'C', 'Giải thích: "Improving" là động từ ở thì hiện tại tiếp diễn, phù hợp với ngữ cảnh của câu khi nói về hành động đang xảy ra ở hiện tại. Câu này nói rằng thành phố đang cải thiện hệ thống giao thông công cộng của mình để chuẩn bị cho hai sự kiện thể thao quốc tế.\n(A) improve (infinitive): "improve" là động từ nguyên mẫu, không phù hợp với ngữ pháp của câu.\n(B) improved (past participle): "improved" là dạng quá khứ phân từ, không phù hợp trong cấu trúc câu này.\n(D) improvement (noun): "improvement" là danh từ, không phù hợp vì cần một động từ dạng V-ing sau "is."', 'Thành phố đang cải thiện hệ thống giao thông công cộng của mình để chuẩn bị cho hai sự kiện thể thao quốc tế.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_002', 'zenlish_practice', 'According to the Harton Fashion Chronicle, many designers _____ green and brown fabrics for their autumn collections this year.', 'to use', 'are using', 'had been used', 'were used', 'B', 'Giải thích: "Are using" là động từ ở thì hiện tại tiếp diễn, phù hợp với ngữ cảnh của câu khi nói về một xu hướng hiện tại trong ngành thời trang. Câu này nói rằng theo Harton Fashion Chronicle, nhiều nhà thiết kế đang sử dụng các loại vải màu xanh lá cây và nâu cho các bộ sưu tập mùa thu của họ năm nay.\n(A) to use (infinitive): "to use" là động từ nguyên mẫu, không phù hợp với ngữ pháp của câu.\n(C) had been used (past perfect passive): "had been used" là động từ ở thì quá khứ hoàn thành bị động, không phù hợp với ngữ cảnh của câu khi nói về xu hướng hiện tại.\n(D) were used (past passive): "were used" là động từ ở thì quá khứ bị động, không phù hợp với ngữ cảnh của câu khi nói về hành động đang diễn ra.', 'Theo Harton Fashion Chronicle, nhiều nhà thiết kế đang sử dụng các loại vải màu xanh lá cây và nâu cho các bộ sưu tập mùa thu của họ năm nay.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_003', 'zenlish_practice', 'We are _____ whether we should expand our capacity here or move to a larger building complex.', 'consider', 'considers', 'considered', 'considering', 'D', 'Giải thích: Trong câu này, "considering" là dạng đúng của động từ cần được sử dụng. "We are considering" có nghĩa là "chúng tôi đang xem xét," diễn tả hành động hiện tại mà công ty đang cân nhắc về việc mở rộng hay chuyển sang một tòa nhà lớn hơn.\n(A) consider (v.): "Consider" là dạng nguyên thể, không phù hợp với cấu trúc của câu khi cần động từ dạng V-ing để đi kèm với "are."\n(B) considers (v.): "Considers" là dạng chia ngôi thứ ba số ít, không phù hợp vì chủ ngữ "we" là ngôi thứ nhất số nhiều.\n(C) considered (v. past): "Considered" là dạng quá khứ, không phù hợp khi câu cần diễn tả một hành động hiện tại đang diễn ra.', 'Chúng tôi đang xem xét liệu chúng tôi nên mở rộng năng lực tại đây hay chuyển đến một khu phức hợp tòa nhà lớn hơn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_004', 'zenlish_practice', 'A service engineer from PX Copytime _____ the broken copy machine at the moment.', 'repair', 'repairs', 'will repair', 'is repairing', 'D', 'Giải thích: Câu này đang nói về hành động đang xảy ra ngay tại thời điểm hiện tại, vì vậy cần sử dụng thì hiện tại tiếp diễn "is repairing."\n(A) repair: Không đúng vì đây là dạng động từ nguyên mẫu, không phù hợp với ngữ cảnh hành động đang diễn ra.\n(B) repairs: Không đúng vì đây là dạng hiện tại đơn, không diễn tả được hành động đang xảy ra ngay lúc nói.\n(C) will repair: Không đúng vì đây là dạng tương lai, không phù hợp với hành động đang diễn ra tại thời điểm hiện tại.', 'Một kỹ sư dịch vụ từ PX Copytime đang sửa chữa máy photocopy bị hỏng ngay lúc này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_005', 'zenlish_practice', 'Mornesse Hardware ______ free flashlights to the first 50 customers next Friday.', 'is offering', 'having offered', 'was offered', 'to offer', 'A', 'Giải thích: Câu này đang nói về một hành động sẽ xảy ra trong tương lai gần, vì vậy cần dùng thì hiện tại tiếp diễn "is offering" để diễn tả rằng hành động cung cấp đèn pin miễn phí sẽ xảy ra vào ngày thứ Sáu tới.\n(B) having offered: Không đúng vì đây là dạng hiện tại hoàn thành phân từ, không phù hợp với cấu trúc câu yêu cầu thì hiện tại tiếp diễn.\n(C) was offered: Không đúng vì đây là thì quá khứ bị động, không phù hợp với ý nghĩa hành động trong tương lai gần.\n(D) to offer: Không đúng vì đây là dạng nguyên mẫu, không phù hợp với cấu trúc câu yêu cầu thì hiện tại tiếp diễn.', 'Mornesse Hardware sẽ cung cấp đèn pin miễn phí cho 50 khách hàng đầu tiên vào thứ Sáu tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_006', 'zenlish_practice', 'The Silvau Division is now ______ a full line of steel products at a new modern facility just outside the city.', 'manufacturer', 'being manufactured', 'manufactured', 'manufacturing', 'D', 'Giải thích: Trong câu này, chủ ngữ "The Silvau Division" cần một động từ để diễn tả hành động hiện tại mà họ đang thực hiện. "Manufacturing" là dạng hiện tại tiếp diễn của động từ "manufacture," nghĩa là "sản xuất." Câu này có nghĩa là Bộ phận Silvau hiện đang sản xuất một dòng sản phẩm thép đầy đủ tại một cơ sở hiện đại mới ngay bên ngoài thành phố.\n(A) manufacturer (n.): "manufacturer" có nghĩa là "nhà sản xuất." Lý do không chọn là vì đây là danh từ, không phù hợp với cấu trúc ngữ pháp của câu.\n(B) being manufactured (passive voice): "being manufactured" có nghĩa là "đang được sản xuất." Lý do không chọn là vì câu cần một động từ chủ động để diễn tả hành động của chủ ngữ.\n(C) manufactured (past participle): "manufactured" có nghĩa là "đã được sản xuất." Lý do không chọn là vì câu cần một động từ dạng hiện tại tiếp diễn để diễn tả hành động đang diễn ra.', 'Bộ phận Silvau hiện đang sản xuất một dòng sản phẩm thép đầy đủ tại một cơ sở hiện đại mới ngay bên ngoài thành phố.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_007', 'zenlish_practice', 'Did you remember to book seat? Oh no, I forgot. I ____ for them now.', 'will be phoning', 'was phoning', 'am phoning', 'phoning', 'C', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động sắp xảy ra ngay tại thời điểm nói. "Am phoning" là dạng đúng, cho thấy người nói đang chuẩn bị gọi điện để đặt chỗ ngay bây giờ.\n(A) will be phoning (v.): "will be phoning" là thì tương lai tiếp diễn, không phù hợp vì câu này cần diễn tả hành động đang diễn ra ngay lập tức.\n(B) was phoning (v.): "was phoning" là thì quá khứ tiếp diễn, không phù hợp vì câu đang nói về một hành động hiện tại.\n(D) phoning (v.): "phoning" không đúng ngữ pháp vì cần một động từ to be trước nó để hoàn thành thì hiện tại tiếp diễn.', 'Bạn có nhớ đặt chỗ không? Ồ không, tôi quên mất. Tôi đang gọi điện để đặt chỗ ngay bây giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_008', 'zenlish_practice', 'Why ____ Ann wearing her new dress now ?', 'do', 'be', 'are', 'is', 'D', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để hỏi về hành động đang diễn ra tại thời điểm hiện tại. "Is" phù hợp với chủ ngữ "Ann," một ngôi thứ ba số ít.\n(A) do (v.): "do" không phù hợp với thì hiện tại tiếp diễn và chủ ngữ ngôi thứ ba số ít.\n(B) be (v.): "be" là dạng nguyên mẫu, không phù hợp trong ngữ cảnh này.\n(C) are (v.): "are" phù hợp với chủ ngữ số nhiều hoặc ngôi thứ hai, không phù hợp với "Ann."', 'Tại sao Ann lại đang mặc chiếc váy mới của cô ấy bây giờ?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_009', 'zenlish_practice', 'Mr Green is ____ next month after forty years service to the company.', 'retreating', 'retiring', 'sacking', 'yielding', 'B', 'Giải thích: "Retiring" có nghĩa là nghỉ hưu, phù hợp với ngữ cảnh của câu này khi nói về việc kết thúc sự nghiệp sau bốn mươi năm làm việc.\n(A) retreating (v.): "Retreating" có nghĩa là rút lui, không phù hợp trong ngữ cảnh này.\n(C) sacking (v.): "Sacking" có nghĩa là sa thải, không phù hợp với ngữ cảnh nói về việc tự nguyện nghỉ hưu.\n(D) yielding (v.): "Yielding" có nghĩa là nhường nhịn hoặc từ bỏ, không phù hợp trong ngữ cảnh này.', 'Ông Green sẽ nghỉ hưu vào tháng tới sau bốn mươi năm cống hiến cho công ty.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0011_q_010', 'zenlish_practice', 'Do you hear the wind ? It ____ very strongly tonight.', 'will be blowing', 'is blowing', 'was blowing', 'blowing', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm nói. "Is blowing" phù hợp với chủ ngữ "it" và diễn tả việc gió đang thổi mạnh vào tối nay.\n(A) will be blowing (v.): "will be blowing" là thì tương lai tiếp diễn, không phù hợp vì câu này cần diễn tả hành động đang diễn ra ngay bây giờ.\n(C) was blowing (v.): "was blowing" là thì quá khứ tiếp diễn, không phù hợp vì câu này đang nói về hiện tại.\n(D) blowing (v.): "blowing" không đúng ngữ pháp vì cần một động từ to be trước nó để hoàn thành thì hiện tại tiếp diễn.', 'Bạn có nghe thấy gió không? Tối nay gió đang thổi rất mạnh.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_001', 'zenlish_practice', 'Ann usually does shopping, but I ____ it now because she isn’t well.', 'will be doing', 'am doing', 'is doing', 'was doing', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang xảy ra tại thời điểm hiện tại. "Am doing" phù hợp với chủ ngữ "I" và diễn tả việc người nói đang làm việc mà Ann thường làm, do cô ấy không khỏe.\n(A) will be doing (v.): "will be doing" là thì tương lai tiếp diễn, không phù hợp vì câu này đang nói về hành động hiện tại.\n(C) is doing (v.): "is doing" là dạng hiện tại tiếp diễn cho ngôi thứ ba số ít, không phù hợp với chủ ngữ "I."\n(D) was doing (v.): "was doing" là thì quá khứ tiếp diễn, không phù hợp vì câu này đang nói về hiện tại.', 'Ann thường đi mua sắm, nhưng bây giờ tôi đang làm điều đó vì cô ấy không khỏe.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_002', 'zenlish_practice', 'I ____ for my car keys but I haven’t seen them yet.', 'am looking', 'looking', 'looks', 'was looking', 'A', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm nói. "Am looking" phù hợp với chủ ngữ "I" và diễn tả việc người nói đang tìm chìa khóa xe của mình.\n(B) looking (v.): "looking" không đúng ngữ pháp vì cần một động từ to be trước nó để hoàn thành thì hiện tại tiếp diễn.\n(C) looks (v.): "looks" là dạng động từ ngôi thứ ba số ít, không phù hợp với chủ ngữ "I."\n(D) was looking (v.): "was looking" là thì quá khứ tiếp diễn, không phù hợp vì câu này đang nói về hiện tại.', 'Tôi đang tìm chìa khóa xe của mình nhưng tôi vẫn chưa thấy chúng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_003', 'zenlish_practice', 'Where is Tom now? He ____ under the car.', 'was lying', 'are lying', 'is lying', 'lying', 'C', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả hành động đang diễn ra ngay tại thời điểm hiện tại. "Is lying" phù hợp với chủ ngữ "He" và diễn tả việc Tom đang nằm dưới chiếc xe.\n(A) was lying (v.): "was lying" là thì quá khứ tiếp diễn, không phù hợp vì câu này đang nói về hiện tại.\n(B) are lying (v.): "are lying" là thì hiện tại tiếp diễn nhưng không phù hợp với chủ ngữ ngôi thứ ba số ít "He."\n(D) lying (v.): "lying" không đúng ngữ pháp vì cần một động từ "to be" trước nó để hoàn thành thì hiện tại tiếp diễn.', 'Tom đang ở đâu bây giờ? Anh ấy đang nằm dưới chiếc xe.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_004', 'zenlish_practice', 'I think he ____ his shoes at present.', 'was polishing', 'is polishing', 'are polishing', 'polishes', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Is polishing" phù hợp với chủ ngữ "he" và diễn tả việc anh ấy đang đánh bóng đôi giày của mình.\n(A) was polishing (v.): "was polishing" là thì quá khứ tiếp diễn, không phù hợp vì câu này đang nói về hiện tại.\n(C) are polishing (v.): "are polishing" là thì hiện tại tiếp diễn nhưng không phù hợp với chủ ngữ ngôi thứ ba số ít "he."\n(D) polishes (v.): "polishes" là thì hiện tại đơn, không phù hợp với ngữ cảnh hiện tại cần diễn tả hành động đang diễn ra.', 'Tôi nghĩ rằng anh ấy đang đánh bóng đôi giày của mình vào lúc này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_005', 'zenlish_practice', 'He didn’t go yesterday, but he’s … go today.', 'planning to', 'plan to', 'plans', 'planning', 'A', 'Giải thích: "Planning to" là cụm từ đúng, diễn tả ý định làm điều gì đó trong tương lai gần. Cụm từ này phù hợp với ngữ cảnh của câu, diễn tả rằng anh ấy không đi hôm qua, nhưng hôm nay anh ấy có kế hoạch sẽ đi.\n(B) plan to (v.): "plan to" không đúng ngữ pháp trong câu này vì động từ chính "planning" cần ở dạng hiện tại tiếp diễn để diễn tả ý định đã được lên kế hoạch trước.\n(C) plans (v.): "plans" là động từ hiện tại đơn ngôi thứ ba số ít, không phù hợp trong ngữ cảnh diễn tả ý định đã được lập trước.\n(D) planning (v.): "planning" không đúng ngữ pháp trong câu này vì thiếu "to" để tạo thành cụm từ "planning to."', 'Anh ấy không đi hôm qua, nhưng anh ấy đang lên kế hoạch đi hôm nay.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_006', 'zenlish_practice', 'Why ____ Ann wearing her new dress now ?', 'do', 'be', 'are', 'is', 'D', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để hỏi về hành động đang diễn ra tại thời điểm hiện tại. "Is" phù hợp với chủ ngữ "Ann," một ngôi thứ ba số ít.\n(A) do (v.): "do" không phù hợp với thì hiện tại tiếp diễn và chủ ngữ ngôi thứ ba số ít.\n(B) be (v.): "be" là dạng nguyên mẫu, không phù hợp trong ngữ cảnh này.\n(C) are (v.): "are" phù hợp với chủ ngữ số nhiều hoặc ngôi thứ hai, không phù hợp với "Ann."', 'Tại sao Ann lại đang mặc chiếc váy mới của cô ấy bây giờ?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_007', 'zenlish_practice', '2. My brother often goes to school by bus, but today he _________ to school by bike.', 'goes', 'is going', 'go', 'are going', 'B', 'Giải thích: Trong câu này, "today" (hôm nay) là một dấu hiệu để sử dụng thì hiện tại tiếp diễn nhằm diễn tả một hành động đang xảy ra tại thời điểm hiện tại. Chủ ngữ "he" là ngôi thứ ba số ít, do đó "is going" là dạng đúng để diễn tả rằng hôm nay anh ấy đi xe đạp đến trường, một điều khác với thói quen thường ngày của anh ấy.\n(A) goes (v): "goes" là động từ ngôi thứ ba số ít ở thì hiện tại đơn, thường dùng để diễn tả thói quen hoặc hành động lặp đi lặp lại. Lý do không chọn là vì câu này cần diễn tả hành động đang diễn ra ngay lúc nói.\n(C) go (v): "go" là động từ nguyên thể, không được chia theo chủ ngữ. Lý do không chọn là vì nó không phù hợp với chủ ngữ ngôi thứ ba số ít và thì hiện tại tiếp diễn.\n(D) are going (v): "are going" là thì hiện tại tiếp diễn nhưng dùng cho chủ ngữ số nhiều. Lý do không chọn là vì chủ ngữ "he" là ngôi thứ ba số ít nên cần dùng "is" thay vì "are".', 'Anh trai tôi thường đi học bằng xe buýt, nhưng hôm nay anh ấy đang đi học bằng xe đạp.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_008', 'zenlish_practice', 'He usually drinks coffee but now he ____ tea .', 'was drinking', 'is drinking', 'drinks', 'will be drinking', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm nói. "Is drinking" phù hợp với chủ ngữ "he" và diễn tả việc anh ấy đang uống trà ngay bây giờ, khác với thói quen thường ngày của anh ấy là uống cà phê.\n(A) was drinking (v.): "was drinking" là thì quá khứ tiếp diễn, không phù hợp vì câu này đang nói về hiện tại.\n(C) drinks (v.): "drinks" là thì hiện tại đơn, không phù hợp với ngữ cảnh khi diễn tả hành động đang diễn ra ngay bây giờ.\n(D) will be drinking (v.): "will be drinking" là thì tương lai tiếp diễn, không phù hợp vì câu này đang nói về hiện tại.', 'Anh ấy thường uống cà phê nhưng bây giờ anh ấy đang uống trà.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_009', 'zenlish_practice', 'Many retirers feel useless because they ____', 'do volunteer work', 'have limited incomes', 'can''''t help themselves', 'aren''t working', 'D', 'Giải thích: Nhiều người nghỉ hưu có cảm giác vô dụng vì họ không còn làm việc nữa. Câu này sử dụng "aren''t working" để diễn tả trạng thái không làm việc của những người nghỉ hưu, điều này có thể khiến họ cảm thấy không còn đóng góp gì.\n(A) do volunteer work: "do volunteer work" có nghĩa là làm công việc tình nguyện, điều này thường không khiến người ta cảm thấy vô dụng.\n(B) have limited incomes: "have limited incomes" nói về thu nhập hạn chế, nhưng không phải là nguyên nhân trực tiếp khiến người ta cảm thấy vô dụng.\n(C) can''t help themselves: "can''t help themselves" có nghĩa là không thể tự giúp đỡ bản thân, không phù hợp với ngữ cảnh.', 'Nhiều người nghỉ hưu cảm thấy vô dụng vì họ không còn làm việc nữa.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0012_q_010', 'zenlish_practice', 'I am saving up because I ____ abroad in July.', 'going', 'went', 'am going', 'will be going', 'C', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một kế hoạch hoặc dự định trong tương lai đã được lên kế hoạch. "Am going" phù hợp với chủ ngữ "I" và diễn tả kế hoạch đi nước ngoài vào tháng 7.\n(A) going: "going" thiếu động từ to be để hoàn thành thì hiện tại tiếp diễn, không đúng ngữ pháp.\n(B) went: "went" là thì quá khứ đơn, không phù hợp vì câu này đang nói về một kế hoạch tương lai.\n(D) will be going: "will be going" là thì tương lai tiếp diễn, có thể sử dụng nhưng không phù hợp bằng hiện tại tiếp diễn trong ngữ cảnh này.', 'Tôi đang tiết kiệm tiền vì tôi sẽ đi nước ngoài vào tháng 7.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_001', 'zenlish_practice', 'I''ll think about your suggestion while I ____ for you.', 'will wait', 'wait', 'am waiting', 'waits', 'B', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) sau liên từ "while" để diễn tả một hành động xảy ra đồng thời với hành động chính trong tương lai. "Wait" phù hợp với chủ ngữ "I" và diễn tả việc người nói sẽ suy nghĩ trong khi chờ đợi.\n(A) will wait (v.): "will wait" không phù hợp vì sau "while" ta thường không dùng thì tương lai.\n(C) am waiting (v.): "am waiting" là thì hiện tại tiếp diễn, có thể dùng trong một số trường hợp, nhưng hiện tại đơn thường được ưu tiên hơn sau "while."\n(D) waits (v.): "waits" là động từ ngôi thứ ba số ít, không phù hợp với chủ ngữ "I."', 'Tôi sẽ suy nghĩ về đề xuất của bạn trong khi tôi chờ đợi bạn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_002', 'zenlish_practice', 'Look! The man (climb) ____ up the tree.', 'is climbing', 'climbs', 'are climbing', 'climb', 'A', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm nói. "Is climbing" phù hợp với chủ ngữ "The man" và diễn tả việc người đàn ông đang trèo lên cây ngay lúc này.\n(B) climbs (v.): "climbs" là thì hiện tại đơn, không phù hợp với ngữ cảnh diễn tả hành động đang diễn ra ngay bây giờ.\n(C) are climbing (v.): "are climbing" là hiện tại tiếp diễn, nhưng không phù hợp với chủ ngữ ngôi thứ ba số ít "The man."\n(D) climb (v.): "climb" là động từ nguyên mẫu, không phù hợp với ngữ cảnh này.', 'Nhìn kìa! Người đàn ông đang trèo lên cây.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_003', 'zenlish_practice', 'The manufacturer ____ changes to its billing proceduress now.', 'implements', 'implemented', 'implementing', 'is implementing', 'D', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Is implementing" phù hợp với chủ ngữ "The manufacturer" và diễn tả việc nhà sản xuất đang thực hiện những thay đổi đối với quy trình thanh toán của họ.\n(A) implements (v.): "implements" là thì hiện tại đơn, không phù hợp với ngữ cảnh diễn tả hành động đang diễn ra ngay bây giờ.\n(B) implemented (v.): "implemented" là thì quá khứ đơn, không phù hợp vì câu này đang nói về hành động hiện tại.\n(C) implementing (v.): "implementing" không đúng ngữ pháp vì cần một động từ "to be" trước nó để hoàn thành thì hiện tại tiếp diễn.', 'Nhà sản xuất đang thực hiện những thay đổi đối với quy trình thanh toán của họ ngay bây giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_004', 'zenlish_practice', 'We are now ____ our efforts to provide better services to our customers.', 'increase', 'increasing', 'increases', 'increased', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Increasing" phù hợp với chủ ngữ "We" và diễn tả việc chúng tôi đang tăng cường nỗ lực để cung cấp dịch vụ tốt hơn cho khách hàng.\n(A) increase (v.): "increase" là động từ nguyên mẫu, không phù hợp với ngữ cảnh này.\n(C) increases (v.): "increases" là thì hiện tại đơn, không phù hợp với ngữ cảnh diễn tả hành động đang diễn ra ngay bây giờ.\n(D) increased (v.): "increased" là thì quá khứ đơn hoặc quá khứ phân từ, không phù hợp vì câu này đang nói về hành động hiện tại.', 'Chúng tôi hiện đang tăng cường nỗ lực để cung cấp dịch vụ tốt hơn cho khách hàng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_005', 'zenlish_practice', 'Ms. Tracy ____ the annual report now.', 'is preparing', 'was preparing', 'prepared', 'have prepared', 'A', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Is preparing" phù hợp với chủ ngữ "Ms. Tracy" và diễn tả việc cô ấy đang chuẩn bị báo cáo thường niên ngay bây giờ.\n(B) was preparing (v.): "was preparing" là thì quá khứ tiếp diễn, không phù hợp vì câu này đang nói về hành động hiện tại.\n(C) prepared (v.): "prepared" là thì quá khứ đơn, không phù hợp vì câu này đang nói về hành động hiện tại.\n(D) have prepared (v.): "have prepared" là thì hiện tại hoàn thành, không phù hợp vì câu này cần diễn tả một hành động đang diễn ra.', 'Cô Tracy đang chuẩn bị báo cáo thường niên ngay bây giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_006', 'zenlish_practice', 'My daughter _________ studying English at Istanbul University.', 'is', 'does', 'do', 'not', 'A', 'Giải thích: Câu này sử dụng động từ "is" trong thì hiện tại đơn để nói về trạng thái hiện tại của "con gái tôi". "Is" phù hợp với chủ ngữ "My daughter" (ngôi thứ ba số ít) và diễn tả việc cô ấy đang học tiếng Anh tại Đại học Istanbul.\n(B) does (v.): "does" là động từ trợ động cho thì hiện tại đơn, không phù hợp với cấu trúc câu này.\n(C) do (v.): "do" không phù hợp với chủ ngữ ngôi thứ ba số ít "My daughter."\n(D) not: "not" là từ phủ định, không thể đứng một mình trong câu này.', 'Con gái tôi đang học tiếng Anh tại Đại học Istanbul.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_007', 'zenlish_practice', 'I want to lose weight, so this week I ____ lunch.', 'am not eating', 'isn’t eating', 'aren’t eating', 'amn’t eating', 'A', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra hoặc một kế hoạch tạm thời trong thời gian này. "Am not eating" phù hợp với chủ ngữ "I" và diễn tả việc người nói quyết định không ăn trưa tuần này.\n(B) isn’t eating (v.): "isn’t eating" không phù hợp với chủ ngữ "I," vì "isn''t" chỉ dùng với ngôi thứ ba số ít.\n(C) aren’t eating (v.): "aren’t eating" không phù hợp với chủ ngữ "I," vì "aren''t" chỉ dùng với số nhiều hoặc ngôi thứ hai.\n(D) amn’t eating: "amn’t" không tồn tại trong tiếng Anh.', 'Tôi muốn giảm cân, vì vậy tuần này tôi không ăn trưa.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_008', 'zenlish_practice', 'Is Chris _____________ this weekend?', 'will work', 'works', 'working', 'worked', 'C', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để hỏi về một kế hoạch hoặc dự định trong tương lai gần. "Working" phù hợp với chủ ngữ "Chris" và diễn tả việc anh ấy có làm việc vào cuối tuần này hay không.\n(A) will work (v.): "will work" là thì tương lai đơn, không phù hợp với cấu trúc câu hỏi này.\n(B) works (v.): "works" là thì hiện tại đơn, không phù hợp với ngữ cảnh hỏi về kế hoạch tương lai.\n(D) worked (v.): "worked" là thì quá khứ đơn, không phù hợp với ngữ cảnh câu hỏi về tương lai.', 'Chris có làm việc vào cuối tuần này không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_009', 'zenlish_practice', 'We ________ enjoying our holiday here so much.', 'don''t', 'are', 'is', 'doesn''t', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Are" phù hợp với chủ ngữ "We" và diễn tả việc chúng tôi đang rất thích kỳ nghỉ của mình ở đây.\n(A) don''t (v.): "don''t" là dạng phủ định, không phù hợp với ngữ cảnh câu này.\n(C) is (v.): "is" chỉ dùng với ngôi thứ ba số ít, không phù hợp với chủ ngữ "We."\n(D) doesn''t (v.): "doesn''t" là dạng phủ định của "does," không phù hợp với chủ ngữ "We."', 'Chúng tôi đang rất thích kỳ nghỉ của mình ở đây.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0013_q_010', 'zenlish_practice', 'We can''t go out tonight because we ________ dinner at my uncle''s house.', 'have', 'are have', 'are having', 'had', 'C', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một kế hoạch hoặc sự kiện đã được sắp xếp trong tương lai gần. "Are having" phù hợp với chủ ngữ "we" và diễn tả việc chúng tôi sẽ ăn tối tại nhà của chú tôi.\n(A) have (v.): "have" là thì hiện tại đơn, không phù hợp với ngữ cảnh của một kế hoạch tương lai gần.\n(B) are have (v.): "are have" không đúng ngữ pháp vì "have" không phải là phân từ hiện tại.\n(D) had (v.): "had" là thì quá khứ đơn, không phù hợp với ngữ cảnh của câu nói về kế hoạch tương lai.', 'Chúng tôi không thể ra ngoài tối nay vì chúng tôi sẽ ăn tối tại nhà của chú tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_001', 'zenlish_practice', 'I ___________ sitting down at the moment.', 'am not', 'are not', 'is', 'don''t', 'A', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả hành động đang xảy ra ngay tại thời điểm hiện tại và dạng phủ định "am not" phù hợp với chủ ngữ "I".\n(B) are not (v.): "are not" không phù hợp với chủ ngữ "I" vì "are" chỉ dùng với số nhiều hoặc ngôi thứ hai.\n(C) is (v.): "is" là dạng khẳng định cho ngôi thứ ba số ít, không phù hợp với chủ ngữ "I".\n(D) don''t (v.): "don''t" là dạng phủ định cho thì hiện tại đơn, không phù hợp với cấu trúc của câu này.', 'Tôi không đang ngồi vào lúc này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_002', 'zenlish_practice', 'I am ______________ about him a lot these days.', 'think', 'thinking', 'thought', 'think of', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động hoặc trạng thái đang diễn ra trong một khoảng thời gian hiện tại. "Thinking" phù hợp với chủ ngữ "I" và diễn tả việc người nói đang suy nghĩ nhiều về anh ấy trong thời gian gần đây.\n(A) think (v.): "think" là động từ nguyên mẫu, không phù hợp với thì hiện tại tiếp diễn.\n(C) thought (v.): "thought" là thì quá khứ đơn, không phù hợp với ngữ cảnh hiện tại của câu.\n(D) think of (v.): "think of" không phù hợp về mặt cấu trúc trong câu này và thiếu sự chia động từ đúng cách.', 'Gần đây tôi đang nghĩ rất nhiều về anh ấy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_003', 'zenlish_practice', 'He ____________ now, but his wife ________________ with him.', 'is leaving / is going', 'leaves / isn''t going', 'is leaving / isn''t going', 'leaves / doesn''t go', 'C', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả hành động đang diễn ra ngay tại thời điểm hiện tại. "Is leaving" và "isn''t going" phù hợp với chủ ngữ "He" và "his wife," diễn tả việc anh ấy đang rời đi bây giờ, nhưng vợ anh ấy thì không đi cùng.\n(A) is leaving / is going: "is going" không phù hợp với ngữ cảnh của câu nói rằng vợ anh ấy không đi cùng.\n(B) leaves / isn''t going: "leaves" là thì hiện tại đơn, không phù hợp với ngữ cảnh của một hành động đang diễn ra ngay bây giờ.\n(D) leaves / doesn''t go: Cả "leaves" và "doesn''t go" đều ở thì hiện tại đơn, không phù hợp với ngữ cảnh hiện tại tiếp diễn.', 'Anh ấy đang rời đi bây giờ, nhưng vợ anh ấy không đi cùng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_004', 'zenlish_practice', 'Some men are waiting outside for you __________.', 'now', 'two hours ago', 'yesterday', 'an hour', 'A', 'Giải thích: "Now" (bây giờ) phù hợp với ngữ cảnh của câu nói về một hành động đang diễn ra ngay tại thời điểm hiện tại. "Some men are waiting outside for you now" có nghĩa là một số người đang chờ bạn ở bên ngoài ngay lúc này.\n(B) two hours ago: "Two hours ago" (hai giờ trước) không phù hợp vì nó ám chỉ thời điểm trong quá khứ, không phù hợp với thì hiện tại tiếp diễn.\n(C) yesterday: "Yesterday" (hôm qua) cũng không phù hợp vì nó ám chỉ thời điểm trong quá khứ.\n(D) an hour: "An hour" (một giờ) không chỉ rõ thời gian hiện tại và không phù hợp trong ngữ cảnh này.', 'Một số người đàn ông đang chờ bạn ở bên ngoài ngay bây giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_005', 'zenlish_practice', 'Some students ____________ their homework in the classroom now.', 'were doing', 'is doing', 'did', 'are doing', 'D', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Are doing" phù hợp với chủ ngữ "Some students" (một số học sinh) và diễn tả việc các học sinh đang làm bài tập về nhà trong lớp học ngay bây giờ.\n(A) were doing (v.): "were doing" là thì quá khứ tiếp diễn, không phù hợp vì câu này đang nói về hiện tại.\n(B) is doing (v.): "is doing" là hiện tại tiếp diễn, nhưng không phù hợp với chủ ngữ số nhiều "Some students."\n(C) did (v.): "did" là thì quá khứ đơn, không phù hợp vì câu này đang nói về hiện tại.', 'Một số học sinh đang làm bài tập về nhà trong lớp học ngay bây giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_006', 'zenlish_practice', 'My mother is busy at the moment. She ______________ her favourite programme.', 'watches', 'is watching', 'has watched', 'watched', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Is watching" phù hợp với chủ ngữ "She" và diễn tả việc mẹ của bạn đang bận vì đang xem chương trình yêu thích của bà ngay bây giờ.\n(A) watches (v.): "watches" là thì hiện tại đơn, không phù hợp với ngữ cảnh của hành động đang diễn ra ngay bây giờ.\n(C) has watched (v.): "has watched" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh nói về hành động đang diễn ra.\n(D) watched (v.): "watched" là thì quá khứ đơn, không phù hợp vì câu này đang nói về hiện tại.', 'Mẹ tôi đang bận lúc này. Bà ấy đang xem chương trình yêu thích của mình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_007', 'zenlish_practice', 'She usually listens to pop music but she _____________ to jazz these days.', 'is listening', 'listens', 'has listened', 'doesn''t listen', 'A', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một sự thay đổi tạm thời trong thói quen của cô ấy. "Is listening" phù hợp với chủ ngữ "she" và diễn tả việc cô ấy đang nghe nhạc jazz trong những ngày này, mặc dù cô ấy thường nghe nhạc pop.\n(B) listens (v.): "listens" là thì hiện tại đơn, không phù hợp với ngữ cảnh của hành động tạm thời.\n(C) has listened (v.): "has listened" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh nói về một thói quen tạm thời hiện tại.\n(D) doesn''t listen (v.): "doesn''t listen" là thì hiện tại đơn phủ định, không phù hợp với ngữ cảnh của câu này.', 'Cô ấy thường nghe nhạc pop nhưng dạo này cô ấy đang nghe nhạc jazz.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_008', 'zenlish_practice', 'I think this coat ____________ to my father.', 'belongs', 'is belonging', 'is belong', 'belong', 'A', 'Giải thích: Câu này sử dụng thì hiện tại đơn (present simple) vì "belong" là một động từ trạng thái (stative verb), không dùng ở thì tiếp diễn. "Belongs" phù hợp với chủ ngữ "this coat" (ngôi thứ ba số ít) và diễn tả rằng chiếc áo khoác này thuộc về bố của tôi.\n(B) is belonging (v.): "is belonging" không đúng ngữ pháp vì "belong" là động từ trạng thái, không dùng ở thì hiện tại tiếp diễn.\n(C) is belong (v.): "is belong" không đúng ngữ pháp, cần dùng "belongs" ở hiện tại đơn.\n(D) belong (v.): "belong" là động từ nguyên mẫu, không phù hợp với chủ ngữ ngôi thứ ba số ít "this coat."', 'Tôi nghĩ rằng chiếc áo khoác này thuộc về bố tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_009', 'zenlish_practice', 'She ___________ to the new boy in her class at the moment.', 'speaks', 'is speaking', 'has spoken', 'spoke', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Is speaking" phù hợp với chủ ngữ "she" và diễn tả việc cô ấy đang nói chuyện với cậu bé mới trong lớp ngay bây giờ.\n(A) speaks (v.): "speaks" là thì hiện tại đơn, không phù hợp với ngữ cảnh của hành động đang diễn ra ngay bây giờ.\n(C) has spoken (v.): "has spoken" là thì hiện tại hoàn thành, không phù hợp vì câu này đang nói về một hành động đang diễn ra.\n(D) spoke (v.): "spoke" là thì quá khứ đơn, không phù hợp vì câu này đang nói về hiện tại.', 'Cô ấy đang nói chuyện với cậu bé mới trong lớp vào lúc này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0014_q_010', 'zenlish_practice', 'She ___________ to the new boy in her class at the moment.', 'speaks', 'is speaking', 'has spoken', 'spoke', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Is speaking" phù hợp với chủ ngữ "she" và diễn tả việc cô ấy đang nói chuyện với cậu bé mới trong lớp ngay bây giờ.\n(A) speaks (v.): "speaks" là thì hiện tại đơn, không phù hợp với ngữ cảnh của hành động đang diễn ra ngay bây giờ.\n(C) has spoken (v.): "has spoken" là thì hiện tại hoàn thành, không phù hợp vì câu này đang nói về một hành động đang diễn ra.\n(D) spoke (v.): "spoke" là thì quá khứ đơn, không phù hợp vì câu này đang nói về hiện tại.', 'Cô ấy đang nói chuyện với cậu bé mới trong lớp vào lúc này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_001', 'zenlish_practice', 'Look! They ________________ towards us.', 'were coming', 'are coming', 'came', 'will come', 'B', 'Giải thích: Câu này sử dụng thì hiện tại tiếp diễn (present continuous) để diễn tả một hành động đang diễn ra ngay tại thời điểm hiện tại. "Are coming" phù hợp với chủ ngữ "they" và diễn tả việc họ đang tiến về phía chúng ta ngay bây giờ.\n(A) were coming (v.): "were coming" là thì quá khứ tiếp diễn, không phù hợp vì câu này đang nói về hiện tại.\n(C) came (v.): "came" là thì quá khứ đơn, không phù hợp vì câu này đang nói về hiện tại.\n(D) will come (v.): "will come" là thì tương lai đơn, không phù hợp vì câu này đang nói về hành động đang diễn ra.', 'Nhìn kìa! Họ đang tiến về phía chúng ta.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_002', 'zenlish_practice', 'What are you __________ for hours?', 'write', 'wrote', 'writing', 'written', 'C', 'Giải thích: Trong câu này, cấu trúc "What are you" yêu cầu một động từ ở dạng hiện tại tiếp diễn để diễn tả một hành động đang diễn ra tại thời điểm nói. "Writing" là động từ dạng V-ing phù hợp với cấu trúc "to be + V-ing," diễn tả hành động "đang viết" trong một khoảng thời gian.\n(A) write (v.): "write" là động từ nguyên thể, không phù hợp với cấu trúc "are you" vì thiếu dạng V-ing.\n(B) wrote (v.): "wrote" là động từ quá khứ đơn, không phù hợp vì câu cần một động từ ở thì hiện tại tiếp diễn.\n(D) written (v. pp): "written" là động từ phân từ hai (past participle), không phù hợp vì đây là dạng dùng trong thì hoàn thành hoặc bị động.', 'Bạn đang viết gì trong nhiều giờ liền?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_003', 'zenlish_practice', 'My sister ____________ English now.', 'was reading', 'reads', 'is reading', 'read', 'C', 'Giải thích: Trong câu này, "now" là dấu hiệu cho thấy hành động đang diễn ra tại thời điểm nói, vì vậy cần sử dụng thì hiện tại tiếp diễn. "Is reading" là động từ ở dạng V-ing sau động từ "to be," phù hợp với cấu trúc thì hiện tại tiếp diễn.\n(A) was reading (v. past continuous): "was reading" là thì quá khứ tiếp diễn, diễn tả một hành động đang xảy ra tại một thời điểm trong quá khứ, không phù hợp vì câu này đang nói về hiện tại.\n(B) reads (v. present simple): "reads" là thì hiện tại đơn, không phù hợp vì câu này cần diễn tả hành động đang diễn ra ngay bây giờ.\n(D) read (v. past simple): "read" là thì quá khứ đơn, không phù hợp vì không mô tả được hành động đang diễn ra tại thời điểm hiện tại.', 'Em gái tôi đang đọc tiếng Anh bây giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_004', 'zenlish_practice', 'I _________ you ____________ this great weather as I am.', 'am hoping / are enjoying', 'hope / are enjoying', 'hope / enjoy', 'am hoping / enjoy', 'B', 'Giải thích: Câu này cần một động từ diễn tả hy vọng (hope) và một động từ diễn tả hành động đang diễn ra ở hiện tại (enjoy). Các động từ chỉ hi vọng (Hope, wish, want, desire) thường chia ở thì hiện tại đơn, diễn tả mong muốn chung. "Are enjoying" là động từ ở thì hiện tại tiếp diễn, diễn tả hành động "đang tận hưởng" ở thời điểm hiện tại.\n(A) am hoping / are enjoying (v. present continuous / v. present continuous): "am hoping" là thì hiện tại tiếp diễn, không cần thiết trong ngữ cảnh này vì hành động hy vọng không nhất thiết phải diễn tả đang diễn ra.\n(C) hope / enjoy (v. present simple / v. present simple): "enjoy" là thì hiện tại đơn, không phù hợp vì ngữ cảnh yêu cầu diễn tả hành động đang diễn ra (hiện tại tiếp diễn).\n(D) am hoping / enjoy (v. present continuous / v. present simple): "am hoping" là hiện tại tiếp diễn, không phù hợp vì "hope" thường được dùng ở hiện tại đơn. "Enjoy" là thì hiện tại đơn, không phù hợp vì ngữ cảnh yêu cầu hiện tại tiếp diễn.', 'Tôi hy vọng bạn đang tận hưởng thời tiết tuyệt vời này giống như tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_005', 'zenlish_practice', 'Martin _________ in front of the window at the moment.', 'stands', 'is standing', 'is stand', 'are standing', 'B', 'Giải thích: Câu này yêu cầu sử dụng thì hiện tại tiếp diễn để diễn tả hành động đang xảy ra tại thời điểm nói. "Is standing" là động từ ở dạng V-ing sau động từ "to be," diễn tả hành động "đang đứng" ở thời điểm hiện tại.\n(A) stands (v. present simple): "stands" là thì hiện tại đơn, không phù hợp vì câu này yêu cầu diễn tả hành động đang diễn ra ngay bây giờ.\n(C) is stand (v. incorrect form): "is stand" không đúng ngữ pháp vì sau "is" cần động từ dạng V-ing (standing).\n(D) are standing (v. incorrect subject-verb agreement): "are standing" không phù hợp vì "Martin" là chủ ngữ số ít, cần sử dụng "is" thay vì "are."', 'Martin đang đứng trước cửa sổ vào lúc này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_006', 'zenlish_practice', 'The population of China _________ more and more.', 'is increasing', 'increase', 'increases', 'are increasing', 'A', 'Giải thích: Chủ ngữ của câu là "The population of China" (dân số Trung Quốc), một cụm danh từ số ít. Trong câu này, chúng ta cần một động từ để diễn tả hành động đang diễn ra, do đó "is increasing" (đang tăng) là thì hiện tại tiếp diễn, phù hợp với ngữ pháp và ngữ cảnh để mô tả một quá trình thay đổi dần dần theo thời gian.\n(B) increase (v): "increase" là động từ nguyên thể, không có dạng chia ngôi thứ ba số ít. Lý do không chọn vì không phù hợp với chủ ngữ số ít và yêu cầu thì hiện tại tiếp diễn.\n(C) increases (v): "increases" là động từ ngôi thứ ba số ít ở thì hiện tại đơn, nhưng không phù hợp với ngữ cảnh diễn tả một quá trình đang diễn ra.\n(D) are increasing (v): "are increasing" là thì hiện tại tiếp diễn nhưng chỉ dùng cho chủ ngữ số nhiều. Lý do không chọn vì "The population" là danh từ số ít, nên cần dùng "is" thay vì "are".', 'Dân số Trung Quốc đang tăng lên ngày càng nhiều.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_007', 'zenlish_practice', 'My brother often goes to school by bus, but today he _________ to school by bike.', 'goes', 'is going', 'go', 'are going', 'B', 'Giải thích: Trong câu này, "today" (hôm nay) là một dấu hiệu để sử dụng thì hiện tại tiếp diễn nhằm diễn tả một hành động đang xảy ra tại thời điểm hiện tại. Chủ ngữ "he" (anh ấy) là ngôi thứ ba số ít, do đó "is going" là dạng đúng để diễn tả rằng hôm nay anh ấy đi xe đạp đến trường, một điều khác với thói quen thường ngày của anh ấy.\n(A) goes (v): "goes" là động từ ngôi thứ ba số ít ở thì hiện tại đơn, thường dùng để diễn tả thói quen hoặc hành động lặp đi lặp lại. Lý do không chọn là vì câu này cần diễn tả hành động đang diễn ra ngay lúc nói.\n(C) go (v): "go" là động từ nguyên thể, không được chia theo chủ ngữ. Lý do không chọn là vì nó không phù hợp với chủ ngữ ngôi thứ ba số ít và thì hiện tại tiếp diễn.\n(D) are going (v): "are going" là thì hiện tại tiếp diễn nhưng dùng cho chủ ngữ số nhiều. Lý do không chọn là vì chủ ngữ "he" là ngôi thứ ba số ít nên cần dùng "is" thay vì "are".', 'Anh trai tôi thường đi học bằng xe buýt, nhưng hôm nay anh ấy đang đi học bằng xe đạp.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_008', 'zenlish_practice', 'They _________ with us at the moment.', 'are staying', 'staying', 'stay', 'is staying', 'A', 'Giải thích: Cụm từ "at the moment" (hiện tại) là dấu hiệu cho thì hiện tại tiếp diễn, diễn tả một hành động đang diễn ra ở thời điểm hiện tại. Chủ ngữ "They" là ngôi thứ ba số nhiều, do đó cần động từ "are" kết hợp với động từ chính "staying" để diễn tả hành động "đang ở lại" cùng với chúng tôi.\n(B) staying (v-ing): "staying" là dạng động từ V-ing nhưng thiếu động từ to be để hoàn thành cấu trúc thì hiện tại tiếp diễn. Lý do không chọn là vì không có "are" đi kèm.\n(C) stay (v): "stay" là động từ nguyên thể, dùng ở thì hiện tại đơn. Lý do không chọn vì câu này cần thì hiện tại tiếp diễn để diễn tả hành động đang xảy ra vào lúc nói.\n(D) is staying (v): "is staying" là thì hiện tại tiếp diễn nhưng dành cho chủ ngữ số ít. Lý do không chọn là vì "They" là ngôi thứ ba số nhiều, cần dùng "are" thay vì "is."', 'Họ đang ở lại với chúng tôi vào lúc này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_009', 'zenlish_practice', 'I _________ for a bicycle, but I can’t find anything good.', 'am looking', 'look', 'looks', 'is looking', 'A', 'Giải thích: Trong câu này, hành động "tìm kiếm" đang diễn ra ngay lúc nói và có từ "but" nối với một tình huống hiện tại. Vì vậy, ta cần dùng thì hiện tại tiếp diễn để diễn tả hành động đang diễn ra. Chủ ngữ "I" cần kết hợp với "am" trong thì hiện tại tiếp diễn, nên "am looking" là đáp án đúng.\n(B) look (v): "look" là động từ nguyên thể, dùng ở thì hiện tại đơn, thường chỉ thói quen hoặc sự thật hiển nhiên. Lý do không chọn vì câu này mô tả hành động đang diễn ra.\n(C) looks (v): "looks" là động từ ngôi thứ ba số ít, không phù hợp với chủ ngữ "I," nên không thể chọn.\n(D) is looking (v): "is looking" là thì hiện tại tiếp diễn nhưng chỉ dùng cho chủ ngữ ngôi thứ ba số ít, không phù hợp với chủ ngữ "I" (ngôi thứ nhất số ít).', 'Tôi đang tìm mua một chiếc xe đạp, nhưng tôi không thể tìm được cái nào tốt cả.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0015_q_010', 'zenlish_practice', 'We (play) _________ Monopoly at the moment.', 'play', 'are playing', 'plays', 'is playing', 'B', 'Giải thích: Cụm từ "at the moment" (ngay lúc này) là dấu hiệu để dùng thì hiện tại tiếp diễn, diễn tả một hành động đang diễn ra. Chủ ngữ "We" là ngôi thứ nhất số nhiều, vì vậy "are" kết hợp với "playing" (dạng V-ing) là cấu trúc đúng để diễn tả rằng chúng ta đang chơi Monopoly ngay lúc này.\n(A) play (v): "play" là động từ nguyên thể, dùng ở thì hiện tại đơn để diễn tả thói quen hoặc sự thật hiển nhiên. Lý do không chọn là vì câu cần diễn tả một hành động đang diễn ra vào thời điểm hiện tại.\n(C) plays (v): "plays" là động từ ngôi thứ ba số ít ở thì hiện tại đơn, không phù hợp với chủ ngữ "We," một chủ ngữ số nhiều.\n(D) is playing (v): "is playing" là thì hiện tại tiếp diễn nhưng chỉ dùng cho chủ ngữ số ít, không phù hợp với "We," là chủ ngữ số nhiều.', 'Chúng tôi đang chơi Cờ tỷ phú ngay lúc này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_001', 'zenlish_practice', 'I ____ a letter saying that we haven’t paid this quarter’s electricity bill yet.', 'had just been received', 'received', 'has just received', 'have just received', 'D', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động vừa mới xảy ra gần đây, và có ảnh hưởng đến hiện tại. "Have just received" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít).\n(A) had just been received (v. past perfect passive): "Had just been received" là thì quá khứ hoàn thành bị động, không phù hợp vì câu này cần một dạng chủ động và hiện tại hoàn thành.\n(B) received (v. past simple): "Received" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả hành động vừa mới xảy ra.\n(C) has just received (v. present perfect, incorrect subject-verb agreement): "Has just received" là dạng hiện tại hoàn thành nhưng chỉ dùng với chủ ngữ số ít ngôi thứ ba, không phù hợp vì chủ ngữ là "I" (ngôi thứ nhất số ít).', 'Tôi vừa nhận được một bức thư nói rằng chúng tôi chưa thanh toán hóa đơn điện của quý này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_002', 'zenlish_practice', 'Jane ____ one dress already, and now she is making another.', 'has made', 'made', 'had made', 'have made', 'A', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để mô tả một hành động đã hoàn tất và có liên quan đến hiện tại. "Has made" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "Jane" (ngôi thứ ba số ít)\n(B) made (v. past simple): "Made" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để thể hiện sự hoàn tất của hành động và liên hệ với hiện tại.\n(C) had made (v. past perfect): "Had made" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả một hành động đã xảy ra trước hiện tại.\n(D) have made (v. present perfect, incorrect subject-verb agreement): "Have made" là dạng hiện tại hoàn thành nhưng chỉ dùng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì chủ ngữ là "Jane" (ngôi thứ ba số ít).', 'Jane đã làm xong một chiếc váy rồi, và bây giờ cô ấy đang làm một cái khác.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_003', 'zenlish_practice', 'No one knows how many documents ____ been lost.', 'has', 'had', 'has had', 'have', 'D', 'Giải thích: Câu này cần một động từ phù hợp với chủ ngữ "documents" (danh từ số nhiều). "Have" là dạng hiện tại đơn của động từ, phù hợp với chủ ngữ số nhiều và là phần của thì hiện tại hoàn thành. Câu này diễn tả việc mất tài liệu không xác định trong quá khứ và ảnh hưởng đến hiện tại\n(A) has (v. present simple, incorrect subject-verb agreement): "Has" là dạng hiện tại đơn nhưng chỉ dùng với chủ ngữ số ít, không phù hợp với chủ ngữ số nhiều "documents."\n(B) had (v. past simple): "Had" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để nói về tình trạng kéo dài từ quá khứ đến hiện tại.\n(C) has had (v. present perfect, incorrect subject-verb agreement): "Has had" là dạng hiện tại hoàn thành nhưng chỉ dùng với chủ ngữ số ít, không phù hợp với chủ ngữ số nhiều "documents."', 'Không ai biết có bao nhiêu tài liệu đã bị mất.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_004', 'zenlish_practice', 'The exhibition has ____ interest in her work.', 'stimulate', 'stimulating', 'stimulated', 'stimulation', 'C', 'Giải thích: Câu này cần một động từ đã hoàn thành để mô tả kết quả của một hành động trong thì hiện tại hoàn thành. "Stimulated" là dạng quá khứ của động từ "stimulate," phù hợp với ngữ cảnh vì nó mô tả hành động đã tạo ra sự quan tâm đến công việc của cô ấy.\n(A) stimulate (v. base form): "Stimulate" là dạng cơ bản của động từ, không phù hợp vì câu này cần một dạng đã hoàn thành để phù hợp với thì hiện tại hoàn thành.\n(B) stimulating (v. present participle/gerund): "Stimulating" là dạng hiện tại phân từ hoặc danh động từ, không phù hợp vì câu này cần một động từ ở dạng quá khứ để phù hợp với ngữ pháp của câu.\n(D) stimulation (n.): "Stimulation" là danh từ có nghĩa là "sự kích thích," không phù hợp vì câu này cần một động từ để diễn tả hành động đã xảy ra.', 'Triển lãm đã tạo ra sự quan tâm đối với công việc của cô ấy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_005', 'zenlish_practice', 'I went there once a long time ago and ____ back since.', 'am not', 'was', 'had not been', 'have not been', 'D', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động chưa xảy ra từ một thời điểm cụ thể trong quá khứ (lần cuối cùng đến đó) đến hiện tại. "Have not been" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít).\n(A) am not (v. present simple, incorrect verb form): "Am not" là thì hiện tại đơn và không phù hợp với ngữ cảnh vì câu này cần thì hiện tại hoàn thành để diễn tả sự liên tục từ quá khứ đến hiện tại.\n(B) was (v. past simple): "Was" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả trạng thái từ quá khứ đến hiện tại.\n(C) had not been (v. past perfect): "Had not been" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả trạng thái từ một thời điểm trong quá khứ đến hiện tại.', 'Tôi đã đến đó một lần cách đây rất lâu và chưa trở lại kể từ đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_006', 'zenlish_practice', 'Since I moved to the town, I ____ home.', 'have not returned', 'will not returned', 'was not returning', 'am not returning', 'A', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động chưa xảy ra từ khi người nói chuyển đến thành phố, và trạng thái này kéo dài đến hiện tại. "Have not returned" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít).\n(B) will not returned (v. future simple, incorrect verb form): "Will not returned" là thì tương lai đơn nhưng không đúng ngữ pháp vì động từ cần phải ở dạng cơ bản là "return," và không phù hợp vì câu này cần thì hiện tại hoàn thành.\n(C) was not returning (v. past continuous, incorrect tense): "Was not returning" là thì quá khứ tiếp diễn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả trạng thái kéo dài từ quá khứ đến hiện tại.\n(D) am not returning (v. present continuous, incorrect tense): "Am not returning" là thì hiện tại tiếp diễn, không phù hợp vì câu này cần thì hiện tại hoàn thành để mô tả một trạng thái từ quá khứ đến hiện tại.', 'Kể từ khi tôi chuyển đến thành phố, tôi chưa trở về nhà.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_007', 'zenlish_practice', 'My aunt ____ out of the house since she bought a new color TV.', 'hasn’t been', 'haven’t been', 'hadn’t been', 'wasn’t', 'A', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một trạng thái bắt đầu trong quá khứ (kể từ khi mua TV) và tiếp tục đến hiện tại. "Hasn''t been" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "My aunt" (ngôi thứ ba số ít).\n(B) haven’t been (v. present perfect, incorrect subject-verb agreement): "Haven’t been" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì chủ ngữ là "My aunt" (ngôi thứ ba số ít).\n(C) hadn’t been (v. past perfect): "Hadn’t been" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả trạng thái kéo dài từ quá khứ đến hiện tại.\n(D) wasn’t (v. past simple): "Wasn’t" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để mô tả tình trạng từ quá khứ đến hiện tại.', 'Dì của tôi đã không ra khỏi nhà kể từ khi bà mua một chiếc TV màu mới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_008', 'zenlish_practice', 'This is the best performance of Hamlet that I ____in years.', 'had seen', 'saw', 'have seen', 'see', 'C', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để so sánh và diễn tả sự trải nghiệm của người nói về một sự kiện (buổi biểu diễn của Hamlet) trong một khoảng thời gian kéo dài đến hiện tại. "Have seen" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít).\n(A) had seen (v. past perfect): "Had seen" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả một trải nghiệm trong một khoảng thời gian kéo dài đến hiện tại.\n(B) saw (v. past simple): "Saw" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả trải nghiệm có liên quan đến hiện tại.\n(D) see (v. present simple): "See" là thì hiện tại đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để mô tả một trải nghiệm kéo dài từ quá khứ đến hiện tại.', 'Đây là buổi biểu diễn Hamlet hay nhất mà tôi đã xem trong nhiều năm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_009', 'zenlish_practice', 'He lost his job last month and since then he ____ out of work.', 'has been', 'had been', 'was', 'have been', 'A', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một trạng thái đã bắt đầu trong quá khứ (kể từ tháng trước) và tiếp tục đến hiện tại. "Has been" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "He" (ngôi thứ ba số ít).\n(B) had been (v. past perfect): "Had been" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả trạng thái từ quá khứ đến hiện tại.\n(C) was (v. past simple): "Was" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để mô tả tình trạng kéo dài từ quá khứ đến hiện tại.\n(D) have been (v. present perfect, incorrect subject-verb agreement): "Have been" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì chủ ngữ là "He" (ngôi thứ ba số ít).', 'Anh ấy đã mất việc vào tháng trước và từ đó đến nay anh ấy không có việc làm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0016_q_010', 'zenlish_practice', 'He ____ to New York three times this year.', 'had been', 'was', 'is', 'has been', 'D', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động đã xảy ra nhiều lần trong năm hiện tại và có ảnh hưởng đến hiện tại. "Has been" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "He" (ngôi thứ ba số ít).\n(A) had been (v. past perfect): "Had been" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để nói về hành động trong năm hiện tại.\n(B) was (v. past simple): "Was" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả sự lặp lại trong năm hiện tại.\n(C) is (v. present simple): "Is" là thì hiện tại đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để nói về các lần đến New York trong năm hiện tại.', 'Anh ấy đã đến New York ba lần trong năm nay.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_001', 'zenlish_practice', 'For the last fifteen years, Tatella, Inc. has _____ consistently among the nation’s ten leading toy manufacturers.', 'rank', 'ranked', 'ranking', 'ranks', 'B', 'Giải thích: "Ranked" là động từ ở thì quá khứ hoàn thành (present perfect), được sử dụng phù hợp với ngữ cảnh của câu khi nói về hành động đã diễn ra liên tục trong mười lăm năm qua. Tatella, Inc. đã xếp hạng ổn định trong số mười nhà sản xuất đồ chơi hàng đầu của quốc gia.\n(A) rank (v. present): "rank" là động từ ở thì hiện tại, không phù hợp với ngữ pháp của câu khi cần động từ ở thì quá khứ hoàn thành.\n(C) ranking (v. present participle/gerund): "ranking" là hiện tại phân từ hoặc danh động từ, không phù hợp với cấu trúc của câu.\n(D) ranks (v. present): "ranks" là động từ ở ngôi thứ ba số ít thì hiện tại, không phù hợp với ngữ pháp của câu.', 'Trong mười lăm năm qua, Tatella, Inc. đã liên tục xếp hạng trong số mười nhà sản xuất đồ chơi hàng đầu của quốc gia.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_002', 'zenlish_practice', 'Polansky Data International _____ transportation for all employees attending the digital media conference in Liverpool next week.', 'has arranged', 'was arranged', 'arranging', 'arrangements', 'A', 'Giải thích: "Has arranged" là động từ ở thì hiện tại hoàn thành, phù hợp với ngữ cảnh của câu khi nói về một hành động đã được hoàn tất trong quá khứ nhưng có liên quan đến thời điểm hiện tại. Câu này nói rằng Polansky Data International đã sắp xếp phương tiện đi lại cho tất cả các nhân viên tham dự hội nghị truyền thông kỹ thuật số ở Liverpool vào tuần tới.\n(B) was arranged (past passive): "was arranged" là động từ ở thì quá khứ bị động, không phù hợp với ngữ cảnh của câu khi cần chủ động.\n(C) arranging (present participle): "arranging" là hiện tại phân từ, không phù hợp với ngữ pháp của câu khi cần một động từ chính.\n(D) arrangements (n.): "arrangements" là danh từ, không phù hợp với ngữ pháp của câu khi cần một động từ.', 'Polansky Data International đã sắp xếp phương tiện đi lại cho tất cả các nhân viên tham dự hội nghị truyền thông kỹ thuật số ở Liverpool vào tuần tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_003', 'zenlish_practice', 'The Salisbury Nature Club''s treasurer _____ and suggested revisions to the budget for the next financial quarter.', 'is examining', 'has examined', 'will examine', 'to examine', 'B', 'Giải thích: "Has examined" là động từ ở thì hiện tại hoàn thành, phù hợp với ngữ cảnh của câu khi nói về một hành động đã xảy ra gần đây và có liên quan đến thời điểm hiện tại. Câu này nói rằng thủ quỹ của Câu lạc bộ Thiên nhiên Salisbury đã kiểm tra và đề xuất những sửa đổi đối với ngân sách cho quý tài chính tiếp theo.\n(A) is examining (present continuous): "is examining" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh khi hành động đã hoàn thành.\n(C) will examine (future simple): "will examine" là thì tương lai đơn, không phù hợp với ngữ cảnh khi hành động đã xảy ra.\n(D) to examine (infinitive): "to examine" là động từ nguyên mẫu, không phù hợp với ngữ pháp của câu.', 'Thủ quỹ của Câu lạc bộ Thiên nhiên Salisbury đã kiểm tra và đề xuất những sửa đổi đối với ngân sách cho quý tài chính tiếp theo.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_004', 'zenlish_practice', 'The falling price of Chinese - made electronics last year _____ a number of companies to plan innovations to their products.', 'causing', 'causes', 'has caused', 'is caused', 'C', 'Giải thích: Trong câu này, cần một thì hiện tại hoàn thành để mô tả kết quả của sự việc trong quá khứ (giá điện tử của Trung Quốc giảm) vẫn còn ảnh hưởng đến hiện tại. "Has caused" là thì hiện tại hoàn thành phù hợp, nghĩa là "đã gây ra," để chỉ rằng sự giảm giá đã dẫn đến việc nhiều công ty lập kế hoạch đổi mới sản phẩm của họ.\n(A) causing (present participle): "Causing" có nghĩa là "gây ra." Lý do không chọn là vì dạng hiện tại phân từ không phù hợp khi cần một động từ để mô tả kết quả của sự việc.\n(B) causes (present simple): "Causes" có nghĩa là "gây ra" ở thì hiện tại đơn. Lý do không chọn là vì thì hiện tại đơn không phản ánh sự việc đã xảy ra trong quá khứ nhưng vẫn có ảnh hưởng đến hiện tại.\n(D) is caused (present passive): "Is caused" có nghĩa là "được gây ra" ở thì hiện tại bị động. Lý do không chọn là vì cấu trúc bị động không phù hợp trong ngữ cảnh khi cần một động từ ở thì hiện tại hoàn thành để mô tả kết quả liên tục.', 'Giá giảm của các thiết bị điện tử sản xuất tại Trung Quốc năm ngoái đã khiến một số công ty lập kế hoạch đổi mới sản phẩm của họ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_005', 'zenlish_practice', 'Soaring fuel prices have _____ to manufacturers seeking raw materials from less remote suppliers.', 'contributed', 'contributions', 'contribute', 'contributor', 'A', 'Giải thích: Trong câu này, cần một động từ quá khứ phân từ để mô tả tác động của việc giá nhiên liệu tăng cao đến các nhà sản xuất. "Contributed" là dạng quá khứ phân từ phù hợp, nghĩa là "đã góp phần," để chỉ rằng việc giá nhiên liệu tăng cao đã góp phần vào việc các nhà sản xuất tìm kiếm nguyên liệu từ các nhà cung cấp ít xa hơn.\n(B) contributions (noun): "Contributions" có nghĩa là "các đóng góp." Lý do không chọn là vì danh từ không phù hợp khi cần một động từ để mô tả hành động.\n(C) contribute (verb, base form): "Contribute" có nghĩa là "góp phần." Lý do không chọn là vì động từ cơ bản không phù hợp khi cần một dạng quá khứ phân từ để mô tả tác động đã xảy ra.\n(D) contributor (noun): "Contributor" có nghĩa là "người đóng góp" hoặc "người góp phần." Lý do không chọn là vì danh từ không phù hợp khi cần một động từ để mô tả tác động.', 'Việc giá nhiên liệu tăng vọt đã góp phần khiến các nhà sản xuất tìm kiếm nguyên liệu từ các nhà cung cấp ít xa hơn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_006', 'zenlish_practice', 'The technician _____ repairs on the machinery, so production of the X220 will resume when she has finished.', 'making', 'had made', 'will have been made', 'has been making', 'D', 'Giải thích: Trong câu này, cần một động từ ở thì hiện tại hoàn thành tiếp diễn để mô tả hành động của kỹ thuật viên đang liên tục thực hiện sửa chữa trên máy móc và hành động này vẫn đang tiếp tục cho đến khi hoàn tất. "Has been making" là thì hiện tại hoàn thành tiếp diễn phù hợp, nghĩa là "đã đang thực hiện," để chỉ rằng kỹ thuật viên đã và đang thực hiện các sửa chữa và sản xuất X220 sẽ tiếp tục khi công việc sửa chữa hoàn tất.\n(A) making (present participle): "Making" có nghĩa là "đang thực hiện." Lý do không chọn là vì dạng hiện tại phân từ không phản ánh sự liên tục của hành động trong quá khứ và hiện tại như thì hiện tại hoàn thành tiếp diễn.\n(B) had made (past perfect): "Had made" có nghĩa là "đã thực hiện." Lý do không chọn là vì thì quá khứ hoàn thành không phù hợp khi mô tả hành động vẫn đang tiếp tục.\n(C) will have been made (future perfect passive): "Will have been made" có nghĩa là "sẽ đã được thực hiện" (bị động). Lý do không chọn là vì cấu trúc bị động và thì tương lai hoàn thành không phù hợp khi mô tả hành động hiện tại đang diễn ra.', 'Kỹ thuật viên đã đang thực hiện các sửa chữa trên máy móc, vì vậy sản xuất X220 sẽ tiếp tục khi cô ấy hoàn tất.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_007', 'zenlish_practice', 'This is the best performance of Hamlet that I ____in years.', 'had seen', 'saw', 'have seen', 'see', 'C', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để so sánh và diễn tả sự trải nghiệm của người nói về một sự kiện (buổi biểu diễn của Hamlet) trong một khoảng thời gian kéo dài đến hiện tại. "Have seen" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít).\n(A) had seen (v. past perfect): "Had seen" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả một trải nghiệm trong một khoảng thời gian kéo dài đến hiện tại.\n(B) saw (v. past simple): "Saw" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả trải nghiệm có liên quan đến hiện tại.\n(D) see (v. present simple): "See" là thì hiện tại đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để mô tả một trải nghiệm kéo dài từ quá khứ đến hiện tại.', 'Đây là buổi biểu diễn Hamlet hay nhất mà tôi đã xem trong nhiều năm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_008', 'zenlish_practice', 'Northeast Community Finance ______ an online system in order to shorten service lines at branch locations.', 'has implemented', 'to be implementing', 'to have been implementing', 'is implemented', 'A', 'Giải thích: Trong câu này, cần một thì hiện tại hoàn thành để chỉ hành động đã được thực hiện trong quá khứ và có ảnh hưởng đến hiện tại. "Has implemented" là thì hiện tại hoàn thành của động từ "implement," nghĩa là "đã triển khai," phù hợp với ngữ cảnh khi nói về việc áp dụng hệ thống trực tuyến để cải thiện dịch vụ.\n(B) to be implementing (đang triển khai): "to be implementing" không phù hợp vì đây là dạng đang thực hiện, không phải thì hiện tại hoàn thành cần cho câu.\n(C) to have been implementing (đã và đang triển khai): "to have been implementing" là dạng hiện tại hoàn thành tiếp diễn, không phù hợp vì cần một thì hiện tại hoàn thành đơn giản để nói về hành động đã được thực hiện.\n(D) is implemented (được triển khai): "is implemented" là thì hiện tại đơn bị động, không phù hợp vì câu cần diễn đạt hành động đã hoàn thành.', 'Northeast Community Finance đã triển khai một hệ thống trực tuyến nhằm rút ngắn thời gian chờ dịch vụ tại các chi nhánh.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_009', 'zenlish_practice', 'Over the past ten years, Bellworth Medical Clinic ______ Atlan Protection officers for all security needs.', 'is hiring', 'were hiring', 'has hired', 'was hired', 'C', 'Giải thích: Trong câu này, ta cần dùng thì hiện tại hoàn thành vì câu bắt đầu với "Over the past ten years" (Trong suốt mười năm qua), diễn tả một hành động đã bắt đầu trong quá khứ và tiếp tục đến hiện tại. "Has hired" là thì hiện tại hoàn thành, phù hợp với ngữ cảnh của câu để chỉ việc thuê nhân viên bảo vệ đã diễn ra và vẫn còn hiệu lực.\n(A) is hiring (present continuous): "is hiring" là thì hiện tại tiếp diễn, không phù hợp vì câu này không diễn tả hành động đang xảy ra ngay bây giờ.\n(B) were hiring (past continuous): "were hiring" là thì quá khứ tiếp diễn, không phù hợp vì không có dấu hiệu chỉ một hành động đang diễn ra trong quá khứ.\n(D) was hired (past simple passive): "was hired" là thì quá khứ đơn ở dạng bị động, không phù hợp vì câu yêu cầu dạng chủ động với nghĩa "thuê" thay vì "được thuê."', 'Trong suốt mười năm qua, Phòng khám Bellworth đã thuê các sĩ quan của Atlan Protection cho tất cả các nhu cầu bảo vệ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0017_q_010', 'zenlish_practice', 'The magazine''s readership ______ almost 20 percent in three months.', 'rise', 'rising', 'to rise', 'has risen', 'D', 'Giải thích: "Has risen" là thì hiện tại hoàn thành, phù hợp với ngữ cảnh diễn tả việc lượng độc giả của tạp chí đã tăng gần 20% trong ba tháng.\n(A) rise (v.): "Rise" là động từ nguyên mẫu, không phù hợp với ngữ pháp và thì của câu này.\n(B) rising (v./adj.): "Rising" là hiện tại phân từ hoặc tính từ, không phù hợp với ngữ pháp của câu này.\n(C) to rise (infinitive): "To rise" là động từ nguyên mẫu có "to," không phù hợp với cấu trúc và thì của câu này.', 'Lượng độc giả của tạp chí đã tăng gần 20% trong ba tháng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_001', 'zenlish_practice', 'In the last hundred years, traveling ____ much easier and more comfortable.', 'has become', 'have becomes', 'became', 'will become', 'A', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả sự thay đổi đã bắt đầu trong quá khứ và tiếp tục có ảnh hưởng đến hiện tại. "Has become" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "traveling" (danh từ số ít) .\n(B) have becomes (v. present perfect, incorrect subject-verb agreement): "Have becomes" là dạng hiện tại hoàn thành nhưng không đúng ngữ pháp vì động từ cần phải ở dạng phân từ hai là "become" và "have" chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít.\n(C) became (v. past simple): "Became" là thì quá khứ đơn, không phù hợp vì câu này cần diễn tả sự thay đổi liên tục từ quá khứ đến hiện tại.\n(D) will become (v. future simple): "Will become" là thì tương lai đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả sự thay đổi từ quá khứ đến hiện tại.', 'Trong suốt một trăm năm qua, việc đi lại đã trở nên dễ dàng và thoải mái hơn nhiều.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_002', 'zenlish_practice', '20. Mr. McGregor ________ machines for Ernst Welding for more than two decades.', 'is repairing', 'has been repairing', 'was repaired', 'had been repaired', 'B', 'Giải thích: for more than two decades (hơn hai thập kỷ) → diễn tả một hành động bắt đầu trong quá khứ và kéo dài đến hiện tại. Sử dụng thì hiện tại hoàn thành tiếp diễn (has been + V-ing) nhấn mạnh tính liên tục của công việc. A. is repairing: hiện tại tiếp diễn → không diễn tả khoảng thời gian dài trong quá khứ C. was repaired: bị động, sai nghĩa D. had been repaired: quá khứ hoàn thành bị động, không đúng ngữ cảnh', 'Ông McGregor đã sửa chữa máy móc cho công ty Ernst Welding hơn hai thập kỷ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_003', 'zenlish_practice', 'When I left school I cut my hair and ____ it short ever since.', 'wear', 'have worn', 'has worn', 'had worn', 'B', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động đã bắt đầu trong quá khứ và vẫn tiếp tục đến hiện tại. "Have worn" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít).\n(A) wear (v. present simple): "Wear" là thì hiện tại đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả trạng thái kéo dài từ quá khứ đến hiện tại.\n(C) has worn (v. present perfect, incorrect subject-verb agreement): "Has worn" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số ít ngôi thứ ba, không phù hợp vì chủ ngữ là "I."\n(D) had worn (v. past perfect): "Had worn" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả một trạng thái liên tục từ quá khứ đến hiện tại.', 'Khi tôi rời trường học, tôi đã cắt tóc và kể từ đó đến giờ tôi đã để tóc ngắn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_004', 'zenlish_practice', 'She ____ me anything about that problem so far.', 'has not telling', 'had not tell', 'has not told', 'will not tell', 'C', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả việc chưa nhận được thông tin về vấn đề đó cho đến thời điểm hiện tại. "Has not told" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "She" (ngôi thứ ba số ít).\n(A) has not telling (v. present perfect continuous, incorrect verb form): "Has not telling" là dạng hiện tại hoàn thành tiếp diễn, không phù hợp vì động từ cần phải ở dạng phân từ hai là "told."\n(B) had not tell (v. past perfect, incorrect verb form): "Had not tell" là thì quá khứ hoàn thành nhưng không đúng ngữ pháp vì động từ cần ở dạng phân từ hai là "told."\n(D) will not tell (v. future simple): "Will not tell" là thì tương lai đơn, không phù hợp với ngữ cảnh vì câu này cần thì hiện tại hoàn thành để diễn tả trạng thái đến hiện tại.', 'Cô ấy chưa nói cho tôi bất kỳ điều gì về vấn đề đó cho đến giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_005', 'zenlish_practice', 'I ____ Tom today but he told Mary that he’d be in for dinner.', 'haven’t seen', 'don’t see', 'hadn’t see', 'hasn’t see', 'A', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả việc chưa gặp Tom cho đến thời điểm hiện tại. "Haven’t seen" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít)\n(B) don’t see (v. present simple): "Don’t see" là thì hiện tại đơn, không phù hợp với ngữ cảnh vì câu này cần diễn tả trạng thái liên tục từ quá khứ đến hiện tại.\n(C) hadn’t see (v. past perfect, incorrect verb form): "Hadn’t see" là thì quá khứ hoàn thành nhưng không đúng ngữ pháp vì động từ "see" cần phải ở dạng phân từ hai (past participle) là "seen."\n(D) hasn’t see (v. present perfect, incorrect subject-verb agreement and verb form): "Hasn’t see" là dạng hiện tại hoàn thành nhưng không đúng vì "hasn’t" chỉ dùng với chủ ngữ số ít ngôi thứ ba và động từ cần ở dạng phân từ hai là "seen."', 'Tôi chưa gặp Tom hôm nay nhưng anh ấy đã nói với Mary rằng anh ấy sẽ về nhà ăn tối.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_006', 'zenlish_practice', 'I''ve been ____ so I must find work soon.', 'unemployed', 'employed', 'employable', 'unemployable', 'A', 'Giải thích: Câu này cần một tính từ để mô tả trạng thái hiện tại của người nói, liên quan đến tình trạng không có việc làm. "Unemployed" có nghĩa là "thất nghiệp," phù hợp với ngữ cảnh của câu.\n(B) employed (adj.): "Employed" có nghĩa là "đang có việc làm," trái ngược với ngữ cảnh của câu vì câu này đang nói về việc không có việc làm.\n(C) employable (adj.): "Employable" có nghĩa là "có thể tuyển dụng," không phù hợp với ngữ cảnh của câu vì câu này cần một trạng thái thất nghiệp, không phải khả năng được tuyển dụng.\n(D) unemployable (adj.): "Unemployable" có nghĩa là "không thể tuyển dụng," không phù hợp với ngữ cảnh vì câu này chỉ nói về tình trạng thất nghiệp, không phải khả năng bị từ chối tuyển dụng.', 'Tôi đã thất nghiệp nên tôi phải tìm việc làm sớm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_007', 'zenlish_practice', 'Unemployment ____ by 4% since January and now stands at just under three million.', 'had raised', 'have raised', 'has risen', 'rose', 'C', 'Giải thích: Câu này yêu cầu thì hiện tại hoàn thành để diễn tả một sự thay đổi đã xảy ra trong quá khứ và có ảnh hưởng đến hiện tại. "Has risen" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "Unemployment" (danh từ số ít).\n(A) had raised (v. past perfect): "Had raised" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả sự thay đổi từ quá khứ đến hiện tại.\n(B) have raised (v. present perfect, incorrect subject-verb agreement): "Have raised" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì chủ ngữ là "Unemployment" (số ít).\n(D) rose (v. past simple): "Rose" là thì quá khứ đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả sự thay đổi từ quá khứ đến hiện tại.', 'Tỷ lệ thất nghiệp đã tăng 4% kể từ tháng Giêng và hiện nay ở mức gần ba triệu.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_008', 'zenlish_practice', 'That is the best book that I ____ on that subject.', 'have read', 'had read', 'read', 'am reading', 'A', 'Giải thích: Câu này yêu cầu thì hiện tại hoàn thành để so sánh và diễn tả sự hoàn tất của hành động đọc sách cho đến hiện tại. "Have read" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít).\n(B) had read (v. past perfect): "Had read" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để nói về hành động đọc đã xảy ra trong quá khứ nhưng có liên quan đến hiện tại.\n(C) read (v. past simple): "Read" là thì quá khứ đơn, không phù hợp vì câu này cần diễn tả ảnh hưởng của việc đọc đến hiện tại.\n(D) am reading (v. present continuous): "Am reading" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu vì câu này cần thì hiện tại hoàn thành để so sánh sự hoàn tất của hành động đọc.', 'Đó là cuốn sách hay nhất mà tôi đã đọc về chủ đề đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_009', 'zenlish_practice', 'There ____ considerable improvements in agriculture since World War II.', 'had been', 'were', 'has been', 'have been', 'D', 'Giải thích: Câu này yêu cầu thì hiện tại hoàn thành để diễn tả những thay đổi hoặc cải tiến đã bắt đầu trong quá khứ và tiếp tục có ảnh hưởng đến hiện tại. "Have been" là dạng đúng của thì hiện tại hoàn thành phù hợp với danh từ số nhiều "improvements."\n(A) had been (v. past perfect): "Had been" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả các cải tiến vẫn có ảnh hưởng đến hiện tại.\n(B) were (v. past simple): "Were" là thì quá khứ đơn, không phù hợp vì không thể diễn tả ảnh hưởng kéo dài từ quá khứ đến hiện tại.\n(C) has been (v. present perfect, incorrect subject-verb agreement): "Has been" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số ít, không phù hợp vì chủ ngữ "improvements" là số nhiều.', 'Kể từ sau Chiến tranh Thế giới thứ hai, đã có những cải tiến đáng kể trong nông nghiệp.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0018_q_010', 'zenlish_practice', 'I used to smoke thirty cigarettes a day, but now I ____ down to ten.', 'has cut', 'be cutting', 'have cut', 'had cut', 'C', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động bắt đầu trong quá khứ và tiếp tục có ảnh hưởng đến hiện tại. "Have cut" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít).\n(A) has cut (v. present perfect, incorrect subject-verb agreement): "Has cut" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số ít ngôi thứ ba, không phù hợp vì chủ ngữ là "I."\n(B) be cutting (v. present continuous, incorrect tense): "Be cutting" là dạng hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu vì cần thì hiện tại hoàn thành để diễn tả sự thay đổi đã xảy ra và còn liên quan đến hiện tại.\n(D) had cut (v. past perfect): "Had cut" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả sự thay đổi từ quá khứ đến hiện tại.', 'Tôi từng hút ba mươi điếu thuốc một ngày, nhưng bây giờ tôi đã giảm xuống còn mười điếu.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_001', 'zenlish_practice', 'The Tyneside Recreation Department ______ suggestions for new programs until the end of this month.', 'has accepted', 'will be accepting', 'accepting', 'to accept', 'B', 'Giải thích: "Will be accepting" là thì tiếp diễn tương lai, phù hợp với việc nhận đề xuất cho đến cuối tháng này.\n(A) has accepted: "Has accepted" là thì hiện tại hoàn thành, không phù hợp với hành động đang tiếp tục trong tương lai.\n(C) accepting: "Accepting" là hiện tại phân từ, không phù hợp trong cấu trúc câu này.\n(D) to accept: "To accept" là động từ nguyên mẫu, không phù hợp với cấu trúc câu này.', 'Phòng Giải trí Tyneside sẽ tiếp nhận các đề xuất cho các chương trình mới đến cuối tháng này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_002', 'zenlish_practice', 'Everyone involved in the Greenfield project ______ in company housing.', 'reside', 'resides', 'residing', 'have resided', 'B', 'Giải thích: Trong câu này, "everyone" là chủ ngữ số ít, vì vậy động từ phải chia theo ngôi thứ ba số ít. "Resides" là dạng đúng của động từ để phù hợp với chủ ngữ số ít.\n(A) reside: Dạng động từ nguyên mẫu không phù hợp với chủ ngữ số ít.\n(C) residing: Dạng hiện tại phân từ không phù hợp trong ngữ cảnh này.\n(D) have resided: Dạng hiện tại hoàn thành không phù hợp với chủ ngữ số ít.', 'Mọi người tham gia vào dự án Greenfield đều sống trong nhà ở của công ty.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_003', 'zenlish_practice', 'More university students _______ in internships in the last five years than ever before.', 'were participated', 'have participated', 'participating', 'will participate', 'B', 'Giải thích: Câu này đang nói về một hành động đã xảy ra trong quá khứ và kéo dài đến hiện tại, vì vậy cần dùng thì hiện tại hoàn thành "have participated" để diễn tả rằng số lượng sinh viên tham gia thực tập đã tăng lên trong 5 năm qua và tiếp tục ảnh hưởng đến hiện tại.\n(A) were participated: Không đúng vì "were participated" là cấu trúc không đúng về mặt ngữ pháp.\n(C) participating: Không đúng vì đây là dạng hiện tại tiếp diễn, không phù hợp với ý nghĩa hành động đã xảy ra trong quá khứ và kéo dài đến hiện tại.\n(D) will participate: Không đúng vì đây là thì tương lai, không phù hợp với thời điểm hành động đã xảy ra trong quá khứ và tiếp tục đến hiện tại.', 'Hơn các sinh viên đại học đã tham gia thực tập trong năm năm qua nhiều hơn bao giờ hết.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_004', 'zenlish_practice', 'We ______ ten inquiries since the advertisement ran in last week''s edition of the newspaper.', 'receive', 'have received', 'will receive', 'receiving', 'B', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành "have received" để diễn tả một hành động đã bắt đầu trong quá khứ và tiếp tục đến hiện tại. Trong trường hợp này, chúng ta đang nói về số lượng yêu cầu (inquiries) mà chúng ta đã nhận được kể từ khi quảng cáo được đăng.\n(A) receive: Không đúng vì đây là thì hiện tại đơn, không phù hợp với ngữ cảnh hành động đã bắt đầu trong quá khứ và tiếp tục đến hiện tại.\n(C) will receive: Không đúng vì đây là thì tương lai, không phù hợp với thời điểm hành động đã xảy ra và vẫn đang tiếp tục đến hiện tại.\n(D) receiving: Không đúng vì đây là dạng hiện tại tiếp diễn, không phù hợp với cấu trúc câu cần thiết trong ngữ cảnh này.', 'Chúng tôi đã nhận được mười yêu cầu kể từ khi quảng cáo được đăng trong số báo tuần trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_005', 'zenlish_practice', 'The Salisbury Nature Club''s treasurer ______ and suggested revisions to the budget for the next financial quarter.', 'is examining', 'has examined', 'will examine', 'to examine', 'B', 'Giải thích: "has examined" là thì hiện tại hoàn thành, phù hợp để diễn tả hành động đã được hoàn tất trong một thời điểm không xác định trước hiện tại. Điều này cho thấy treasurer đã hoàn thành việc kiểm tra và đề xuất các chỉnh sửa cho ngân sách.\n(A) is examining: Không đúng vì đây là thì hiện tại tiếp diễn, diễn tả hành động đang xảy ra, không phù hợp với ngữ cảnh của việc đã hoàn tất.\n(C) will examine: Không đúng vì đây là thì tương lai, không phù hợp với việc đã xảy ra trong quá khứ gần đây.\n(D) to examine: Không đúng vì đây là dạng nguyên mẫu không phù hợp với ngữ pháp của câu.', 'Kế toán của Salisbury Nature Club đã kiểm tra và đề xuất các chỉnh sửa cho ngân sách của quý tài chính tiếp theo.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_006', 'zenlish_practice', 'Polansky Data International ______ transportation for all employees attending the digital media conference in Liverpool next week.', 'has arranged', 'was arranged', 'arranging', 'arrangements', 'A', 'Giải thích: "has arranged" là thì hiện tại hoàn thành, diễn tả rằng hành động sắp xếp phương tiện giao thông đã được hoàn tất trước thời điểm hiện tại. Điều này cho thấy việc sắp xếp đã được thực hiện và có hiệu lực trong bối cảnh hiện tại.\n(B) was arranged: Không đúng vì đây là thì quá khứ bị động, không phù hợp với việc hành động đã hoàn tất gần đây.\n(C) arranging: Không đúng vì đây là dạng hiện tại tiếp diễn, không phù hợp với ngữ cảnh đã hoàn tất hành động.\n(D) arrangements: Không đúng vì đây là danh từ, không phù hợp với cấu trúc của câu yêu cầu động từ.', 'Polansky Data International đã sắp xếp phương tiện giao thông cho tất cả nhân viên tham dự hội nghị truyền thông kỹ thuật số tại Liverpool vào tuần tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_007', 'zenlish_practice', 'So far, many beautiful buildings ____ been built in Bangkok.', 'have', 'has', 'to have', 'having', 'A', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động đã xảy ra trong quá khứ và vẫn còn ảnh hưởng đến hiện tại. "Have been built" là dạng đúng của thì hiện tại hoàn thành khi chủ ngữ là "many beautiful buildings" (danh từ số nhiều).\n(B) has (v. present perfect, incorrect subject-verb agreement): "has" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số ít, không phù hợp vì chủ ngữ "many beautiful buildings" là số nhiều.\n(C) to have (infinitive): "to have" là động từ nguyên thể có "to," không phù hợp với ngữ pháp của câu vì cần thì hiện tại hoàn thành.\n(D) having (v. gerund): "having" là danh động từ, không phù hợp với cấu trúc ngữ pháp cần động từ chính ở thì hiện tại hoàn thành.', 'Cho đến nay, nhiều tòa nhà đẹp đã được xây dựng ở Bangkok.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_008', 'zenlish_practice', 'Michael ____ lived in Peru for ten years.', 'have', 'has', 'had', 'to have', 'B', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động bắt đầu trong quá khứ và vẫn tiếp tục đến hiện tại. "Has lived" là dạng đúng của thì hiện tại hoàn thành khi chủ ngữ là "Michael" (ngôi thứ ba số ít).\n(A) have (v. present perfect, incorrect subject-verb agreement): "have" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì "Michael" là ngôi thứ ba số ít.\n(C) had (v. past perfect): "had" là thì quá khứ hoàn thành, không phù hợp với ngữ cảnh vì câu này cần thì hiện tại hoàn thành.\n(D) to have (infinitive): "to have" là động từ nguyên thể có "to," không phù hợp với ngữ pháp của câu vì cần thì hiện tại hoàn thành.', 'Michael đã sống ở Peru được mười năm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_009', 'zenlish_practice', 'It ____ rained every day so far this week.', 'had', 'have', 'is having', 'has', 'D', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động đã xảy ra nhiều lần trong quá khứ và tiếp tục đến hiện tại. "Has rained" là dạng đúng của thì hiện tại hoàn thành khi chủ ngữ là "It" (ngôi thứ ba số ít).\n(A) had (v. past perfect): "had" là thì quá khứ hoàn thành, không phù hợp với ngữ cảnh vì câu này cần thì hiện tại hoàn thành.\n(B) have (v. present perfect, incorrect subject-verb agreement): "have" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì "It" là ngôi thứ ba số ít.\n(C) is having (v. present continuous): "is having" là thì hiện tại tiếp diễn, không phù hợp vì câu này cần thì hiện tại hoàn thành.', 'Cho đến nay, tuần này trời đã mưa mỗi ngày.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0019_q_010', 'zenlish_practice', 'I ____ told you hundreds of times not to do that.', 'have', 'has', 'having', 'had', 'A', '4. I ____ told you hundreds of times not to do that. Đáp án đúng là:\n(A) have Giải thích: Câu này sử dụng thì hiện tại hoàn thành để nói về hành động đã xảy ra nhiều lần trong quá khứ và vẫn còn liên quan đến hiện tại (vẫn còn bực bội / nhắc lại).\n(B) has: dùng cho he/she/it, không dùng cho I\n(C) having: V-ing, không thể làm động từ chính\n(D) had: quá khứ hoàn thành → chỉ dùng khi có một hành động xảy ra trước một mốc thời gian trong quá khứ.', 'Tôi đã nói với bạn hàng trăm lần không được làm điều đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_001', 'zenlish_practice', 'He ____ warned her many times not to talk in class. But she still pays no heed to him.', 'have', 'to have', 'had', 'has', 'D', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả hành động đã xảy ra nhiều lần trong quá khứ và có ảnh hưởng đến hiện tại. "Has warned" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "He" (ngôi thứ ba số ít).\n(A) have (v. present perfect, incorrect subject-verb agreement): "Have" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì chủ ngữ là "He."\n(B) to have (infinitive): "To have" là động từ nguyên thể, không phù hợp với ngữ pháp câu vì cần thì hiện tại hoàn thành.\n(C) had (v. past perfect): "Had" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để nói về các hành động đã xảy ra nhiều lần trong quá khứ và vẫn có liên quan đến hiện tại.', 'Anh ấy đã cảnh báo cô ấy nhiều lần không được nói chuyện trong lớp. Nhưng cô ấy vẫn không chú ý đến anh ấy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_002', 'zenlish_practice', 'Why ____ these letters been mailed ?', 'has not', 'having not', 'have not', 'is', 'C', 'Giải thích: Câu này yêu cầu sử dụng thì hiện tại hoàn thành bị động để hỏi về trạng thái của một hành động đã xảy ra và có ảnh hưởng đến hiện tại. "Have not been mailed" là dạng đúng của thì hiện tại hoàn thành bị động với chủ ngữ số nhiều "these letters."\n(A) has not (v. present perfect, incorrect subject-verb agreement): "has not" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số ít, không phù hợp vì chủ ngữ là "these letters," danh từ số nhiều.\n(B) having not (v. gerund phrase): "having not" là danh động từ, không phù hợp vì câu cần thì hiện tại hoàn thành bị động.\n(D) is (v. present simple, incorrect verb form): "is" là thì hiện tại đơn, không phù hợp với ngữ cảnh của câu vì cần thì hiện tại hoàn thành bị động.', 'Tại sao những bức thư này chưa được gửi đi?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_003', 'zenlish_practice', 'This is the first time I ____ done the experiment on plant breeding.', 'is', 'would', 'had', 'have', 'D', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để nói về lần thứ nhất/ thứ 2/... hành động nào đó diễn ra. "Have done" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "I" (ngôi thứ nhất số ít).\n(A) is (v. present simple, incorrect verb form): "is" là thì hiện tại đơn, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả một trải nghiệm lần đầu.\n(B) would (v. conditional): "would" là động từ ở dạng điều kiện, không phù hợp với ngữ cảnh của câu vì cần thì hiện tại hoàn thành.\n(C) had (v. past perfect): "had" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để nói về một sự kiện lần đầu tiên.', 'Đây là lần đầu tiên tôi thực hiện thí nghiệm về nhân giống cây trồng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_004', 'zenlish_practice', 'He ____ gone overseas to continue his education.', 'has', 'have', 'to have', 'had', 'A', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động đã xảy ra và có liên quan đến hiện tại. "Has gone" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "He" (ngôi thứ ba số ít).\n(B) have (v. present perfect, incorrect subject-verb agreement): "have" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì chủ ngữ là "He."\n(C) to have (infinitive): "to have" là động từ nguyên thể, không phù hợp vì câu cần thì hiện tại hoàn thành.\n(D) had (v. past perfect): "had" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả trạng thái hiện tại.', 'Anh ấy đã ra nước ngoài để tiếp tục việc học của mình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_005', 'zenlish_practice', 'She ____ lost her handbag with the considerable sum of 2,000 dollars in it.', 'have', 'be', 'has', 'had', 'C', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một hành động đã xảy ra trong quá khứ và vẫn còn liên quan đến hiện tại. "Has lost" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "She" (ngôi thứ ba số ít).\n(A) have (v. present perfect, incorrect subject-verb agreement): "have" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì chủ ngữ là "She."\n(B) be (v. present simple): "be" là động từ thì hiện tại đơn, không phù hợp vì câu cần thì hiện tại hoàn thành.\n(D) had (v. past perfect): "had" là thì quá khứ hoàn thành, không phù hợp vì câu này cần thì hiện tại hoàn thành để diễn tả tình trạng hiện tại.', 'Cô ấy đã làm mất chiếc túi xách với số tiền lớn 2.000 đô la trong đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_006', 'zenlish_practice', 'Television ____ existed only for the last forty or fifty years.', 'to have', 'has', 'having', 'have', 'B', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành để diễn tả một tình trạng bắt đầu trong quá khứ và tiếp tục đến hiện tại. "Has existed" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "Television" (danh từ số ít).\n(A) to have (infinitive): "to have" là động từ nguyên thể, không phù hợp vì câu này cần thì hiện tại hoàn thành.\n(C) having (v. gerund): "having" là danh động từ, không phù hợp với cấu trúc ngữ pháp của câu vì cần thì hiện tại hoàn thành.\n(D) have (v. present perfect, incorrect subject-verb agreement): "have" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì "Television" là số ít.', 'Truyền hình đã tồn tại chỉ trong bốn mươi hoặc năm mươi năm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_007', 'zenlish_practice', 'Anyone who ____ his work cannot go.', 'have not finished', 'having not finished', 'has not finished', 'was not finish', 'C', 'Giải thích: Câu này yêu cầu một động từ ở thì hiện tại hoàn thành để diễn tả một hành động chưa hoàn tất đến thời điểm hiện tại. "Has not finished" là dạng đúng của thì hiện tại hoàn thành với chủ ngữ số ít "Anyone" (mặc dù "anyone" được xem là số ít, trong ngữ cảnh này thì "has" là lựa chọn đúng).\n(A) have not finished (v. present perfect, incorrect subject-verb agreement): "have not finished" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số nhiều hoặc ngôi thứ nhất số ít, không phù hợp vì chủ ngữ "Anyone" yêu cầu "has."\n(B) having not finished (v. gerund phrase): "having not finished" là dạng danh động từ, không phù hợp vì câu cần thì hiện tại hoàn thành.\n(D) was not finish (v. past simple, incorrect verb form): "was not finish" là dạng thì quá khứ đơn và không đúng ngữ pháp vì động từ không phải ở dạng phân từ hai (past participle).', 'Bất kỳ ai chưa hoàn thành công việc của mình thì không thể đi được.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_008', 'zenlish_practice', 'What measures ____ been taken to control the crowd at Saturday’s football match ?', 'has', 'to have', 'have', 'having', 'C', 'Giải thích: Câu này sử dụng thì hiện tại hoàn thành bị động để hỏi về những biện pháp đã được thực hiện đến hiện tại. "Have been taken" là dạng đúng của thì hiện tại hoàn thành bị động khi chủ ngữ là "measures" (danh từ số nhiều).\n(A) has (v. present perfect, incorrect subject-verb agreement): "has" là dạng hiện tại hoàn thành nhưng chỉ sử dụng với chủ ngữ số ít, không phù hợp vì "measures" là số nhiều.\n(B) to have (infinitive): "to have" là động từ nguyên thể, không phù hợp với ngữ pháp của câu vì cần dạng hiện tại hoàn thành bị động.\n(D) having (v. gerund): "having" là danh động từ, không phù hợp vì câu này cần thì hiện tại hoàn thành bị động.', 'Những biện pháp gì đã được thực hiện để kiểm soát đám đông tại trận đấu bóng đá vào thứ Bảy?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_009', 'zenlish_practice', 'The magazine’s readership _________ almost 20 percent in three months.', 'rise', 'rising', 'to rise', 'has risen', 'D', 'Giải thích: "Has risen" là thì hiện tại hoàn thành, phù hợp để diễn tả một sự việc đã bắt đầu trong quá khứ và vẫn còn liên quan đến hiện tại (trong khoảng thời gian ba tháng gần đây).\n(A) rise (base form): "rise" là động từ nguyên thể, không phù hợp với ngữ pháp của câu.\n(B) rising (present participle): "rising" là dạng phân từ hiện tại, không phù hợp vì câu yêu cầu một động từ chính đã hoàn thành.\n(C) to rise (infinitive): "to rise" là dạng động từ nguyên thể có "to", không phù hợp với cấu trúc của câu.', 'Số lượng độc giả của tạp chí đã tăng gần 20% trong ba tháng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0020_q_010', 'zenlish_practice', 'By the time the merger was announced, Trexler Co, ________ operating under its new name, Trexler-Compton, Inc.', 'begins', 'will begin', 'had begun', 'having begun', 'C', 'Giải thích: "Had begun" là thì quá khứ hoàn thành, dùng để diễn tả một hành động đã xảy ra và hoàn thành trước một hành động khác trong quá khứ (ở đây là trước khi vụ sáp nhập được công bố).\n(A) begins (present simple): "begins" là thì hiện tại đơn, không phù hợp vì câu nói về một sự việc đã xảy ra trong quá khứ.\n(B) will begin (future tense): "will begin" là thì tương lai, không phù hợp vì câu cần một động từ ở thì quá khứ.\n(D) having begun (perfect participle): "having begun" là dạng phân từ hoàn thành, không đúng ngữ pháp trong câu này.', 'Khi vụ sáp nhập được công bố, công ty Trexler đã bắt đầu hoạt động dưới tên mới, Trexler-Compton, Inc.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_001', 'zenlish_practice', 'The office complex _____ on the outskirts of the pedestrian shopping area.', 'will be built', 'built', 'are building', 'builder', 'A', 'Giải thích: "Will be built" là động từ ở thì tương lai bị động, phù hợp để diễn tả một hành động sẽ xảy ra trong tương lai. Câu này nói rằng khu phức hợp văn phòng sẽ được xây dựng ở vùng ngoại ô của khu vực mua sắm dành cho người đi bộ.\n(B) built (v. past participle/adj.): "built" có thể là quá khứ phân từ hoặc tính từ, nhưng không phù hợp với ngữ cảnh khi câu nói về một hành động trong tương lai.\n(C) are building (present continuous): "are building" là thì hiện tại tiếp diễn, không phù hợp vì câu cần diễn tả hành động trong tương lai.\n(D) builder (n.): "builder" là danh từ, không phù hợp với ngữ pháp của câu khi cần một động từ.', 'Khu phức hợp văn phòng sẽ được xây dựng ở vùng ngoại ô của khu vực mua sắm dành cho người đi bộ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_002', 'zenlish_practice', 'By the time the magazine article on home security devices _____ on the newsstands, the pricing information was already outdated.', 'appears', 'appeared', 'will appear', 'appearing', 'B', 'Giải thích: "Appeared" là động từ ở thì quá khứ đơn, phù hợp với ngữ cảnh của câu khi nói về một sự kiện đã xảy ra trong quá khứ. Câu này nói rằng khi bài báo về các thiết bị an ninh gia đình xuất hiện trên các sạp báo, thông tin về giá cả đã lỗi thời.\n(A) appears (present simple): "appears" là động từ ở thì hiện tại đơn, không phù hợp với ngữ cảnh của câu khi nói về sự kiện đã xảy ra trong quá khứ.\n(C) will appear (future simple): "will appear" là động từ ở thì tương lai đơn, không phù hợp với ngữ cảnh của câu khi nói về sự kiện đã xảy ra trong quá khứ.\n(D) appearing (present participle): "appearing" là hiện tại phân từ, không phù hợp với ngữ pháp của câu khi cần một động từ ở thì quá khứ đơn.', 'Khi bài báo về các thiết bị an ninh gia đình xuất hiện trên các sạp báo, thông tin về giá cả đã lỗi thời.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_003', 'zenlish_practice', 'ZG Dental thanks all staff members who ____ marketing materials at last week’s National Dentistry Expo in Pittsburgh.', 'distribute', 'distributes', 'distributed', 'distributing', 'C', 'Giải thích: Cần điền động từ thì quá khứ trong mệnh đề quan hệ bắt đầu bằng "who" để mô tả việc mà "staff members" đã làm trong sự kiện diễn ra vào tuần trước. "Distributed" là động từ ở thì quá khứ đơn, phù hợp với ngữ cảnh của câu khi nói về hành động phân phát tài liệu tiếp thị tại sự kiện National Dentistry Expo tuần trước.\n(A) distribute (v. base form): "Distribute" là động từ nguyên mẫu, không phù hợp với ngữ cảnh của câu khi nói về một hành động đã xảy ra trong quá khứ.\n(B) distributes (v. present singular): "Distributes" là động từ ngôi thứ ba số ít thì hiện tại, không phù hợp với ngữ cảnh của câu khi nói về một hành động đã xảy ra trong quá khứ.\n(D) distributing (v. present participle): "Distributing" là hiện tại phân từ, không phù hợp với ngữ pháp của câu khi cần một động từ ở thì quá khứ đơn.', 'ZG Dental cảm ơn tất cả các nhân viên đã phân phát tài liệu tiếp thị tại National Dentistry Expo tuần trước ở Pittsburgh.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_004', 'zenlish_practice', 'The assets of Marble Faun Publishing Company _____ last quarter when one of their main local distributors went out of business.', 'suffer', 'suffers', 'suffering', 'suffered', 'D', 'Giải thích: Trong câu này, cần một thì quá khứ đơn để mô tả tình trạng của tài sản của Marble Faun Publishing Company trong quý trước. "Suffered" là thì quá khứ đơn phù hợp, nghĩa là "chịu đựng" hoặc "bị ảnh hưởng," để chỉ rằng tài sản của công ty đã gặp vấn đề trong quá khứ khi một trong những nhà phân phối chính của họ phá sản.\n(A) suffer (present simple): "Suffer" có nghĩa là "chịu đựng." Lý do không chọn là vì thì hiện tại không phù hợp để mô tả tình trạng trong quá khứ.\n(B) suffers (present simple, third person singular): "Suffers" có nghĩa là "chịu đựng" ở ngôi thứ ba số ít. Lý do không chọn là vì thì hiện tại không phù hợp khi mô tả tình trạng đã xảy ra trong quá khứ.\n(C) suffering (present participle): "Suffering" có nghĩa là "đang chịu đựng." Lý do không chọn là vì dạng hiện tại phân từ không phù hợp khi cần một động từ ở thì quá khứ để mô tả sự kiện đã xảy ra.', 'Tài sản của Marble Faun Publishing Company đã chịu ảnh hưởng trong quý trước khi một trong những nhà phân phối chính của họ phá sản.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_005', 'zenlish_practice', 'The Wallace Goldberg Committee of Environmental Awareness unanimously _____ the technical team of Walpole Enterprises for their annual award.', 'select', 'selecting', 'selected', 'was selected', 'C', 'Giải thích: Trong câu này, cần một thì quá khứ đơn để mô tả hành động của ủy ban trong việc chọn đội ngũ kỹ thuật của Walpole Enterprises. "Selected" là thì quá khứ đơn phù hợp, nghĩa là "đã chọn," để chỉ rằng ủy ban đã chọn đội ngũ kỹ thuật cho giải thưởng hàng năm. Câu này nhấn mạnh hành động đã hoàn tất trong quá khứ.\n(A) select (present simple): "Select" có nghĩa là "chọn." Lý do không chọn là vì thì hiện tại đơn không phù hợp khi mô tả một hành động đã xảy ra trong quá khứ.\n(B) selecting (present participle): "Selecting" có nghĩa là "đang chọn." Lý do không chọn là vì dạng hiện tại phân từ không phù hợp trong ngữ cảnh cần mô tả hành động đã hoàn tất.\n(D) was selected (past passive): "Was selected" có nghĩa là "đã được chọn" (bị động). Lý do không chọn là vì câu này cần một động từ ở dạng chủ động để mô tả hành động của ủy ban, không phải của đội ngũ kỹ thuật.', 'Ủy ban Wallace Goldberg về Ý thức Môi trường đã nhất trí chọn đội ngũ kỹ thuật của Walpole Enterprises cho giải thưởng hàng năm của họ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_006', 'zenlish_practice', 'Several staff heads _____ a better understanding of the importance of motivation and teamwork from the last workshop.', 'gaining', 'will gain', 'gained', 'were gained', 'C', 'Giải thích: Trong câu này, cần một động từ ở thì quá khứ đơn để mô tả việc các trưởng nhóm đã nhận được sự hiểu biết tốt hơn từ workshop trước đó (from the last workshop). "Gained" là dạng quá khứ đơn phù hợp, nghĩa là "đã nhận được".\n(A) gaining (present participle): "Gaining" có nghĩa là "đang nhận được." Lý do không chọn là vì dạng hiện tại phân từ không phù hợp khi mô tả một hành động đã xảy ra trong quá khứ.\n(B) will gain (future simple): "Will gain" có nghĩa là "sẽ nhận được." Lý do không chọn là vì thì tương lai không phù hợp khi mô tả một hành động đã xảy ra trong quá khứ.\n(D) were gained (past passive): "Were gained" có nghĩa là "đã được nhận." Lý do không chọn là vì cấu trúc bị động không phù hợp khi cần mô tả hành động đã xảy ra trực tiếp từ góc độ chủ động.', 'Một số trưởng nhóm đã nhận được sự hiểu biết tốt hơn về tầm quan trọng của động lực và làm việc nhóm từ workshop trước đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_007', 'zenlish_practice', 'Because of the airline strike, Mr. Susan _____ his plan for a business trip to Paris.', 'postpone', 'to postpone', 'should be postponed', 'had to postpone', 'D', 'Giải thích: Câu này cần một động từ để hoàn thành ý nghĩa, đặc biệt là diễn tả nghĩa bắt buộc hoặc cần thiết do sự kiện xảy ra (đình công hãng hàng không). Cụm "had to postpone" có nghĩa là "đã phải hoãn," phù hợp với ngữ cảnh câu nói về việc Mr. Susan bắt buộc phải hoãn chuyến đi do đình công.\n(A) postpone (v.): "postpone" có nghĩa là "hoãn lại." Lý do không chọn là vì nó cần được chia thì để phù hợp với thời gian quá khứ và ngữ cảnh câu.\n(B) to postpone (to + v.): "to postpone" cũng có nghĩa là "hoãn lại," nhưng sự xuất hiện của "to" khiến nó không phù hợp về mặt cú pháp trong câu này vì không có động từ trợ giúp nào yêu cầu dạng nguyên mẫu.\n(C) should be postponed (modal + be + pp.): Cụm từ này có nghĩa là "nên được hoãn lại," dùng cho chủ ngữ là vật.', 'Do đình công hãng hàng không, ông Susan đã phải hoãn kế hoạch đi công tác tới Paris.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_008', 'zenlish_practice', 'Members of the state council _____ last month at the Lincoln Expo Center for their lastest conference and annual meeting.', 'convened', 'convenes', 'convening', 'convene', 'A', 'Giải thích: Câu này cần động từ chính mô tả một hành động đã xảy ra trong quá khứ (last month) .\n(B) convenes (present simple): "convenes" là dạng ngôi thứ ba số ít của thì hiện tại đơn, sử dụng cho các hành động thường xuyên hoặc lặp đi lặp lại, không phù hợp với ngữ cảnh câu này đang nói về một sự kiện cụ thể trong quá khứ.\n(C) convening (present participle/gerund): "convening" có thể là dạng danh động từ hoặc đang tiến hành, nhưng không hoàn thành câu được vì thiếu trợ động từ hoặc bối cảnh phù hợp.\n(D) convene (base form): "convene" là dạng nguyên mẫu của động từ, thường được sử dụng sau các động từ modal hoặc trong câu mệnh lệnh, không phù hợp cho câu tường thuật đã xảy ra trong quá khứ.', 'Các thành viên của hội đồng bang đã tụ họp vào tháng trước tại Trung tâm Triển lãm Lincoln cho hội nghị mới nhất và cuộc họp thường niên của họ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_009', 'zenlish_practice', 'Mr. Khana made a phone call yesterday during which he ______ for the delay in the shipment of the clothing order.', 'to apologize', 'apologized', 'apologize', 'will be apologizing', 'B', 'Giải thích: Trong câu này, cần một động từ ở thì quá khứ đơn để diễn tả hành động đã xảy ra trong quá khứ, cụ thể là trong cuộc điện thoại của ông Khana. "Apologized" là dạng quá khứ đơn của động từ "apologize," phù hợp với ngữ cảnh câu mô tả rằng ông Khana đã gọi điện thoại vào ngày hôm qua và đã xin lỗi vì sự chậm trễ trong việc giao hàng.\n(A) to apologize (infinitive): "To apologize" là động từ nguyên mẫu, không phù hợp vì câu này cần một động từ chia ở thì quá khứ.\n(C) apologize (base form): "Apologize" là dạng nguyên mẫu của động từ, không phù hợp vì câu này cần một động từ chia ở thì quá khứ.\n(D) will be apologizing (future continuous): "Will be apologizing" là thì tương lai tiếp diễn, không phù hợp vì câu này cần một động từ ở thì quá khứ.', 'Ông Khana đã gọi điện thoại vào ngày hôm qua, trong đó ông ấy đã xin lỗi vì sự chậm trễ trong việc giao hàng quần áo.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0021_q_010', 'zenlish_practice', 'The research team _____ several policies on how sensitive issues should be tackled.', 'implementation', 'to implement', 'implemented', 'implementing', 'C', 'Giải thích: Câu này thiếu động từ chính, chỉ có "implemented" là đáp án phù hợp.\n(A) implementation (n.): "Implementation" có nghĩa là "việc thực hiện," không thể làm động từ chính trong câu.\n(B) to implement (infinitive verb): "To implement" là dạng to V, không thể làm động từ chính.\n(D) implementing (gerund/participle): "Implementing" là dạng danh động từ hoặc hiện tại phân từ, không thể làm động từ chính.', 'Nhóm nghiên cứu đã thực hiện một số chính sách về cách giải quyết các vấn đề nhạy cảm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_001', 'zenlish_practice', 'Whether or not the new marketing approaches which the firm _____ has been effective remains to be seen.', 'to adopt', 'has been adopted', 'adopted', 'were adopting', 'C', 'Giải thích: Câu này cần động từ chia theo chủ ngữ "the firm" trong mệnh đề quan hệ bắt đầu bằng "which". Trong câu này, chúng ta cần một thì quá khứ đơn để miêu tả hành động đã xảy ra trước đây, tức là các phương pháp tiếp thị mà công ty đã áp dụng. "Adopted" là dạng quá khứ của động từ "adopt" (áp dụng), phù hợp với ngữ cảnh của câu.\n(A) to adopt (infinitive): "To adopt" không phù hợp vì câu cần dạng quá khứ của động từ.\n(B) has been adopted (present perfect passive): "Has been adopted" không phù hợp vì câu cần động từ dạng chủ động, không phải dạng bị động.\n(D) were adopting (past continuous): "Were adopting" không phù hợp vì "the firm" là danh từ số ít.', 'Hiệu quả của các phương pháp tiếp thị mới mà công ty đã áp dụng vẫn chưa được xác định.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_002', 'zenlish_practice', 'Ms. Rodriguez will speak about a banking conference she ______ in Lisbon last month.', 'attends', 'attended', 'will attend', 'attend', 'B', 'Giải thích: "Attended" là thì quá khứ đơn, phù hợp với ngữ cảnh diễn tả việc bà Rodriguez sẽ nói về một hội nghị ngân hàng mà bà đã tham dự ở Lisbon vào tháng trước.\n(A) attends (v.): "Attends" là thì hiện tại đơn, không phù hợp với ngữ cảnh của câu này.\n(C) will attend (v.): "Will attend" là thì tương lai đơn, không phù hợp với ngữ cảnh của câu này.\n(D) attend (v.): "Attend" là động từ nguyên mẫu, không phù hợp với cấu trúc và ngữ cảnh của câu này.', 'Bà Rodriguez sẽ nói về một hội nghị ngân hàng mà bà đã tham dự ở Lisbon vào tháng trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_003', 'zenlish_practice', 'Last year, the Hansford Automobile catalog ______ air-conditioning as a standard feature in all automobiles.', 'listed', 'list', 'listing', 'to list', 'A', 'Giải thích: Trong câu này, động từ "list" cần được chia theo thì quá khứ để phù hợp với thời gian "Last year." Vì vậy, "listed" là dạng quá khứ của động từ "list" là phù hợp nhất.\n(B) list: Không đúng vì động từ này đang ở dạng hiện tại, không phù hợp với thì quá khứ của câu.\n(C) listing: Không đúng vì đây là dạng phân từ hiện tại, không phù hợp với cấu trúc câu.\n(D) to list: Không đúng vì đây là dạng động từ nguyên mẫu, không phù hợp với ngữ cảnh thì quá khứ.', 'Năm ngoái, catalog của Hansford Automobile đã liệt kê điều hòa không khí là một tính năng tiêu chuẩn trong tất cả các loại ô tô.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_004', 'zenlish_practice', 'By the time the magazine article on home security devices ______ on the newsstands, the pricing information was already outdated.', 'appears', 'appeared', 'will appear', 'appearing', 'B', 'Giải thích: Trong câu này, thì quá khứ đơn "appeared" được sử dụng để chỉ một sự kiện đã xảy ra trước một thời điểm khác trong quá khứ. Thì này hợp với ngữ cảnh khi thông tin về giá cả đã lỗi thời trước khi bài báo xuất hiện trên các quầy báo.\n(A) appears: Không đúng vì đây là thì hiện tại đơn, không phù hợp với việc diễn tả một hành động đã xảy ra trước đó.\n(C) will appear: Không đúng vì đây là thì tương lai, không phù hợp với ngữ cảnh câu đã nói về sự việc trong quá khứ.\n(D) appearing: Không đúng vì đây là dạng hiện tại phân từ, không phù hợp với yêu cầu về thì của câu.', 'Vào thời điểm bài báo trên tạp chí về thiết bị an ninh nhà ở xuất hiện trên các quầy báo, thông tin về giá cả đã lỗi thời.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_005', 'zenlish_practice', 'She ______ me once at the hospital last year.', 'met', 'meet', 'meets', 'meeting', 'A', 'Giải thích: Câu này sử dụng thì quá khứ đơn để diễn tả một hành động đã xảy ra và hoàn tất trong quá khứ (tại bệnh viện vào năm ngoái). "Met" là dạng quá khứ của động từ "meet," phù hợp với ngữ cảnh vì nó diễn tả một lần gặp gỡ đã xảy ra trong quá khứ.\n(B) meet (v. base form): "Meet" là dạng cơ bản của động từ, không phù hợp vì câu này cần một dạng thì quá khứ để nói về một hành động đã hoàn tất trong quá khứ.\n(C) meets (v. present simple, incorrect subject-verb agreement): "Meets" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn.\n(D) meeting (gerund/participle): "Meeting" là danh động từ hoặc hiện tại phân từ, không phù hợp với thì quá khứ', 'Cô ấy đã gặp tôi một lần tại bệnh viện vào năm ngoái.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_006', 'zenlish_practice', 'Last night, there was nothing to watch on T.V, we ______out.', 'go', 'went', 'goes', 'gone', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả hành động đã xảy ra và hoàn tất trong quá khứ (đi ra ngoài vào tối qua). "Went" là dạng quá khứ của động từ "go," phù hợp với ngữ cảnh vì nó diễn tả hành động đã hoàn tất trong quá khứ.\n(A) go (v. base form): "Go" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) goes (v. present simple, incorrect subject-verb agreement): "Goes" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn.\n(D) gone (v. past participle): "Gone" là dạng phân từ hai của động từ "go," không phù hợp vì câu này cần thì quá khứ đơn và không sử dụng dạng phân từ hai trực tiếp.', 'Tối qua, không có gì để xem trên TV, chúng tôi đã đi ra ngoài.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_007', 'zenlish_practice', 'I can’t find the book I ______ here an hour ago.', 'leave', 'left', 'leaves', 'leaving', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (bỏ cuốn sách ở đây một giờ trước). "Left" là dạng quá khứ của động từ "leave," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) leave (v. base form): "Leave" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) leaves (v. present simple, incorrect tense): "Leaves" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn.\n(D) leaving (v. present participle): "Leaving" là dạng hiện tại phân từ, không phù hợp vì câu này cần thì quá khứ đơn.', 'Tôi không thể tìm thấy cuốn sách mà tôi đã để ở đây một giờ trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_008', 'zenlish_practice', 'My brother ______ not go to school yesterday, and neither did I.', 'did', 'do', 'does', 'is', 'A', 'Giải thích: Câu này sử dụng thì quá khứ đơn với động từ "did" để diễn tả một hành động đã không xảy ra trong quá khứ (em trai của tôi không đi học vào ngày hôm qua). "Did" là dạng quá khứ của động từ "do," phù hợp với ngữ cảnh vì nó được sử dụng trong câu phủ định với "not."\n(B) do (v. base form, incorrect tense): "Do" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã không xảy ra trong quá khứ.\n(C) does (v. present simple, incorrect tense): "Does" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn để nói về hành động trong quá khứ.\n(D) is (v. present simple, incorrect tense): "Is" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn để diễn tả hành động đã xảy ra trong quá khứ.', 'Em trai của tôi đã không đi học ngày hôm qua, và tôi cũng vậy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_009', 'zenlish_practice', 'Last month, the oil prices ______ up again by 20 %.', 'go', 'goes', 'went', 'going', 'C', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả hành động giá dầu tăng lên đã xảy ra và hoàn tất trong quá khứ (tháng trước). "Went" là dạng quá khứ của động từ "go," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) go (v. base form): "Go" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.\n(B) goes (v. present simple, incorrect tense): "Goes" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn.\n(D) going (v. present participle): "Going" là dạng hiện tại phân từ, không phù hợp vì câu này cần thì quá khứ đơn.', 'Tháng trước, giá dầu đã tăng lên 20%.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0022_q_010', 'zenlish_practice', 'The first human beings probably ______ about 1.5 million years ago.', 'lived', 'living', 'lives', 'live', 'A', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (những con người đầu tiên sống khoảng 1.5 triệu năm trước). "Lived" là dạng quá khứ của động từ "live," phù hợp với ngữ cảnh vì nó diễn tả một hành động đã xảy ra trong quá khứ .\n(B) living (v. present participle): "Living" là dạng hiện tại phân từ, không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.\n(C) lives (v. present simple, incorrect tense): "Lives" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn để nói về một hành động đã xảy ra trong quá khứ.\n(D) live (v. base form): "Live" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã hoàn tất trong quá khứ.', 'Những con người đầu tiên có lẽ đã sống khoảng 1,5 triệu năm trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_001', 'zenlish_practice', 'The boy had a narrow escape when he ______ across the road in front of the bus.', 'runs', 'run', 'running', 'ran', 'D', 'Giải thích: Hành động "chạy" và "had a narrow escape" cùng xảy ra trong quá khứ (cậu bé đã chạy qua đường trước khi chiếc xe buýt đến). "Ran" là dạng quá khứ của động từ "run," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) runs (v. present simple, incorrect tense): "Runs" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.\n(B) run (v. base form): "Run" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ để diễn tả hành động đã xảy ra trong quá khứ.\n(C) running (v. present participle): "Running" là dạng hiện tại phân từ, không phù hợp vì câu này cần thì quá khứ đơn.', 'Cậu bé đã thoát hiểm trong gang tấc khi cậu chạy qua đường trước mặt chiếc xe buýt.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_002', 'zenlish_practice', 'Since they ______, we have been able to work on the project.', 'come', 'coming', 'came', 'are coming', 'C', 'Giải thích: Mệnh đề sau Since cần chia ở thì quá khứ đơn để mô tả một mốc thời gian trong quá khứ (từ khi họ đến).\n(A) come (v. base form): "Come" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ đơn để nói về hành động đã xảy ra trong quá khứ.\n(B) coming (v. present participle): "Coming" là dạng hiện tại phân từ, không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.\n(D) are coming (v. present continuous): "Are coming" là thì hiện tại tiếp diễn và không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trước hiện tại.', 'Kể từ khi họ đến, chúng tôi đã có thể làm việc trên dự án.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_003', 'zenlish_practice', 'Dr. Zhivago, who we ______ six months ago, has now left Bangkok.', 'see', 'sees', 'saw', 'seeing', 'C', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (chúng tôi đã gặp Dr. Zhivago sáu tháng trước). "Saw" là dạng quá khứ của động từ "see," nghĩa là "gặp, thấy".\n(A) see (v. base form): "See" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(B) sees (v. present simple, incorrect tense): "Sees" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.', NULL, '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_004', 'zenlish_practice', 'After I had arrived at the bus terminus, I ______a crowd of schoolboys.', 'found', 'find', 'finding', 'am finding', 'A', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra sau một hành động khác đã hoàn tất trong quá khứ (sau khi tôi đến bến xe buýt, tôi đã gặp một đám học sinh). "Found" là dạng quá khứ của động từ "find," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(B) find (v. base form): "Find" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.\n(C) finding (v. present participle): "Finding" là dạng hiện tại phân từ, không phù hợp vì câu này cần thì quá khứ đơn.\n(D) am finding (v. present continuous, incorrect tense): "Am finding" là thì hiện tại tiếp diễn và không phù hợp vì câu này cần thì quá khứ đơn.', 'Sau khi tôi đã đến bến xe buýt, tôi đã gặp một đám học sinh.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_005', 'zenlish_practice', 'Where __________ your family __________ on the summer holiday last year?', 'do - go', 'does – go', 'did – go', 'did – went', 'C', 'Giải thích: Câu này là một câu hỏi trong thì quá khứ đơn, vì vậy cần sử dụng "did" để tạo câu hỏi và động từ chính phải ở dạng cơ bản. "Did" là trợ động từ dùng để hỏi về hành động đã xảy ra trong quá khứ, và "go" là dạng cơ bản của động từ "go," phù hợp với ngữ cảnh.\n(A) do – go (incorrect tense): "Do" là trợ động từ cho thì hiện tại, không phù hợp vì câu này cần thì quá khứ.\n(B) does – go (incorrect tense and subject-verb agreement): "Does" là trợ động từ cho thì hiện tại và không phù hợp vì câu này cần thì quá khứ.\n(D) did – went (incorrect verb form): "Went" là dạng quá khứ của động từ "go," nhưng khi sử dụng "did" để tạo câu hỏi, động từ chính phải ở dạng cơ bản "go."', 'Gia đình bạn đã đi đâu vào kỳ nghỉ hè năm ngoái?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_006', 'zenlish_practice', 'He had taught in this school before he (leave)____ for London.', 'left', 'leave', 'leaving', 'had left', 'A', 'Giải thích: Câu này sử dụng thì quá khứ hoàn thành (had taught) để mô tả một hành động đã xảy ra trước một thời điểm trong quá khứ khác (trước khi anh ấy rời đi). "Left" là dạng quá khứ của động từ "leave," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trước hành động khác trong quá khứ.\n(B) leave (v. base form, incorrect tense): "Leave" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ để mô tả hành động xảy ra trước một thời điểm trong quá khứ.\n(C) leaving (v. present participle): "Leaving" là dạng hiện tại phân từ, không phù hợp vì câu này cần thì quá khứ.\n(D) had left (incorrect tense for the second action): "Had left" là thì quá khứ hoàn thành, nhưng không phù hợp vì câu này chỉ cần thì quá khứ đơn cho hành động đã xảy ra trước một thời điểm khác trong quá khứ.', 'Anh ấy đã dạy ở trường này trước khi anh ấy rời đi London.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_007', 'zenlish_practice', 'She (win) ___ the gold medal in 1986.', 'win', 'won', 'to won', 'have win', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (cô ấy đã giành huy chương vàng vào năm 1986). "Won" là dạng quá khứ của động từ "win," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) win (v. base form): "Win" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) to won (incorrect form): "To won" là dạng không chính xác vì không phải là một dạng động từ hợp lệ trong tiếng Anh.\n(D) have win (incorrect tense): "Have win" là dạng hiện tại hoàn thành không đúng trong ngữ cảnh này, vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.', 'Cô ấy đã giành huy chương vàng vào năm 1986.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_008', 'zenlish_practice', 'I (study)__________ French when I was a child.', 'studies', 'study', 'studied', 'were studied', 'C', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (tôi đã học tiếng Pháp khi tôi còn là một đứa trẻ). "Studied" là dạng quá khứ của động từ "study," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) studies (v. present simple, incorrect tense): "Studies" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(B) study (v. base form, incorrect tense): "Study" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(D) were study (incorrect form): "Were study" là dạng không chính xác vì không phải là một dạng động từ hợp lệ trong tiếng Anh và không phù hợp với ngữ pháp của câu.', 'Tôi đã học tiếng Pháp khi tôi còn là một đứa trẻ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_009', 'zenlish_practice', 'Snow White was the daughter of a beautiful queen, who died when the girl (be) __________ young.', 'was', 'were', 'has been', 'is', 'A', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một trạng thái đã xảy ra và hoàn tất trong quá khứ (người mẹ đã chết khi cô gái còn trẻ). "Was" là dạng quá khứ của động từ "be," phù hợp với ngữ cảnh vì nó diễn tả một trạng thái trong quá khứ liên quan đến thời điểm khi Snow White còn nhỏ.\n(B) were (incorrect tense): "Were" là dạng quá khứ của động từ "be" cho số nhiều hoặc ngôi thứ hai, không phù hợp với ngôi số ít (cô gái).\n(C) has been (present perfect, incorrect tense): "Has been" là thì hiện tại hoàn thành, không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.\n(D) is (present simple, incorrect tense): "Is" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả trạng thái đã xảy ra trong quá khứ.', 'Snow White là con gái của một nữ hoàng xinh đẹp, người đã chết khi cô gái còn trẻ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0023_q_010', 'zenlish_practice', 'Ms. Helen ____ transferred to the Chicago branch last week.', 'is', 'will be', 'has been', 'was', 'D', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (Ms. Helen đã được chuyển đến chi nhánh Chicago tuần trước). "Was" là dạng quá khứ của động từ "be," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra và hoàn tất trong quá khứ.\n(A) is (present simple, incorrect tense): "Is" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(B) will be (future simple, incorrect tense): "Will be" là thì tương lai và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) has been (present perfect, incorrect tense): "Has been" là thì hiện tại hoàn thành, không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra và hoàn tất trong quá khứ.', 'Cô Helen đã được chuyển đến chi nhánh Chicago tuần trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_001', 'zenlish_practice', 'He ____ elected as vice president of our company in the last week’s meeting.', 'is', 'was', 'will be', 'were', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (anh ấy đã được bầu làm phó chủ tịch trong cuộc họp tuần trước). "Was" là dạng quá khứ của động từ "be," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ .\n(A) is (present simple, incorrect tense): "Is" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) will be (future simple, incorrect tense): "Will be" là thì tương lai và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(D) were (incorrect form): "Were" là dạng quá khứ của động từ "be" cho số nhiều hoặc ngôi thứ hai, không phù hợp với ngôi số ít (anh ấy).', 'Anh ấy đã được bầu làm phó chủ tịch của công ty chúng tôi trong cuộc họp tuần trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_002', 'zenlish_practice', 'The sales manager ____ our company six years ago.', 'will join', 'joined', 'joins', 'is joining', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (giám đốc bán hàng đã gia nhập công ty chúng tôi sáu năm trước). "Joined" là dạng quá khứ của động từ "join," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) will join (future simple, incorrect tense): "Will join" là thì tương lai và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) joins (present simple, incorrect tense): "Joins" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(D) is joining (present continuous, incorrect tense): "Is joining" là thì hiện tại tiếp diễn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.', 'Giám đốc bán hàng đã gia nhập công ty chúng tôi sáu năm trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_003', 'zenlish_practice', 'I ___________ to the cinema three times last week.', 'was go', 'went', 'did go', 'goed', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (tôi đã đi xem phim ba lần tuần trước). "Went" là dạng quá khứ của động từ "go," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) was go (incorrect form): "Was go" là dạng không chính xác vì không phải là một cấu trúc động từ hợp lệ trong tiếng Anh.\n(C) did go (correct form but less common): "Did go" là một cách chính xác để nhấn mạnh hành động trong quá khứ, nhưng không cần thiết trong câu này. Thì quá khứ đơn "went" là lựa chọn chính xác và tự nhiên hơn.\n(D) goed (incorrect form): "Goed" là dạng không chính xác vì không phải là một dạng hợp lệ của động từ "go."', 'Tôi đã đi xem phim ba lần tuần trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_004', 'zenlish_practice', 'The money ____ deposited in the bank last Friday.', 'was', 'is', 'has been', 'will be', 'A', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (tiền đã được gửi vào ngân hàng vào thứ Sáu tuần trước). "Was" là dạng quá khứ của động từ "be," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(B) is (present simple, incorrect tense): "Is" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) has been (present perfect, incorrect tense): "Has been" là thì hiện tại hoàn thành, không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.\n(D) will be (future simple, incorrect tense): "Will be" là thì tương lai và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.', 'Số tiền đã được gửi vào ngân hàng vào thứ Sáu tuần trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_005', 'zenlish_practice', 'Mozart ___________ more than 600 pieces of music.', 'writes', 'wrote', 'writed', 'was wrote', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (Mozart đã viết hơn 600 tác phẩm âm nhạc). "Wrote" là dạng quá khứ của động từ "write," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) writes (present simple, incorrect tense): "Writes" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) writed (incorrect form): "Writed" không phải là dạng hợp lệ của động từ "write." Dạng đúng là "wrote."\n(D) was wrote (incorrect form): "Was wrote" là một cấu trúc không chính xác vì không phải là một dạng hợp lệ trong tiếng Anh. Đúng cấu trúc là "wrote."', 'Mozart đã viết hơn 600 tác phẩm âm nhạc.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_006', 'zenlish_practice', 'The City Hall ____ constructed in 1945.', 'were', 'was', 'is', 'will be', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (Tòa thị chính đã được xây dựng vào năm 1945). "Was" là dạng quá khứ của động từ "be," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) were (incorrect form): "Were" là dạng quá khứ của động từ "be" cho số nhiều hoặc ngôi thứ hai, không phù hợp với ngôi số ít (tòa nhà).\n(C) is (present simple, incorrect tense): "Is" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(D) will be (future simple, incorrect tense): "Will be" là thì tương lai và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.', 'Tòa thị chính đã được xây dựng vào năm 1945.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_007', 'zenlish_practice', 'She _______ the first question but she _______ others.', 'answered / answered', 'answered / didn''t answer', 'was answer / answered', 'answered / not answer', 'B', 'Giải thích: Liên từ "but" thể hiện sự đối lập trong 2 vế câu nên vế sau phải chia ở dạng phủ định. Chỉ có "didn''t answer" là đúng ngữ pháp.\n(A) answered / answered (incorrect for negation): Cả hai hành động đều sử dụng "answered" mà không có phần phủ định cho hành động không xảy ra.\n(C) was answer / answered (incorrect form): "Was answer" là dạng không chính xác vì động từ "answer" không được chia theo cách này. "Answered" là dạng đúng cho hành động đã xảy ra.\n(D) answered / not answer (incorrect form): "Not answer" không phải là cấu trúc chính xác trong tiếng Anh để phủ định động từ. Đúng là "didn''t answer."', 'Cô ấy đã trả lời câu hỏi đầu tiên nhưng cô ấy không trả lời các câu hỏi khác.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_008', 'zenlish_practice', 'The window was open and a bird ___________ into the room.', 'fly', 'flew', 'was flew', 'did fly', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (một con chim đã bay vào phòng khi cửa sổ đang mở). "Flew" là dạng quá khứ của động từ "fly," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) fly (present simple, incorrect tense): "Fly" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) was flew (incorrect form): "Was flew" không phải là một cấu trúc hợp lệ trong tiếng Anh. Dạng đúng là "flew."\n(D) did fly (correct form but less common): "Did fly" là một cách chính xác để nhấn mạnh hành động trong quá khứ, nhưng không cần thiết trong câu này. Thì quá khứ đơn "flew" là lựa chọn chính xác và tự nhiên hơn.', 'Cửa sổ đã mở và một con chim đã bay vào phòng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_009', 'zenlish_practice', 'When I was three, I _______ to be an actor.', 'want', 'was want', 'wanted', 'did want', 'C', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một trạng thái hoặc mong muốn trong quá khứ (khi tôi ba tuổi, tôi đã muốn trở thành một diễn viên). "Wanted" là dạng quá khứ của động từ "want," phù hợp với ngữ cảnh vì nó diễn tả mong muốn đã xảy ra trong quá khứ.\n(A) want (present simple, incorrect tense): "Wa nt" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả mong muốn trong quá khứ.\n(B) was want (incorrect form): "Was want" không phải là cấu trúc hợp lệ trong tiếng Anh. Dạng đúng là "wanted."\n(D) did want (correct form but less common): "Did want" là một cách chính xác để nhấn mạnh mong muốn trong quá khứ, nhưng không cần thiết trong câu này. Thì quá khứ đơn "wanted" là lựa chọn chính xác và tự nhiên hơn.', 'Khi tôi ba tuổi, tôi đã muốn trở thành một diễn viên.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0024_q_010', 'zenlish_practice', 'I __________ a lot of money yesterday. I __________ an expensive dress.', 'spend / buy', 'spent / buy', 'spent / bought', 'was spent / bought', 'C', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả các hành động đã xảy ra và hoàn tất trong quá khứ (yesterday). "Spent" là dạng quá khứ của động từ "spend," và "bought" là dạng quá khứ của động từ "buy." Phần đầu câu mô tả việc tiêu tiền, và phần sau mô tả hành động mua sắm.\n(A) spend / buy (incorrect tense): "Spend" và "buy" đều là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả các hành động đã xảy ra trong quá khứ.\n(B) spent / buy (incorrect tense for second verb): "Spent" là dạng quá khứ của "spend," nhưng "buy" là thì hiện tại đơn, không phù hợp với ngữ cảnh vì câu cần thì quá khứ cho cả hai động từ.\n(D) was spent / bought: "Was spent" là dạng bị động, không đi với chủ ngữ "I"', 'Tôi đã tiêu rất nhiều tiền vào ngày hôm qua. Tôi đã mua một chiếc váy đắt tiền.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_001', 'zenlish_practice', 'He _______ his examination because he _______ very hard.', 'pass / study', 'past / was study', 'was past / studied', 'passed / studied', 'D', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả các hành động đã xảy ra và hoàn tất trong quá khứ. "Passed" là dạng quá khứ của động từ "pass," và "studied" là dạng quá khứ của động từ "study." Phần đầu câu mô tả việc vượt qua kỳ thi, và phần sau mô tả hành động học tập chăm chỉ.\n(A) pass / study (incorrect tense): "Pass" và "study" đều là thì hiện tại đơn và cũng chưa chia theo chủ ngữ ngôi thứ ba số ít "he".\n(B) past / was study (incorrect form and tense): "Past" không phải là dạng đúng của động từ "pass," và "was study" sai ngữ pháp vì động từ to be không đi với động từ thường.\n(C) was past / studied (incorrect form): "Was past" không phải là cấu trúc đúng cho động từ "pass." Dạng đúng là "passed."', 'Anh ấy đã vượt qua kỳ thi vì anh ấy đã học rất chăm chỉ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_002', 'zenlish_practice', 'Mattew ____________ his favourite TV program last night.', 'watches', 'was watched', 'watch', 'watched', 'D', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (Matthew đã xem chương trình TV yêu thích của mình vào tối qua). "Watched" là dạng quá khứ của động từ "watch," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) watches (present simple, incorrect tense): "Watches" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(B) was watched (incorrect form): "Was watched" là dạng bị động và không phù hợp với ngữ cảnh của câu vì hành động là do Matthew thực hiện, không phải bị thực hiện.\n(C) watch (present simple, incorrect tense): "Watch" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.', 'Matthew đã xem chương trình TV yêu thích của mình vào tối qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_003', 'zenlish_practice', 'Alex and Felix __________ fishing yesterday afternoon.', 'were go', 'are go', 'went', 'did went', 'C', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (Alex và Felix đã đi câu cá vào chiều hôm qua). "Went" là dạng quá khứ của động từ "go," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) were go (incorrect form): "Were go" không phải là cấu trúc hợp lệ trong tiếng Anh. Đúng cấu trúc là "went."\n(B) are go (present simple, incorrect tense): "Are go" là thì hiện tại và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(D) did went (incorrect form): "Did went" là một cấu trúc không chính xác vì khi dùng "did" trong câu hỏi hoặc phủ định thì phải sử dụng động từ gốc, không phải dạng quá khứ.', 'Alex và Felix đã đi câu cá vào chiều hôm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_004', 'zenlish_practice', 'The police ___________ me on my way home last night.', 'was stop', 'stopped', 'stops', 'stopping', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (cảnh sát đã dừng tôi trên đường về nhà tối qua). "Stopped" là dạng quá khứ của động từ "stop," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) was stop (incorrect form): "Was stop" không phải là cấu trúc hợp lệ trong tiếng Anh. Đúng cấu trúc là "stopped."\n(C) stops (present simple, incorrect tense): "Stops" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(D) stopping (present participle, incorrect form): "Stopping" là dạng hiện tại phân từ, không phù hợp với ngữ cảnh khi câu cần thì quá khứ.', 'Cảnh sát đã dừng tôi trên đường về nhà tối qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_005', 'zenlish_practice', 'Last Saturday, Ginger ___________ her room.', 'was cleaned', 'tidied', 'was vacuumed', 'tidies', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hành động đã xảy ra và hoàn tất trong quá khứ (Ginger đã dọn dẹp phòng của cô ấy vào thứ Bảy tuần trước). "Tidied" là dạng quá khứ của động từ "tidy," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) was cleaned (incorrect form): "Was cleaned" là dạng bị động, không phù hợp vì câu này yêu cầu động từ chủ động để mô tả hành động mà Ginger đã thực hiện.\n(C) was vacuumed (incorrect form): "Was vacuumed" cũng là dạng bị động và không phù hợp vì câu này yêu cầu động từ chủ động.\n(D) tidies (present simple, incorrect tense): "Tidies" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.', 'Hôm thứ Bảy tuần trước, Ginger đã dọn dẹp phòng của cô ấy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_006', 'zenlish_practice', 'First she _________ the phone and then she ________ down the message.', 'answered / wrote', 'answered / is writing', 'answers / wrote', 'right now', 'A', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả hai hành động đã xảy ra liên tiếp trong quá khứ (cô ấy đã trả lời điện thoại trước tiên và sau đó đã viết lại tin nhắn). "Answered" là dạng quá khứ của động từ "answer," và "wrote" là dạng quá khứ của động từ "write," phù hợp với ngữ cảnh vì cả hai hành động đều xảy ra trong quá khứ.\n(B) answered / is writing (incorrect tense for second verb): "Is writing" là thì hiện tại tiếp diễn, không phù hợp vì câu này cần thì quá khứ cho cả hai động từ.\n(C) answers / wrote (incorrect tense for first verb): "Answers" là thì hiện tại đơn, không phù hợp vì câu này cần thì quá khứ cho cả hai động từ.\n(D) right now (incorrect option): "Right now" không phải là một sự lựa chọn đúng cho động từ trong câu này.', 'Trước tiên cô ấy đã trả lời điện thoại và sau đó cô ấy đã viết lại tin nhắn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_007', 'zenlish_practice', 'What ______ you ___________ for lunch?', 'did / have', 'did / had', 'were / have', 'are / had', 'A', 'Giải thích: Câu này sử dụng thì quá khứ đơn để hỏi về hành động đã xảy ra trong quá khứ (bạn đã ăn gì cho bữa trưa?). "Did" được sử dụng để tạo câu hỏi trong thì quá khứ đơn, và "have" là dạng gốc của động từ "have," phù hợp với cấu trúc của câu hỏi.\n(B) did / had (incorrect tense for second verb): "Had" là dạng quá khứ của "have," nhưng khi sử dụng "did" để tạo câu hỏi trong thì quá khứ, chúng ta phải dùng động từ gốc "have" thay vì "had."\n(C) were / have (incorrect auxiliary verb): "Were" không phù hợp trong câu hỏi này vì nó thường được dùng trong thì tiếp diễn hoặc bị động, trong khi câu hỏi này cần thì quá khứ đơn với "did."\n(D) are / had (incorrect tense and auxiliary verb): "Are" là thì hiện tại và "had" là dạng quá khứ, nhưng không phù hợp với cấu trúc của câu hỏi về hành động trong quá khứ.', 'Bạn đã ăn gì cho bữa trưa?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_008', 'zenlish_practice', 'Philip and Robert ___________ hide and seek when they were little.', 'plays', 'played', 'were play', 'were played', 'B', 'Giải thích: Câu này sử dụng thì quá khứ đơn để mô tả một hoạt động đã xảy ra và hoàn tất trong quá khứ (Philip và Robert đã chơi trốn tìm khi còn nhỏ). "Played" là dạng quá khứ của động từ "play," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) plays (present simple, incorrect tense): "Plays" là thì hiện tại đơn, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) were play (incorrect form): "Were play" không phải là cấu trúc hợp lệ trong tiếng Anh. Đúng cấu trúc là "played."\n(D) were played (incorrect form): "Were played" là dạng bị động và không phù hợp vì câu này yêu cầu động từ chủ động để mô tả hành động mà Philip và Robert đã thực hiện.', 'Philip và Robert đã chơi trò trốn tìm khi họ còn nhỏ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_009', 'zenlish_practice', 'The boy had a narrow escape when he ______ across the road in front of the bus.', 'runs', 'run', 'running', 'ran', 'D', 'Giải thích: Hành động "chạy" và "had a narrow escape" cùng xảy ra trong quá khứ (cậu bé đã chạy qua đường trước khi chiếc xe buýt đến). "Ran" là dạng quá khứ của động từ "run," phù hợp với ngữ cảnh vì nó diễn tả hành động đã xảy ra trong quá khứ.\n(A) runs (v. present simple, incorrect tense): "Runs" là thì hiện tại đơn và không phù hợp vì câu này cần thì quá khứ đơn để mô tả hành động đã xảy ra trong quá khứ.\n(B) run (v. base form): "Run" là dạng cơ bản của động từ, không phù hợp vì câu này cần thì quá khứ để diễn tả hành động đã xảy ra trong quá khứ.\n(C) running (v. present participle): "Running" là dạng hiện tại phân từ, không phù hợp vì câu này cần thì quá khứ đơn.', 'Cậu bé đã thoát hiểm trong gang tấc khi cậu chạy qua đường trước mặt chiếc xe buýt.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0025_q_010', 'zenlish_practice', 'Ms. Rodriguez will speak about a banking conference she ________ in Lisbon last month.', 'attends', 'attended', 'will attend', 'attend', 'B', 'Giải thích: "Attended" là động từ quá khứ đơn, phù hợp vì câu đang nói về một sự kiện đã xảy ra trong quá khứ "last month"\n(A) attends (present simple): "attends" là thì hiện tại đơn, không phù hợp vì sự kiện đã diễn ra trong quá khứ.\n(C) will attend (future tense): "will attend" là thì tương lai, không phù hợp với ngữ cảnh nói về một sự kiện đã xảy ra.\n(D) attend (bare infinitive): "attend" là dạng động từ nguyên thể, không đúng ngữ pháp trong câu này.', 'Bà Rodriguez sẽ nói về một hội nghị ngân hàng mà bà ấy đã tham dự ở Lisbon vào tháng trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_001', 'zenlish_practice', 'When Paxton Enterprises _____ its textile division, several middle managers were laid off.', 'were restructured', 'restructures', 'was restructuring', 'to restructure', 'C', 'Giải thích: When + quá khứ tiếp diễn dùng để diễn tả một quá trình đang diễn ra trong quá khứ, trong lúc đó một sự việc khác xảy ra.\n(A) were restructured: bị động + số nhiều → sai chủ ngữ\n(B) restructures: hiện tại đơn → không phù hợp vì mệnh đề sau ở quá khứ\n(D) to restructure: to V → không thể đứng sau when', 'Khi Paxton Enterprises tái cấu trúc bộ phận dệt may của mình, một số quản lý cấp trung đã bị sa thải.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_002', 'zenlish_practice', 'While I ____ to work, I saw an accident.', 'be driving', 'am driving', 'was driving', 'are driving', 'C', 'Giải thích: While thường đi với quá khứ tiếp diễn để diễn tả một hành động đang diễn ra thì một hành động khác xen vào. was driving = hành động đang diễn ra; saw = hành động xen vào\n(A) be driving (incorrect form): "Be driving" không phải là cấu trúc đúng trong thì quá khứ. Đúng cấu trúc là "was driving."\n(B) am driving (present continuous, incorrect tense): "Am driving" là thì hiện tại tiếp diễn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(D) are driving (present continuous, incorrect tense): "Are driving" là thì hiện tại tiếp diễn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.', 'Khi tôi đang lái xe đến nơi làm việc, tôi đã thấy một vụ tai nạn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_003', 'zenlish_practice', 'My mom ____ in the sea when she saw a dolphin.', 'was swimming', 'was swiming', 'were swimming', 'were swiming', 'A', 'Giải thích: Câu này sử dụng thì quá khứ tiếp diễn để mô tả một hành động đang xảy ra trong quá khứ (mẹ tôi đang bơi trong biển khi bà thấy một con cá heo). "Was swimming" là dạng quá khứ tiếp diễn của động từ "swim," phù hợp với ngữ cảnh vì nó diễn tả hành động đang xảy ra khi một sự kiện khác xảy ra.\n(B) was swiming (incorrect spelling): "Swiming" là cách viết sai của "swimming." Đúng cấu trúc là "was swimming."\n(C) were swimming (incorrect subject agreement): "Were swimming" là dạng quá khứ tiếp diễn cho chủ ngữ số nhiều hoặc "you," không phù hợp với chủ ngữ số ít "my mom."\n(D) were swiming (incorrect form and spelling): "Were swiming" là dạng sai về cả thì và cách viết. Đúng cấu trúc là "was swimming."', 'Mẹ tôi đang bơi trong biển khi bà thấy một con cá heo.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_004', 'zenlish_practice', 'What did you watch on TV while you _____ dinner yesterday?', 'were having', 'was having', 'had', 'are having', 'A', 'Giải thích: Câu này sử dụng thì quá khứ tiếp diễn sau While để mô tả một hành động đang xảy ra trong quá khứ (bạn đã xem gì trên TV khi bạn đang ăn tối hôm qua). "Were having" là dạng quá khứ tiếp diễn của động từ "have," phù hợp với ngữ cảnh vì nó diễn tả hành động đang xảy ra khi một sự kiện khác xảy ra.\n(B) was having: sai vì chủ ngữ là you → phải dùng were\n(C) had: quá khứ đơn, không nhấn mạnh hành động đang diễn ra\n(D) are having: hiện tại tiếp diễn, không phù hợp với yesterday', 'Bạn đã xem gì trên TV khi bạn đang ăn tối hôm qua?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_005', 'zenlish_practice', '____ it ____ when you woke up this morning?', 'Is….raining', 'Was ….. raining', 'Is….rain', 'Were…… raining', 'B', 'Giải thích: Câu này sử dụng thì quá khứ tiếp diễn để hỏi về thời tiết đang xảy ra vào một thời điểm trong quá khứ (when you woke up). "Was raining" là dạng quá khứ tiếp diễn của động từ "rain," phù hợp với ngữ cảnh vì nó diễn tả thời tiết đang xảy ra trong quá khứ.\n(A) Is/raining (incorrect tense): "Is raining" là thì hiện tại tiếp diễn và không phù hợp vì câu này cần thì quá khứ để hỏi về thời tiết trong quá khứ.\n(C) Is/rain (incorrect tense): "Is rain" là thì hiện tại và không phù hợp vì câu này cần thì quá khứ để hỏi về thời tiết trong quá khứ.\n(D) Were/raining (incorrect subject agreement): "Were raining" là dạng quá khứ tiếp diễn cho chủ ngữ số nhiều hoặc "you," không phù hợp với chủ ngữ số ít "it."', 'Trời có đang mưa khi bạn tỉnh dậy vào sáng nay không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_006', 'zenlish_practice', 'My brother ______ in Ireland when he met his girlfriend.', 'study', 'was studying', 'were study', 'was study', 'B', 'Giải thích: Câu này sử dụng thì quá khứ tiếp diễn để mô tả một hành động đang xảy ra trong quá khứ (anh trai của tôi đang học ở Ireland khi anh ấy gặp bạn gái của mình). "Was studying" là dạng quá khứ tiếp diễn của động từ "study," phù hợp với ngữ cảnh vì nó diễn tả hành động đang xảy ra khi một sự kiện khác xảy ra.\n(A) study (incorrect tense): "Study" là thì hiện tại đơn, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) were study (incorrect form): "Were study" sai vì động từ to be không đi với động từ thường.\n(D) was study (incorrect form): "Was study" sai vì động từ to be không đi với động từ thường.', 'Anh trai của tôi đang học ở Ireland khi anh ấy gặp bạn gái của mình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_007', 'zenlish_practice', 'My dad found some money while he_____ his suitcase.', 'packing', 'package', 'are packing', 'was packing', 'D', 'Giải thích: Câu này sử dụng thì quá khứ tiếp diễn để mô tả một hành động đang xảy ra trong quá khứ (bố tôi đã tìm thấy một số tiền trong khi ông ấy đang đóng gói vali). "Was packing" là dạng quá khứ tiếp diễn của động từ "pack," phù hợp với ngữ cảnh vì nó diễn tả hành động đang xảy ra khi một sự kiện khác xảy ra.\n(A) packing (incorrect form): "Packing" là dạng hiện tại phân từ hoặc danh động từ, không đủ để tạo thành câu hoàn chỉnh khi cần thì quá khứ tiếp diễn.\n(B) package (incorrect form): "Package" là động từ trong thì hiện tại, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) are packing (incorrect tense): "Are packing" là thì hiện tại tiếp diễn, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.', 'Bố tôi đã tìm thấy một số tiền trong khi ông ấy đang đóng gói vali.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_008', 'zenlish_practice', 'My grandma tried pizza for the first time while she _____ in Italy.', 'staying', 'is staying', 'is stayed', 'was staying', 'D', 'Giải thích: Câu này sử dụng thì quá khứ tiếp diễn để mô tả một hành động đang xảy ra trong quá khứ (bà tôi đã thử pizza lần đầu tiên trong khi bà đang ở Italy). "Was staying" là dạng quá khứ tiếp diễn của động từ "stay," phù hợp với ngữ cảnh vì nó diễn tả hành động đang xảy ra khi một sự kiện khác xảy ra.\n(A) staying (incorrect form): "Staying" là dạng hiện tại phân từ hoặc danh động từ, không đủ để tạo thành câu hoàn chỉnh khi cần thì quá khứ tiếp diễn.\n(B) is staying (incorrect tense): "Is staying" là thì hiện tại tiếp diễn, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) is stayed (incorrect form): "Is stayed" không phải là dạng hợp lệ của động từ "stay" và cũng không phù hợp với thì quá khứ.', 'Bà tôi đã thử pizza lần đầu tiên trong khi bà đang ở Italy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_009', 'zenlish_practice', 'Sharon was chatting on her cell phone while her mother ____ dinner and her father was reading the newspaper.', 'is making', 'was making', 'making', 'were making', 'B', 'Giải thích: Câu này liệt kê 3 hành động cùng xảy ra trong quá khứ (Sharon đang trò chuyện trên điện thoại di động trong khi mẹ cô ấy đang nấu ăn và bố cô ấy đang đọc báo).\n(A) is making (incorrect tense): "Is making" là thì hiện tại tiếp diễn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(C) making (incorrect form): "Making" là dạng hiện tại phân từ hoặc danh động từ, không đủ để tạo thành câu hoàn chỉnh khi cần thì quá khứ tiếp diễn.\n(D) were making (incorrect subject agreement): "Were making" là dạng quá khứ tiếp diễn cho chủ ngữ số nhiều hoặc "you," không phù hợp với chủ ngữ số ít "her mother."', 'Sharon đang trò chuyện trên điện thoại di động trong khi mẹ cô ấy đang nấu ăn và bố cô ấy đang đọc báo.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0026_q_010', 'zenlish_practice', 'When the police asked Nick where he was at 2 a .m. last night, he said he ____ .', 'is sleeping', 'sleeping', 'will be sleeping', 'was sleeping', 'D', 'Giải thích: Câu này sử dụng thì quá khứ tiếp diễn để mô tả hành động đang xảy ra tại một thời điểm cụ thể trong quá khứ (lúc 2 giờ sáng hôm qua).\n(A) is sleeping (incorrect tense): "Is sleeping" là thì hiện tại tiếp diễn và không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(B) sleeping (incorrect form): "Sleeping" là dạng hiện tại phân từ hoặc danh động từ, không đủ để tạo thành câu hoàn chỉnh khi cần thì quá khứ tiếp diễn.\n(C) will be sleeping (incorrect tense): "Will be sleeping" là thì tương lai tiếp diễn, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.', 'Khi cảnh sát hỏi Nick anh ấy đang ở đâu lúc 2 giờ sáng hôm qua, anh ấy nói rằng anh ấy đang ngủ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_001', 'zenlish_practice', 'She ____ on her report when the fire took place.', 'worked', 'was working', 'has worked', 'is working', 'B', 'Giải thích: Câu này sử dụng thì quá khứ tiếp diễn để mô tả một hành động đang xảy ra trong quá khứ (đang làm báo cáo) thì một hành động khác xen vào (xảy ra vụ hỏa hoạn).\n(A) worked (incorrect tense): "Worked" là thì quá khứ đơn, không phù hợp vì câu này cần thì quá khứ tiếp diễn để mô tả một hành động đang xảy ra khi một sự kiện khác xảy ra.\n(C) has worked (incorrect tense): "Has worked" là thì hiện tại hoàn thành, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.\n(D) is working (incorrect tense): "Is working" là thì hiện tại tiếp diễn, không phù hợp vì câu này cần thì quá khứ để mô tả hành động đã xảy ra trong quá khứ.', 'Cô ấy đang làm việc trên báo cáo khi vụ hỏa hoạn xảy ra.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_002', 'zenlish_practice', 'My brother and sister ____ playing tennis at 11 am yesterday.', 'were', 'are', 'will be', 'was', 'A', 'Giải thích: Trong câu này, "yesterday" là một dấu hiệu chỉ thời gian trong quá khứ. "At 11 am" cũng chỉ một thời điểm cụ thể trong quá khứ. Vì chủ ngữ "My brother and sister" là số nhiều (hai người), động từ cần phải ở dạng quá khứ tiếp diễn và phải chia cho ngôi thứ ba số nhiều, do đó "were" là lựa chọn đúng.\n(B) are (v.): "are" có nghĩa là "thì, là, ở" dùng ở hiện tại, không phù hợp với mốc thời gian trong quá khứ "yesterday".\n(C) will be (v.): "will be" là dạng tương lai đơn, không phù hợp vì câu hỏi yêu cầu thì quá khứ.\n(D) was (v.): "was" là dạng quá khứ của "be" nhưng dùng cho ngôi thứ ba số ít, không phù hợp vì chủ ngữ là số nhiều.', 'Anh trai và chị gái của tôi đang chơi tennis lúc 11 giờ sáng hôm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_003', 'zenlish_practice', 'It ____ and cloudy when we left Ireland.', 'was rain', 'was raining', 'is raining', 'raining', 'B', 'Giải thích: Trong câu này, "when we left Ireland" là mệnh đề chỉ hành động trong quá khứ. Để mô tả hành động đang xảy ra tại một thời điểm trong quá khứ, chúng ta sử dụng thì quá khứ tiếp diễn. "Was raining" là động từ ở dạng quá khứ tiếp diễn, diễn tả hành động "đang mưa" và phù hợp với ngữ pháp của câu.\n(A) was rain (v.): "was rain" là cấu trúc sai, vì "rain" là danh từ hoặc động từ nguyên thể và không thể kết hợp trực tiếp với "was". Để mô tả hành động, cần dùng "raining" (danh động từ).\n(C) is raining (v.): "is raining" là dạng hiện tại tiếp diễn, không phù hợp vì câu đang ở thì quá khứ.\n(D) raining (v.): "raining" không có động từ "to be" đứng trước, vì vậy cấu trúc không hoàn chỉnh và không đúng ngữ pháp.', 'Trời đang mưa và có mây khi chúng tôi rời Ireland.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_004', 'zenlish_practice', 'Our CEO ____ an important workshop at this time yesterday.', 'will be attending', 'was attending', 'attended', 'is attended', 'B', 'Giải thích: Trong câu này, "at this time yesterday" là một dấu hiệu chỉ thời gian trong quá khứ, yêu cầu sử dụng thì quá khứ tiếp diễn để diễn tả một hành động đang xảy ra tại một thời điểm cụ thể trong quá khứ. "Was attending" là dạng quá khứ tiếp diễn, phù hợp với ngữ pháp và nghĩa của câu.\n(A) will be attending (v.): "will be attending" là dạng tương lai tiếp diễn, không phù hợp vì câu yêu cầu thì quá khứ.\n(C) attended (v.): "attended" là động từ ở dạng quá khứ đơn, không thể hiện được hành động đang diễn ra tại một thời điểm cụ thể trong quá khứ.\n(D) is attended (v.): "is attended" là dạng bị động của động từ "attend" ở thì hiện tại đơn, không phù hợp vì câu cần thì quá khứ và không cần dạng bị động.', 'Giám đốc điều hành của chúng tôi đang tham dự một hội thảo quan trọng vào thời điểm này hôm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_005', 'zenlish_practice', 'Ms Thomas ____ in the new employee development session at 3 o’clock yesterday.', 'participates', 'participate', 'is participating', 'was participating', 'D', 'Giải thích: Trong câu này, "at 3 o’clock yesterday" là một dấu hiệu chỉ thời gian trong quá khứ, yêu cầu sử dụng thì quá khứ tiếp diễn để diễn tả một hành động đang xảy ra tại một thời điểm cụ thể trong quá khứ. "Was participating" là động từ ở dạng quá khứ tiếp diễn, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) participates (v.): "participates" là dạng hiện tại đơn, không phù hợp vì câu yêu cầu thì quá khứ.\n(B) participate (v.): "participate" là động từ nguyên mẫu hoặc dạng không chia, không phù hợp với ngữ pháp của câu.\n(C) is participating (v.): "is participating" là dạng hiện tại tiếp diễn, không phù hợp vì câu yêu cầu thì quá khứ.', 'Bà Thomas đang tham gia buổi phát triển nhân viên mới lúc 3 giờ chiều hôm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_006', 'zenlish_practice', 'The man ____ his letter in the post office at that time yesterday.', 'is sending', 'was sending', 'sending', 'was senting', 'B', 'Giải thích: Trong câu này, "at that time yesterday" là một dấu hiệu chỉ thời gian trong quá khứ, yêu cầu sử dụng thì quá khứ tiếp diễn để diễn tả một hành động đang xảy ra tại một thời điểm cụ thể trong quá khứ. "Was sending" là động từ ở dạng quá khứ tiếp diễn, phù hợp với ngữ pháp và nghĩa của câu.\n(A) is sending (v.): "is sending" là dạng hiện tại tiếp diễn, không phù hợp vì câu yêu cầu thì quá khứ.\n(C) sending (v.): "sending" không có động từ "to be" đứng trước, vì vậy cấu trúc không hoàn chỉnh và không đúng ngữ pháp.\n(D) was senting (v.): "Senting" không phải là một từ đúng ngữ pháp.', 'Người đàn ông đang gửi thư của mình ở bưu điện vào thời điểm đó hôm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_007', 'zenlish_practice', 'Some useful ideas were suggested while the social committee was ____ the club’s programme for the coming season.', 'discussing', 'discussed', 'be discussing', 'discusses', 'A', 'Giải thích: Trong câu này, "was" là động từ to be ở thì quá khứ tiếp diễn, theo sau bởi một động từ dạng V-ing để diễn tả hành động đang xảy ra tại một thời điểm trong quá khứ. "Discussing" là dạng đúng của động từ "discuss" khi đi kèm với "was" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ pháp của câu.\n(B) discussed (v.): "discussed" là động từ ở dạng quá khứ đơn hoặc quá khứ phân từ, không phù hợp vì câu yêu cầu thì quá khứ tiếp diễn.\n(C) be discussing (v.): "was" không đi với động từ nguyên mẫu "be".\n(D) discusses (v.): "discusses" là dạng hiện tại đơn, không phù hợp vì câu yêu cầu thì quá khứ.', 'Một số ý tưởng hữu ích đã được đề xuất trong khi ủy ban xã hội đang thảo luận về chương trình của câu lạc bộ cho mùa tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_008', 'zenlish_practice', 'We _______________ down when we saw the woman.', 'walked', 'were walkes', 'were walking', 'walking', 'C', 'Giải thích: Trong câu này, "when we saw the woman" chỉ một hành động xảy ra tại một thời điểm cụ thể trong quá khứ. "Were walking" là dạng quá khứ tiếp diễn, diễn tả hành động đang diễn ra trước khi hành động khác xen vào (saw the woman).\n(A) walked (v.): "walked" là dạng quá khứ đơn, diễn tả một hành động hoàn thành trong quá khứ, nhưng không thể hiện được hành động đang xảy ra tại thời điểm gặp người phụ nữ.\n(B) were walkes (v.): "walkes" không phải là một từ đúng ngữ pháp.\n(D) walking (v.): "walking" không có động từ "to be" đứng trước, vì vậy cấu trúc không hoàn chỉnh và không đúng ngữ pháp.', 'Chúng tôi đang đi bộ thì nhìn thấy người phụ nữ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_009', 'zenlish_practice', 'While Ms Montello was at one meeting, her assistant was ____ another one for her.', 'arrangement', 'arranging', 'arranged', 'arrange', 'B', 'Giải thích: Trong câu này, "was" là động từ to be ở thì quá khứ tiếp diễn, theo sau bởi một động từ dạng V-ing để diễn tả hành động đang xảy ra tại một thời điểm trong quá khứ. "Arranging" là dạng đúng của động từ "arrange" khi đi kèm với "was" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ pháp của câu.\n(A) arrangement (n.): "arrangement" là danh từ, có nghĩa là "sự sắp xếp," không phù hợp vì câu yêu cầu một động từ.\n(C) arranged (v.): "arranged" là động từ ở dạng quá khứ đơn hoặc quá khứ phân từ, không phù hợp vì câu yêu cầu thì quá khứ tiếp diễn.\n(D) arrange (v.): "arrange" là động từ nguyên mẫu, không phù hợp vì cần dạng V-ing để kết hợp với "was."', 'Trong khi bà Montello đang ở một cuộc họp, trợ lý của bà ấy đang sắp xếp một cuộc họp khác cho bà.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0027_q_010', 'zenlish_practice', 'I ___________________ TV when I ____________ a loud noise', 'was watching / was hearing', 'watched / was hearing', 'watched / heard', 'was watching / heard', 'D', 'Giải thích: Hành động "xem TV" đang xảy ra thì hành động "nghe thấy tiếng ồn lớn" đột ngột xen vào nên động từ "xem TV" chia quá khứ tiếp diễn và "nghe thấy" chia ở thì quá khứ đơn.', 'Tôi đang xem TV thì nghe thấy một tiếng động lớn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_001', 'zenlish_practice', 'Mrs Adams was ___________ dinner at 6 o''clock yesterday morning.', 'has', 'had', 'have', 'having', 'D', 'Giải thích: Trong câu này, "was" là động từ to be ở thì quá khứ tiếp diễn, theo sau bởi một động từ dạng V-ing để diễn tả hành động đang diễn ra tại một thời điểm cụ thể trong quá khứ. "Having" là dạng đúng của động từ "have" khi đi kèm với "was" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ pháp của câu.\n(A) has (v.): "has" là dạng hiện tại đơn, không phù hợp với thì quá khứ của câu.\n(B) had (v.): "had" là động từ ở dạng quá khứ đơn, không diễn tả được hành động đang diễn ra tại một thời điểm cụ thể.\n(C) have (v.): "have" là động từ nguyên mẫu, không phù hợp vì cần dạng V-ing để kết hợp với "was."', 'Bà Adams đang ăn tối vào lúc 6 giờ sáng hôm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_002', 'zenlish_practice', 'I ____ to the professor when Julie came and interrupted us.', 'was speaking', 'is speaking', 'am speaking', 'will be speaking', 'A', 'Giải thích: Trong câu này, "was speaking" là dạng quá khứ tiếp diễn, diễn tả một hành động đang diễn ra trong quá khứ ("tôi đang nói chuyện với giáo sư") khi một hành động khác xen vào ("Julie đến và làm gián đoạn chúng tôi"). Thì quá khứ tiếp diễn là thích hợp nhất để diễn tả hành động đang diễn ra khi bị gián đoạn.\n(B) is speaking (v.): "is speaking" là dạng hiện tại tiếp diễn, không phù hợp với thì quá khứ của câu.\n(C) am speaking (v.): "am speaking" cũng là dạng hiện tại tiếp diễn, không phù hợp với ngữ cảnh quá khứ.\n(D) will be speaking (v.): "will be speaking" là dạng tương lai tiếp diễn, không phù hợp vì câu cần diễn tả hành động trong quá khứ.', 'Tôi đang nói chuyện với giáo sư thì Julie đến và làm gián đoạn chúng tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_003', 'zenlish_practice', 'What _________ Add and Helen __________ when you broke the glass?', 'are / doing', 'was / doing', 'were / doing', 'did / did', 'C', 'Giải thích: Trong câu này, "were doing" là dạng quá khứ tiếp diễn, diễn tả một hành động đang diễn ra trong quá khứ ("Add và Helen đang làm gì") khi một hành động khác xảy ra ("khi bạn làm vỡ chiếc ly"). Cấu trúc "were + V-ing" là phù hợp để diễn tả hành động đang diễn ra tại một thời điểm cụ thể trong quá khứ, với "were" được sử dụng vì chủ ngữ là số nhiều ("Add và Helen").\n(A) are / doing (v.): "are doing" là dạng hiện tại tiếp diễn, không phù hợp với ngữ cảnh quá khứ của câu.\n(B) was / doing (v.): "was" chỉ dùng cho chủ ngữ số ít, không phù hợp vì "Add và Helen" là số nhiều.\n(D) did / did (v.): "did" là dạng quá khứ đơn, không phù hợp với việc diễn tả hành động đang xảy ra khi bị gián đoạn.', 'Add và Helen đang làm gì khi bạn làm vỡ chiếc ly?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_004', 'zenlish_practice', 'At 3 a .m. last night, our neighbors ____loud music!', 'did still play', 'are still playing', 'were still playing', 'will be playing', 'C', 'Giải thích: Trong câu này, "At 3 a.m. last night" là dấu hiệu chỉ thời gian trong quá khứ, yêu cầu sử dụng thì quá khứ tiếp diễn để diễn tả hành động đang xảy ra tại một thời điểm cụ thể. "Were still playing" là dạng đúng của động từ "play" ở thì quá khứ tiếp diễn, diễn tả việc hàng xóm vẫn đang chơi nhạc lớn vào lúc 3 giờ sáng.\n(A) did still play (v.): "did still play" là cấu trúc sai vì "did" không được sử dụng để diễn tả hành động đang tiếp diễn trong quá khứ.\n(B) are still playing (v.): "are still playing" là dạng hiện tại tiếp diễn, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) will be playing (v.): "will be playing" là dạng tương lai tiếp diễn, không phù hợp vì câu cần diễn tả hành động trong quá khứ.', 'Vào lúc 3 giờ sáng hôm qua, hàng xóm của chúng tôi vẫn đang chơi nhạc lớn!', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_005', 'zenlish_practice', 'While I ___________________ for English test yesterday, my brother _____________ fun with his friends.', 'was studying / was having', 'studied / was having', 'was studied / had', 'was studying / was hasing', 'A', 'Giải thích: Câu này có hai hành động đang diễn ra song song tại một thời điểm trong quá khứ, vì vậy cần sử dụng thì quá khứ tiếp diễn cho cả hai động từ. "Was studying" diễn tả hành động "đang học" và "was having" diễn tả hành động "đang vui chơi," cả hai đều phù hợp với ngữ cảnh của câu.\n(B) studied / was having (v.): "studied" là quá khứ đơn, không phù hợp vì hành động "học" đang diễn ra song song với hành động "vui chơi" của người khác, cần sử dụng quá khứ tiếp diễn.\n(C) was studied / had (v.): "was studied" là dạng bị động sai, và "had" là quá khứ đơn, không phù hợp với ngữ cảnh.\n(D) was studying / was hasing (v.): "was hasing" là cấu trúc sai vì "hase" không phải là một động từ, đúng ra phải là "having."', 'Trong khi tôi đang học cho bài kiểm tra tiếng Anh hôm qua, anh trai tôi đang vui chơi với bạn bè của mình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_006', 'zenlish_practice', 'Pam was constantly ____about everybody. Nobody at the office trusted her!', 'gossipled', 'gossiping', 'be gossiping', 'gossip', 'B', 'Giải thích: Trong câu này, "was constantly" là một dấu hiệu chỉ việc xảy ra liên tục trong quá khứ và yêu cầu động từ dạng V-ing để diễn tả hành động đang xảy ra hoặc lặp đi lặp lại trong một khoảng thời gian cụ thể. "Gossiping" là dạng đúng của động từ "gossip" trong cấu trúc quá khứ tiếp diễn.\n(A) gossipled (v.): "gossipled" là dạng sai vì "gossip" không có dạng "gossipled."\n(C) be gossiping (v.): "be gossiping" là dạng không chia, không phù hợp với ngữ pháp của câu.\n(D) gossip (v.): "gossip" là động từ nguyên mẫu, không phù hợp vì cần dạng V-ing để kết hợp với "was."', 'Pam liên tục buôn chuyện về mọi người. Không ai ở văn phòng tin tưởng cô ấy!', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_007', 'zenlish_practice', 'While I ____ to your story, I remembered that my wife asked me to go to the mechanic to get out our car.', 'am listening', 'was listening', 'have been listening', 'listening', 'B', 'Giải thích: Trong câu này, "while" là dấu hiệu chỉ một hành động đang diễn ra tại một thời điểm cụ thể trong quá khứ. Để diễn tả hành động "nghe câu chuyện" đang diễn ra khi một hành động khác xảy ra ("nhớ ra vợ yêu cầu đi đến thợ sửa xe"), cần sử dụng thì quá khứ tiếp diễn. "Was listening" là dạng đúng của động từ "listen" trong cấu trúc quá khứ tiếp diễn.\n(A) am listening (v.): "am listening" là dạng hiện tại tiếp diễn, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) have been listening (v.): "have been listening" là dạng hiện tại hoàn thành tiếp diễn, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) listening (v.): "listening" không có động từ "to be" đứng trước, vì vậy cấu trúc không hoàn chỉnh và không đúng ngữ pháp.', 'Trong khi tôi đang lắng nghe câu chuyện của bạn, tôi nhớ ra rằng vợ tôi đã yêu cầu tôi đi đến thợ sửa xe để lấy xe của chúng tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_008', 'zenlish_practice', '______ they swimming when the phone rang?', 'Were', 'Are', 'Do', 'Did', 'A', 'Giải thích: Trong câu này, "when the phone rang" là dấu hiệu chỉ hành động xảy ra tại một thời điểm cụ thể trong quá khứ. Để diễn tả một hành động đang diễn ra trong quá khứ, câu hỏi cần sử dụng thì quá khứ tiếp diễn. "Were" là trợ động từ phù hợp cho chủ ngữ số nhiều ("they") trong cấu trúc câu hỏi ở thì quá khứ tiếp diễn.\n(B) Are (v.): "Are" là trợ động từ ở thì hiện tại, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) Do (v.): "Do" là trợ động từ ở thì hiện tại, không phù hợp với ngữ cảnh và không được dùng trong cấu trúc quá khứ tiếp diễn.\n(D) Did (v.): "Did" là trợ động từ ở thì quá khứ đơn, không phù hợp với việc diễn tả hành động đang diễn ra trong quá khứ.', 'Họ có đang bơi khi điện thoại reo không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_009', 'zenlish_practice', 'Yesterday, at six I ___________ dinner.', 'was preparing', 'was prepare', 'was prepared', 'did prepare', 'A', 'Giải thích: Trong câu này, "Yesterday, at six" là dấu hiệu chỉ một thời điểm cụ thể trong quá khứ, yêu cầu sử dụng thì quá khứ tiếp diễn để diễn tả hành động đang xảy ra tại thời điểm đó. "Was preparing" là dạng đúng của động từ "prepare" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ pháp của câu.\n(B) was prepare (v.): "was prepare" là cấu trúc sai vì "prepare" cần ở dạng V-ing (preparing) để phù hợp với "was."\n(C) was prepared (v.): "was prepared" là dạng quá khứ phân từ bị động, không phù hợp vì câu cần một động từ chủ động ở dạng V-ing.\n(D) did prepare (v.): "did prepare" là cấu trúc quá khứ đơn, không phù hợp với yêu cầu của câu là diễn tả hành động đang diễn ra.', 'Hôm qua, vào lúc sáu giờ, tôi đang chuẩn bị bữa tối.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0028_q_010', 'zenlish_practice', 'The girls __________ while the boys __________ around the garden.', 'were chatting / were running', 'talked / ran', 'were talking / was running', 'were chatting / ran', 'A', 'Giải thích: Trong câu này, hai hành động đang diễn ra song song tại cùng một thời điểm trong quá khứ, vì vậy cần sử dụng thì quá khứ tiếp diễn cho cả hai động từ. "Were chatting" diễn tả hành động "các cô gái đang nói chuyện" và "were running" diễn tả hành động "các cậu bé đang chạy," cả hai đều phù hợp với ngữ pháp và ngữ cảnh của câu.\n(B) talked / ran (v.): "talked" và "ran" đều là dạng quá khứ đơn, không diễn tả đúng hai hành động đang diễn ra đồng thời.\n(C) were talking / was running (v.): "were talking" phù hợp cho chủ ngữ số nhiều "the girls," nhưng "was running" không phù hợp vì chủ ngữ "the boys" là số nhiều, nên cần "were running."\n(D) were chatting / ran (v.): "were chatting" đúng, nhưng "ran" là quá khứ đơn, không diễn tả đúng hai hành động đang diễn ra đồng thời.', 'Các cô gái đang trò chuyện trong khi các cậu bé đang chạy quanh vườn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_001', 'zenlish_practice', 'Katie and Emma ____________ a picture when I entered the class.', 'was drawing', 'were drawing', 'drew', 'were drew', 'B', 'Giải thích: Trong câu này, "when I entered the class" chỉ một hành động xảy ra tại một thời điểm cụ thể trong quá khứ. Để diễn tả hành động "Katie và Emma đang vẽ một bức tranh" đang diễn ra khi hành động khác xảy ra, cần sử dụng thì quá khứ tiếp diễn. "Were drawing" là dạng đúng của động từ "draw" khi đi kèm với "Katie và Emma" (chủ ngữ số nhiều) trong cấu trúc quá khứ tiếp diễn.\n(A) was drawing (v.): "was drawing" không phù hợp vì "Katie and Emma" là chủ ngữ số nhiều, cần "were" thay vì "was."\n(C) drew (v.): "drew" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi một hành động khác xảy ra.\n(D) were drew (v.): "were drew" là cấu trúc sai, vì "drew" là dạng quá khứ đơn của "draw" và không phù hợp trong cấu trúc này.', 'Katie và Emma đang vẽ một bức tranh khi tôi bước vào lớp học.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_002', 'zenlish_practice', '. The students ______________ when the teacher entered the class.', 'were talk', 'talked', 'were talking', 'were talked', 'C', 'Giải thích: Trong câu này, "when the teacher entered the class" chỉ một hành động xảy ra tại một thời điểm cụ thể trong quá khứ. Để diễn tả hành động "các học sinh đang nói chuyện" đang diễn ra khi hành động khác xảy ra, cần sử dụng thì quá khứ tiếp diễn. "Were talking" là dạng đúng của động từ "talk" khi đi kèm với "the students" (chủ ngữ số nhiều) trong cấu trúc quá khứ tiếp diễn.\n(A) were talk (v.): "were talk" là cấu trúc sai vì "talk" cần ở dạng V-ing (talking) để phù hợp với "were."\n(B) talked (v.): "talked" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi một hành động khác xảy ra.\n(D) were talked (v.): "were talked" là cấu trúc sai vì "talked" là dạng quá khứ đơn và không phù hợp trong cấu trúc này.', 'Các học sinh đang nói chuyện khi giáo viên bước vào lớp học.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_003', 'zenlish_practice', 'I burnt my shirt while I ___________ it.', 'am ironing', 'was ironing', 'ironed', 'irons', 'B', 'Giải thích: Trong câu này, "while" chỉ ra rằng hai hành động xảy ra đồng thời, và "I burnt my shirt" là một hành động xảy ra tại một thời điểm cụ thể trong quá khứ khi một hành động khác đang diễn ra. Để diễn tả hành động "đang là áo" trong quá khứ khi sự cố xảy ra, cần sử dụng thì quá khứ tiếp diễn. "Was ironing" là dạng đúng của động từ "iron" trong cấu trúc này.\n(A) am ironing (v.): "am ironing" là dạng hiện tại tiếp diễn, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) ironed (v.): "ironed" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi một hành động khác xảy ra.\n(D) irons (v.): "irons" là dạng hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.', 'Tôi đã làm cháy áo sơ mi khi đang là nó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_004', 'zenlish_practice', 'The teacher was angry because some students ___________ football in the class when he came in.', 'are playing', 'played', 'have played', 'were playing', 'D', 'Giải thích: Trong câu này, "when he came in" chỉ một hành động xảy ra tại một thời điểm cụ thể trong quá khứ. Để diễn tả hành động "các học sinh đang chơi bóng" đang diễn ra khi giáo viên bước vào lớp, cần sử dụng thì quá khứ tiếp diễn. "Were playing" là dạng đúng của động từ "play" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) are playing (v.): "are playing" là dạng hiện tại tiếp diễn, không phù hợp với ngữ cảnh quá khứ của câu.\n(B) played (v.): "played" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi một hành động khác xảy ra.\n(C) have played (v.): "have played" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Giáo viên tức giận vì một số học sinh đang chơi bóng trong lớp khi thầy bước vào.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_005', 'zenlish_practice', 'My father ____________ the bushes in the garden while we ________________.', 'pruned / played', 'was pruning / were playing', 'prunes / played', 'were pruning / was playing', 'B', 'Giải thích: Trong câu này, cả hai hành động "pruning the bushes" (cắt tỉa cây) và "playing" (chơi) đang diễn ra đồng thời trong quá khứ. Để diễn tả hai hành động này xảy ra song song tại một thời điểm cụ thể trong quá khứ, cần sử dụng thì quá khứ tiếp diễn cho cả hai động từ. "Was pruning" và "were playing" đều là dạng quá khứ tiếp diễn phù hợp với ngữ cảnh và ngữ pháp của câu.\n(A) pruned / played (v.): "pruned" và "played" là dạng quá khứ đơn, không phù hợp để diễn tả hai hành động đang diễn ra song song.\n(C) prunes / played (v.): "prunes" là dạng hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu, và "played" là quá khứ đơn, không diễn tả được hành động đang diễn ra.\n(D) were pruning / was playing (v.): "were pruning" không phù hợp vì chủ ngữ "My father" là số ít, cần dùng "was pruning." Ngược lại, "was playing" không phù hợp với chủ ngữ "we" là số nhiều, cần dùng "were playing."', 'Bố tôi đang cắt tỉa cây trong vườn trong khi chúng tôi đang chơi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_006', 'zenlish_practice', 'My father __________ a novel while I _______ TV.', 'was read / was watching', 'were reading / was watching', 'read / watched', 'was reading / was watching', 'D', 'Giải thích: Trong câu này, cả hai hành động "reading a novel" (đọc tiểu thuyết) và "watching TV" (xem TV) đang diễn ra đồng thời tại một thời điểm cụ thể trong quá khứ. Để diễn tả hai hành động này xảy ra song song trong quá khứ, cần sử dụng thì quá khứ tiếp diễn cho cả hai động từ. "Was reading" và "was watching" đều là dạng quá khứ tiếp diễn phù hợp với ngữ cảnh và ngữ pháp của câu.\n(A) was read / was watching (v.): "was read" là cấu trúc sai, vì "read" ở đây cần ở dạng V-ing (reading) để kết hợp với "was."\n(B) were reading / was watching (v.): "were reading" không phù hợp vì chủ ngữ "My father" là số ít, cần dùng "was reading."\n(C) read / watched (v.): "read" và "watched" là dạng quá khứ đơn, không phù hợp để diễn tả hai hành động đang diễn ra đồng thời.', 'Bố tôi đang đọc tiểu thuyết trong khi tôi đang xem TV.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_007', 'zenlish_practice', 'My sister burnt her finger while she _______.', 'cooked', 'was cooking', 'cooks', 'was cook', 'B', 'Giải thích: Trong câu này, "while" là dấu hiệu chỉ ra rằng hành động "burnt her finger" (làm bỏng ngón tay) xảy ra trong quá khứ trong khi một hành động khác đang diễn ra. Để diễn tả hành động "đang nấu ăn" trong quá khứ khi sự cố xảy ra, cần sử dụng thì quá khứ tiếp diễn. "Was cooking" là dạng đúng của động từ "cook" trong cấu trúc này.\n(A) cooked (v.): "cooked" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi một hành động khác xảy ra.\n(C) cooks (v.): "cooks" là dạng hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) was cook (v.): "was cook" là cấu trúc sai vì "cook" cần ở dạng V-ing (cooking) để kết hợp với "was."', 'Chị tôi bị bỏng ngón tay khi đang nấu ăn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_008', 'zenlish_practice', 'I couldn''t watch the match because I __________ my homework at that time.', 'was do', 'was did', 'did', 'was doing', 'D', 'Giải thích: Trong câu này, "at that time" chỉ ra rằng hành động "doing my homework" đang diễn ra trong quá khứ khi một hành động khác (xem trận đấu) không thể thực hiện được. Để diễn tả hành động "đang làm bài tập" trong quá khứ, cần sử dụng thì quá khứ tiếp diễn. "Was doing" là dạng đúng của động từ "do" trong cấu trúc này.\n(A) was do (v.): "was do" là cấu trúc sai vì "do" cần ở dạng V-ing (doing) để kết hợp với "was."\n(B) was did (v.): "was did" là cấu trúc sai vì "did" là dạng quá khứ đơn và không kết hợp với "was."\n(C) did (v.): "did" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi một hành động khác không thể thực hiện được.', 'Tôi không thể xem trận đấu vì lúc đó tôi đang làm bài tập.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_009', 'zenlish_practice', 'My father _____________ the newspaper while my mother ____________ the floor.', 'was reading / was vacuuming', 'read / vacuumed', 'was read / was vacuuming', 'has read / has vacuumed', 'A', 'Giải thích: Trong câu này, cả hai hành động "reading the newspaper" (đọc báo) và "vacuuming the floor" (hút bụi sàn) đang diễn ra đồng thời tại một thời điểm cụ thể trong quá khứ. Để diễn tả hai hành động này xảy ra song song trong quá khứ, cần sử dụng thì quá khứ tiếp diễn cho cả hai động từ. "Was reading" và "was vacuuming" đều là dạng quá khứ tiếp diễn phù hợp với ngữ cảnh và ngữ pháp của câu.\n(B) read / vacuumed (v.): "read" và "vacuumed" đều là dạng quá khứ đơn, không phù hợp để diễn tả hai hành động đang diễn ra đồng thời.\n(C) was read / was vacuuming (v.): "was read" là dạng bị động sai, vì "read" cần ở dạng V-ing (reading) để kết hợp với "was."\n(D) has read / has vacuumed (v.): "has read" và "has vacuumed" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Bố tôi đang đọc báo trong khi mẹ tôi đang hút bụi sàn nhà.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0029_q_010', 'zenlish_practice', 'The kids _____________ in the garden when it suddenly started to rain.', 'played', 'playing', 'were playing', 'was playing', 'C', 'Giải thích: Trong câu này, "when it suddenly started to rain" chỉ một hành động xảy ra tại một thời điểm cụ thể trong quá khứ, yêu cầu diễn tả một hành động đang diễn ra trước đó. Để diễn tả hành động "các đứa trẻ đang chơi" khi mưa bất ngờ bắt đầu, cần sử dụng thì quá khứ tiếp diễn. "Were playing" là dạng đúng của động từ "play" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) played (v.): "played" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi một hành động khác xảy ra.\n(B) playing (v.): "playing" không có động từ "to be" đứng trước, vì vậy cấu trúc không hoàn chỉnh và không đúng ngữ pháp.\n(D) was playing (v.): "was playing" không phù hợp vì chủ ngữ "the kids" là số nhiều, cần dùng "were playing."', 'Các đứa trẻ đang chơi trong vườn thì bất ngờ trời bắt đầu mưa.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_001', 'zenlish_practice', 'While I ____________ in my room, my sister left home.', 'was studying', 'studied', 'study', 'have studied', 'A', 'Giải thích: Trong câu này, "While" là dấu hiệu chỉ ra rằng hai hành động xảy ra đồng thời trong quá khứ. Để diễn tả hành động "tôi đang học bài" khi một hành động khác xảy ra ("chị tôi rời khỏi nhà"), cần sử dụng thì quá khứ tiếp diễn. "Was studying" là dạng đúng của động từ "study" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ cảnh của câu.\n(B) studied (v.): "studied" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi một hành động khác xảy ra.\n(C) study (v.): "study" là dạng hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) have studied (v.): "have studied" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Trong khi tôi đang học bài trong phòng, chị tôi đã rời khỏi nhà.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_002', 'zenlish_practice', 'My mother ____________ the dished at six o''clock yesterday.', 'were washing', 'was washed', 'was washing', 'washes', 'C', 'Giải thích: Trong câu này, "at six o''clock yesterday" là dấu hiệu chỉ một thời điểm cụ thể trong quá khứ, yêu cầu sử dụng thì quá khứ tiếp diễn để diễn tả hành động đang xảy ra tại thời điểm đó. "Was washing" là dạng đúng của động từ "wash" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ pháp của câu.\n(A) were washing (v.): "were washing" không phù hợp vì chủ ngữ "My mother" là số ít, cần dùng "was" thay vì "were."\n(B) was washed (v.): "was washed" là dạng bị động, không phù hợp vì câu cần một động từ chủ động.\n(D) washes (v.): "washes" là dạng hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.', 'Mẹ tôi đang rửa bát vào lúc sáu giờ chiều hôm qua.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_003', 'zenlish_practice', '_______ you doing your homework at six o''clock last night?', 'are', 'did', 'have', 'were', 'D', 'Giải thích: Trong câu này, "at six o''clock last night" là dấu hiệu chỉ một thời điểm cụ thể trong quá khứ, yêu cầu sử dụng thì quá khứ tiếp diễn. Để đặt câu hỏi về một hành động đang diễn ra trong quá khứ, cần sử dụng "were" cho chủ ngữ số nhiều hoặc ngôi thứ hai số ít/số nhiều (you). "Were you doing" là cấu trúc đúng của động từ "do" trong thì quá khứ tiếp diễn.\n(A) Are (v.): "Are" là dạng hiện tại, không phù hợp với ngữ cảnh quá khứ của câu.\n(B) Did (v.): "Did" là dạng quá khứ đơn, không phù hợp với việc diễn tả hành động đang diễn ra trong quá khứ.\n(C) Have (v.): "Have" thường được dùng trong thì hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Bạn có đang làm bài tập về nhà vào lúc sáu giờ tối qua không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_004', 'zenlish_practice', 'Emma _____________ to work when I saw her.', 'walked', 'was walked', 'was walking', 'walks', 'C', 'Giải thích: Trong câu này, "when I saw her" chỉ một hành động xảy ra tại một thời điểm cụ thể trong quá khứ, yêu cầu diễn tả một hành động đang diễn ra trước đó. Để diễn tả hành động "Emma đang đi bộ đến chỗ làm" khi tôi nhìn thấy cô ấy, cần sử dụng thì quá khứ tiếp diễn. "Was walking" là dạng đúng của động từ "walk" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) walked (v.): "walked" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi một hành động khác xảy ra.\n(B) was walked (v.): "was walked" là dạng bị động sai, vì "walk" cần ở dạng V-ing (walking) để kết hợp với "was."\n(D) walks (v.): "walks" là dạng hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.', 'Emma đang đi bộ đến chỗ làm khi tôi nhìn thấy cô ấy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_005', 'zenlish_practice', 'Most of the time we __________ in the park.', 'were sat', 'sitting', 'was sitting', 'were sitting', 'D', 'Giải thích: Trong câu này, "Most of the time" có thể chỉ một hành động đang diễn ra liên tục trong quá khứ, yêu cầu sử dụng thì quá khứ tiếp diễn để diễn tả hành động này. "Were sitting" là dạng đúng của động từ "sit" trong cấu trúc quá khứ tiếp diễn, phù hợp với ngữ cảnh của câu.\n(A) were sat (v.): "were sat" là dạng bị động sai, vì "sit" cần ở dạng V-ing (sitting) để kết hợp với "were."\n(B) sitting (v.): "sitting" không có động từ "to be" đứng trước, vì vậy cấu trúc không hoàn chỉnh và không đúng ngữ pháp.\n(C) was sitting (v.): "was sitting" không phù hợp vì chủ ngữ "we" là số nhiều, cần dùng "were sitting."', 'Phần lớn thời gian, chúng tôi đang ngồi trong công viên.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_006', 'zenlish_practice', 'The teacher tried to explain but they __________.', 'were listening', 'weren''t listening', 'listened', 'have listened', 'B', 'Giải thích: Tried to explain (quá khứ) + but → diễn tả sự tương phản. Quá khứ tiếp diễn (weren’t listening) cho thấy tình trạng đang diễn ra tại thời điểm đó: họ không chú ý lắng nghe khi giáo viên đang giải thích.\n(A) were listening (v.): "were listening" là dạng quá khứ tiếp diễn khẳng định, không phù hợp vì câu yêu cầu thể phủ định.\n(C) listened (v.): "listened" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi hành động khác xảy ra.\n(D) have listened (v.): "have listened" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Giáo viên cố gắng giải thích nhưng họ không lắng nghe.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_007', 'zenlish_practice', 'My baby brother ______________ loudly so I couldn''t do my homework.', 'was cried', 'cried', 'was crying', 'has cried', 'C', 'Giải thích: Trong câu này, "so I couldn''t do my homework" chỉ ra rằng hành động "khóc" đang diễn ra trong quá khứ và gây cản trở cho việc làm bài tập. Để diễn tả hành động đang diễn ra trong quá khứ, cần sử dụng thì quá khứ tiếp diễn. "Was crying" là dạng đúng của động từ "cry" trong cấu trúc quá khứ tiếp diễn.\n(A) was cried (v.): "was cried" là cấu trúc bị động sai, vì "cry" cần ở dạng V-ing (crying) để kết hợp với "was."\n(B) cried (v.): "cried" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi hành động khác xảy ra.\n(D) has cried (v.): "has cried" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Em trai tôi đang khóc rất to nên tôi không thể làm bài tập.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_008', 'zenlish_practice', 'I broke that window while I ___________ the room.', 'was painting', 'was paint', 'painted', 'has painted', 'A', 'Giải thích: Trong câu này, "while" chỉ ra rằng hai hành động đang diễn ra đồng thời trong quá khứ. Để diễn tả hành động "tôi đang sơn phòng" khi hành động khác xảy ra (làm vỡ cửa sổ), cần sử dụng thì quá khứ tiếp diễn. "Was painting" là dạng đúng của động từ "paint" trong cấu trúc quá khứ tiếp diễn.\n(B) was paint (v.): "was paint" là cấu trúc sai vì "paint" cần ở dạng V-ing (painting) để kết hợp với "was."\n(C) painted (v.): "painted" là dạng quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra khi hành động khác xảy ra.\n(D) has painted (v.): "has painted" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Tôi đã làm vỡ cửa sổ khi đang sơn phòng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_009', 'zenlish_practice', 'I _________ a squirrel under a tree and it ____________ a nut in its mouth.', 'was seeing / was carrying', 'see / carried', 'saw / was carrying', 'was seeing / carried', 'C', 'Giải thích: Trong câu này, hành động "saw" (nhìn thấy) là một hành động xảy ra tại một thời điểm cụ thể trong quá khứ và được diễn tả bằng thì quá khứ đơn. Hành động "was carrying" (đang mang) là hành động đang diễn ra tại thời điểm đó, vì vậy cần sử dụng thì quá khứ tiếp diễn. Sự kết hợp giữa quá khứ đơn cho hành động chính (saw) và quá khứ tiếp diễn cho hành động đang diễn ra (was carrying) là phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) was seeing / was carrying (v.): "was seeing" không phù hợp vì "see" là động từ chỉ trạng thái và thường không sử dụng ở thì tiếp diễn.\n(B) see / carried (v.): "see" là dạng hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu, và "carried" là quá khứ đơn, không phù hợp để diễn tả hành động đang diễn ra.\n(D) was seeing / carried (v.): "was seeing" là cấu trúc sai, như đã giải thích ở trên.', 'Tôi đã nhìn thấy một con sóc dưới gốc cây và nó đang mang một hạt trong miệng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0030_q_010', 'zenlish_practice', 'Ms. Chor relayed her concerns about the company ''s financial situation while she _____ a meeting with the manager.', 'having', 'will have', 'was having', 'has', 'C', 'Giải thích: Trong câu này, cần một thì quá khứ tiếp diễn để mô tả hành động của Ms. Chor trong quá khứ khi bà đang tham dự một cuộc họp với quản lý. "Was having" là thì quá khứ tiếp diễn phù hợp, nghĩa là "đang tham dự," để chỉ rằng bà đã bày tỏ mối quan tâm trong khi cuộc họp đang diễn ra.\n(A) having (present participle): "Having" là dạng hiện tại phân từ, không đủ để diễn tả hành động đang xảy ra trong quá khứ.\n(B) will have (future simple): "Will have" có nghĩa là "sẽ có." Lý do không chọn là vì thì tương lai không phù hợp trong ngữ cảnh mô tả một hành động đã xảy ra trong quá khứ.\n(D) has (present simple): "Has" là thì hiện tại đơn. Lý do không chọn là vì thì hiện tại không phù hợp khi mô tả hành động trong quá khứ.', 'Bà Chor đã truyền đạt những mối quan tâm của mình về tình hình tài chính của công ty trong khi bà đang tham dự một cuộc họp với quản lý.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_001', 'zenlish_practice', 'Dr. Suzuki arrived for the awards ceremony on time even though her train _____ twenty minutes late.', 'is leaving', 'will leave', 'to leave', 'had left', 'D', 'Giải thích: "Had left" là động từ ở thì quá khứ hoàn thành, phù hợp với ngữ cảnh của câu khi nói về một sự kiện đã xảy ra trước một sự kiện khác trong quá khứ. Câu này nói rằng mặc dù tàu của Dr. Suzuki đã rời đi muộn 20 phút, bà ấy vẫn đến lễ trao giải đúng giờ .\n(A) is leaving (present continuous): "is leaving" là động từ ở thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của câu khi nói về sự việc đã xảy ra trong quá khứ.\n(B) will leave (future simple): "will leave" là động từ ở thì tương lai đơn, không phù hợp với ngữ cảnh của câu khi nói về sự việc đã xảy ra trong quá khứ.\n(C) to leave (infinitive): "to leave" là động từ nguyên mẫu, không phù hợp với ngữ pháp của câu.', 'Dr. Suzuki đã đến lễ trao giải đúng giờ mặc dù tàu của bà đã rời ga muộn 20 phút.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_002', 'zenlish_practice', 'The grocery store ______ vegetables from out of town until local prices went down last month.', 'is buying', 'will be buying', 'has been buying', 'had been buying', 'D', '"Đáp án đúng là:\n(D) had been buying Giải thích: Trong câu này, cần một thì quá khứ hoàn thành tiếp diễn để chỉ một hành động đã xảy ra và kéo dài trước một thời điểm trong quá khứ. ""Had been buying"" là thì quá khứ hoàn thành tiếp diễn, phù hợp với ngữ cảnh câu mô tả rằng cửa hàng tạp hóa đã mua rau từ ngoài thị trấn trước khi giá cả địa phương giảm xuống vào tháng trước.\n(A) is buying (present continuous): ""Is buying"" là thì hiện tại tiếp diễn, không phù hợp vì câu này nói về một hành động đã xảy ra trong quá khứ.\n(B) will be buying (future continuous): ""Will be buying"" là thì tương lai tiếp diễn, không phù hợp vì câu này cần một thì quá khứ.\n(C) has been buying (present perfect continuous): ""Has been buying"" là thì hiện tại hoàn thành tiếp diễn, không phù hợp vì câu này cần một thì quá khứ.', 'Cửa hàng tạp hóa đã mua rau từ ngoài thị trấn cho đến khi giá cả địa phương giảm xuống vào tháng trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_003', 'zenlish_practice', 'By the time the merger was announced, Trexler Co. ______ operating under its new name, Trexler-Compton, Inc.', 'begins', 'will begin', 'had begun', 'having begun', 'C', 'Giải thích: "Had begun" là thì quá khứ hoàn thành, phù hợp với ngữ cảnh diễn tả việc khi việc sáp nhập được công bố, Trexler Co. đã bắt đầu hoạt động dưới tên mới là Trexler-Compton, Inc.\n(A) begins (v.): "Begins" là động từ ở thì hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu này.\n(B) will begin (v.): "Will begin" là thì tương lai đơn, không phù hợp với ngữ cảnh của câu này.\n(D) having begun (phrase): "Having begun" là hiện tại hoàn thành phân từ, không phù hợp với cấu trúc ngữ pháp của câu này.', 'Khi việc sáp nhập được công bố, Trexler Co. đã bắt đầu hoạt động dưới tên mới là Trexler-Compton, Inc.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_004', 'zenlish_practice', 'The 10:17 A.M. train _____ already left before Mr.Abaki''s team arrived at the station.', 'has', 'had', 'is', 'will have', 'B', 'Giải thích: Câu này sử dụng thì quá khứ hoàn thành "had left" để diễn tả một hành động đã xảy ra và hoàn tất trước một thời điểm cụ thể trong quá khứ (trước khi đội của ông Abaki đến ga). Thì quá khứ hoàn thành được dùng để nhấn mạnh rằng hành động đã xảy ra trước một thời điểm hoặc hành động khác trong quá khứ.\n(A) has: Không đúng vì đây là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh của câu là một hành động đã hoàn tất trước một thời điểm trong quá khứ.\n(C) is: Không đúng vì đây là thì hiện tại, không phù hợp với ngữ cảnh của câu.\n(D) will have: Không đúng vì đây là thì tương lai hoàn thành, không phù hợp với việc mô tả một hành động đã xảy ra trong quá khứ.', 'Chuyến tàu lúc 10:17 sáng đã rời trước khi đội của ông Abaki đến ga.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_005', 'zenlish_practice', 'The farmer’s barn caught fire during the night. By the time the fire fighters arrived, the building ______ to the ground.', 'burned', 'had been burned', 'had burned', 'was burned', 'C', 'Giải thích: Trong câu này, "By the time the fire fighters arrived" chỉ ra rằng hành động xảy ra trước một hành động khác trong quá khứ. Để diễn tả hành động "tòa nhà đã bị cháy rụi" trước khi lính cứu hỏa đến, cần sử dụng thì quá khứ hoàn thành. "Had burned" là dạng đúng của động từ "burn" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) burned (v.): "burned" là dạng quá khứ đơn, không phù hợp để diễn tả một hành động xảy ra trước một hành động khác trong quá khứ.\n(B) had been burned (v.): bị động → không cần thiết, câu không nhấn mạnh tác nhân gây cháy\n(D) was burned (v.): "was burned" là dạng quá khứ đơn bị động, không phù hợp vì cần diễn tả hành động xảy ra trước trong quá khứ.', 'Chuồng của người nông dân bị cháy vào ban đêm. Khi lính cứu hỏa đến, tòa nhà đã bị cháy rụi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_006', 'zenlish_practice', 'Mrs. Pike ______ the door before the customers arrived .', 'has open', 'had opened', 'would opened', 'has opened', 'B', 'Giải thích: Trong câu này, "before the customers arrived" chỉ ra rằng hành động "mở cửa" xảy ra trước một hành động khác trong quá khứ. Để diễn tả hành động "bà Pike đã mở cửa" trước khi khách hàng đến, cần sử dụng thì quá khứ hoàn thành. "Had opened" là dạng đúng của động từ "open" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) has open (v.): "has open" là cấu trúc sai vì "has" cần đi kèm với quá khứ phân từ (opened).\n(C) would open (v.): "would open" là dạng tương lai trong quá khứ hoặc diễn tả thói quen trong quá khứ, không phù hợp với ngữ cảnh của câu.\n(D) has opened (v.): "has opened" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Bà Pike đã mở cửa trước khi khách hàng đến.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_007', 'zenlish_practice', 'Alexander Graham Bell ________ the telephone by the time I was born.', 'had already invented', 'has already invented', 'already invented', 'already invented', 'A', 'Giải thích: Trong câu này, "by the time I was born" chỉ ra rằng hành động "phát minh ra điện thoại" đã xảy ra trước một mốc thời gian cụ thể trong quá khứ (khi tôi sinh ra). Để diễn tả hành động này, cần sử dụng thì quá khứ hoàn thành. "Had already invented" là dạng đúng của động từ "invent" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(B) has already finished (v.): "has already finished" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu và không diễn tả được hành động "phát minh ra điện thoại."\n(C) already finished (v.): "already finished" không có trợ động từ "had" nên không đúng cấu trúc quá khứ hoàn thành.\n(D) already finish (v.): "already finish" là cấu trúc sai vì cần sử dụng "had already finished" cho cấu trúc quá khứ hoàn thành.', 'Alexander Graham Bell đã phát minh ra điện thoại trước khi tôi sinh ra.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_008', 'zenlish_practice', 'I ______ my document before the power went out in the computer lab.', 'had save', 'have saved', 'had saved', 'saved', 'C', 'Giải thích: Trong câu này, "before the power went out in the computer lab" chỉ ra rằng hành động "lưu tài liệu" đã xảy ra trước khi mất điện. Để diễn tả hành động này, cần sử dụng thì quá khứ hoàn thành. "Had saved" là dạng đúng của động từ "save" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) had save (v.): "had save" là cấu trúc sai vì cần sử dụng quá khứ phân từ "saved" thay vì "save."\n(B) have saved (v.): "have saved" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) saved (v.): "saved" là quá khứ đơn, không thể hiện được hành động xảy ra trước một hành động khác trong quá khứ.', 'Tôi đã lưu tài liệu của mình trước khi mất điện trong phòng máy tính.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_009', 'zenlish_practice', 'Doctor Pike left the hospital after he ____ an uneventful evening on duty. He was thinking of his day of rest.', 'has had', 'had been', 'will have', 'had had', 'D', 'Giải thích: Trong câu này, "after he" chỉ ra rằng hành động "có một buổi tối yên bình" đã xảy ra trước khi bác sĩ Pike rời khỏi bệnh viện. Để diễn tả hành động này, cần sử dụng thì quá khứ hoàn thành. "Had had" là dạng quá khứ hoàn thành của động từ "have," phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) has had (v.): "has had" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(B) had been (v.): "had been" là dạng quá khứ hoàn thành của "be," nhưng không phù hợp vì câu yêu cầu diễn tả việc "có" (have) một buổi tối yên bình.\n(C) will have (v.): "will have" là dạng tương lai đơn, không phù hợp với ngữ cảnh quá khứ của câu.', 'Bác sĩ Pike rời bệnh viện sau khi đã có một buổi tối yên bình trực ca. Ông đang nghĩ đến ngày nghỉ của mình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0031_q_010', 'zenlish_practice', 'He ____email before, so I showed him how to use it.', 'had not used', 'have not used', 'has not used', 'was not using', 'A', 'Giải thích: Trong câu này, hành động "had not used email before" xảy ra trước khi bạn "showed him how to use it" trong quá khứ. Để diễn tả hành động chưa từng sử dụng email trước khi học cách sử dụng, cần sử dụng thì quá khứ hoàn thành. "Had not used" là dạng đúng của động từ "use" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(B) have not used (v.): "have not used" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) has not used (v.): "has not used" cũng là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) was not using (v.): "was not using" là dạng quá khứ tiếp diễn, không phù hợp vì câu cần diễn tả hành động đã xảy ra trước trong quá khứ.', 'Anh ấy chưa từng sử dụng email trước đây, vì vậy tôi đã chỉ cho anh ấy cách sử dụng nó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_001', 'zenlish_practice', 'If we _____ the news sooner, we would have written to John.', 'received', 'receive', 'will receive', 'had received', 'D', 'Giải thích: Trong câu điều kiện loại 3, dùng để diễn tả một tình huống trong quá khứ không thực sự xảy ra, cấu trúc đúng là "If + past perfect" (quá khứ hoàn thành) cho mệnh đề điều kiện. Vì vậy, "had received" là dạng quá khứ hoàn thành phù hợp với ngữ cảnh của câu.\n(A) received (v.): "received" là dạng quá khứ đơn, không phù hợp với cấu trúc câu điều kiện loại 3.\n(B) receive (v.): "receive" là dạng hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) will receive (v.): "will receive" là dạng tương lai đơn, không phù hợp với ngữ cảnh quá khứ của câu.', 'Nếu chúng tôi nhận được tin sớm hơn, chúng tôi đã viết thư cho John.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_002', 'zenlish_practice', 'The salesman was telling me that he ______ ten cars the previous week.', 'sold', 'had sold', 'would sell', 'has sold', 'B', 'Giải thích: Trong câu này, "the previous week" chỉ ra rằng hành động "bán mười chiếc xe" đã xảy ra trước khi người bán hàng "telling me" (kể với tôi). Để diễn tả hành động xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had sold" là dạng đúng của động từ "sell" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) sold (v.): "sold" là dạng quá khứ đơn, không diễn tả được hành động xảy ra trước trong quá khứ.\n(C) would sell (v.): "would sell" là dạng tương lai trong quá khứ, không phù hợp với ngữ cảnh của câu.\n(D) has sold (v.): "has sold" là dạng hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Người bán hàng nói với tôi rằng anh ta đã bán được mười chiếc xe vào tuần trước.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_003', 'zenlish_practice', 'The weather was terrible. I wish it ____ warmer.', 'was', 'has been', 'were', 'had been', 'D', 'Giải thích: Trong câu này, "wish" được sử dụng để diễn tả một điều không thực tế hoặc một điều ước trái ngược với thực tế trong quá khứ. Khi diễn tả điều ước trái ngược với một tình huống trong quá khứ, ta sử dụng cấu trúc "wish + past perfect." "Had been" là dạng quá khứ hoàn thành phù hợp với ngữ cảnh của câu.\n(A) was (v.): "was" là quá khứ đơn, không phù hợp để diễn tả điều ước trong quá khứ.\n(B) has been (v.): "has been" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) were (v.): "were" thường được sử dụng với câu điều ước trái với hiện tại, không phù hợp với ngữ cảnh quá khứ của câu.', 'Thời tiết thật tồi tệ. Tôi ước nó đã ấm hơn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_004', 'zenlish_practice', 'He signed the contract after he _____ each statement carefully.', 'reads', 'read', 'has read', 'had read', 'D', 'Giải thích: Trong câu này, "after he" chỉ ra rằng hành động "đọc kỹ từng điều khoản" đã xảy ra trước khi anh ấy "kí hợp đồng." Để diễn tả hành động đã xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had read" là dạng đúng của động từ "read" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) reads (v.): "reads" là hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.\n(B) read (v.): "read" ở đây là quá khứ đơn, nhưng không diễn tả được hành động xảy ra trước trong quá khứ.\n(C) has read (v.): "has read" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Anh ấy đã ký hợp đồng sau khi đã đọc kỹ từng điều khoản.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_005', 'zenlish_practice', 'They ______ at this school before they became interpreters.', 'had taught', 'have taught', 'taught', 'were taught', 'A', 'Giải thích: Trong câu này, "before they became interpreters" chỉ ra rằng hành động "dạy tại trường" đã xảy ra trước khi họ trở thành phiên dịch viên. Để diễn tả một hành động xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had taught" là dạng đúng của động từ "teach" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu .\n(B) have taught (v.): "have taught" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) taught (v.): "taught" là quá khứ đơn, nhưng không diễn tả được hành động xảy ra trước trong quá khứ.\n(D) were taught (v.): "were taught" là dạng bị động, không phù hợp với ngữ cảnh của câu.', 'Họ đã dạy ở trường này trước khi trở thành phiên dịch viên.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_006', 'zenlish_practice', 'She _________ the ocean before she moved to Vancouver.', 'had never seen', 'never seen', 'have never seen', 'had never saw', 'A', 'Giải thích: Trong câu này, "before she moved to Vancouver" chỉ ra rằng hành động "chưa từng nhìn thấy đại dương" đã xảy ra trước khi cô ấy chuyển đến Vancouver. Để diễn tả một hành động xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had never seen" là dạng đúng của động từ "see" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(B) never seen (v.): "never seen" thiếu trợ động từ "had" để tạo thành quá khứ hoàn thành, do đó không đúng cấu trúc.\n(C) have never seen (v.): "have never seen" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) had never saw (v.): "had never saw" là cấu trúc sai, vì "see" cần ở dạng quá khứ phân từ "seen" để kết hợp với "had."', 'Cô ấy chưa từng nhìn thấy đại dương trước khi chuyển đến Vancouver.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_007', 'zenlish_practice', 'By the time Jason arrived to help, we ______ moving everything.', 'has already finished', 'already finished', 'had already finished', 'already finish', 'C', 'Giải thích: Trong câu này, "By the time Jason arrived to help" chỉ ra rằng hành động "hoàn thành việc di chuyển mọi thứ" đã xảy ra trước khi Jason đến giúp. Để diễn tả một hành động xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had already finished" là dạng đúng của động từ "finish" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) has already finished (v.): "has already finished" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(B) already finished (v.): "already finished" thiếu trợ động từ "had" để tạo thành quá khứ hoàn thành, do đó không đúng cấu trúc.\n(D) already finish (v.): "already finish" là cấu trúc sai vì "finish" cần ở dạng quá khứ phân từ "finished" và cần trợ động từ "had."', 'Khi Jason đến để giúp, chúng tôi đã hoàn thành việc di chuyển mọi thứ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_008', 'zenlish_practice', 'The teacher ________ out when I arrived in the classroom.', 'goes', 'have gone', 'has gone', 'had gone', 'D', 'Giải thích: Trong câu này, "when I arrived in the classroom" chỉ ra rằng hành động "giáo viên đã ra ngoài" đã xảy ra trước khi bạn đến lớp. Để diễn tả một hành động xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had gone" là dạng đúng của động từ "go" trong cấu trúc quá khứ hoàn thành, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) goes (v.): "goes" là hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.\n(B) have gone (v.): "have gone" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) has gone (v.): "has gone" cũng là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Giáo viên đã ra ngoài khi tôi đến lớp học.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_009', 'zenlish_practice', 'I’m sorry you failed the examination. Frankly, I wish I _____ harder.', 'had studied', 'studying', 'was studying', 'did study', 'A', 'Giải thích: Trong câu này, "I wish" được sử dụng để diễn tả một điều không thực tế hoặc một điều ước trái ngược với thực tế trong quá khứ. Khi diễn tả điều ước trái ngược với một tình huống trong quá khứ, ta sử dụng cấu trúc "wish + past perfect." "Had studied" là dạng quá khứ hoàn thành phù hợp với ngữ cảnh của câu.\n(B) studying (v.): "studying" là dạng V-ing, không phù hợp trong cấu trúc này.\n(C) was studying (v.): "was studying" là quá khứ tiếp diễn, không phù hợp với cấu trúc điều ước trong quá khứ.\n(D) did study (v.): "did study" là quá khứ đơn nhấn mạnh, không phù hợp với cấu trúc câu điều ước trong quá khứ.', 'Anh xin lỗi vì em đã thi trượt. Thành thật mà nói, anh ước gì mình đã học chăm chỉ hơn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0032_q_010', 'zenlish_practice', 'I am sorry I didn’t see my uncle yesterday, I wish _____.', 'I saw him', 'I have seen him', 'I didn’t see him', 'I had seen him', 'D', 'Giải thích: Trong câu này, "I wish" được sử dụng để diễn tả một điều không thực tế hoặc một điều ước trái ngược với thực tế trong quá khứ. Khi diễn tả điều ước trái ngược với một tình huống trong quá khứ, ta sử dụng cấu trúc "wish + past perfect." "I had seen him" là dạng quá khứ hoàn thành phù hợp với ngữ cảnh của câu.\n(A) I saw him (v.): "I saw him" là quá khứ đơn, không phù hợp với cấu trúc câu điều ước trong quá khứ.\n(B) I have seen him (v.): "I have seen him" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) I didn’t see him (v.): "I didn’t see him" là quá khứ đơn phủ định, không phù hợp với cấu trúc điều ước trong quá khứ.', 'Anh xin lỗi vì đã không gặp chú hôm qua, anh ước gì mình đã gặp chú ấy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_001', 'zenlish_practice', 'Experiments in the sonic imaging of moving objects ______ in both the United States and Europe well before the Second World War.', 'were conducting', 'have been conducted', 'being conducted', 'had been conducted', 'D', 'Giải thích: Trong câu này, "well before the Second World War" chỉ ra rằng hành động "các thí nghiệm trong việc tạo hình ảnh âm thanh của các vật thể di chuyển" đã xảy ra trước một mốc thời gian cụ thể trong quá khứ. Để diễn tả hành động đã hoàn thành trước một thời điểm trong quá khứ, cần sử dụng thì quá khứ hoàn thành bị động. "Had been conducted" là dạng quá khứ hoàn thành bị động phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) were conducting (v.): "were conducting" là quá khứ tiếp diễn chủ động, không phù hợp với cấu trúc bị động cần thiết trong câu.\n(B) have been conducted (v.): "have been conducted" là hiện tại hoàn thành bị động, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) being conducted (v.): "being conducted" thiếu trợ động từ "had been" để tạo thành thì quá khứ hoàn thành bị động.', 'Các thí nghiệm trong việc tạo hình ảnh âm thanh của các vật thể di chuyển đã được tiến hành ở cả Hoa Kỳ và Châu Âu từ lâu trước Chiến tranh Thế giới thứ hai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_002', 'zenlish_practice', 'The lights went out because we ____ the electricity bill.', 'had not paid', 'have not pay', 'has not paid', 'would not pay', 'A', 'Giải thích: Trong câu này, "The lights went out" chỉ ra rằng hành động "đèn tắt" đã xảy ra sau khi chúng ta "không trả hóa đơn điện." Để diễn tả hành động "không trả hóa đơn điện" xảy ra trước khi đèn tắt, cần sử dụng thì quá khứ hoàn thành. "Had not paid" là dạng đúng của động từ "pay" trong cấu trúc quá khứ hoàn thành phủ định, phù hợp với ngữ pháp và ngữ cảnh của câu.\n(B) have not pay (v.): "have not pay" là cấu trúc sai vì "pay" cần ở dạng quá khứ phân từ "paid" và trợ động từ "have" không phù hợp với ngữ cảnh quá khứ.\n(C) has not paid (v.): "has not paid" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) would not pay (v.): "would not pay" diễn tả một sự từ chối hoặc một thói quen trong quá khứ, không phù hợp với ngữ cảnh của câu.', 'Đèn đã tắt vì chúng tôi chưa trả hóa đơn điện.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_003', 'zenlish_practice', 'After he ______ a highly successful computer business for two years, he started his second business in a small garage.', 'has run', 'had run', 'runs', 'was running', 'B', 'Giải thích: Trong câu này, hành động "khởi chạy một doanh nghiệp máy tính rất thành công trong hai năm" đã xảy ra trước khi anh ấy "bắt đầu doanh nghiệp thứ hai trong một gara nhỏ." Để diễn tả hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had run" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) has run (v.): "has run" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) runs (v.): "runs" là hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) was running (v.): "was running" là quá khứ tiếp diễn, không phù hợp với ngữ cảnh cần diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ.', 'Sau khi đã điều hành một doanh nghiệp máy tính rất thành công trong hai năm, anh ấy bắt đầu doanh nghiệp thứ hai trong một gara nhỏ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_004', 'zenlish_practice', 'George _________ his furniture before he moved to Japan.', 'have sold', 'had sold', 'had sell', 'sells', 'B', 'Giải thích: Trong câu này, hành động "bán đồ nội thất" đã xảy ra trước khi George "chuyển đến Nhật Bản." Để diễn tả hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had sold" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) have sold (v.): "have sold" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) had sell (v.): "had sell" là cấu trúc sai vì "sell" cần ở dạng quá khứ phân từ "sold" để kết hợp với "had."\n(D) sells (v.): "sells" là hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.', 'George đã bán đồ nội thất của mình trước khi chuyển đến Nhật Bản.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_005', 'zenlish_practice', 'Larry _________ his homework already by the time Roy came over.', 'have finish', 'finishes', 'had finish', 'had finished', 'D', 'Giải thích: Trong câu này, hành động "hoàn thành bài tập về nhà" của Larry đã xảy ra trước khi Roy "đến." Để diễn tả hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had finished" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) have finish (v.): "have finish" là cấu trúc sai vì "finish" cần ở dạng quá khứ phân từ "finished," và "have" không phù hợp với ngữ cảnh quá khứ.\n(B) finishes (v.): "finishes" là hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) had finish (v.): "had finish" là cấu trúc sai vì "finish" cần ở dạng quá khứ phân từ "finished."', 'Larry đã hoàn thành bài tập về nhà của mình trước khi Roy đến.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_006', 'zenlish_practice', 'Ruth ________ an Australian until she met John.', 'had never met', 'have never met', 'never met', 'never have met', 'A', 'Giải thích: Trong câu này, hành động "gặp một người Úc" chưa bao giờ xảy ra trước khi Ruth "gặp John." Để diễn tả một hành động chưa bao giờ xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had never met" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(B) have never met (v.): "have never met" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) never met (v.): "never met" là quá khứ đơn, không diễn tả được hành động chưa xảy ra trước một hành động khác trong quá khứ.\n(D) never have met (v.): "never have met" là cấu trúc sai, vì "have" cần đứng trước chủ ngữ nếu dùng trong thì hiện tại hoàn thành.', 'Ruth chưa bao giờ gặp một người Úc cho đến khi cô ấy gặp John.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_007', 'zenlish_practice', 'I ________ a little Spanish before I went to Mexico.', 'study', 'had studied', 'had study', 'have studied', 'B', 'Giải thích: Trong câu này, hành động "học một chút tiếng Tây Ban Nha" đã xảy ra trước khi bạn "đi đến Mexico." Để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had studied" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) study (v.): "study" là hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) had study (v.): "had study" là cấu trúc sai vì "study" cần ở dạng quá khứ phân từ "studied."\n(D) have studied (v.): "have studied" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Tôi đã học một chút tiếng Tây Ban Nha trước khi tôi đi đến Mexico.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_008', 'zenlish_practice', 'He asked me to give his book back but I ____________ it.', 'have lost', 'had lost', 'was lost', 'lost', 'B', 'Giải thích: Trong câu này, hành động "làm mất cuốn sách" đã xảy ra trước khi anh ấy yêu cầu bạn trả lại. Để diễn tả một hành động đã xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had lost" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) have lost (v.): "have lost" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) was lost (v.): "was lost" là dạng bị động, không phù hợp với ngữ cảnh vì bạn là người làm mất cuốn sách.\n(D) lost (v.): "lost" là quá khứ đơn, nhưng không diễn tả được hành động xảy ra trước trong quá khứ.', 'Anh ấy yêu cầu tôi trả lại cuốn sách của mình nhưng tôi đã làm mất nó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_009', 'zenlish_practice', 'I ________ such majestic mountains before I went to Banff.', 'never seen', 'had never seen', 'never have seen', 'never saw', 'B', 'Giải thích: Trong câu này, hành động "chưa từng thấy những ngọn núi hùng vĩ" xảy ra trước khi bạn "đi đến Banff." Để diễn tả một hành động chưa từng xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had never seen" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu .\n(A) never seen (v.): "never seen" thiếu trợ động từ "had" để tạo thành quá khứ hoàn thành, do đó không đúng cấu trúc.\n(C) never have seen (v.): "never have seen" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) never saw (v.): "never saw" là quá khứ đơn, không diễn tả được hành động xảy ra trước trong quá khứ.', 'Tôi chưa từng thấy những ngọn núi hùng vĩ như vậy trước khi tôi đến Banff.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0033_q_010', 'zenlish_practice', 'I couldn’t see the teacher because he ____________ before I arrived the school.', 'had left', 'has left', 'left', 'was leaving', 'A', 'Giải thích: Trong câu này, hành động "thầy giáo rời đi" đã xảy ra trước khi bạn "đến trường." Để diễn tả một hành động đã xảy ra trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had left" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(B) has left (v.): "has left" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) left (v.): "left" là quá khứ đơn, nhưng không diễn tả được hành động xảy ra trước trong quá khứ.\n(D) was leaving (v.): "was leaving" là quá khứ tiếp diễn, không phù hợp vì không diễn tả hành động đã hoàn thành trước một hành động khác.', 'Tôi không thể gặp thầy giáo vì thầy đã rời đi trước khi tôi đến trường.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_001', 'zenlish_practice', 'When they arrived, we _________ the test.', 'had already started', 'have already started', 'starts', 'already starting', 'A', 'Giải thích: Trong câu này, hành động "chúng tôi đã bắt đầu bài kiểm tra" xảy ra trước khi "họ đến." Để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had already started" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(B) have already started (v.): "have already started" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) starts (v.): "starts" là hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) already starting (v.): "already starting" là cấu trúc sai, vì cần dạng quá khứ hoàn thành "had already started."', 'Khi họ đến, chúng tôi đã bắt đầu bài kiểm tra.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_002', 'zenlish_practice', 'He was very tired because he ____________ the bags upstairs.', 'have carried', 'had carried', 'carried', 'has carried', 'B', 'Giải thích: Trong câu này, hành động "mang túi lên lầu" xảy ra trước khi anh ấy "rất mệt." Để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had carried" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) have carried (v.): "have carried" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) carried (v.): "carried" là quá khứ đơn, không diễn tả được hành động xảy ra trước trong quá khứ.\n(D) has carried (v.): "has carried" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Anh ấy rất mệt vì đã mang túi lên lầu.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_003', 'zenlish_practice', 'She answered all of the questions in the exam because she ____________ very well.', 'was studied', 'had studied', 'has been studied', 'have studied', 'B', 'Giải thích: Trong câu này, hành động "học rất chăm chỉ" đã xảy ra trước khi cô ấy "trả lời tất cả các câu hỏi trong kỳ thi." Để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had studied" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) was studied (v.): "was studied" là dạng bị động sai, vì câu yêu cầu một động từ chủ động.\n(C) has been studied (v.): "has been studied" là dạng hiện tại hoàn thành bị động, không phù hợp với ngữ cảnh và cấu trúc của câu.\n(D) have studied (v.): "have studied" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Cô ấy đã trả lời tất cả các câu hỏi trong kỳ thi vì cô ấy đã học rất chăm chỉ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_004', 'zenlish_practice', 'I needed to know what ______________ to my car.', 'happened', 'had happened', 'has happened', 'happens', 'B', 'Giải thích: Trong câu này, hành động "cần biết điều gì đã xảy ra" xảy ra sau khi một sự việc nào đó đã xảy ra với chiếc xe. Để diễn tả một hành động hoặc sự kiện đã hoàn thành trước một thời điểm khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had happened" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) happened (v.): "happened" là quá khứ đơn, không diễn tả được hành động đã xảy ra trước một hành động khác trong quá khứ.\n(C) has happened (v.): "has happened" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(D) happens (v.): "happens" là hiện tại đơn, không phù hợp với ngữ cảnh quá khứ của câu.', 'Tôi cần biết điều gì đã xảy ra với chiếc xe của mình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_005', 'zenlish_practice', 'I went to bed after I _____________ off the television.', 'had switch', 'has switched', 'switched', 'had switched', 'D', 'Giải thích: Trong câu này, hành động "tắt tivi" đã xảy ra trước khi bạn "đi ngủ." Để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had switched" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) had switch (v.): "had switch" là cấu trúc sai vì "switch" cần ở dạng quá khứ phân từ "switched."\n(B) has switched (v.): "has switched" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) switched (v.): "switched" là quá khứ đơn, không diễn tả được hành động đã xảy ra trước trong quá khứ.', 'Tôi đi ngủ sau khi đã tắt tivi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_006', 'zenlish_practice', 'I was sure that I ___________ the place before.', 'seen', 'had seen', 'had saw', 'have seen', 'B', 'Giải thích: Trong câu này, bạn muốn diễn tả rằng hành động "nhìn thấy nơi đó" đã xảy ra trước thời điểm bạn chắc chắn về điều đó. Để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had seen" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) seen (v.): "seen" thiếu trợ động từ "had" để tạo thành quá khứ hoàn thành, do đó không đúng cấu trúc.\n(C) had saw (v.): "had saw" là cấu trúc sai, vì "see" cần ở dạng quá khứ phân từ "seen" để kết hợp với "had."\n(D) have seen (v.): "have seen" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.', 'Tôi chắc chắn rằng tôi đã nhìn thấy nơi đó trước đây.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_007', 'zenlish_practice', '. When I came round in the hospital I realised I ____________________ the car.', 'crashed', 'has crashed', 'have crashed', 'had crashed', 'D', 'Giải thích: Trong câu này, hành động "đâm xe" đã xảy ra trước khi bạn "tỉnh lại trong bệnh viện." Để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ, cần sử dụng thì quá khứ hoàn thành. "Had crashed" là dạng quá khứ hoàn thành phù hợp với ngữ pháp và ngữ cảnh của câu.\n(A) crashed (v.): "crashed" là quá khứ đơn, không diễn tả được hành động đã xảy ra trước một hành động khác trong quá khứ.\n(B) has crashed (v.): "has crashed" là hiện tại hoàn thành, không phù hợp với ngữ cảnh quá khứ của câu.\n(C) have crashed (v.): "have crashed" cũng là hiện tại hoàn thành và không phù hợp với ngữ cảnh quá khứ của câu.', 'Khi tôi tỉnh lại trong bệnh viện, tôi nhận ra rằng mình đã đâm xe.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_008', 'zenlish_practice', 'We __________ the car for five years when we sold it.', 'had had', 'had have', 'had', 'have had', 'A', 'Giải thích: Hành động "sở hữu chiếc xe" xảy ra trước một hành động khác trong quá khứ là "bán xe" nên cần được chia ở thì quá khứ hoàn thành.\n(B) had have: Cấu trúc này sai ngữ pháp vì không tồn tại "had have" trong tiếng Anh.\n(C) had: "Had" là động từ quá khứ đơn, nhưng trong câu này cần sử dụng quá khứ hoàn thành để diễn tả hành động đã hoàn thành trước một hành động khác.\n(D) have had: Đây là thì hiện tại hoàn thành, không phù hợp vì câu đang nói về hai hành động trong quá khứ.', 'Chúng tôi đã sở hữu chiếc xe được năm năm khi chúng tôi bán nó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_009', 'zenlish_practice', 'He behaved as if he ________ the best book in the world.', 'written', 'wrote', 'had writed', 'had written', 'D', 'Giải thích: Câu này sử dụng cấu trúc "as if" để diễn tả một giả định trái ngược với thực tế nên phải lùi một thì. Câu này đang ở thì quá khứ đơn (behaved) nên động từ sau as if phải lùi thành thì quá khứ hoàn thành.\n(A) written: Đây là quá khứ phân từ (past participle) của "write," nhưng thiếu trợ động từ "had" để tạo thành thì quá khứ hoàn thành.\n(B) wrote: Đây là động từ quá khứ đơn\n(C) had writed: "Writed" không phải là dạng đúng của động từ "write" trong bất kỳ thì nào. Dạng quá khứ phân từ đúng là "written."', 'Anh ta cư xử như thể mình đã viết cuốn sách hay nhất trên thế giới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0034_q_010', 'zenlish_practice', 'He ________ an amazing musician before he died.', 'was been', 'had been', 'has been', 'was', 'B', 'Giải thích: Câu này sử dụng thì quá khứ hoàn thành (past perfect) "had been" để diễn tả một trạng thái kéo dài trước một hành động khác trong quá khứ. "Had been" cho thấy anh ấy đã là một nhạc sĩ tài năng trong một khoảng thời gian trước khi qua đời.\n(A) was been: Cấu trúc này sai ngữ pháp vì không có "was been" trong tiếng Anh.\n(C) has been: Đây là thì hiện tại hoàn thành, không phù hợp vì câu đang nói về một sự kiện đã hoàn thành trong quá khứ trước khi anh ấy qua đời.\n(D) was: Đây là động từ quá khứ đơn, nhưng trong câu này, quá khứ hoàn thành "had been" mới phù hợp để diễn tả một trạng thái kéo dài trước một hành động khác.', 'Anh ấy đã là một nhạc sĩ tài năng trước khi qua đời.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_001', 'zenlish_practice', 'After I ____________________ my homework, I watched the TV.', 'have done', 'had done', 'had did', 'done', 'B', 'Giải thích: Câu này sử dụng thì quá khứ hoàn thành (past perfect) "had done" để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ. "Had done" là dạng quá khứ hoàn thành của "do," diễn tả hành động làm xong bài tập trước khi xem TV.\n(A) have done: Đây là thì hiện tại hoàn thành, không phù hợp vì câu nói về một hành động trong quá khứ.\n(C) had did: "Did" là dạng quá khứ đơn của "do," không phù hợp vì sau "had" cần dùng quá khứ phân từ, tức là "done."\n(D) done: "Done" là quá khứ phân từ của "do," nhưng thiếu trợ động từ "had" để tạo thành thì quá khứ hoàn thành.', 'Sau khi tôi đã làm xong bài tập, tôi xem TV.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_002', 'zenlish_practice', 'The film ________________ by the time we got to the cinema.', 'started', 'has started', 'had started', 'had start', 'C', 'Giải thích: Câu này sử dụng thì quá khứ hoàn thành (past perfect) "had started" để diễn tả một hành động đã xảy ra trước một hành động khác trong quá khứ. "Had started" cho biết bộ phim đã bắt đầu trước khi chúng tôi đến rạp chiếu phim.\n(A) started: Đây là quá khứ đơn, không phù hợp vì câu cần sử dụng quá khứ hoàn thành để diễn tả hành động đã xảy ra trước khi chúng tôi đến rạp.\n(B) has started: Đây là thì hiện tại hoàn thành, không phù hợp vì câu đang nói về một sự kiện trong quá khứ.\n(D) had start: Cấu trúc này sai ngữ pháp vì "start" là dạng nguyên thể, cần phải sử dụng dạng quá khứ phân từ "started" sau "had."', 'Bộ phim đã bắt đầu khi chúng tôi đến rạp chiếu phim.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_003', 'zenlish_practice', 'By the time we got there, he _______________ .', 'have left', 'has left', 'left', 'had left', 'D', 'Giải thích: Câu này sử dụng thì quá khứ hoàn thành (past perfect) "had left" để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ. "Had left" cho biết anh ấy đã rời đi trước khi chúng tôi đến.\n(A) have left: Đây là thì hiện tại hoàn thành, nhưng sai ngữ pháp vì cần sử dụng "had" thay vì "have" để phù hợp với quá khứ hoàn thành.\n(B) has left: Đây cũng là thì hiện tại hoàn thành, nhưng không phù hợp vì câu đang nói về một sự kiện trong quá khứ.\n(C) left: Đây là quá khứ đơn, nhưng câu cần sử dụng quá khứ hoàn thành để diễn tả hành động đã xảy ra trước khi chúng tôi đến.', 'Khi chúng tôi đến đó, anh ấy đã rời đi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_004', 'zenlish_practice', 'Lynne left the restaurant after she ___________________ eating.', 'finished', 'had finished', 'has finished', 'had finish', 'B', 'Giải thích: Câu này sử dụng thì quá khứ hoàn thành (past perfect) "had finished" để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ. "Had finished" cho biết Lynne đã hoàn tất việc ăn uống trước khi rời khỏi nhà hàng.\n(A) finished: Đây là quá khứ đơn, nhưng câu cần sử dụng quá khứ hoàn thành để diễn tả hành động đã hoàn thành trước hành động khác trong quá khứ.\n(C) has finished: Đây là thì hiện tại hoàn thành, không phù hợp vì câu nói về một sự kiện trong quá khứ.\n(D) had finish: "Finish" không phải là dạng đúng của động từ khi sử dụng với "had"; dạng đúng là "finished."', 'Lynne đã rời khỏi nhà hàng sau khi cô ấy hoàn tất việc ăn uống.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_005', 'zenlish_practice', 'When Yuka _______ washing the dishes, she _______ the TV on.', 'finished, had turned', 'turned, had finished', 'had finished, turned', 'had turned, finished', 'C', 'Giải thích: Câu này sử dụng thì quá khứ hoàn thành (past perfect) "had finished" để diễn tả hành động đã hoàn thành trước một hành động khác trong quá khứ, và thì quá khứ đơn "turned" để diễn tả hành động xảy ra sau đó. "Had finished" cho biết Yuka đã hoàn tất việc rửa bát trước khi cô ấy bật TV.\n(A) finished, had turned: Cấu trúc này sai ngữ pháp vì "had turned" không phù hợp với thì quá khứ đơn của hành động sau.\n(B) turned, had finished: "Had finished" cần phải đứng trước "turned" để đúng với trình tự thời gian trong quá khứ hoàn thành.\n(D) had turned, finished: Cấu trúc này sai vì "had turned" không cần thiết để diễn tả hành động xảy ra trước hành động khác trong quá khứ.', 'Khi Yuka hoàn tất việc rửa bát, cô ấy đã bật TV.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_006', 'zenlish_practice', 'Fraser _______ sushi before he _______ to Japan.', 'never ate, had come', 'came, had never eaten', 'had come, never ate', 'had never eaten, came', 'D', 'Giải thích: Câu này sử dụng thì quá khứ hoàn thành (past perfect) "had never eaten" để diễn tả một hành động chưa xảy ra trước một thời điểm hoặc hành động khác trong quá khứ. "Had never eaten" cho biết Fraser chưa bao giờ ăn sushi trước khi đến Nhật Bản. "Came" là quá khứ đơn, diễn tả hành động chính trong quá khứ.\n(A) never ate, had come: Cấu trúc này sai ngữ pháp vì "had come" cần phải đứng trước "never ate" để đúng với trình tự thời gian của quá khứ hoàn thành.\n(B) came, had never eaten: "Had never eaten" cần phải sử dụng thì quá khứ hoàn thành để diễn tả hành động chưa xảy ra trước hành động khác trong quá khứ.\n(C) had come, never ate: Cấu trúc này sai vì "had come" không phù hợp với ngữ cảnh của câu khi cần diễn tả hành động chưa xảy ra trước hành động chính.', 'Fraser chưa bao giờ ăn sushi trước khi anh ấy đến Nhật Bản.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_007', 'zenlish_practice', 'When Airi _______ at school, she realized she _______ her textbook.', 'had arrived, forgot', 'arrived, had forgotten', 'forgot, had arrived', 'had forgotten, arrived', 'B', 'Giải thích: Trong câu này, động từ “arrived” là thì quá khứ đơn, diễn tả hành động xảy ra trong quá khứ khi Airi đến trường. Động từ “had forgotten” là thì quá khứ hoàn thành, diễn tả hành động xảy ra trước hành động "arrived". Theo thứ tự thời gian, Airi đã quên sách trước khi đến trường, vì vậy sử dụng "arrived" ở quá khứ đơn và "had forgotten" ở quá khứ hoàn thành là phù hợp.\n(A) had arrived, forgot: "had arrived" là thì quá khứ hoàn thành, không phù hợp vì hành động "arrived" xảy ra sau khi quên sách. "forgot" là thì quá khứ đơn, không đúng thứ tự thời gian.\n(C) forgot, had arrived: không hợp lý về mặt nghĩa\n(D) had forgotten, arrived: "had forgotten" là thì quá khứ hoàn thành, "arrived" là thì quá khứ đơn, đúng về thứ tự thời gian nhưng không phù hợp về nghĩa.', 'Khi Airi đến trường, cô ấy nhận ra rằng mình đã quên sách giáo khoa.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_008', 'zenlish_practice', 'I _______ any money on the weekend because I _______ my wallet on Friday.', 'didn''t have, had lost', 'hadn''t had, lost', 'didn''t lose, hadn''t had', 'hadn''t lost, didn''t have', 'A', 'Giải thích: Trong câu này, động từ “didn''t have” là thì quá khứ đơn, diễn tả hành động không có tiền vào cuối tuần. Động từ “had lost” là thì quá khứ hoàn thành, diễn tả hành động xảy ra trước việc không có tiền. Vì vậy, “had lost” cho biết lý do tại sao người nói không có tiền, tức là vì đã mất ví vào thứ Sáu trước đó.\n(B) hadn''t had, lost: "hadn''t had" là thì quá khứ hoàn thành, không phù hợp vì hành động không có tiền xảy ra vào cuối tuần. "lost" là thì quá khứ đơn, không đúng với thứ tự thời gian vì mất ví xảy ra trước việc không có tiền.\n(C) didn''t lose, hadn''t had: "didn''t lose" là thì quá khứ đơn, không phù hợp vì mất ví đã xảy ra trước việc không có tiền. "hadn''t had" là thì quá khứ hoàn thành, không phù hợp với tình huống vì không có tiền xảy ra vào cuối tuần.\n(D) hadn''t lost, didn''t have: "hadn''t lost" là thì quá khứ hoàn thành, không phù hợp vì hành động mất ví xảy ra trước việc không có tiền. "didn''t have" là thì quá khứ đơn, đúng về thứ tự thời gian nhưng không phù hợp với cấu trúc câu.', 'Tôi không có tiền vào cuối tuần vì tôi đã mất ví vào thứ Sáu.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_009', 'zenlish_practice', 'When we went to Osaka, my friend _______ a lot about the city because she _______ there many times.', 'was, had known', 'had known, was', 'knew, had been', 'had been, knew', 'C', 'Giải thích: Trong câu này, động từ “knew” là thì quá khứ đơn, diễn tả kiến thức mà bạn của người nói đã có khi họ đến Osaka. Động từ “had been” là thì quá khứ hoàn thành, diễn tả hành động xảy ra trước khi họ đi đến Osaka. Vì vậy, bạn của người nói đã có nhiều kiến thức về thành phố (knew) vì đã từng đến đó nhiều lần (had been).\n(A) was, had known: "was" là thì quá khứ đơn, không phù hợp vì cần một động từ để mô tả kiến thức hiện có. "had known" là thì quá khứ hoàn thành, không phù hợp vì mô tả kiến thức trước khi có nhiều chuyến đi.\n(B) had known, was: "had known" là thì quá khứ hoàn thành, không đúng thứ tự thời gian vì cần một động từ để mô tả kiến thức hiện có. "was" là thì quá khứ đơn, không phù hợp vì cần mô tả kiến thức thay vì tình trạng.\n(D) had been, knew: "had been" là thì quá khứ hoàn thành, đúng về thứ tự thời gian nhưng không phù hợp vì cần một động từ mô tả kiến thức hiện có. "knew" là thì quá khứ đơn, không đúng vì kiến thức đã được hình thành trước khi đi đến Osaka.', 'Khi chúng tôi đến Osaka, bạn tôi biết rất nhiều về thành phố vì cô ấy đã đến đó nhiều lần.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0035_q_010', 'zenlish_practice', 'It was a very difficult movie, but I _______ it because I _______ the book.', 'had understood, read', 'read, had understood', 'had read, understood', 'understood, had read', 'D', 'Giải thích: Trong câu này, động từ “understood” là thì quá khứ đơn, diễn tả sự hiểu biết về bộ phim trong quá khứ. Động từ “had read” là thì quá khứ hoàn thành, diễn tả hành động đọc sách đã xảy ra trước khi xem phim. Do đó, việc đọc sách trước (had read) giúp người nói hiểu được bộ phim (understood).\n(A) had understood, read: "had understood" là thì quá khứ hoàn thành, không phù hợp vì sự hiểu biết xảy ra sau khi đọc sách. "read" là thì quá khứ đơn, không đúng vì đọc sách đã xảy ra trước.\n(B) read, had understood: "read" là thì quá khứ đơn, không phù hợp vì cần một động từ để mô tả sự hiểu biết. "had understood" là thì quá khứ hoàn thành, không đúng vì sự hiểu biết xảy ra sau khi xem phim.\n(C) had read, understood: "had read" là thì quá khứ hoàn thành, đúng vì việc đọc sách xảy ra trước khi xem phim. "understood" là thì quá khứ đơn, đúng về thứ tự thời gian nhưng không đúng vì cần mô tả sự hiểu biết đã xảy ra sau khi đọc sách.', 'Đó là một bộ phim rất khó, nhưng tôi hiểu được nó vì tôi đã đọc cuốn sách.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_001', 'zenlish_practice', 'At the next staff meeting, Yoshihiro Miura _____ the most promising products under development.', 'will discuss', 'had discussed', 'discussing', 'to discuss', 'A', 'Giải thích: "Will discuss" là động từ ở thì tương lai đơn, phù hợp với ngữ cảnh của câu khi nói về một hành động sẽ diễn ra trong tương lai. Câu này nói rằng tại cuộc họp nhân viên tiếp theo, Yoshihiro Miura sẽ thảo luận về các sản phẩm triển vọng nhất đang được phát triển.\n(B) had discussed (v. past perfect): "had discussed" là động từ ở thì quá khứ hoàn thành, không phù hợp với ngữ cảnh của câu khi câu nói về một hành động trong tương lai.\n(C) discussing (v. present participle): "discussing" là hiện tại phân từ, không phù hợp với cấu trúc câu khi cần một động từ chính ở thì tương lai đơn.\n(D) to discuss (infinitive): "to discuss" là động từ nguyên mẫu, không phù hợp với ngữ pháp của câu.', 'Tại cuộc họp nhân viên tiếp theo, Yoshihiro Miura sẽ thảo luận về các sản phẩm triển vọng nhất đang được phát triển.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_002', 'zenlish_practice', 'Real estate agents in Stranton anticipate that property values _____ in the coming year.', 'increasingly', 'increasing', 'will increase', 'to increase', 'C', 'Giải thích: "Will increase" là động từ ở thì tương lai đơn, phù hợp với ngữ cảnh của câu khi nói về một dự đoán hoặc kỳ vọng về tương lai. Câu này nói rằng các đại lý bất động sản ở Stranton dự đoán rằng giá trị bất động sản sẽ tăng trong năm tới.\n(A) increasingly (adv.): "increasingly" là trạng từ, không phù hợp với ngữ pháp của câu khi cần một động từ.\n(B) increasing (v. present participle): "increasing" là hiện tại phân từ, không phù hợp với cấu trúc của câu khi cần một động từ chính.\n(D) to increase (infinitive): "to increase" là động từ nguyên mẫu, không phù hợp với ngữ pháp của câu.', 'Các đại lý bất động sản ở Stranton dự đoán rằng giá trị bất động sản sẽ tăng trong năm tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_003', 'zenlish_practice', 'At the next meeting, the board of directors _____ a new chairperson for the forthcoming fiscal year.', 'elected', 'elects', 'will elect', 'will be elected', 'C', 'Giải thích: Trong câu này, cần một động từ ở thì tương lai đơn để mô tả hành động sẽ xảy ra tại cuộc họp tiếp theo. "Will elect" là thì tương lai đơn phù hợp, nghĩa là "sẽ bầu," để chỉ rằng hội đồng quản trị sẽ thực hiện hành động bầu chọn một chủ tịch mới cho năm tài chính tới.\n(A) elected (past simple): "Elected" có nghĩa là "đã bầu." Lý do không chọn là vì thì quá khứ đơn không phù hợp khi mô tả một hành động sẽ xảy ra trong tương lai.\n(B) elects (present simple): "Elects" có nghĩa là "bầu chọn" ở thì hiện tại đơn. Lý do không chọn là vì thì hiện tại đơn không phản ánh rằng hành động sẽ xảy ra trong tương lai.\n(D) will be elected (future passive): "Will be elected" có nghĩa là "sẽ được bầu" (bị động). Lý do không chọn là vì cấu trúc bị động không phù hợp khi cần mô tả hành động chủ động của hội đồng quản trị.', 'Tại cuộc họp tiếp theo, hội đồng quản trị sẽ bầu chọn một chủ tịch mới cho năm tài chính sắp tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_004', 'zenlish_practice', 'Beginning in August, free parking _____ available to anyone taking the commuter train from Green Cyty.', 'were', 'to be', 'being', 'will be', 'D', 'Giải thích: Trong câu này, cần một động từ ở thì tương lai đơn để mô tả tình trạng miễn phí đỗ xe sẽ có hiệu lực từ tháng Tám. "Will be" là thì tương lai đơn phù hợp, nghĩa là "sẽ được," để chỉ rằng đỗ xe miễn phí sẽ có sẵn cho bất kỳ ai sử dụng tàu điện từ Green City bắt đầu từ tháng Tám.\n(A) were (past simple): "Were" có nghĩa là "đã được." Lý do không chọn là vì thì quá khứ không phù hợp khi mô tả một tình trạng sẽ xảy ra trong tương lai.\n(B) to be (infinitive): "To be" có nghĩa là "để được." Lý do không chọn là vì cấu trúc này không phù hợp trong ngữ cảnh khi cần một động từ chính cho câu thể hiện một tình trạng trong tương lai.\n(C) being (present participle): "Being" có nghĩa là "đang được." Lý do không chọn là vì dạng hiện tại phân từ không phản ánh một tình trạng trong tương lai.', 'Bắt đầu từ tháng Tám, đỗ xe miễn phí sẽ được cung cấp cho bất kỳ ai sử dụng tàu điện từ Green City.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_005', 'zenlish_practice', 'Maria Vega ''s keynote address at next month'' s entrepreneurs Symposium in Singapore _____ by a short video.', 'was preceded', 'will be preceded', 'would precede', 'were to precede', 'B', 'Giải thích: Trong câu này, cần một động từ ở thì tương lai đơn để mô tả rằng bài phát biểu chính của Maria Vega tại hội nghị sẽ được một video ngắn chiếu trước đó. "Will be preceded" là thì tương lai bị động phù hợp, nghĩa là "sẽ được trước," để chỉ rằng video ngắn sẽ được chiếu trước khi bài phát biểu chính diễn ra.\n(A) was preceded (past simple passive): "Was preceded" có nghĩa là "đã được trước." Lý do không chọn là vì thì quá khứ bị động không phù hợp khi mô tả một sự việc sẽ xảy ra trong tương lai.\n(C) would precede (conditional): "Would precede" có nghĩa là "sẽ trước" trong điều kiện. Lý do không chọn là vì cấu trúc điều kiện không phù hợp trong ngữ cảnh mô tả hành động chắc chắn sẽ xảy ra trong tương lai.\n(D) were to precede (past conditional): "Were to precede" có nghĩa là "đã phải trước" trong điều kiện quá khứ. Lý do không chọn là vì cấu trúc này không phù hợp với ngữ cảnh khi cần mô tả hành động sẽ xảy ra trong tương lai.', 'Bài phát biểu chính của Maria Vega tại Hội nghị Doanh nhân vào tháng tới ở Singapore sẽ được một video ngắn chiếu trước đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_006', 'zenlish_practice', 'The company _____ working on the project for the main office even before it chose the land to build on.', 'will begin', 'had begun', 'has begun', 'is beginning', 'B', 'Giải thích: Trong câu này, cần một động từ ở thì quá khứ hoàn thành để mô tả một hành động (làm việc trên dự án) đã xảy ra trước một hành động khác trong quá khứ (chọn đất để xây dựng). "Had begun" là thì quá khứ hoàn thành phù hợp, nghĩa là "đã bắt đầu," để chỉ rằng công ty đã bắt đầu làm việc trên dự án trước khi chọn đất để xây dựng.\n(A) will begin (future simple): "Will begin" có nghĩa là "sẽ bắt đầu." Lý do không chọn là vì thì tương lai không phù hợp với ngữ cảnh mô tả một hành động đã xảy ra trước một thời điểm trong quá khứ.\n(C) has begun (present perfect): "Has begun" có nghĩa là "đã bắt đầu." Lý do không chọn là vì thì hiện tại hoàn thành không phù hợp khi cần mô tả một hành động đã xảy ra trước một thời điểm trong quá khứ.\n(D) is beginning (present continuous): "Is beginning" có nghĩa là "đang bắt đầu." Lý do không chọn là vì thì hiện tại tiếp diễn không phù hợp khi hành động đã xảy ra trong quá khứ.', 'Công ty đã bắt đầu làm việc trên dự án cho văn phòng chính ngay cả trước khi chọn đất để xây dựng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_007', 'zenlish_practice', 'Following the visit to your production facility in Hong Kong next week, We _____ a comprehensive factory automation program to meet your company ''s needs.', 'will create', 'was created', 'having created', 'had created', 'A', 'Giải thích: Trong câu này, cần một động từ ở thì tương lai đơn để mô tả hành động sẽ xảy ra sau một sự kiện cụ thể trong tương lai (thăm cơ sở sản xuất). "Will create" là thì tương lai đơn phù hợp, nghĩa là "sẽ tạo ra," để chỉ rằng chúng tôi sẽ tạo ra một chương trình tự động hóa nhà máy toàn diện để đáp ứng nhu cầu của công ty bạn sau chuyến thăm.\n(B) was created (past simple passive): "Was created" có nghĩa là "đã được tạo ra." Lý do không chọn là vì thì quá khứ bị động không phù hợp với ngữ cảnh khi mô tả một hành động sẽ xảy ra trong tương lai.\n(C) having created (present participle): "Having created" có nghĩa là "đã tạo ra" trong dạng hiện tại phân từ. Lý do không chọn là vì cấu trúc này không phù hợp với ngữ cảnh khi cần một động từ chính ở thì tương lai.\n(D) had created (past perfect): "Had created" có nghĩa là "đã tạo ra" trước một thời điểm trong quá khứ. Lý do không chọn là vì thì quá khứ hoàn thành không phù hợp với ngữ cảnh khi mô tả hành động sẽ xảy ra trong tương lai.', 'Sau chuyến thăm cơ sở sản xuất của bạn ở Hong Kong vào tuần tới, chúng tôi sẽ tạo ra một chương trình tự động hóa nhà máy toàn diện để đáp ứng nhu cầu của công ty bạn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_008', 'zenlish_practice', 'The lease with The Pawlicki Group ______ if modifications to the existing offices are made.', 'had continued', 'will be continued', 'was continuing', 'has been continuing', 'B', 'Giải thích: Trong câu này, cần một dạng của động từ "continue" ở thì tương lai bị động để diễn đạt rằng hợp đồng thuê sẽ được tiếp tục nếu có các sửa đổi. "Will be continued" là dạng tương lai bị động, phù hợp với ngữ cảnh câu chỉ điều kiện tương lai khi có sự thay đổi.\n(A) had continued (past perfect): "had continued" là thì quá khứ hoàn thành, không phù hợp vì câu này nói về tương lai chứ không phải quá khứ.\n(C) was continuing (past continuous): "was continuing" là thì quá khứ tiếp diễn, không phù hợp vì câu này cần một thì tương lai để nói về điều kiện sẽ xảy ra.\n(D) has been continuing (present perfect continuous): "has been continuing" là thì hiện tại hoàn thành tiếp diễn, không phù hợp vì câu này cần một thì tương lai.', 'Hợp đồng thuê với Tập đoàn Pawlicki sẽ được tiếp tục nếu có sự sửa đổi đối với các văn phòng hiện tại.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_009', 'zenlish_practice', 'After the team meeting next week, Ms. Li ______ whether the project deadline needs to be changed.', 'to decide', 'deciding', 'will decide', 'has decided', 'C', 'Giải thích: Trong câu này, cần một động từ ở thì tương lai đơn để chỉ hành động sẽ xảy ra sau cuộc họp đội ngũ vào tuần tới. "Will decide" là dạng tương lai đơn của động từ "decide," phù hợp với ngữ cảnh câu mô tả rằng Ms. Li sẽ quyết định liệu có cần thay đổi hạn chót dự án hay không sau cuộc họp.\n(A) to decide (infinitive): "to decide" là dạng nguyên mẫu của động từ, không phù hợp vì không có dấu hiệu của một cấu trúc cần nguyên mẫu với "to" ở đây.\n(B) deciding (present participle): "deciding" là dạng hiện tại phân từ, không phù hợp vì câu này cần một động từ chỉ tương lai, không phải mô tả một hành động đang diễn ra hoặc liên tục.\n(D) has decided (present perfect): "has decided" là thì hiện tại hoàn thành, không phù hợp vì câu này mô tả một hành động sẽ xảy ra trong tương lai, không phải một hành động đã hoàn thành.', 'Sau cuộc họp đội ngũ vào tuần tới, Ms. Li sẽ quyết định liệu hạn chót dự án có cần được thay đổi hay không.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0036_q_010', 'zenlish_practice', 'While he is not enthusiastic about the suggestions, Mr. Shang ______ them.', 'considering', 'to consider', 'will consider', 'consider', 'C', 'Giải thích: Trong câu này, cần một động từ ở thì tương lai đơn để diễn tả hành động mà Mr. Shang sẽ thực hiện. "Will consider" là thì tương lai đơn của động từ "consider," phù hợp với ngữ cảnh câu mô tả rằng mặc dù Mr. Shang không nhiệt tình với những gợi ý, ông ấy sẽ xem xét chúng.\n(A) considering (present participle): "Considering" là dạng hiện tại phân từ, không phù hợp vì không diễn đạt được ý nghĩa tương lai của hành động.\n(B) to consider (infinitive): "To consider" là dạng nguyên mẫu của động từ, không phù hợp vì không diễn đạt được thì tương lai của hành động trong ngữ cảnh này.\n(D) consider (base form): "Consider" là dạng nguyên mẫu của động từ, không phù hợp vì câu này cần động từ chia theo thì tương lai.', 'Mặc dù ông không nhiệt tình với những gợi ý, nhưng ông Shang sẽ xem xét chúng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_001', 'zenlish_practice', 'Unless the shipment of tiles arrives early, work on the lobby floor ______ after the holiday.', 'has commenced', 'commencing', 'will commence', 'commenced', 'C', 'Giải thích: Trong câu này, cần một thì tương lai để diễn tả hành động sẽ xảy ra sau khi có điều kiện nhất định (như việc hàng gạch đến sớm). "Will commence" là thì tương lai đơn, nghĩa là "sẽ bắt đầu," phù hợp để chỉ rằng công việc sẽ bắt đầu sau kỳ nghỉ nếu hàng gạch không đến sớm.\n(A) has commenced (hiện tại hoàn thành): "has commenced" nghĩa là "đã bắt đầu," không phù hợp vì câu cần một thì tương lai.\n(B) commencing (dạng hiện tại phân từ): "commencing" là dạng hiện tại phân từ của động từ "commence," không phù hợp vì câu cần một thì tương lai.\n(D) commenced (quá khứ đơn): "commenced" có nghĩa là "đã bắt đầu," không phù hợp vì câu cần một thì tương lai.', 'Trừ khi hàng gạch đến sớm, công việc trên sàn sảnh sẽ bắt đầu sau kỳ nghỉ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_002', 'zenlish_practice', 'The envelope that we are going to send you _____ all the nescessary documents that you need to fill out.', 'was enclosing', 'will be enclosed', 'enclosed', 'will enclose', 'D', 'Giải thích: Trong câu này, "will enclose" là thì tương lai đơn, phù hợp để diễn tả hành động mà phong bì sẽ thực hiện trong tương lai. Đây là cấu trúc đúng để nói về việc phong bì sẽ chứa các tài liệu cần thiết mà bạn phải điền vào.\n(A) was enclosing: Không đúng vì thì quá khứ tiếp diễn không phù hợp với ngữ cảnh tương lai của câu.\n(B) will be enclosed: Không đúng vì cấu trúc bị động không phù hợp với ngữ cảnh hành động của phong bì.\n(C) enclosed: Không đúng vì thì quá khứ đơn không phù hợp với ngữ cảnh tương lai.', 'Phong bì mà chúng tôi sẽ gửi cho bạn sẽ chứa tất cả các tài liệu cần thiết mà bạn cần điền vào.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_003', 'zenlish_practice', 'Milldell Bus Company''s service connecting the city''s two airports ______ shortly.', 'commence', 'commencing', 'commenced', 'will commence', 'D', 'Giải thích: "Will commence" là thì tương lai đơn, phù hợp với ngữ cảnh diễn tả việc dịch vụ của Công ty Xe buýt Milldell kết nối hai sân bay của thành phố sẽ sớm bắt đầu.\n(A) commence (v.): "Commence" là động từ nguyên mẫu, không phù hợp với ngữ pháp của câu này.\n(B) commencing (v.): "Commencing" là hiện tại phân từ, không phù hợp với ngữ cảnh cần thì tương lai.\n(C) commenced (v.): "Commenced" là quá khứ đơn, không phù hợp với ngữ cảnh của câu này.', 'Dịch vụ của Công ty Xe buýt Milldell kết nối hai sân bay của thành phố sẽ sớm bắt đầu.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_004', 'zenlish_practice', 'At the next staff meeting, Yoshihiro Miura ______ the most promising products under development.', 'will discuss', 'had discussed', 'discussing', 'to discuss', 'A', 'Giải thích: Trong câu này, thì tương lai "will discuss" được sử dụng để chỉ một hành động sẽ xảy ra trong tương lai. Vì cuộc họp nhân viên tiếp theo chưa xảy ra, nên thì tương lai là lựa chọn phù hợp.\n(B) had discussed: Không đúng vì thì quá khứ hoàn thành không phù hợp với ngữ cảnh về một hành động trong tương lai.\n(C) discussing: Không đúng vì đây là dạng hiện tại phân từ, không phù hợp với ngữ cảnh câu.\n(D) to discuss: Không đúng vì đây là dạng nguyên mẫu và không phù hợp với yêu cầu về thì của câu.', 'Tại cuộc họp nhân viên tiếp theo, Yoshihiro Miura sẽ thảo luận về các sản phẩm hứa hẹn nhất đang được phát triển.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_005', 'zenlish_practice', 'Real estate agents in Stranton anticipate that property values ______ in the coming year.', 'increasingly', 'increasing', 'will increase', 'to increase', 'C', 'Giải thích: Trong câu này, "will increase" là dạng thì tương lai phù hợp để diễn tả dự đoán về sự thay đổi giá trị bất động sản trong năm tới.\n(A) increasingly: Không đúng vì đây là trạng từ và không phù hợp với ngữ pháp của câu.\n(B) increasing: Không đúng vì đây là dạng hiện tại phân từ, không phù hợp với cấu trúc dự đoán về tương lai.\n(D) to increase: Không đúng vì đây là dạng nguyên mẫu và không phù hợp với cấu trúc của câu dự đoán.', 'Các đại lý bất động sản ở Stranton dự đoán rằng giá trị bất động sản sẽ tăng trong năm tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_006', 'zenlish_practice', 'The winter agenda of the company''s community service club ______ later this afternoon.', 'circulated', 'has circulated', 'has been circulating', 'will be circulated', 'D', 'Giải thích: Trong câu này, "later this afternoon" ám chỉ một hành động sẽ xảy ra trong tương lai. Vì vậy, câu cần sử dụng thì tương lai bị động. "Will be circulated" là dạng bị động của "will circulate," có nghĩa là "sẽ được phân phát." Câu này có nghĩa là chương trình mùa đông của câu lạc bộ dịch vụ cộng đồng của công ty sẽ được phân phát vào chiều nay.\n(A) circulated (v.): "circulated" là thì quá khứ của "circulate," có nghĩa là "đã phân phát." Lý do không chọn là vì thì quá khứ không phù hợp với ngữ cảnh chỉ tương lai.\n(B) has circulated (v.): "has circulated" là thì hiện tại hoàn thành, có nghĩa là "đã phân phát." Lý do không chọn là vì thì này chỉ một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp với ngữ cảnh tương lai.\n(C) has been circulating (v.): "has been circulating" là thì hiện tại hoàn thành tiếp diễn, có nghĩa là "đã và đang được phân phát." Lý do không chọn là vì câu này cần một hành động đơn lẻ sẽ xảy ra trong tương lai, không phải hành động đang diễn ra.', 'Chương trình mùa đông của câu lạc bộ dịch vụ cộng đồng của công ty sẽ được phân phát vào chiều nay.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_007', 'zenlish_practice', 'The news will ____ released as soon as possible.', 'be', 'is', 'are', 'been', 'A', 'Giải thích: Trong câu này, "will" là thì tương lai, và khi sử dụng thì tương lai, động từ chính phải ở dạng nguyên mẫu không có "to" (đi kèm với "will"). Vì vậy, động từ chính trong câu phải là "be" để phù hợp với cấu trúc câu: "will + be + past participle."\n(B) is: "is" là thì hiện tại đơn, không phù hợp với "will" để diễn tả tương lai.\n(C) are: "are" là thì hiện tại đơn, không phù hợp với "will" trong cấu trúc câu này.\n(D) been: "been" là phân từ quá khứ của động từ "be", không phù hợp với cấu trúc của câu khi cần động từ nguyên mẫu sau "will."', 'Tin tức sẽ được phát hành càng sớm càng tốt.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_008', 'zenlish_practice', 'After we finish this video, I ________ all of this director’s movies.', 'will see', 'will be seeing', 'will have seen', 'will have been seen', 'C', 'Giải thích: Cụm “all of this director’s movies” cho thấy kết quả hoàn tất (xem hết toàn bộ) và điều này sẽ xảy ra trong tương lai (sau khi xem nốt video này) nên cần sử dụng thì tương lai hoàn thành (will have + past participle). Vì vậy, "will have seen" là lựa chọn chính xác.\n(A) will see: "will see" là thì tương lai đơn, không diễn tả rõ hành động sẽ hoàn tất trước một thời điểm trong tương lai.\n(B) will be seeing: "will be seeing" là thì tương lai tiếp diễn, không phù hợp với yêu cầu của câu vì không diễn tả hành động hoàn tất trước thời điểm tương lai.\n(D) will have been seen: "will have been seen" là thì tương lai hoàn thành bị động, không phù hợp vì câu này cần một dạng chủ động.', 'Sau khi chúng tôi hoàn thành video này, tôi sẽ xem tất cả các bộ phim của đạo diễn này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_009', 'zenlish_practice', 'The final performance of the play will____ place on Monday.', 'take', 'taken', 'takes', 'took', 'A', 'Giải thích: Trong câu này, "will" là thì tương lai, và khi sử dụng thì tương lai, động từ chính phải ở dạng nguyên mẫu không có "to" (đi kèm với "will"). Vì vậy, động từ chính trong câu phải là "take" để phù hợp với cấu trúc câu: "will + base form of the verb."\n(B) taken: "taken" là phân từ quá khứ, không phù hợp với cấu trúc của câu khi cần động từ nguyên mẫu sau "will."\n(C) takes: "takes" là thì hiện tại đơn, không phù hợp với "will" để diễn tả tương lai.\n(D) took: "took" là thì quá khứ đơn, không phù hợp với "will" để diễn tả tương lai.', 'Buổi biểu diễn cuối cùng của vở kịch sẽ diễn ra vào thứ Hai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0037_q_010', 'zenlish_practice', 'He____ asleep unless he is kept active continuously.', 'shall fall', 'fall', 'falling', 'will fall', 'D', 'Giải thích: Trong câu này, "unless" yêu cầu một mệnh đề điều kiện để diễn tả một tình huống tương lai. Để nói rằng điều gì sẽ xảy ra trong tương lai nếu điều kiện không được thực hiện, chúng ta sử dụng thì tương lai đơn với "will". Do đó, "will fall" là lựa chọn chính xác để diễn tả rằng anh ấy sẽ ngủ nếu không được giữ cho hoạt động liên tục.\n(A) shall fall: "shall fall" là thì tương lai với "shall", thường không được sử dụng trong ngữ cảnh điều kiện như vậy.\n(B) fall: "fall" là thì hiện tại đơn, không phù hợp với ngữ cảnh điều kiện của tương lai.\n(C) falling: "falling" là dạng tiếp diễn, không phù hợp với cấu trúc câu điều kiện với "unless".', 'Nếu không được vận động liên tục, anh ấy sẽ ngủ gật.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_001', 'zenlish_practice', 'You can try asking Martin for help but ____.', 'it won’t do you any good', 'it’s not doing you any good', 'it won’t be doing you any good', 'it doesn’t do you any good', 'A', 'Giải thích: Trong câu này, chúng ta cần một cách diễn đạt để chỉ ra rằng việc nhờ Martin giúp đỡ có thể không mang lại lợi ích. "It won’t do you any good" là lựa chọn chính xác vì sử dụng thì tương lai đơn "won’t do" để dự đoán rằng hành động này sẽ không có lợi trong tương lai.\n(B) it’s not doing you any good: "it’s not doing" là thì hiện tại tiếp diễn, không phù hợp vì câu cần dự đoán tương lai về lợi ích của hành động.\n(C) it won’t be doing you any good: "it won’t be doing" là thì tương lai tiếp diễn, không cần thiết ở đây vì không cần nhấn mạnh hành động đang xảy ra liên tục trong tương lai.\n(D) it doesn’t do you any good: "it doesn’t do" là thì hiện tại đơn, không phù hợp với ngữ cảnh dự đoán tương lai.', 'Bạn có thể thử nhờ Martin giúp đỡ nhưng điều đó sẽ không có lợi cho bạn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_002', 'zenlish_practice', 'I am not sure but it ____________________ tomorrow.', 'is going to rain', 'will rains', 'will going to rain', 'will rain', 'A', 'Giải thích: Trong câu này, "I am not sure but it" yêu cầu một dự đoán về thời tiết trong tương lai. Dù "không chắc chắn" nhưng ngầm hiểu là có dấu hiệu sắp mưa vì có liên từ "but". Câu này có thể hiểu là "Tôi không chắc 100%, nhưng có dấu hiệu trời sắp mưa".\n(B) will rains: "will rains" là sai vì động từ "rain" không được chia ở dạng số nhiều sau "will."\n(C) will going to rain: "will going to rain" là cấu trúc sai vì "will" và "going to" không được sử dụng cùng nhau trong cấu trúc dự đoán.\n(D) will rain: "will rain" là cũng đúng để dự đoán về thời tiết, nhưng không phù hợp với ngữ cảnh cần sự không chắc chắn với dự đoán hiện tại như "is going to rain."', 'Tôi không chắc chắn nhưng có thể sẽ mưa vào ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_003', 'zenlish_practice', 'A: This letter is in French, and I don''t know French. Can you help me? B: Sure, I ___________ it for you.', 'am going to translate', 'won''t translate', 'will translate', 'am translate', 'C', 'Giải thích: Trong câu này, người nói đang phản hồi một yêu cầu giúp đỡ và đưa ra sự cam kết trong tương lai. "Will translate" là thì tương lai đơn, phù hợp để thể hiện lời hứa hay quyết định ngay tại thời điểm nói.\n(A) am going to translate: "am going to translate" cũng đúng về mặt ngữ pháp và có thể sử dụng để diễn tả ý định trong tương lai. Tuy nhiên, "will translate" thường được sử dụng hơn trong các phản hồi trực tiếp như vậy.\n(B) won''t translate: "won''t translate" là thì tương lai phủ định, không phù hợp vì nó diễn tả việc từ chối không giúp đỡ.\n(D) am translate: "am translate" là sai vì thiếu thì hiện tại tiếp diễn phù hợp; nên dùng "am translating" nếu muốn dùng thì hiện tại tiếp diễn.', 'A: Lá thư này bằng tiếng Pháp và tôi không biết tiếng Pháp. Bạn có thể giúp tôi không? B: Chắc chắn, tôi sẽ dịch nó cho bạn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_004', 'zenlish_practice', 'People will ___________ on the moon in the future.', 'living', 'live', 'are live', 'be live', 'B', 'Giải thích: Trong câu này, "will" là thì tương lai, và khi sử dụng "will" để dự đoán về một sự việc trong tương lai, động từ chính phải ở dạng nguyên mẫu không có "to" (đi kèm với "will"). Do đó, "live" là lựa chọn chính xác để diễn tả rằng con người sẽ sống trên mặt trăng trong tương lai.\n(A) living: "living" là dạng động từ hiện tại tiếp diễn hoặc dạng danh động từ, không phù hợp với cấu trúc câu yêu cầu thì tương lai.\n(C) are live: "are live" là cấu trúc sai vì "are" là thì hiện tại, không phù hợp với "will" để diễn tả tương lai.\n(D) be live: "be live" không phải là một cấu trúc đúng để diễn tả hành động trong tương lai; "live" là động từ chính cần thiết ở đây.', 'Con người sẽ sống trên mặt trăng trong tương lai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_005', 'zenlish_practice', 'When Tom arrives, we ___________ a party.', 'will has', 'have', 'are going to has', 'will have', 'D', 'Giải thích: Trong câu này, "When Tom arrives" là mốc thời gian trong tương lai, và mệnh đề chính diễn tả một hành động sẽ diễn ra trong tương lai nên cần dùng will + động từ nguyên mẫu.\n(A) will has: "will has" là sai vì sau "will" cần động từ nguyên mẫu.\n(B) have: "have" là thì hiện tại, không phù hợp với ngữ cảnh của câu nói về hành động trong tương lai.\n(C) are going to has: "are going to has" là sai về cấu trúc vì sau "be going to" cần động từ nguyên mẫu.', 'Khi Tom đến, chúng tôi sẽ tổ chức một bữa tiệc.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_006', 'zenlish_practice', 'Nobody _______________ recognize you in that wig.', 'are going to', 'will', 'won''t', 'isn''t go to', 'B', 'Giải thích: Câu này diễn tả dự đoán trong tương lai "sẽ không có ai nhận ra bạn".\n(A) are going to: sai vì nobody là chủ ngữ số ít → phải là is going to\n(C) won’t: sai vì "Nobody" đã mang nghĩa phủ định\n(D) isn’t go to: sai cấu trúc (động từ nguyên mẫu "go" không thể đi sau động từ to be "is")', 'Không ai sẽ nhận ra bạn trong bộ tóc giả đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_007', 'zenlish_practice', 'I _______ return the book after I read it.', 'will', 'am', 'not', 'going to', 'A', 'Giải thích: Trong câu này, để diễn tả một hành động sẽ xảy ra trong tương lai (trả sách) sau khi hoàn thành một hành động khác (sau khi đọc cuốn sách), chúng ta sử dụng thì tương lai đơn với "will."\n(B) am: "am" là thì hiện tại đơn và không đi trước động từ thường "return".\n(C) not: "not" là một từ phủ định, cần đi với trợ động từ\n(D) going to: "going to" thiếu động từ to be để tạo thành cấu trúc thì tương lai gần.', 'Tôi sẽ trả lại cuốn sách sau khi tôi đọc xong.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_008', 'zenlish_practice', 'Tom _____________ at eight tomorrow morning.', 'will arrives', 'arrives', 'will going to arrive', 'will arrive', 'D', 'Giải thích: Trong câu này, để diễn tả một hành động sẽ xảy ra trong tương lai, chúng ta sử dụng thì tương lai đơn với "will." Đối với câu này, cấu trúc đúng là "will arrive" để thể hiện rằng Tom sẽ đến vào lúc tám giờ sáng ngày mai.\n(A) will arrives: "will arrives" là sai về ngữ pháp vì động từ "arrives" không được chia đúng với "will."\n(B) arrives: "arrives" là thì hiện tại đơn, không phù hợp với cấu trúc thì tương lai cần thiết ở đây.\n(C) will going to arrive: "will going to arrive" là cấu trúc sai vì "will" và "going to" không được sử dụng cùng nhau.', 'Tom sẽ đến vào lúc tám giờ sáng ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_009', 'zenlish_practice', 'They (do) ___________it for you tomorrow.', 'will do', 'do', 'are doing', 'have done', 'A', 'Giải thích: Trong câu này, để diễn tả một hành động sẽ xảy ra trong tương lai, chúng ta sử dụng thì tương lai đơn với "will." Vì vậy, cấu trúc đúng là "will do" để thể hiện rằng họ sẽ làm điều đó cho bạn vào ngày mai.\n(B) do: "do" là thì hiện tại đơn, không phù hợp để diễn tả hành động trong tương lai.\n(C) are doing: "are doing" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của dự đoán hành động trong tương lai.\n(D) have done: "have done" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh khi cần diễn tả hành động trong tương lai.', 'Họ sẽ làm điều đó cho bạn vào ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0038_q_010', 'zenlish_practice', 'I __________ here until he __________ me.', 'will stay/ answers', 'stay/ will answer', 'stay/ answer', 'will stay/ will answer', 'A', 'Giải thích: Đây là câu có mệnh đề thời gian với until. Mệnh đề chính (nói về tương lai) dùng will + V (will stay); nhưng mệnh đề thời gian với until / when / after / before / as soon as KHÔNG dùng thì tương lai (will) mà phải dùng hiện tại đơn để nói về tương lai.', 'Tôi sẽ ở đây cho đến khi anh ấy trả lời tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_001', 'zenlish_practice', 'It is possible that in fifty years, there ________ any tigers in the world.', 'aren''t going to be', 'won''t be', 'isn''t', 'aren''t', 'B', 'Giải thích: Trong câu này, chúng ta cần một cấu trúc phù hợp để dự đoán một khả năng trong tương lai, và "won''t be" là cấu trúc đúng để thể hiện sự phủ định trong thì tương lai. "Won''t be" (will not be) thể hiện rằng có thể không còn hổ trên thế giới trong tương lai.\n(A) aren''t going to be: "aren''t going to be" là thì tương lai gần và cũng có thể sử dụng để dự đoán, nhưng "won''t be" thường được dùng nhiều hơn trong các dự đoán kiểu này.\n(C) isn''t: "isn''t" là thì hiện tại phủ định, không phù hợp với dự đoán trong tương lai.\n(D) aren''t: "aren''t" là thì hiện tại phủ định, không phù hợp với dự đoán trong tương lai.', 'Có thể trong năm mươi năm nữa, sẽ không còn bất kỳ con hổ nào trên thế giới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_002', 'zenlish_practice', 'I promise I ____________ you everything in the end.', 'am tell', 'am going to tell', 'will tell', 'told', 'C', 'Giải thích: Dùng thì tương lai đơn để nói về lời hứa hay cam kết thực hiện điều gì đó trong tương lai.\n(A) am tell: "am tell" là cấu trúc sai về ngữ pháp; cần sử dụng "am telling" nếu sử dụng thì hiện tại tiếp diễn.\n(B) am going to tell: "am going to tell" là cấu trúc thì tương lai gần và không dùng khi nói về lời hứa.\n(D) told: "told" là thì quá khứ, không phù hợp với ngữ cảnh cam kết về hành động trong tương lai.', 'Tôi hứa rằng tôi sẽ kể cho bạn mọi thứ vào cuối cùng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_003', 'zenlish_practice', 'I am sure you ___________ a good time staying with Richard.', 'are going to have', 'will have', 'are have', 'has', 'B', 'Giải thích: Dùng thì tương lai đơn để nói về dự đoán chủ quan trong tương lai. "Will have" là cấu trúc đúng để diễn tả rằng bạn chắc chắn sẽ có khoảng thời gian tốt khi ở với Richard.\n(A) are going to have: "are going to have" là cấu trúc thì tương lai gần và có thể sử dụng để diễn tả dự đoán khi có căn cứ, trong khi câu này không đề cập căn cứ nào để đưa ra dự đoán.\n(C) are have: "are have" là cấu trúc sai về ngữ pháp; cần sử dụng "are having" nếu muốn sử dụng thì hiện tại tiếp diễn.\n(D) has: "has" là thì hiện tại đơn và không phù hợp với ngữ cảnh của sự dự đoán trong tương lai.', 'Tôi chắc chắn rằng bạn sẽ có một khoảng thời gian tốt khi ở với Richard.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_004', 'zenlish_practice', 'When ______ you know your exam results?', 'are you going to', 'will', 'are', 'have', 'A', 'Giải thích: Trong câu này, để hỏi về thời điểm của một sự kiện trong tương lai, cấu trúc "are you going to" là phù hợp nhất để hỏi về dự định hoặc kế hoạch. Câu hỏi này tìm hiểu khi nào bạn dự định biết kết quả kỳ thi của mình.\n(B) will: "will" có thể được sử dụng để hỏi về thời điểm trong tương lai, nhưng đối với sự kiện có lịch cụ thể như ngày biết điểm thi thì nên dùng "Be going to"\n(C) are: "are" là thì hiện tại và không phù hợp để hỏi về thời điểm của sự kiện trong tương lai.\n(D) have: "have" không phù hợp với ngữ cảnh câu hỏi về thời điểm trong tương lai.', 'Khi nào bạn sẽ biết kết quả kỳ thi của mình?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_005', 'zenlish_practice', 'I am sure that everything ____________ be all right in the end.', 'is going to', 'is', 'might', 'will', 'D', 'Giải thích: Trong câu này, để thể hiện sự chắc chắn, niềm tin (believe that) về một điều gì đó sẽ xảy ra trong tương lai, chúng ta sử dụng "will."\n(A) is going to: thường dùng khi có kế hoạch trước, hoặc có dấu hiệu rõ ràng ở hiện tại thay vì niềm tin chủ quan của người nói.\n(B) is: "is" là thì hiện tại đơn và không phù hợp với ngữ cảnh của sự dự đoán về tương lai.\n(C) might: "might" thể hiện sự không chắc chắn hoặc khả năng có thể xảy ra, không phù hợp với sự chắc chắn được diễn tả trong câu.', 'Tôi chắc chắn rằng mọi thứ sẽ ổn vào cuối cùng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_006', 'zenlish_practice', 'We believe that she (recover) ________from her illness soon.', 'is going to recover', 'recovered', 'will recover', 'is recovering', 'C', 'Giải thích: Cần dùng thì tương lai đơn để thể hiện niềm tin (believe) vào việc một điều gì đó sẽ xảy ra trong tương lai.\n(A) is going to recover: "is going to recover" là cấu trúc thì tương lai gần, thường dùng khi có kế hoạch trước, hoặc có dấu hiệu rõ ràng ở hiện tại thay vì niềm tin chủ quan của người nói.\n(B) recovered: "recovered" là thì quá khứ, không phù hợp với ngữ cảnh dự đoán sự hồi phục trong tương lai.\n(D) is recovering: "is recovering" là thì hiện tại tiếp diễn, không phù hợp với việc dự đoán một sự hồi phục sẽ xảy ra trong tương lai.', 'Chúng tôi tin rằng cô ấy sẽ hồi phục từ căn bệnh của mình sớm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_007', 'zenlish_practice', 'People say that in 2050 computers ___________ really small.', 'will be', 'are going to be', 'are being', 'will been', 'A', 'Giải thích: Trong câu này, chúng ta cần dự đoán về một sự việc trong tương lai xa, và cấu trúc "will be" là phù hợp nhất để thể hiện rằng mọi người nghĩ rằng máy tính sẽ trở nên rất nhỏ vào năm 2050.\n(B) are going to be: "are going to be" là cấu trúc thì tương lai gần, cũng có thể sử dụng, nhưng "will be" thường được dùng hơn trong các dự đoán về tương lai xa.\n(C) are being: "are being" là thì hiện tại tiếp diễn, không phù hợp với việc dự đoán về tương lai.\n(D) will been: "will been" là cấu trúc sai về ngữ pháp; cần là "will have been" nếu muốn sử dụng thì hiện tại hoàn thành trong tương lai.', 'Người ta nói rằng vào năm 2050, máy tính sẽ trở nên rất nhỏ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_008', 'zenlish_practice', 'We ________ out when the rain stops.', 'will go', 'go', 'went', 'are going', 'A', 'Giải thích: Trong câu này, chúng ta đang nói về một hành động sẽ xảy ra trong tương lai khi một điều kiện (mưa ngừng) xảy ra. Cấu trúc "will go" là phù hợp để diễn tả hành động sẽ thực hiện trong tương lai sau khi điều kiện được đáp ứng.\n(B) go: "go" là thì hiện tại đơn, không phù hợp với ngữ cảnh của việc dự đoán hành động trong tương lai.\n(C) went: "went" là thì quá khứ, không phù hợp với ngữ cảnh của hành động sẽ xảy ra trong tương lai.\n(D) are going: "are going" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của dự đoán hành động trong tương lai.', 'Chúng tôi sẽ ra ngoài khi mưa ngừng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_009', 'zenlish_practice', 'I imagine the stadium _____________ full for the match on Saturday.', 'is be', 'is going to', 'will be', 'is going to be', 'C', 'Giải thích: Khi nói về dự đoán chủ quan về một sự việc trong tương lai cần dùng thì tương lai đơn. Trong câu này, chúng ta dự đoán về tình trạng của sân vận động vào trận đấu ngày thứ bảy nên "will be" là phù hợp.\n(A) is be: "is be" là cấu trúc sai về ngữ pháp; cần là "is" hoặc "will be."\n(B) is going to: sau "is going to" là động từ, trong khi "full" là tính từ\n(D) is going to be: dự đoán không có căn cứ nên dùng "will be".', 'Tôi tưởng tượng rằng sân vận động sẽ kín vào trận đấu vào thứ Bảy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0039_q_010', 'zenlish_practice', 'My father (call) __________ you in 5 minutes.', 'is calling', 'will call', 'has called', 'called', 'B', 'Giải thích: Trong câu này, chúng ta đang nói về một hành động sẽ xảy ra trong tương lai, cụ thể là trong 5 phút tới nên "will call" là đáp án phù hợp.\n(A) is calling: "is calling" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của việc dự đoán một hành động trong tương lai.\n(C) has called: "has called" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh hành động sẽ xảy ra trong tương lai.\n(D) called: "called" là thì quá khứ, không phù hợp với ngữ cảnh hành động trong tương lai.', 'Cha tôi sẽ gọi bạn trong 5 phút nữa.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_001', 'zenlish_practice', 'Do you think you ___________ work here when you are fifty years old?', 'are will', 'will be', 'are going to', 'will', 'D', 'Giải thích: Câu này cần dùng thì tương lai đơn để hỏi về một tình trạng hoặc hành động sẽ xảy ra trong tương lai xa (khi bạn 50 tuổi).\n(A) are will: "are will" là cấu trúc sai ngữ pháp.\n(B) will be: không thể đứng trước động từ thường "work".\n(C) are going to: "are going to" là cấu trúc thì tương lai gần.', 'Bạn có nghĩ rằng bạn sẽ làm việc ở đây khi bạn 50 tuổi không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_002', 'zenlish_practice', 'According to weather report, it ___________ sunny tomorrow.', 'is going to', 'is be', 'will', 'will be', 'D', 'Giải thích: Trong câu này, chúng ta dự đoán về thời tiết vào ngày mai nên cần dùng thì tương lai. Chỉ có "Will be" là đúng ngữ pháp.\n(A) is going to: "is going to" thiếu động từ nguyên mẫu đi sau\n(B) is be: "is be" là cấu trúc sai\n(C) will: "will" cần đi kèm với động từ chính để hoàn chỉnh cấu trúc, như "will be."', 'Theo báo cáo thời tiết, trời sẽ nắng vào ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_003', 'zenlish_practice', 'If it rains, he (stay) __________ at home.', 'has stayed', 'is staying', 'stayed', 'will stay', 'D', 'Giải thích: Trong câu điều kiện loại 1 (thực tế và có thể xảy ra trong tương lai), chúng ta sử dụng cấu trúc "will + động từ nguyên mẫu" để diễn tả hành động sẽ xảy ra khi điều kiện được thỏa mãn. Câu này dự đoán rằng nếu trời mưa, anh ấy sẽ ở nhà.\n(A) has stayed: "has stayed" là thì hiện tại hoàn thành, không phù hợp với cấu trúc câu điều kiện loại 1.\n(B) is staying: "is staying" là thì hiện tại tiếp diễn, không phù hợp với cấu trúc câu điều kiện loại 1.\n(C) stayed: "stayed" là thì quá khứ, không phù hợp với ngữ cảnh của câu điều kiện loại 1.', 'Nếu trời mưa, anh ấy sẽ ở nhà.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_004', 'zenlish_practice', 'The Browns __________ their housework when you __________ next Sunday.', 'will do/ come', 'do/ will come', 'will do/ will come', 'do/ come', 'A', 'Giải thích: Câu này nói về một hành động trong tương lai với mệnh đề thời gian "when..." diễn tả thời điểm xảy ra. Hành động chính dùng thì tương lai (will do) còn động từ trong mệnh đề thời gian phải dùng thì hiện tại đơn (come).\n(B) do/ will come: "do" là thì hiện tại đơn, không phù hợp khi dự đoán một hành động sẽ xảy ra trong tương lai.\n(C) will do/ will come: Dùng hai lần "will" không đúng trong câu này. Khi có một hành động trong tương lai sẽ xảy ra khi một điều kiện khác xảy ra, chúng ta chỉ dùng "will" cho hành động tương lai chính và thì hiện tại cho mệnh đề thời gian.\n(D) do/ come: "do" và "come" là thì hiện tại đơn, không phù hợp khi dự đoán một hành động sẽ xảy ra trong tương lai.', 'Nhà Browns sẽ làm việc nhà của họ khi bạn đến vào Chủ nhật tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_005', 'zenlish_practice', 'When I __________ Mr Pike tomorrow, I __________ him of that.', 'will see/ remind', 'see / will remind', 'will see/ will remind', 'see/ remind', 'B', 'Giải thích: Câu này nói về một hành động trong tương lai với mệnh đề thời gian "when..." diễn tả thời điểm xảy ra. Hành động chính dùng thì tương lai (will remind) còn động từ trong mệnh đề thời gian phải dùng thì hiện tại đơn (see).', 'Khi tôi gặp ông Pike vào ngày mai, tôi sẽ nhắc ông ấy về điều đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_006', 'zenlish_practice', 'I think he __________ as soon as he __________ the news.', 'will leave/ knows', 'leaves/ will know', 'leave/ will know', 'leaves/ knows', 'A', 'Giải thích: Câu này nói về một hành động trong tương lai với mệnh đề thời gian "as soon as..." (ngay sau khi) diễn tả thời điểm xảy ra. Hành động chính dùng thì tương lai (will leave) còn động từ trong mệnh đề thời gian phải dùng thì hiện tại đơn (knows).', 'Tôi nghĩ anh ấy sẽ rời đi ngay khi anh ấy biết tin.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_007', 'zenlish_practice', 'We __________ home as soon as we have finished our work.', 'go', 'will go', 'went', 'would go', 'B', 'Giải thích: Câu này nói về một hành động trong tương lai với mệnh đề thời gian "as soon as..." (ngay sau khi) diễn tả thời điểm xảy ra nên hành động chính phải chia ở thì tương lai đơn (will go)', 'Chúng tôi sẽ về nhà ngay khi chúng tôi hoàn thành công việc.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_008', 'zenlish_practice', 'Our English teacher __________ that lesson to us tomorrow.', 'will explain', 'explain', 'explains', 'has explained', 'A', 'Giải thích: Trong câu này, chúng ta dự đoán một hành động sẽ xảy ra trong tương lai. Do đó, chúng ta cần sử dụng "will + động từ nguyên mẫu" để diễn tả hành động sẽ được thực hiện vào ngày mai.\n(B) explain: "explain" là thì hiện tại đơn, không phù hợp khi nói về một hành động sẽ xảy ra trong tương lai.\n(C) explains: "explains" là thì hiện tại đơn, không phù hợp với ngữ cảnh dự đoán hành động trong tương lai.\n(D) has explained: "has explained" là thì hiện tại hoàn thành, không phù hợp khi dự đoán hành động trong tương lai.', 'Giáo viên tiếng Anh của chúng tôi sẽ giải thích bài học đó cho chúng tôi vào ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_009', 'zenlish_practice', 'My mother __________ to stay with us next weekend.', 'come', 'comes', 'will come', 'has come', 'C', 'Giải thích: Khi dự đoán một hành động sẽ xảy ra trong tương lai, chúng ta sử dụng cấu trúc "will + động từ nguyên mẫu." Trong câu này, chúng ta đang nói về việc mẹ của bạn sẽ đến thăm vào cuối tuần tới.\n(A) come: "come" là thì hiện tại đơn, không phù hợp khi dự đoán hành động trong tương lai.\n(B) comes: "comes" là thì hiện tại đơn, không phù hợp với ngữ cảnh dự đoán hành động trong tương lai.\n(D) has come: "has come" là thì hiện tại hoàn thành, không phù hợp khi nói về dự đoán hành động trong tương lai.', 'Mẹ tôi sẽ đến ở với chúng tôi vào cuối tuần tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0040_q_010', 'zenlish_practice', 'Milldell Bus Company’s service connecting the city’s two airports ________ shortly.', 'commence', 'commencing', 'commenced', 'will commence', 'D', 'Giải thích: Trong câu này, từ "shortly" (nghĩa là "sớm, trong thời gian ngắn") chỉ ra rằng hành động sẽ xảy ra trong tương lai gần. Do đó, chúng ta cần sử dụng thì tương lai đơn "will commence" (sẽ bắt đầu) để diễn đạt hành động "bắt đầu" của dịch vụ xe buýt kết nối giữa hai sân bay của thành phố.\n(A) commence (v.): "commence" có nghĩa là "bắt đầu." Lý do không chọn là vì đây là động từ nguyên mẫu, không phù hợp với ngữ pháp khi cần động từ chia ở thì tương lai.\n(B) commencing (gerund/present participle): "commencing" có nghĩa là "đang bắt đầu." Lý do không chọn là vì đây là danh động từ hoặc phân từ hiện tại, không phù hợp với ngữ pháp của câu khi cần động từ chia ở thì tương lai.\n(C) commenced (v., past tense): "commenced" có nghĩa là "đã bắt đầu." Lý do không chọn là vì đây là động từ chia ở thì quá khứ, không phù hợp khi câu cần thì tương lai đơn.', 'Dịch vụ của Công ty Xe buýt Milldell kết nối hai sân bay của thành phố sẽ sớm bắt đầu.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_001', 'zenlish_practice', 'The Tyneside Recreation Department _____ suggestions for new programs until the end of this month.', 'has accepted', 'will be accepting', 'accepting', 'to accept', 'B', 'Giải thích: "Will be accepting" là thì tương lai tiếp diễn, phù hợp với ngữ cảnh của câu để diễn tả rằng Sở Giải trí Tyneside sẽ tiếp tục nhận các đề xuất cho các chương trình mới cho đến cuối tháng này.\n(A) has accepted (present perfect): "has accepted" có nghĩa là "đã chấp nhận," không phù hợp với ngữ cảnh khi câu nói về một hành động sẽ diễn ra trong tương lai.\n(C) accepting (present participle): "accepting" là hiện tại phân từ, không phù hợp với cấu trúc câu khi cần một động từ tương lai.\n(D) to accept (infinitive): "to accept" là động từ nguyên mẫu, không phù hợp với cấu trúc của câu.', 'Sở Giải trí Tyneside sẽ tiếp nhận các đề xuất cho các chương trình mới cho đến cuối tháng này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_002', 'zenlish_practice', 'Because of a sudden decrease in sales, Mikkelsen Clothing suspended its current advertising campaign and _____ it substantially.', 'to modify', 'will be modifying', 'having modified', 'modifying', 'B', 'Giải thích: "Will be modifying" là động từ ở thì tương lai tiếp diễn, phù hợp với ngữ cảnh của câu khi diễn tả rằng Mikkelsen Clothing sẽ tiến hành thay đổi chiến dịch quảng cáo của mình trong tương lai do sự giảm đột ngột doanh số bán hàng.\n(A) to modify (infinitive): "to modify" là động từ nguyên mẫu, không phù hợp với ngữ pháp của câu.\n(C) having modified (perfect participle): "having modified" là quá khứ phân từ hoàn thành, không phù hợp với ngữ cảnh của câu.\n(D) modifying (present participle): "modifying" là hiện tại phân từ, không phù hợp với ngữ pháp của câu khi cần một động từ ở thì tương lai.', 'Do sự giảm đột ngột doanh số bán hàng, Mikkelsen Clothing đã tạm ngừng chiến dịch quảng cáo hiện tại và sẽ tiến hành thay đổi nó một cách đáng kể.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_003', 'zenlish_practice', 'The Brew Beverage Company ______ free samples in grocery stores next week.', 'providing', 'has been providing', 'was providing', 'will be providing', 'D', 'Giải thích: Câu này đang nói về một hành động sẽ xảy ra trong tương lai, vì vậy cần dùng thì tương lai tiếp diễn "will be providing" để diễn tả rằng hành động phát mẫu miễn phí sẽ xảy ra trong tuần tới.\n(A) providing: Không đúng vì đây là dạng hiện tại phân từ, không phù hợp với cấu trúc câu yêu cầu thì tương lai.\n(B) has been providing: Không đúng vì đây là thì hiện tại hoàn thành tiếp diễn, không phù hợp với ý nghĩa hành động trong tương lai.\n(C) was providing: Không đúng vì đây là thì quá khứ tiếp diễn, không phù hợp với ý nghĩa hành động trong tương lai.', 'Công ty Brew Beverage sẽ cung cấp các mẫu miễn phí tại các cửa hàng tạp hóa vào tuần tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_004', 'zenlish_practice', 'We ___________ our presentation at this time tomorrow morning.', 'made', 'have made', 'will be making', 'maked', 'C', 'Giải thích: Trong câu này, chúng ta đang nói về một hành động sẽ xảy ra trong tương lai và sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai. Vì vậy, cần sử dụng thì tương lai tiếp diễn "will be + V-ing.\n(A) made: "made" là thì quá khứ, không phù hợp với ngữ cảnh nói về hành động sẽ xảy ra trong tương lai.\n(B) have made: "have made" là thì hiện tại hoàn thành, không phù hợp khi nói về hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai.\n(D) maked: "maked" là dạng sai của động từ "make," không phải là một dạng đúng của thì.', 'Chúng tôi sẽ đang thực hiện bài thuyết trình của mình vào thời điểm này vào sáng mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_005', 'zenlish_practice', 'When you arrive, I _____ fruit.', 'will probably pick', 'am probably picking', 'probably pick', 'will probably be picking', 'D', 'Giải thích: Trong câu này, khi một hành động sẽ xảy ra cùng với một hành động khác trong tương lai, chúng ta dùng thì tương lai tiếp diễn để diễn tả hành động sẽ đang xảy ra tại thời điểm cụ thể trong tương lai. "Will probably be picking" phù hợp với ngữ cảnh vì hành động picking sẽ đang xảy ra khi bạn đến.\n(A) will probably pick: "will probably pick" là thì tương lai đơn, không phù hợp với việc diễn tả một hành động đang xảy ra khi hành động khác xảy ra.\n(B) am probably picking: "am probably picking" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh dự đoán hành động trong tương lai.\n(C) probably pick: "probably pick" là thì hiện tại đơn, không phù hợp với ngữ cảnh dự đoán hành động trong tương lai.', 'Khi bạn đến, tôi có thể sẽ đang hái trái cây.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_006', 'zenlish_practice', 'When they _________ tomorrow, we ________ in the sea.', 'come/ be swim', 'come/ will be swimming', 'came/ will be swimming', 'have come/ swim', 'B', 'Giải thích: Trong câu này, chúng ta cần diễn tả một hành động sẽ xảy ra trong tương lai (hành động "swimming") khi một hành động khác (hành động "come") xảy ra. Cấu trúc "will be + V-ing" được sử dụng để diễn tả hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(A) come/ be swim: "be swim" là dạng sai của động từ, không phù hợp với ngữ pháp.\n(C) came/ will be swimming: "came" là thì quá khứ, không phù hợp với ngữ cảnh nói về hành động sẽ xảy ra trong tương lai.\n(D) have come/ swim: "have come" là thì hiện tại hoàn thành, không phù hợp khi dự đoán hành động đang diễn ra trong tương lai.', 'Khi họ đến vào ngày mai, chúng tôi sẽ đang bơi ở biển.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_007', 'zenlish_practice', 'They _____ for Japan at 7 a.m tomorrow.', 'had been left', 'is leaving', 'will be leaving', 'leaving', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. Vì "They" là chủ ngữ số nhiều và hành động "leaving" sẽ xảy ra tại một thời điểm trong tương lai, chúng ta sử dụng "will be leaving."\n(A) had been left: "had been left" là thì quá khứ hoàn thành bị động, không phù hợp với ngữ cảnh.\n(B) is leaving: "is leaving" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh nói về hành động trong tương lai với chủ ngữ số nhiều.\n(D) leaving: "leaving" là dạng phân từ hiện tại, không đủ để diễn tả hành động tương lai với thì tương lai tiếp diễn.', 'Họ sẽ đang rời đi Nhật Bản vào lúc 7 giờ sáng ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_008', 'zenlish_practice', 'This time next month, I _____ on a beach.', 'will sit', 'will be sitting', 'am sitting', 'am going to sit', 'B', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. Vì "This time next month" chỉ thời điểm trong tương lai khi hành động đang diễn ra, chúng ta dùng "will be sitting."\n(A) will sit: "will sit" là thì tương lai đơn, không phù hợp với việc diễn tả hành động đang diễn ra tại một thời điểm cụ thể trong tương lai.\n(C) am sitting: "am sitting" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của thời điểm trong tương lai.\n(D) am going to sit: "am going to sit" là thì hiện tại tiếp diễn cho dự đoán hoặc kế hoạch trong tương lai, không phù hợp để diễn tả hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.', 'Vào thời điểm này tháng tới, tôi sẽ đang ngồi trên một bãi biển.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_009', 'zenlish_practice', '- A: I''ll ring you tomorrow at six. - B: No, don''t ring at six. I ____ the baby then. Ring later.', 'am bathing', 'bath', 'will be bathing', 'will bath', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "I will be bathing the baby then" nghĩa là "tôi sẽ đang tắm cho em bé vào thời điểm đó."\n(A) am bathing: "am bathing" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của hành động đang xảy ra trong tương lai.\n(B) bath: "bath" là danh từ hoặc động từ ở dạng nguyên thể, không phù hợp với cấu trúc câu yêu cầu.\n(D) will bath: "will bath" là dạng sai của động từ "bath," không phải là một dạng đúng của thì tương lai.', '- A: Tôi sẽ gọi cho bạn vào lúc sáu giờ mai. - B: Không, đừng gọi lúc sáu giờ. Tôi sẽ đang tắm cho em bé vào lúc đó. Gọi sau nhé.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0041_q_010', 'zenlish_practice', 'At noon tomorrow, I ________ on a beach somewhere.', '‘ll be relaxing', 'relax', 'will being relax', 'relaxed', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "I’ll be relaxing" nghĩa là "tôi sẽ đang thư giãn" vào thời điểm đó.\n(B) relax: "relax" là thì hiện tại đơn, không phù hợp với việc diễn tả hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(C) will being relax: "will being relax" là cấu trúc sai. Cấu trúc đúng là "will be relaxing."\n(D) relaxed: "relaxed" là thì quá khứ hoặc quá khứ phân từ, không phù hợp với việc diễn tả hành động trong tương lai.', 'Vào trưa mai, tôi sẽ đang thư giãn trên một bãi biển ở đâu đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_001', 'zenlish_practice', 'Tomorrow at 5 o’clock, she ____ ready to go out.', 'will be getting', 'is getting ready', 'was getting ready', 'will getting', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "She will be getting ready" nghĩa là "cô ấy sẽ đang chuẩn bị sẵn sàng" vào thời điểm đó.\n(B) is getting ready: "is getting ready" là thì hiện tại tiếp diễn, không phù hợp với việc diễn tả hành động trong tương lai.\n(C) was getting ready: "was getting ready" là thì quá khứ tiếp diễn, không phù hợp với việc diễn tả hành động trong tương lai.\n(D) will getting: "will getting" là cấu trúc sai. Cấu trúc đúng là "will be getting."', 'Vào lúc 5 giờ ngày mai, cô ấy sẽ đang chuẩn bị sẵn sàng để ra ngoài.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_002', 'zenlish_practice', 'Ramu _____ the house and Preeti will be washing the clothes.', 'was cleaning', 'is cleaning', 'have been cleaning', 'will be cleaning', 'D', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "Ramu will be cleaning the house" nghĩa là "Ramu sẽ đang dọn dẹp nhà cửa" vào thời điểm đó, khi mà Preeti sẽ đang giặt quần áo.\n(A) was cleaning: "was cleaning" là thì quá khứ tiếp diễn, không phù hợp với việc diễn tả hành động trong tương lai.\n(B) is cleaning: "is cleaning" là thì hiện tại tiếp diễn, không phù hợp với việc diễn tả hành động trong tương lai.\n(C) have been cleaning: "have been cleaning" là thì hiện tại hoàn thành tiếp diễn, không phù hợp với việc diễn tả hành động trong tương lai.', 'Ramu sẽ đang dọn dẹp nhà cửa và Preeti sẽ đang giặt quần áo.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_003', 'zenlish_practice', 'At 10 p.m tonight, I _______ dinner with my friend.', 'will be eating', 'ate', 'have eaten', 'has eaten', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "I will be eating dinner with my friend" nghĩa là "tôi sẽ đang ăn tối với bạn của tôi" vào lúc 10 giờ tối hôm nay.\n(B) ate: "ate" là thì quá khứ đơn, không phù hợp với việc diễn tả hành động trong tương lai.\n(C) have eaten: "have eaten" là thì hiện tại hoàn thành, không phù hợp với việc diễn tả hành động trong tương lai.\n(D) has eaten: "has eaten" là thì hiện tại hoàn thành ở ngôi thứ ba số ít, không phù hợp với việc diễn tả hành động trong tương lai.', 'Vào lúc 10 giờ tối hôm nay, tôi sẽ đang ăn tối với bạn của tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_004', 'zenlish_practice', 'My parents ________ Da Nang at this time next month.', 'visiting', 'have visited', 'will be visiting', 'visited', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "My parents will be visiting Da Nang" nghĩa là "bố mẹ tôi sẽ đang thăm Đà Nẵng" vào thời điểm này vào tháng tới.\n(A) visiting: "visiting" là thì hiện tại tiếp diễn, không phù hợp với việc diễn tả hành động trong tương lai.\n(B) have visited: "have visited" là thì hiện tại hoàn thành, không phù hợp với việc diễn tả hành động trong tương lai.\n(D) visited: "visited" là thì quá khứ đơn, không phù hợp với việc diễn tả hành động trong tương lai.', 'Bố mẹ tôi sẽ đang thăm Đà Nẵng vào thời điểm này vào tháng tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_005', 'zenlish_practice', 'Will Monu ____ TV at this time tomorrow?', 'watching', 'watched', 'watch', 'be watching', 'D', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "Will Monu be watching TV at this time tomorrow?" nghĩa là "Monu có đang xem TV vào thời điểm này vào ngày mai không?"\n(A) watching: "watching" là thì hiện tại tiếp diễn, không phù hợp với việc diễn tả hành động trong tương lai.\n(B) watched: "watched" là thì quá khứ đơn, không phù hợp với việc diễn tả hành động trong tương lai.\n(C) watch: "watch" là thì hiện tại đơn, không phù hợp với việc diễn tả hành động trong tương lai.', 'Monu có đang xem TV vào thời điểm này vào ngày mai không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_006', 'zenlish_practice', 'I _________ at the pub while you are taking your exam!', 'be drinking', 'will be drinking', 'have drunk', 'drank', 'B', 'Giải thích: Câu này mô tả 2 hành động đang xảy ra song song trong một khoảng thời gian trong tương lai, 2 mệnh đề liên kết bằng "while" (trong khi) nên 2 động từ đều chia ở thì tương lai tiếp diễn.\n(A) be drinking: "be drinking" thiếu trợ động từ "will"\n(C) have drunk: "have drunk" là thì hiện tại hoàn thành, không phù hợp với việc diễn tả hành động sẽ đang xảy ra trong tương lai.\n(D) drank: "drank" là thì quá khứ đơn, không phù hợp với việc diễn tả hành động trong tương lai.', 'Tôi sẽ đang uống ở quán rượu trong khi bạn đang làm bài thi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_007', 'zenlish_practice', 'What ____ at this time tomorrow ?', 'will you do', 'will you have done', 'will you be doing', 'will you have been doing', 'C', 'Giải thích: Trong câu hỏi này, chúng ta cần dùng thì tương lai tiếp diễn "will be + V-ing" để hỏi về một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "What will you be doing at this time tomorrow?" nghĩa là "Bạn sẽ đang làm gì vào thời điểm này ngày mai?"\n(A) will you do: "will you do" là thì tương lai đơn, không phù hợp khi hỏi về hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(B) will you have done: "will you have done" là thì tương lai hoàn thành, dùng để hỏi về hành động đã hoàn thành trước một thời điểm trong tương lai, không phù hợp trong ngữ cảnh này.\n(D) will you have been doing: "will you have been doing" là thì tương lai hoàn thành tiếp diễn, dùng để hỏi về một hành động đã xảy ra trong một khoảng thời gian trước một thời điểm cụ thể trong tương lai, không phù hợp khi hỏi về hành động tại một thời điểm cụ thể trong tương lai.', 'Bạn sẽ đang làm gì vào thời điểm này ngày mai?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_008', 'zenlish_practice', 'They ______________ when I arrive there at tomorrow night.', 'will be sleeping', 'will sleeping', 'slept', 'are going to sleep', 'A', 'Giải thích: Trong câu này, chúng ta cần dùng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "They will be sleeping when I arrive there tomorrow night" nghĩa là "Họ sẽ đang ngủ khi tôi đến đó vào tối mai."\n(B) will sleeping: "will sleeping" là dạng sai của thì tương lai tiếp diễn.\n(C) slept: "slept" là thì quá khứ, không phù hợp với ngữ cảnh nói về hành động sẽ đang xảy ra trong tương lai.\n(D) are going to sleep: "are going to sleep" là thì hiện tại tiếp diễn dùng để dự đoán, không phù hợp khi nói về hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.', 'Họ sẽ đang ngủ khi tôi đến đó vào tối mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_009', 'zenlish_practice', 'Their parents ______________ their house when they return home tomorrow.', 'will be painted', 'will have paint', 'have painted', 'will be painting', 'D', 'Giải thích: Trong câu này, chúng ta cần dùng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "Their parents will be painting their house when they return home tomorrow" nghĩa là "Cha mẹ của họ sẽ đang sơn nhà khi họ về nhà vào ngày mai."\n(A) will be painted: "will be painted" là thì tương lai bị động, không phù hợp với ngữ cảnh câu.\n(B) will have paint: "will have paint" là dạng sai, không phải là thì tương lai tiếp diễn và không phù hợp với ngữ cảnh.\n(C) have painted: "have painted" là thì hiện tại hoàn thành, không phù hợp khi nói về hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai.', 'Cha mẹ của họ sẽ đang sơn nhà khi họ về nhà vào ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0042_q_010', 'zenlish_practice', 'When she comes, they ___________dinner.', 'will has', 'will be haveing', 'will having', 'will be having', 'D', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "They will be having dinner when she comes" nghĩa là "Họ sẽ đang ăn tối khi cô ấy đến."\n(A) will has: "will has" là dạng sai của thì tương lai, không đúng ngữ pháp.\n(B) will be haveing: "haveing" là dạng sai của động từ "have," không phải là một dạng đúng của thì tiếp diễn.\n(C) will having: "will having" là dạng sai của thì tương lai tiếp diễn, không đúng ngữ pháp.', 'Họ sẽ đang ăn tối khi cô ấy đến.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_001', 'zenlish_practice', 'This time tomorrow you __________sitting in a deck chair on the beach.', 'will', 'are', 'were', 'will be', 'D', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "You will be sitting in a deck chair on the beach" nghĩa là "Bạn sẽ đang ngồi trên ghế dài trên bãi biển vào thời điểm này vào ngày mai."\n(A) will: "will" không đủ để diễn tả hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(B) are: "are" là thì hiện tại, không phù hợp với ngữ cảnh của câu.\n(C) were: "were" là thì quá khứ, không phù hợp với ngữ cảnh của hành động trong tương lai.', 'Vào thời điểm này ngày mai, bạn sẽ đang ngồi trên ghế dài trên bãi biển.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_002', 'zenlish_practice', 'Will you be _____________ there when I arrive?', 'waited', 'waiting', 'wait', 'have waited', 'B', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "Will you be waiting there when I arrive?" nghĩa là "Bạn sẽ đang chờ ở đó khi tôi đến phải không?"\n(A) waited: "waited" là thì quá khứ hoặc quá khứ hoàn thành, không phù hợp với ngữ cảnh của hành động trong tương lai.\n(C) wait: "wait" là động từ ở dạng nguyên thể, không phù hợp với cấu trúc câu yêu cầu thì tiếp diễn.\n(D) have waited: "have waited" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh của hành động sẽ đang xảy ra trong tương lai.', 'Bạn sẽ đang chờ ở đó khi tôi đến phải không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_003', 'zenlish_practice', 'David’s daughter is studying at secondary school now and she ______________ at university when David is 55.', 'will studying', 'studies', 'has studied', 'will be studying', 'D', 'Giải thích: Trong câu này, chúng ta đang nói về một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "She will be studying at university when David is 55" nghĩa là "Cô ấy sẽ đang học ở trường đại học khi David 55 tuổi."\n(A) will studying: "will studying" là cấu trúc sai, không phù hợp với thì tương lai tiếp diễn.\n(B) studies: "studies" là thì hiện tại đơn, không phù hợp với ngữ cảnh diễn tả hành động trong tương lai.\n(C) has studied: "has studied" là thì hiện tại hoàn thành, không phù hợp khi nói về hành động sẽ đang diễn ra trong tương lai.', 'Con gái của David đang học ở trường trung học bây giờ và cô ấy sẽ đang học ở đại học khi David 55 tuổi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_004', 'zenlish_practice', 'Next summer, when his wife and his children are on holiday, he ______________ English.', 'will learn', 'was learning', 'will be learning', 'will have learning', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "He will be learning English next summer" nghĩa là "Anh ấy sẽ đang học tiếng Anh vào mùa hè tới."\n(A) will learn: "will learn" là thì tương lai đơn, không phù hợp khi diễn tả hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai.\n(B) was learning: "was learning" là thì quá khứ tiếp diễn, không phù hợp với ngữ cảnh của câu.\n(D) will have learning: "will have learning" là cấu trúc sai, không phải là một dạng đúng của thì tương lai.', 'Vào mùa hè tới, khi vợ và các con của anh ấy đang trong kỳ nghỉ, anh ấy sẽ đang học tiếng Anh.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_005', 'zenlish_practice', 'The engineers ______________ on another project when you come here.', 'will working', 'will be working', 'will be worked', 'will have worked', 'B', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "The engineers will be working on another project when you come here" nghĩa là "Các kỹ sư sẽ đang làm việc trên một dự án khác khi bạn đến đây."\n(A) will working: "will working" là cấu trúc sai, không phải là một dạng đúng của thì tương lai tiếp diễn.\n(C) will be worked: "will be worked" là cấu trúc sai, không phù hợp với thì tương lai tiếp diễn.\n(D) will have worked: "will have worked" là thì tương lai hoàn thành, không phù hợp khi nói về hành động sẽ đang xảy ra trong tương lai.', 'Các kỹ sư sẽ đang làm việc trên một dự án khác khi bạn đến đây.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_006', 'zenlish_practice', 'At 8 o’clock this evening, my friends and I _________a famous film at the cinema.', 'am watching', 'watched', 'will be watching', 'watch', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "My friends and I will be watching a famous film at the cinema" nghĩa là "Tôi và các bạn của tôi sẽ đang xem một bộ phim nổi tiếng tại rạp chiếu phim vào lúc 8 giờ tối."\n(A) am watching: "am watching" là thì hiện tại tiếp diễn, không phù hợp khi nói về hành động sẽ đang xảy ra trong tương lai.\n(B) watched: "watched" là thì quá khứ, không phù hợp với ngữ cảnh nói về hành động sẽ đang xảy ra trong tương lai.\n(D) watch: "watch" là dạng nguyên thể hoặc thì hiện tại đơn, không phù hợp với cấu trúc câu yêu cầu.', 'Vào lúc 8 giờ tối hôm nay, tôi và các bạn của tôi sẽ đang xem một bộ phim nổi tiếng tại rạp chiếu phim.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_007', 'zenlish_practice', 'l''m going on holiday on Saturday. This time next week, I______on a beach in the sea.', 'will lie', 'am lying', 'will be lying', 'should be lying', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "I will be lying on a beach in the sea" nghĩa là "Tôi sẽ đang nằm trên bãi biển vào thời điểm này tuần tới."\n(A) will lie: "will lie" là thì tương lai đơn, không phù hợp khi nói về hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(B) am lying: "am lying" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh của hành động sẽ xảy ra trong tương lai.\n(D) should be lying: "should be lying" là thì tương lai với nghĩa dự đoán hoặc giả định, không phù hợp khi chỉ cần diễn tả hành động đang xảy ra trong tương lai.', 'Tôi sẽ đang nằm trên bãi biển vào thời điểm này tuần tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_008', 'zenlish_practice', 'My parents ________ Europe at this time next week.', 'will visit', 'will be visiting', 'are visiting', 'visit', 'B', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "My parents will be visiting Europe" nghĩa là "Bố mẹ tôi sẽ đang ở châu Âu vào thời điểm này tuần tới."\n(A) will visit: "will visit" là thì tương lai đơn, không phù hợp khi muốn nhấn mạnh hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(C) are visiting: "are visiting" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh khi diễn tả hành động sẽ xảy ra trong tương lai.\n(D) visit: "visit" là dạng nguyên thể của động từ, không phù hợp với cấu trúc câu yêu cầu thì tương lai.', 'Bố mẹ tôi sẽ đang ở châu Âu vào thời điểm này tuần tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_009', 'zenlish_practice', 'When she comes, they ___________dinner.', 'will has', 'will be haveing', 'will having', 'will be having', 'D', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "They will be having dinner" nghĩa là "họ sẽ đang ăn tối khi cô ấy đến."\n(A) will has: "will has" là sai cú pháp và không phải là một dạng đúng của thì.\n(B) will be haveing: "haveing" là dạng sai của động từ "have," đúng phải là "having."\n(C) will having: "will having" là cấu trúc sai, cần dùng "will be having" để đúng ngữ pháp.', 'Khi cô ấy đến, họ sẽ đang ăn tối.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0043_q_010', 'zenlish_practice', 'When they ________ tomorrow, we ________ in the sea.', 'come - swim', 'are coming - swim', 'are coming - are swimming', 'come – will be swimming', 'D', 'Giải thích: Trong mệnh đề phụ chỉ thời gian bắt đầu bằng "When" và diễn tả hành động trong tương lai (có từ nhận biết "tomorrow"), động từ được chia ở thì hiện tại đơn ("come"). Trong mệnh đề chính, hành động "will be swimming" (sẽ đang bơi) diễn tả một hành động sẽ đang xảy ra tại một thời điểm xác định trong tương lai (khi hành động ở mệnh đề phụ xảy ra). Cấu trúc này thường dùng để nhấn mạnh sự việc đang diễn ra khi có sự việc khác xen vào trong tương lai. A. come - swim: Sai ngữ pháp ở mệnh đề chính. Cần dùng thì tương lai để diễn tả hành động sẽ xảy ra vào ngày mai. B. are coming - swim: Sai ngữ pháp ở cả hai mệnh đề. Mệnh đề "when" không dùng thì hiện tại tiếp diễn trong trường hợp này, và mệnh đề chính cần thì tương lai. C. are coming - are swimming: Sai ngữ pháp ở mệnh đề "when". Cấu trúc phối hợp thì không phù hợp.', 'Khi họ đến vào ngày mai, chúng tôi sẽ đang bơi ở biển.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_001', 'zenlish_practice', 'This time tomorrow, _______________in the train on our way to Venice.', 'we''ll be sitting', 'we will have sitting', 'we''ll have sat', 'we''ll have been sitting', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "This time tomorrow, we''ll be sitting in the train on our way to Venice" nghĩa là "Vào thời điểm này ngày mai, chúng tôi sẽ đang ngồi trên tàu trên đường đến Venice."\n(B) we will have sitting: "will have sitting" là dạng sai, không phù hợp với cấu trúc thì.\n(C) we''ll have sat: "will have sat" là thì tương lai hoàn thành, không phù hợp với ngữ cảnh hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(D) we''ll have been sitting: "will have been sitting" là thì tương lai hoàn thành tiếp diễn, không cần thiết trong ngữ cảnh này.', 'Vào thời điểm này ngày mai, chúng tôi sẽ đang ngồi trên tàu trên đường đến Venice.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_002', 'zenlish_practice', 'They _________ their presentation at this time tomorrow morning.', 'are making', 'are going to make', 'will be making', 'will make', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "They will be making their presentation at this time tomorrow morning" nghĩa là "Họ sẽ đang thực hiện bài thuyết trình của mình vào thời điểm này vào sáng mai."\n(A) are making: "are making" là thì hiện tại tiếp diễn, không phù hợp khi nói về hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai.\n(B) are going to make: "are going to make" là thì tương lai gần, không phù hợp khi nhấn mạnh hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(D) will make: "will make" là thì tương lai đơn, không nhấn mạnh sự tiếp diễn của hành động.', 'Họ sẽ đang thực hiện bài thuyết trình của mình vào thời điểm này vào sáng mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_003', 'zenlish_practice', 'They ________ pingpong when their father comes back home.', 'will play', 'will be playing', 'play', 'would play', 'B', 'Giải thích: Trong câu này, chúng ta đang nói về một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. Do đó, cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả hành động đang xảy ra khi một sự kiện khác xảy ra. "They will be playing pingpong when their father comes back home" nghĩa là "Họ sẽ đang chơi bóng bàn khi bố của họ trở về nhà."\n(A) will play: "will play" là thì tương lai đơn, không nhấn mạnh sự tiếp diễn của hành động.\n(C) play: "play" là thì hiện tại đơn, không phù hợp với ngữ cảnh của hành động sẽ đang xảy ra trong tương lai.\n(D) would play: "would play" thường được dùng trong các tình huống giả định hoặc điều kiện không chắc chắn, không phù hợp với câu này.', 'Họ sẽ đang chơi bóng bàn khi bố của họ trở về nhà.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_004', 'zenlish_practice', 'This time tomorrow you __________sitting in a deck chair on the beach.', 'will', 'are', 'were', 'will be', 'D', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "You will be sitting in a deck chair on the beach" nghĩa là "Bạn sẽ đang ngồi trên ghế bãi biển vào thời điểm này ngày mai."\n(A) will: "will" là thì tương lai đơn, không thể hiện sự tiếp diễn của hành động.\n(B) are: "are" là thì hiện tại đơn, không phù hợp với ngữ cảnh của hành động sẽ xảy ra trong tương lai.\n(C) were: "were" là thì quá khứ, không phù hợp với ngữ cảnh của hành động sẽ xảy ra trong tương lai.', 'Vào thời điểm này ngày mai, bạn sẽ đang ngồi trên ghế bãi biển.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_005', 'zenlish_practice', 'My mom _________ dinner when my dad comes home tomorrow.', 'will be cooking', 'will cook', 'cooked', 'cooks', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "My mom will be cooking dinner" nghĩa là "Mẹ tôi sẽ đang nấu bữa tối khi bố tôi về nhà vào ngày mai."\n(B) will cook: "will cook" là thì tương lai đơn, không thể hiện sự tiếp diễn của hành động.\n(C) cooked: "cooked" là thì quá khứ, không phù hợp với ngữ cảnh của hành động sẽ xảy ra trong tương lai.\n(D) cooks: "cooks" là thì hiện tại đơn, không phù hợp với ngữ cảnh của hành động sẽ xảy ra trong tương lai.', 'Mẹ tôi sẽ đang nấu bữa tối khi bố tôi về nhà vào ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_006', 'zenlish_practice', 'At 8 am tomorrow, Claire _______ an important meeting with a client.', 'had', 'had had', 'will be having', 'will have', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "Claire will be having an important meeting" nghĩa là "Claire sẽ đang có một cuộc họp quan trọng" vào lúc 8 giờ sáng mai.\n(A) had: "had" là thì quá khứ, không phù hợp với ngữ cảnh của hành động sẽ xảy ra trong tương lai.\n(B) had had: "had had" là thì quá khứ hoàn thành, không phù hợp khi nói về hành động sẽ xảy ra trong tương lai.\n(D) will have: "will have" là thì tương lai đơn, không thể hiện sự tiếp diễn của hành động.', 'Vào lúc 8 giờ sáng mai, Claire sẽ đang có một cuộc họp quan trọng với khách hàng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_007', 'zenlish_practice', 'Andy ________ a video when I arrive tonight.', 'will be watching', 'watched', 'will watch', 'will have watched', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "Andy will be watching a video" nghĩa là "Andy sẽ đang xem video" khi bạn đến tối nay.\n(B) watched: "watched" là thì quá khứ, không phù hợp với ngữ cảnh nói về hành động sẽ đang xảy ra trong tương lai.\n(C) will watch: "will watch" là thì tương lai đơn, không thể hiện sự tiếp diễn của hành động.\n(D) will have watched: "will have watched" là thì tương lai hoàn thành, không phù hợp khi nói về hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai.', 'Andy sẽ đang xem một video khi tôi đến tối nay.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_008', 'zenlish_practice', 'It _________when I reach Bangkok.', 'will have probably rained', 'is probably raining', 'will probably be raining', 'will be rained', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will probably be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai và có thể xảy ra. "It will probably be raining" nghĩa là "trời có thể đang mưa" khi bạn đến Bangkok.\n(A) will have probably rained: "will have probably rained" là thì tương lai hoàn thành, không phù hợp với ngữ cảnh.\n(B) is probably raining: "is probably raining" là thì hiện tại tiếp diễn, không phù hợp với thời điểm trong tương lai.\n(D) will be rained: "will be rained" không phải là dạng đúng của động từ trong thì tương lai.', 'Trời có thể đang mưa khi tôi đến Bangkok.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_009', 'zenlish_practice', '- Can we meet tomorrow? - Yes, but not in the afternoon. I ______.', 'will be working', 'will work', 'have worked', 'will have worked', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "I will be working" nghĩa là "tôi sẽ đang làm việc" vào buổi chiều mai.\n(B) will work: "will work" là thì tương lai đơn, không thể hiện sự tiếp diễn của hành động.\n(C) have worked: "have worked" là thì hiện tại hoàn thành, không phù hợp với ngữ cảnh của hành động sẽ đang xảy ra trong tương lai.\n(D) will have worked: "will have worked" là thì tương lai hoàn thành, không phù hợp với ngữ cảnh.', '- Chúng ta có thể gặp nhau vào ngày mai không? - Có, nhưng không phải vào buổi chiều. Tôi sẽ đang làm việc.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0044_q_010', 'zenlish_practice', 'Tomorrow afternoon we’re going to play tennis from 3 o’clock until 4.30. So at 4 o’clock, we _______ tennis.', 'will be playing', 'will play', 'played', 'will have played', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "We will be playing tennis" nghĩa là "chúng tôi sẽ đang chơi tennis" vào lúc 4 giờ chiều.\n(B) will play: "will play" là thì tương lai đơn, không thể hiện sự tiếp diễn của hành động.\n(C) played: "played" là thì quá khứ, không phù hợp với ngữ cảnh của hành động sẽ xảy ra trong tương lai.\n(D) will have played: "will have played" là thì tương lai hoàn thành, không phù hợp với ngữ cảnh.', 'Chiều mai, chúng tôi sẽ chơi tennis từ 3 giờ đến 4 giờ rưỡi. Vì vậy, vào lúc 4 giờ, chúng tôi sẽ đang chơi tennis.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_001', 'zenlish_practice', 'They ______ their presentation at this time tomorrow morning.', 'will make', 'made', 'will be making', 'will have made', 'C', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "They will be making their presentation" nghĩa là "họ sẽ đang thực hiện bài thuyết trình của mình" vào thời điểm cụ thể vào sáng mai.\n(A) will make: "will make" là thì tương lai đơn, không thể hiện sự tiếp diễn của hành động.\n(B) made: "made" là thì quá khứ, không phù hợp với ngữ cảnh của hành động sẽ xảy ra trong tương lai.\n(D) will have made: "will have made" là thì tương lai hoàn thành, không phù hợp với ngữ cảnh của hành động đang xảy ra tại một thời điểm trong tương lai.', 'Họ sẽ đang thực hiện bài thuyết trình của mình vào thời điểm này vào sáng mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_002', 'zenlish_practice', 'At 8 p.m tonight I _________ dinner with my family.', 'will be eating', 'ate', 'have eaten', 'will have eaten', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "I will be eating dinner with my family" nghĩa là "tôi sẽ đang ăn tối với gia đình vào lúc 8 giờ tối hôm nay."\n(B) ate: "ate" là thì quá khứ, không phù hợp với ngữ cảnh nói về hành động sẽ xảy ra trong tương lai.\n(C) have eaten: "have eaten" là thì hiện tại hoàn thành, không phù hợp khi nói về hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(D) will have eaten: "will have eaten" là thì tương lai hoàn thành, không phù hợp với ngữ cảnh của hành động đang xảy ra tại một thời điểm trong tương lai.', 'Vào lúc 8 giờ tối hôm nay, tôi sẽ đang ăn tối với gia đình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_003', 'zenlish_practice', 'Tomorrow at nine I ______ a test.', 'will take', 'will be taking', 'will have taken', 'will have been taken', 'B', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "I will be taking a test" nghĩa là "tôi sẽ đang làm bài kiểm tra vào lúc 9 giờ sáng mai."\n(A) will take: "will take" là thì tương lai đơn, không phù hợp khi cần diễn tả hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(C) will have taken: "will have taken" là thì tương lai hoàn thành, không phù hợp với ngữ cảnh của hành động đang xảy ra tại một thời điểm trong tương lai.\n(D) will have been taken: "will have been taken" là thì tương lai hoàn thành tiếp diễn, không phù hợp với ngữ cảnh của hành động đang xảy ra tại một thời điểm trong tương lai.', 'Vào lúc 9 giờ sáng mai, tôi sẽ đang làm bài kiểm tra.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_004', 'zenlish_practice', 'This time next year I ______ in London.', 'will live', 'will be living', 'was living', 'will have been living', 'B', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "I will be living in London" nghĩa là "tôi sẽ đang sống ở London vào thời điểm này năm sau."\n(A) will live: "will live" là thì tương lai đơn, không phù hợp khi cần diễn tả hành động đang xảy ra tại một thời điểm cụ thể trong tương lai.\n(C) was living: "was living" là thì quá khứ tiếp diễn, không phù hợp với ngữ cảnh tương lai.\n(D) will have been living: "will have been living" là thì tương lai hoàn thành tiếp diễn, thường được dùng để diễn tả một hành động đã bắt đầu trong quá khứ và sẽ tiếp tục đến một thời điểm trong tương lai. Tuy nhiên, trong câu này, "will be living" là sự lựa chọn phù hợp hơn để chỉ một hành động đang xảy ra trong tương lai.', 'Vào thời điểm này năm sau, tôi sẽ đang sống ở London.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_005', 'zenlish_practice', 'At this time next Thursday, Sarah ________to New York on her business trip.', 'travelled', 'will be travelling', 'was travelling', 'will have traveled', 'B', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "Sarah will be travelling to New York" nghĩa là "Sarah sẽ đang đi công tác đến New York vào thời điểm này thứ Năm tới."\n(A) travelled: "travelled" là thì quá khứ đơn, không phù hợp với ngữ cảnh tương lai.\n(C) was travelling: "was travelling" là thì quá khứ tiếp diễn, không phù hợp với ngữ cảnh tương lai.\n(D) will have traveled: "will have traveled" là thì tương lai hoàn thành, thường được dùng để diễn tả một hành động đã hoàn thành trước một thời điểm trong tương lai. Tuy nhiên, trong câu này, "will be travelling" là sự lựa chọn phù hợp hơn để chỉ hành động đang xảy ra trong tương lai.', 'Vào thời điểm này thứ Năm tới, Sarah sẽ đang đi công tác đến New York.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_006', 'zenlish_practice', 'The Browns __________ their housework when you come next Sunday.', 'will be doing', 'will do', 'will have done', 'do', 'A', 'Giải thích: Trong câu này, chúng ta cần sử dụng thì tương lai tiếp diễn "will be + V-ing" để diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai. "The Browns will be doing their housework" nghĩa là "Gia đình Browns sẽ đang làm công việc nhà khi bạn đến vào Chủ nhật tới."\n(B) will do: "will do" là thì tương lai đơn, không thể hiện rõ rằng hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai.\n(C) will have done: "will have done" là thì tương lai hoàn thành, thường dùng để diễn tả hành động đã hoàn thành trước một thời điểm trong tương lai.\n(D) do: "do" là thì hiện tại đơn, không phù hợp với ngữ cảnh tương lai.', 'Gia đình Browns sẽ đang làm công việc nhà khi bạn đến vào Chủ nhật tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_007', 'zenlish_practice', 'We ________ biogas for cooking when he comes next week.', 'have used', 'will be using', 'will use', 'are using', 'B', 'Giải thích: Trong câu này, cấu trúc "will be using" là thì tương lai tiếp diễn, được sử dụng để chỉ ra một hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai. Khi nói "when he comes next week," chúng ta đang nói về một hành động sẽ đang xảy ra vào thời điểm người đó đến, nên "will be using" là lựa chọn phù hợp nhất để diễn tả ý định sử dụng biogas cho việc nấu nướng vào lúc đó.\n(A) have used: Cấu trúc "have used" là thì hiện tại hoàn thành, thường được sử dụng để diễn đạt một hành động đã xảy ra và hoàn tất ở quá khứ và có ảnh hưởng tới hiện tại. Đây không phải là lựa chọn phù hợp trong ngữ cảnh nói về một kế hoạch hay hành động sẽ xảy ra trong tương lai.\n(C) will use: Thì tương lai đơn "will use" được sử dụng để chỉ một hành động sẽ xảy ra tại một thời điểm trong tương lai mà không nhấn mạnh sự tiếp diễn của hành động đó. Trong ngữ cảnh này, việc sử dụng "will be using" (tương lai tiếp diễn) là chính xác hơn vì nó nhấn mạnh hành động đang diễn ra tại thời điểm người đó đến.\n(D) are using: "Are using" là thì hiện tại tiếp diễn, diễn tả một hành động đang diễn ra tại thời điểm hiện tại hoặc liên tục trong một khoảng thời gian. Trong câu này, nếu sử dụng "are using," nó sẽ không phản ánh đúng ý định hành động sẽ xảy ra trong tương lai, mà chỉ phù hợp khi nói về một hành động đang xảy ra ngay bây giờ.', 'Chúng tôi sẽ đang sử dụng biogas để nấu ăn khi anh ấy đến vào tuần tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_008', 'zenlish_practice', 'What ________ at 7:00 pm next Sunday?', 'have you been doing', 'are you doing', 'will you be doing', 'have you done', 'C', 'Giải thích: Trong câu hỏi này, "will you be doing" là thì tương lai tiếp diễn, được sử dụng để hỏi về một hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai, cụ thể là vào lúc 7:00 tối Chủ Nhật tuần tới.\n(A) have you been doing: Cấu trúc "have you been doing" là thì hiện tại hoàn thành tiếp diễn, thường dùng để hỏi về một hành động đã bắt đầu trong quá khứ và vẫn đang tiếp tục ở hiện tại, không phù hợp trong ngữ cảnh này khi muốn hỏi về hành động trong tương lai.\n(B) are you doing: "Are you doing" là thì hiện tại tiếp diễn, dùng để hỏi về một hành động đang diễn ra ở thời điểm hiện tại hoặc tương lai gần đã được sắp xếp. Tuy nhiên, câu này đang hỏi về một thời điểm cụ thể trong tương lai xa hơn, nên "will you be doing" là lựa chọn chính xác hơn.\n(D) have you done: "Have you done" là thì hiện tại hoàn thành, dùng để hỏi về một hành động đã hoàn thành trước thời điểm hiện tại. Điều này không phù hợp với ngữ cảnh của câu hỏi này, vì câu hỏi đang đề cập đến một hành động tương lai.', 'Bạn sẽ đang làm gì vào lúc 7:00 tối Chủ Nhật tuần tới?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_009', 'zenlish_practice', 'At midnight next New Year''s Eve, I _______ the firework with Tom.', 'will have not been watching', 'was watching', 'will not be watching', 'am watching', 'C', 'Giải thích: Trong câu này, "will not be watching" là thì tương lai tiếp diễn phủ định, được sử dụng để diễn tả một hành động sẽ không đang diễn ra tại một thời điểm cụ thể trong tương lai, ở đây là lúc nửa đêm vào Đêm Giao Thừa năm mới.\n(A) will have not been watching: Cấu trúc "will have not been watching" là thì tương lai hoàn thành tiếp diễn phủ định, dùng để chỉ một hành động đã bắt đầu trong quá khứ và tiếp tục cho đến một thời điểm cụ thể trong tương lai. Đây không phải là cấu trúc phù hợp trong ngữ cảnh này, vì câu chỉ cần diễn đạt rằng bạn sẽ không đang xem pháo hoa tại thời điểm cụ thể.\n(B) was watching: "Was watching" là thì quá khứ tiếp diễn, diễn tả một hành động đang diễn ra tại một thời điểm cụ thể trong quá khứ, không phù hợp khi câu hỏi đề cập đến tương lai.\n(D) am watching: "Am watching" là thì hiện tại tiếp diễn, dùng để nói về một hành động đang diễn ra ở hiện tại hoặc tương lai gần đã được sắp xếp. Tuy nhiên, câu này đang nói về thời điểm trong tương lai xa hơn, nên cần sử dụng thì tương lai tiếp diễn.', 'Vào lúc nửa đêm Đêm Giao Thừa năm mới, tôi sẽ không đang xem pháo hoa với Tom.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0045_q_010', 'zenlish_practice', 'This time next week, we ________ camping in the mountains.', 'weren’t going', 'hadn’t gone', 'will not be going', 'won''t have gone', 'C', 'Giải thích: "Will not be going" là thì tương lai tiếp diễn phủ định, được sử dụng để diễn tả một hành động sẽ không đang diễn ra tại một thời điểm cụ thể trong tương lai. Trong trường hợp này, "this time next week" ám chỉ thời điểm vào tuần sau, và câu diễn đạt rằng vào thời điểm đó, chúng ta sẽ không đang đi cắm trại trên núi.\n(A) weren’t going: "Weren’t going" là thì quá khứ tiếp diễn phủ định, diễn tả một hành động đã không đang diễn ra tại một thời điểm cụ thể trong quá khứ, không phù hợp khi câu hỏi đề cập đến tương lai.\n(B) hadn’t gone: "Hadn’t gone" là thì quá khứ hoàn thành phủ định, diễn tả một hành động đã không xảy ra trước một thời điểm khác trong quá khứ. Điều này không phù hợp với ngữ cảnh đang nói về một hành động trong tương lai.\n(D) won''t have gone: "Won''t have gone" là thì tương lai hoàn thành phủ định, diễn tả một hành động sẽ không hoàn thành trước một thời điểm nhất định trong tương lai. Cấu trúc này không phù hợp vì câu hỏi không cần diễn đạt hành động sẽ hoàn thành mà chỉ cần nói về hành động sẽ không đang diễn ra.', 'Vào thời điểm này tuần sau, chúng ta sẽ không đang đi cắm trại trên núi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_001', 'zenlish_practice', 'By the time Clear Blaze Technology''s word processing program goes on the market, software engineers _____ its remaining flaws.', 'will have corrected', 'had been correcting', 'are correcting', 'will correct', 'A', 'Giải thích: "By the time" là dấu hiệu của thì hoàn thành, mệnh đề sau đó ở thì hiện tại đơn (goes on the market) diễn tả hành động sẽ diễn ra trong tương lai. Trong câu này, cần một thì tương lai hoàn thành để chỉ rằng hành động sửa lỗi của các kỹ sư phần mềm sẽ hoàn tất trước thời điểm chương trình xử lý văn bản được đưa ra thị trường.\n(B) had been correcting (past perfect continuous): "Had been correcting" có nghĩa là "đã đang sửa chữa" trong quá khứ. Lý do không chọn là vì thì quá khứ hoàn thành tiếp diễn không phù hợp trong ngữ cảnh cần mô tả hành động sẽ hoàn tất trước một thời điểm trong tương lai.\n(C) are correcting (present continuous): "Are correcting" có nghĩa là "đang sửa chữa." Lý do không chọn là vì thì hiện tại tiếp diễn không phù hợp trong ngữ cảnh mô tả một hành động sẽ hoàn tất trước một thời điểm trong tương lai.\n(D) will correct (future simple): "Will correct" có nghĩa là "sẽ sửa chữa." Lý do không chọn là vì thì tương lai đơn không thể hiện rõ rằng hành động sẽ hoàn tất trước một thời điểm trong tương lai.', 'Trước khi chương trình xử lý văn bản của Clear Blaze Technology được đưa ra thị trường, các kỹ sư phần mềm sẽ đã sửa chữa các lỗi còn lại của nó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_002', 'zenlish_practice', 'By the time Ms. Valspar retires as president of Movene Technologies, she _____ to increase the company ''s market share significantly.', 'manages', 'will have managed', 'managed', 'has been managed', 'B', 'Giải thích: By the time + mệnh đề ở thì hiện tại đơn là dấu hiệu sử dụng thì tương lai hoàn thành để mô tả một hành động sẽ được hoàn tất trước thời điểm cụ thể trong tương lai (khi Ms. Valspar nghỉ hưu). "Will have managed" là thì tương lai hoàn thành phù hợp, nghĩa là "sẽ đã thực hiện được," để chỉ rằng Ms. Valspar sẽ hoàn tất việc tăng thị phần của công ty trước khi nghỉ hưu.\n(A) manages (present simple): "Manages" có nghĩa là "quản lý." Lý do không chọn là vì thì hiện tại đơn không phản ánh rằng hành động sẽ được hoàn tất trước một thời điểm trong tương lai.\n(C) managed (past simple): "Managed" có nghĩa là "đã quản lý." Lý do không chọn là vì thì quá khứ không phù hợp khi mô tả hành động sẽ được hoàn tất trong tương lai.\n(D) has been managed (present perfect passive): "Has been managed" có nghĩa là "đã được quản lý" (bị động). Lý do không chọn là vì cấu trúc bị động và thì hiện tại hoàn thành không phù hợp khi cần mô tả một hành động chủ động sẽ được hoàn tất trước thời điểm trong tương lai.', 'Trước khi bà Valspar nghỉ hưu với tư cách là chủ tịch của Movene Technologies, bà sẽ đã tăng thị phần của công ty đáng kể.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_003', 'zenlish_practice', 'By this time next year, I _______ 250 dollars.', 'will have saved', 'save', 'will save', 'have saved', 'A', 'Giải thích: "By this time this year" (trước thời điểm này năm sau) là dấu hiệu cần sử dụng thì tương lai hoàn thành tiếp diễn. Ở đây, câu muốn nói rằng "vào thời điểm này năm sau," bạn sẽ đã tiết kiệm được 250 đô la, nên "will have saved" là lựa chọn chính xác nhất.\n(B) save: "Save" là thì hiện tại đơn, dùng để nói về thói quen hoặc sự thật chung, không phù hợp khi câu hỏi đang nói về một hành động hoàn thành trong tương lai.\n(C) will save: "Will save" là thì tương lai đơn, dùng để diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh việc hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(D) have saved: "Have saved" là thì hiện tại hoàn thành, thường diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp trong ngữ cảnh đang nói về tương lai.', 'Vào thời điểm này năm sau, tôi sẽ đã tiết kiệm được 250 đô la.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_004', 'zenlish_practice', 'He says he _______ the draft by 5 o’clock this afternoon.', 'has finished', 'is finishing', 'will have finished', 'will finish', 'C', 'Giải thích: By + mốc thời gian trong tương lai (5 o''clock this afternoon) là dấu hiệu cần sử dụng thì tương lai hoàn thành để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Câu này muốn nói rằng anh ấy sẽ đã hoàn thành bản thảo vào lúc 5 giờ chiều nay.\n(A) has finished: "Has finished" là thì hiện tại hoàn thành, dùng để diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp khi câu hỏi đang nói về một hành động sẽ hoàn thành trong tương lai.\n(B) is finishing: "Is finishing" là thì hiện tại tiếp diễn, dùng để diễn tả một hành động đang diễn ra tại thời điểm hiện tại hoặc tương lai gần, không phù hợp với ngữ cảnh cần diễn đạt một hành động đã hoàn thành trước một thời điểm cụ thể trong tương lai.\n(D) will finish: "Will finish" là thì tương lai đơn, dùng để diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh việc hành động đó sẽ hoàn thành trước một thời điểm cụ thể.', 'Anh ấy nói rằng anh ấy sẽ đã hoàn thành bản thảo vào lúc 5 giờ chiều nay.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_005', 'zenlish_practice', 'By the end of this week, my illness ______ me £100.', 'cost', 'will have cost', 'have cost', 'will cost', 'B', 'Giải thích: By + mốc thời gian trong tương lai (the end of this week) là dấu hiệu cần sử dụng thì tương lai hoàn thành để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Câu này muốn nói rằng "tính đến cuối tuần này," bệnh tật của tôi sẽ đã tiêu tốn của tôi £100."\n(A) cost: "Cost" là thì hiện tại đơn hoặc quá khứ đơn, không phù hợp trong ngữ cảnh đang nói về một hành động hoàn thành trong tương lai.\n(C) have cost: "Have cost" là thì hiện tại hoàn thành, thường được dùng để diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp khi câu hỏi đề cập đến tương lai.\n(D) will cost: "Will cost" là thì tương lai đơn, dùng để diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh việc hành động đó sẽ hoàn thành trước một thời điểm cụ thể.', 'Đến cuối tuần này, căn bệnh của tôi sẽ đã tiêu tốn của tôi £100.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_006', 'zenlish_practice', 'By the end of next year, I ______ here twenty-five years.', 'will be', 'will have been', 'am', 'was', 'B', 'Giải thích: By + mốc thời gian trong tương lai (the end of next year) là dấu hiệu cần sử dụng thì tương lai hoàn thành để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Câu muốn nói rằng "vào cuối năm sau," tôi sẽ đã ở đây được hai mươi lăm năm.\n(A) will be: "Will be" là thì tương lai đơn, diễn tả một trạng thái hoặc hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh việc trạng thái đó sẽ kéo dài bao lâu trước một thời điểm cụ thể.\n(C) am: "Am" là thì hiện tại đơn, chỉ diễn tả một trạng thái ở hiện tại, không phù hợp khi câu hỏi đang nói về thời gian trong tương lai.\n(D) was: "Was" là thì quá khứ đơn, diễn tả một trạng thái hoặc hành động đã xảy ra trong quá khứ, không phù hợp với ngữ cảnh cần nói về tương lai.', 'Đến cuối năm sau, tôi sẽ đã ở đây được hai mươi lăm năm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_007', 'zenlish_practice', 'When we reach Crewe, we ____ half of the journey.', 'will do', 'are doing', 'did', 'will have done', 'D', 'Giải thích: "Will have done" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng khi chúng ta đến Crewe, chúng ta sẽ đã hoàn thành một nửa hành trình.\n(A) will do: "Will do" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh việc hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(B) are doing: "Are doing" là thì hiện tại tiếp diễn, chỉ một hành động đang diễn ra ở thời điểm hiện tại hoặc tương lai gần, không phù hợp với ngữ cảnh đang nói về tương lai hoàn thành.\n(C) did: "Did" là thì quá khứ đơn, diễn tả một hành động đã xảy ra trong quá khứ, không phù hợp khi câu hỏi đề cập đến tương lai.', 'Khi chúng ta đến Crewe, chúng ta sẽ đã hoàn thành một nửa hành trình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_008', 'zenlish_practice', 'By the time we get to the party, everything ______.', 'will have been eaten', 'will be eaten', 'is eaten', 'have been eaten', 'A', 'Giải thích: By the time + mệnh đề ở thì hiện tại (nhưng diễn tả sự việc sẽ diễn ra trong tương lai) là dấu hiệu cần sử dụng thì tương lai hoàn thành để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Câu này cần sử dụng cấu trúc bị động để nói rằng "mọi thứ đã được ăn hết".\n(B) will be eaten: "Will be eaten" là thì tương lai đơn ở dạng bị động, dùng để diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(C) is eaten: "Is eaten" là thì hiện tại đơn ở dạng bị động, dùng để diễn tả một hành động hiện tại hoặc sự thật chung, không phù hợp với ngữ cảnh cần nói về tương lai.\n(D) have been eaten: "Have been eaten" là thì hiện tại hoàn thành ở dạng bị động, dùng để diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp khi câu hỏi đề cập đến tương lai.', 'Khi chúng ta đến bữa tiệc, mọi thứ sẽ đã bị ăn hết.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_009', 'zenlish_practice', 'By midnight, he _____ unconscious for forty-eight hours.', 'is', 'will have been', 'will be', 'has been', 'B', 'Giải thích: By + mốc thời gian trong tương lai (midnight) là dấu hiệu cần sử dụng thì tương lai hoàn thành để diễn tả một hành động sẽ hoàn thành tính đến một thời điểm cụ thể trong tương lai. Câu này muốn nói rằng vào lúc nửa đêm, anh ấy sẽ đã duy trì ở trạng thái bất tỉnh trong bốn mươi tám giờ.\n(A) is: "Is" là thì hiện tại đơn, dùng để diễn tả một trạng thái ở hiện tại, không phù hợp khi câu hỏi đang nói về thời gian trong tương lai.\n(C) will be: "Will be" là thì tương lai đơn, dùng để diễn tả một trạng thái hoặc hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh thời gian kéo dài của trạng thái đó.\n(D) has been: "Has been" là thì hiện tại hoàn thành, dùng để diễn tả một hành động hoặc trạng thái đã bắt đầu trong quá khứ và kéo dài đến hiện tại, không phù hợp khi câu hỏi đề cập đến một thời điểm cụ thể trong tương lai.', 'Vào lúc nửa đêm, anh ấy sẽ đã bất tỉnh được bốn mươi tám giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0046_q_010', 'zenlish_practice', 'I hope they _______ this road by the time we come back next summer.', 'repaired', 'will have repaired', 'will repair', 'would repair', 'B', 'Giải thích: By the time + mệnh đề ở thì hiện tại đơn (we come back) là dấu hiệu sử dụng thì tương lai hoàn thành để mô tả một hành động sẽ được hoàn tất trước thời điểm cụ thể trong tương lai. Câu này cần sử dụng cấu trúc bị động để nói rằng con đường sẽ đã được sửa chữa xong.\n(A) repaired: "Repaired" là thì quá khứ đơn, dùng để diễn tả một hành động đã hoàn thành trong quá khứ, không phù hợp với ngữ cảnh nói về tương lai.\n(C) will repair: "Will repair" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(D) would repair: "Would repair" là thì điều kiện trong quá khứ, dùng để diễn tả một hành động có thể xảy ra trong quá khứ nhưng không chắc chắn, không phù hợp với ngữ cảnh nói về tương lai.', 'Tôi hy vọng họ sẽ đã sửa xong con đường này trước khi chúng tôi quay lại vào mùa hè tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_001', 'zenlish_practice', 'I _____ this book by tomorrow evening.', 'will finish', 'am finishing', 'will have finished', 'finishes', 'C', 'Giải thích: "Will have finished" được sử dụng để diễn tả một hành động sẽ hoàn tất trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, hành động hoàn thành việc đọc sách sẽ xảy ra trước "tomorrow evening". Các đáp án khác không phù hợp với ý nghĩa này.\n(A) will finish: Diễn tả hành động hoàn thành trong tương lai nhưng không chỉ rõ sẽ hoàn thành trước thời điểm cụ thể.\n(B) am finishing: Diễn tả hành động đang xảy ra trong hiện tại hoặc tương lai gần, không phù hợp với ngữ cảnh hoàn thành trước một thời điểm cụ thể.\n(D) finishes: Không đúng vì không sử dụng thì tương lai để diễn tả hành động hoàn tất trước một thời điểm trong tương lai.', NULL, '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_002', 'zenlish_practice', 'I ____ all the preparations before you come home tonight.', 'have made', 'am making', 'will make', 'will have made', 'D', 'Giải thích: "Will have made" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng tất cả các chuẩn bị sẽ đã được hoàn thành trước khi bạn về nhà tối nay.\n(A) have made: "Have made" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp với ngữ cảnh nói về tương lai.\n(B) am making: "Am making" là thì hiện tại tiếp diễn, dùng để diễn tả một hành động đang diễn ra tại thời điểm hiện tại, không phù hợp khi câu hỏi đang nói về một hành động trong tương lai.\n(C) will make: "Will make" là thì tương lai đơn, dùng để diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.', 'Tôi sẽ đã chuẩn bị xong mọi thứ trước khi bạn về nhà tối nay.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_003', 'zenlish_practice', 'By the end of the term, I ______ all twenty volumes.', 'will read', 'are reading', 'will have read', 'have read', 'C', 'Giải thích: "Will have read" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng vào cuối học kỳ, bạn sẽ đã đọc hết tất cả hai mươi tập sách.\n(A) will read: "Will read" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(B) are reading: "Are reading" là thì hiện tại tiếp diễn, dùng để diễn tả một hành động đang diễn ra tại thời điểm hiện tại hoặc tương lai gần, không phù hợp với ngữ cảnh cần nói về một hành động hoàn thành trong tương lai.\n(D) have read: "Have read" là thì hiện tại hoàn thành, dùng để diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp khi câu hỏi đề cập đến tương lai.', 'Vào cuối học kỳ, tôi sẽ đã đọc xong tất cả hai mươi tập sách.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_004', 'zenlish_practice', 'By this time tomorrow morning, we ______ our injections.', 'have', 'have had', 'will have had', 'will have', 'C', 'Giải thích: "Will have had" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào thời điểm này sáng mai," chúng ta sẽ đã tiêm xong.\n(A) have: "Have" là thì hiện tại đơn, không phù hợp khi câu hỏi nói về một hành động sẽ hoàn thành trong tương lai.\n(B) have had: "Have had" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp với ngữ cảnh tương lai.\n(D) will have: "Will have" là cấu trúc tương lai đơn, nhưng không đầy đủ, cần phải có một động từ đi kèm, và trong trường hợp này cần là "had" để hoàn chỉnh cụm "will have had."', 'Vào thời điểm này sáng mai, chúng ta sẽ đã tiêm xong.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_005', 'zenlish_practice', 'By the time he leaves school, his parents _____ £25,000 on his education.', 'have spent', 'will spend', 'spend', 'will have spent', 'D', 'Giải thích: "Will have spent" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "khi cậu ấy rời trường," bố mẹ cậu ấy sẽ đã chi 25.000 bảng cho việc học của cậu.\n(A) have spent: "Have spent" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp với ngữ cảnh tương lai.\n(B) will spend: "Will spend" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(C) spend: "Spend" là thì hiện tại đơn, không phù hợp khi câu hỏi nói về một hành động trong tương lai.', 'Khi cậu ấy rời trường, bố mẹ cậu ấy sẽ đã chi 25.000 bảng cho việc học của cậu.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_006', 'zenlish_practice', 'On the fourth of next month, he _______ in prison for ten years.', 'will have been', 'have been', 'was', 'is', 'A', 'Giải thích: "Will have been" là thì tương lai hoàn thành, được sử dụng để diễn tả một trạng thái hoặc hành động sẽ kéo dài đến một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào ngày 4 tháng sau," anh ta sẽ đã ở trong tù được mười năm.\n(B) have been: "Have been" là thì hiện tại hoàn thành, diễn tả một hành động hoặc trạng thái đã kéo dài từ quá khứ đến hiện tại, nhưng không phù hợp với ngữ cảnh nói về một thời điểm cụ thể trong tương lai.\n(C) was: "Was" là thì quá khứ đơn, diễn tả một trạng thái hoặc hành động đã xảy ra trong quá khứ, không phù hợp khi câu hỏi đang đề cập đến tương lai.\n(D) is: "Is" là thì hiện tại đơn, không phù hợp khi câu hỏi đang nói về một trạng thái sẽ kéo dài đến một thời điểm trong tương lai.', 'Vào ngày 4 tháng sau, anh ta sẽ đã ở trong tù được mười năm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_007', 'zenlish_practice', 'The collector _______ his set by the end of the year.', 'will complete', 'has completed', 'will be completing', 'will have completed', 'D', 'Giải thích: "Will have completed" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào cuối năm," người sưu tầm sẽ đã hoàn thành bộ sưu tập của mình.\n(A) will complete: "Will complete" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(B) has completed: "Has completed" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp với ngữ cảnh tương lai.\n(C) will be completing: "Will be completing" là thì tương lai tiếp diễn, dùng để diễn tả một hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai, nhưng không phù hợp khi câu này yêu cầu diễn đạt sự hoàn thành của hành động.', 'Người sưu tầm sẽ đã hoàn thành bộ sưu tập của mình vào cuối năm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_008', 'zenlish_practice', 'When you come back, I _____ all the housework.', 'finished', 'have finished', 'will have finished', 'will finish', 'C', 'Giải thích: "Will have finished" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng khi bạn trở về, tôi sẽ đã hoàn thành tất cả công việc nhà.\n(A) finished: "Finished" là thì quá khứ đơn, diễn tả một hành động đã hoàn thành trong quá khứ, không phù hợp với ngữ cảnh tương lai.\n(B) have finished: "Have finished" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.\n(D) will finish: "Will finish" là thì tương lai đơn, dùng để diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.', 'Khi bạn trở về, tôi sẽ đã hoàn thành tất cả công việc nhà.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_009', 'zenlish_practice', 'As many as ten-million children _____ with the virus by the end of this decade.', 'will have been infected', 'have been infected', 'will be infecting', 'had been infected', 'A', 'Giải thích: "Will have been infected" là thì tương lai hoàn thành bị động, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào cuối thập kỷ này," có tới mười triệu trẻ em sẽ đã bị nhiễm virus.\n(B) have been infected: "Have been infected" là thì hiện tại hoàn thành bị động, dùng để diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp với ngữ cảnh nói về tương lai.\n(C) will be infecting: "Will be infecting" là thì tương lai tiếp diễn ở dạng chủ động, không phù hợp vì câu cần một cấu trúc bị động để diễn tả việc bị nhiễm virus.\n(D) had been infected: "Had been infected" là thì quá khứ hoàn thành bị động, dùng để diễn tả một hành động đã xảy ra và hoàn thành trước một thời điểm khác trong quá khứ, không phù hợp với ngữ cảnh nói về tương lai.', 'Có tới mười triệu trẻ em sẽ đã bị nhiễm virus vào cuối thập kỷ này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0047_q_010', 'zenlish_practice', 'By the end of my university course, I ______ 1,200 lectures.', 'attend', 'attended', 'have attended', 'will have attended', 'D', 'Giải thích: "Will have attended" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào cuối khóa học đại học của tôi," tôi sẽ đã tham dự 1.200 bài giảng.\n(A) attend: "Attend" là thì hiện tại đơn, dùng để diễn tả một hành động xảy ra thường xuyên hoặc theo thói quen, không phù hợp với ngữ cảnh nói về tương lai.\n(B) attended: "Attended" là thì quá khứ đơn, diễn tả một hành động đã xảy ra trong quá khứ, không phù hợp với ngữ cảnh nói về tương lai.\n(C) have attended: "Have attended" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.', 'Vào cuối khóa học đại học của tôi, tôi sẽ đã tham dự 1.200 bài giảng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_001', 'zenlish_practice', 'By the end of next year, they _____ the new stadium.', 'will finish', 'finish', 'will have finished', 'are finishing', 'C', 'Giải thích: "Will have finished" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào cuối năm sau," họ sẽ đã hoàn thành sân vận động mới.\n(A) will finish: "Will finish" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(B) finish: "Finish" là thì hiện tại đơn, dùng để diễn tả một hành động xảy ra thường xuyên hoặc theo thói quen, không phù hợp với ngữ cảnh nói về tương lai.\n(D) are finishing: "are finishing" là thì hiện tại tiếp diễn, dùng để diễn tả một hành động đang diễn ra ở hiện tại hoặc tương lai gần, nhưng không phù hợp với ngữ cảnh cần nói về một hành động hoàn thành trước một thời điểm cụ thể trong tương lai.', 'Vào cuối năm sau, họ sẽ đã hoàn thành sân vận động mới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_002', 'zenlish_practice', 'When we reach Valparaiso, we ______ all round the world.', 'have sailed', 'will have sailed', 'sailed', 'are sailing', 'B', 'Giải thích: "Will have sailed" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng khi chúng ta đến Valparaiso, chúng ta sẽ đã đi vòng quanh thế giới.\n(A) have sailed: "Have sailed" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.\n(C) sailed: "Sailed" là thì quá khứ đơn, diễn tả một hành động đã xảy ra trong quá khứ, không phù hợp với ngữ cảnh nói về tương lai.\n(D) are sailing: "Are sailing" là thì hiện tại tiếp diễn, dùng để diễn tả một hành động đang diễn ra ở hiện tại hoặc tương lai gần, nhưng không phù hợp với ngữ cảnh cần nói về một hành động đã hoàn thành trước một thời điểm cụ thể trong tương lai.', 'Khi chúng ta đến Valparaiso, chúng ta sẽ đã đi vòng quanh thế giới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_003', 'zenlish_practice', 'He will have ________ all about it by Monday.', 'forgetting', 'forgotten', 'be forgetting', 'forget', 'B', 'Giải thích: "Forgotten" là dạng quá khứ phân từ của động từ "forget" và được sử dụng trong cấu trúc "will have forgotten" ở thì tương lai hoàn thành, để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng vào thứ Hai, anh ấy sẽ đã quên hết mọi thứ.\n(A) forgetting: "Forgetting" là dạng hiện tại tiếp diễn, không phù hợp với cấu trúc thì tương lai hoàn thành.\n(C) be forgetting: "Be forgetting" không phải là một cấu trúc ngữ pháp chính xác cho thì tương lai hoàn thành.\n(D) forget: "Forget" là dạng nguyên thể, không phù hợp khi cần sử dụng quá khứ phân từ trong thì tương lai hoàn thành.', 'Anh ấy sẽ đã quên hết mọi chuyện vào thứ Hai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_004', 'zenlish_practice', 'By next winter, they _____ four houses in that field.', 'build', 'built', 'will have built', 'have built', 'C', 'Giải thích: "Will have built" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào mùa đông tới," họ sẽ đã xây xong bốn ngôi nhà trên cánh đồng đó.\n(A) build: "Build" là thì hiện tại đơn, dùng để diễn tả một hành động xảy ra thường xuyên hoặc theo thói quen, không phù hợp với ngữ cảnh nói về tương lai.\n(B) built: "Built" là thì quá khứ đơn, diễn tả một hành động đã xảy ra trong quá khứ, không phù hợp với ngữ cảnh nói về tương lai.\n(D) have built: "Have built" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.', 'Vào mùa đông tới, họ sẽ đã xây xong bốn ngôi nhà trên cánh đồng đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_005', 'zenlish_practice', '(You/finish) ____ the report by the deadline?', 'Will you have finished', 'Did you finish', 'Have you finished', 'Do you finish?', 'A', 'Giải thích: "Will you have finished" là cấu trúc thì tương lai hoàn thành, được sử dụng để hỏi về một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai, trong trường hợp này là trước hạn chót.\n(B) Did you finish: "Did you finish" là thì quá khứ đơn, dùng để hỏi về một hành động đã hoàn thành trong quá khứ, không phù hợp với ngữ cảnh hỏi về tương lai.\n(C) Have you finished: "Have you finished" là thì hiện tại hoàn thành, dùng để hỏi về một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh hỏi về tương lai.\n(D) Do you finish: "Do you finish" là thì hiện tại đơn, không phù hợp khi câu hỏi muốn biết về việc hoàn thành công việc trong tương lai.', 'Bạn sẽ hoàn thành báo cáo trước hạn chót chứ?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_006', 'zenlish_practice', 'The train _____ before we reach the station.', 'will leave', 'is leaving', 'has left', 'will have left', 'D', 'Giải thích: "Will have left" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng tàu sẽ đã rời đi trước khi chúng ta đến ga.\n(A) will leave: "Will leave" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(B) is leaving: "Is leaving" là thì hiện tại tiếp diễn, dùng để diễn tả một hành động đang diễn ra hoặc đã được lên kế hoạch trong tương lai gần, nhưng không phù hợp với ngữ cảnh yêu cầu diễn tả một hành động đã hoàn thành trước khi chúng ta đến.\n(C) has left: "Has left" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.', 'Tàu sẽ đã rời đi trước khi chúng ta đến ga.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_007', 'zenlish_practice', 'By the end of this month, 5,000 people ______ this exhibition.', 'will have seen', 'will see', 'saw', 'have seen', 'A', 'Giải thích: "Will have seen" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào cuối tháng này," 5.000 người sẽ đã tham quan triển lãm này.\n(B) will see: "Will see" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(C) saw: "Saw" là thì quá khứ đơn, diễn tả một hành động đã xảy ra trong quá khứ, không phù hợp với ngữ cảnh nói về tương lai.\n(D) have seen: "Have seen" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.', 'Vào cuối tháng này, 5.000 người sẽ đã tham quan triển lãm này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_008', 'zenlish_practice', 'I think that everything ______ ready for the project procedure by the end of next month.', 'has been', 'had been', 'is', 'will have been', 'D', 'Giải thích: "Will have been" là thì tương lai hoàn thành, được sử dụng để diễn tả một trạng thái hoặc hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào cuối tháng sau," mọi thứ sẽ đã sẵn sàng cho quy trình dự án.\n(A) has been: "Has been" là thì hiện tại hoàn thành, diễn tả một hành động hoặc trạng thái đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.\n(B) had been: "Had been" là thì quá khứ hoàn thành, diễn tả một hành động hoặc trạng thái đã hoàn thành trước một thời điểm khác trong quá khứ, không phù hợp với ngữ cảnh tương lai.\n(C) is: "Is" là thì hiện tại đơn, diễn tả một trạng thái ở hiện tại, không phù hợp với ngữ cảnh nói về tương lai.', 'Tôi nghĩ rằng mọi thứ sẽ đã sẵn sàng cho quy trình dự án vào cuối tháng sau.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_009', 'zenlish_practice', 'By the time you receive this letter, I _____ for Japan.', 'will have left', 'have left', 'left', 'leave', 'A', 'Giải thích: "Will have left" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "khi bạn nhận được lá thư này," tôi sẽ đã rời khỏi đi Nhật Bản.\n(B) have left: "Have left" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.\n(C) left: "Left" là thì quá khứ đơn, diễn tả một hành động đã xảy ra trong quá khứ, không phù hợp với ngữ cảnh tương lai.\n(D) leave: "Leave" là thì hiện tại đơn, không phù hợp khi câu này đang nói về một hành động đã hoàn thành trước một thời điểm cụ thể trong tương lai.', 'Khi bạn nhận được lá thư này, tôi sẽ đã rời đi Nhật Bản.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0048_q_010', 'zenlish_practice', 'She (finish) ____ her exams by then, so we can go out for dinner.', 'will have finished', 'finished', 'didn’t finish', 'finishes', 'A', 'Giải thích: "Will have finished" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "đến lúc đó," cô ấy sẽ đã hoàn thành xong kỳ thi của mình, vì vậy chúng ta có thể đi ăn tối.\n(B) finished: "Finished" là thì quá khứ đơn, diễn tả một hành động đã xảy ra trong quá khứ, không phù hợp với ngữ cảnh nói về tương lai.\n(C) didn’t finish: "Didn’t finish" là thì quá khứ đơn ở dạng phủ định, không phù hợp với ngữ cảnh yêu cầu nói về một hành động sẽ hoàn thành trong tương lai.\n(D) finishes: "Finishes" là thì hiện tại đơn, không phù hợp khi câu này đang nói về một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai.', 'Cô ấy sẽ đã hoàn thành xong kỳ thi vào lúc đó, vì vậy chúng ta có thể đi ăn tối', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_001', 'zenlish_practice', 'I (read) ____ the book before the next class.', 'read', 'will have read', 'have read', 'are reading', 'B', 'Giải thích: "Will have read" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "tôi sẽ đã đọc xong cuốn sách trước buổi học tiếp theo."\n(A) read: "Read" có thể là thì hiện tại đơn hoặc quá khứ đơn, không phù hợp khi câu này đang nói về một hành động sẽ hoàn thành trước một thời điểm trong tương lai.\n(C) have read: "Have read" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.\n(D) are reading: "Are reading" là thì hiện tại tiếp diễn, diễn tả một hành động đang diễn ra ở hiện tại hoặc tương lai gần, nhưng không phù hợp với ngữ cảnh yêu cầu diễn tả một hành động đã hoàn thành trước một thời điểm trong tương lai.', 'Tôi sẽ đã đọc xong cuốn sách trước buổi học tiếp theo.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_002', 'zenlish_practice', 'How long (you/be) ____ in this company when you retire?', 'will have you been', 'have you been', 'are you been', 'are you', 'A', 'Giải thích: "Will have you been" là thì tương lai hoàn thành, được sử dụng để hỏi về khoảng thời gian một người sẽ trải qua trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu hỏi muốn biết "bạn sẽ đã làm việc trong công ty này bao lâu khi bạn nghỉ hưu."\n(B) have you been: "Have you been" là thì hiện tại hoàn thành, thường dùng để hỏi về khoảng thời gian đã trải qua đến hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.\n(C) are you been: Đây là một cấu trúc ngữ pháp không chính xác.\n(D) are you: "Are you" là thì hiện tại đơn, không phù hợp khi câu hỏi yêu cầu một cấu trúc để hỏi về thời gian trải qua đến một thời điểm trong tương lai.', 'Bạn sẽ đã làm việc trong công ty này bao lâu khi bạn nghỉ hưu?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_003', 'zenlish_practice', 'When he retires, he __________ 30 films.', 'have made', 'will have made', 'is making', 'makes', 'B', 'Giải thích: "Will have made" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "khi anh ấy nghỉ hưu," anh ấy sẽ đã làm được 30 bộ phim.\n(A) have made: "Have made" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp với ngữ cảnh nói về tương lai.\n(C) is making: "Is making" là thì hiện tại tiếp diễn, diễn tả một hành động đang diễn ra ở hiện tại hoặc tương lai gần, nhưng không phù hợp với ngữ cảnh yêu cầu diễn tả một hành động đã hoàn thành trước một thời điểm cụ thể trong tương lai.\n(D) makes: "Makes" là thì hiện tại đơn, không phù hợp khi câu này đang nói về một hành động sẽ hoàn thành trước một thời điểm trong tương lai.', 'Khi anh ấy nghỉ hưu, anh ấy sẽ đã làm được 30 bộ phim.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_004', 'zenlish_practice', 'We _________ the play by September.', 'are rehearsed', 'will have rehearsed', 'will be rehearsing', 'have rehearsed', 'B', 'Giải thích: "Will have rehearsed" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "chúng tôi sẽ đã tập luyện xong vở kịch vào tháng Chín."\n(A) are rehearsed: "Are rehearsed" là thì hiện tại bị động, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động hoàn thành trong tương lai.\n(C) will be rehearsing: "Will be rehearsing" là thì tương lai tiếp diễn, diễn tả một hành động sẽ đang diễn ra tại một thời điểm trong tương lai, không phù hợp khi câu này muốn nói về hành động đã hoàn thành.\n(D) have rehearsed: "Have rehearsed" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.', 'Chúng tôi sẽ đã tập luyện xong vở kịch vào tháng Chín.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_005', 'zenlish_practice', 'Come over to my house around 9 o’clock. By then, I _________ my history essay and we can go see a movie.', 'will complete', 'will have completing', 'will have completed', 'would complete', 'C', 'Giải thích: "Will have completed" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "khoảng 9 giờ, tôi sẽ đã hoàn thành bài luận lịch sử của mình, và chúng ta có thể đi xem phim."\n(A) will complete: "Will complete" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(B) will have completing: Đây không phải là cấu trúc ngữ pháp đúng. Động từ sau "will have" phải ở dạng quá khứ phân từ (completed).\n(D) would complete: "Would complete" là thì điều kiện, thường dùng để diễn tả một hành động có thể xảy ra trong một tình huống giả định, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trong tương lai.', 'Hãy đến nhà tôi khoảng 9 giờ. Lúc đó, tôi sẽ đã hoàn thành xong bài luận lịch sử của mình và chúng ta có thể đi xem phim.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_006', 'zenlish_practice', 'Fortunately, our son _____________ school by the time the new tests are introduced.', 'will have left', 'will be left', 'will be leaving', 'will leave', 'A', 'Giải thích: "Will have left" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "may mắn thay, con trai chúng tôi sẽ đã rời khỏi trường trước khi các bài kiểm tra mới được đưa ra."\n(B) will be left: "Will be left" là thì tương lai đơn ở dạng bị động, nhưng không phù hợp trong ngữ cảnh này vì nó diễn tả trạng thái bị bỏ lại, không phải hành động rời khỏi.\n(C) will be leaving: "Will be leaving" là thì tương lai tiếp diễn, diễn tả một hành động sẽ đang diễn ra tại một thời điểm trong tương lai, nhưng không phù hợp khi câu này muốn nói về một hành động đã hoàn thành trước một thời điểm trong tương lai.\n(D) will leave: "Will leave" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai, nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.', 'May mắn thay, con trai chúng tôi sẽ đã rời khỏi trường trước khi các bài kiểm tra mới được đưa ra.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_007', 'zenlish_practice', 'I __________ enough mushrooms before you start cooking.', 'have found', 'am finding', 'will have found', 'found', 'C', 'Giải thích: "Will have found" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "tôi sẽ đã tìm đủ nấm trước khi bạn bắt đầu nấu ăn."\n(A) have found: "Have found" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh nói về tương lai.\n(B) am finding: "Am finding" là thì hiện tại tiếp diễn, diễn tả một hành động đang diễn ra tại thời điểm hiện tại, nhưng không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trong tương lai.\n(D) found: "Found" là thì quá khứ đơn, diễn tả một hành động đã xảy ra trong quá khứ, không phù hợp với ngữ cảnh nói về tương lai.', 'Tôi sẽ đã tìm đủ nấm trước khi bạn bắt đầu nấu ăn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_008', 'zenlish_practice', 'Before Saturday, I will have _______ all my homework.', 'did', 'do', 'does', 'done', 'D', 'Giải thích: "Will have done" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "trước thứ Bảy, tôi sẽ đã làm xong tất cả bài tập của mình."\n(A) did: "Did" là thì quá khứ đơn, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trong tương lai.\n(B) do: "Do" là thì hiện tại đơn, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai.\n(C) does: "Does" là thì hiện tại đơn, được sử dụng với ngôi thứ ba số ít, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trong tương lai.', 'Trước thứ Bảy, tôi sẽ đã làm xong tất cả bài tập của mình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_009', 'zenlish_practice', 'By the end of this season, he ______ 50 matches in this team.', 'will play', 'will have played', 'will have been playing', 'played', 'B', 'Giải thích: "Will have played" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "đến cuối mùa giải này, anh ấy sẽ đã chơi 50 trận trong đội này."\n(A) will play: "Will play" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(C) will have been playing: "Will have been playing" là thì tương lai tiếp diễn hoàn thành, diễn tả một hành động sẽ đang tiếp tục hoặc đang diễn ra tại một thời điểm trong tương lai, không phù hợp khi câu muốn nói về một hành động đã hoàn thành.\n(D) played: "Played" là thì quá khứ đơn, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trong tương lai.', 'Đến cuối mùa giải này, anh ấy sẽ đã chơi 50 trận trong đội này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0049_q_010', 'zenlish_practice', 'In two years, he ____________ for this company for ten years.', 'worked', 'will have worked', 'will be working', 'did work', 'B', 'Giải thích: "Will have worked" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "trong hai năm nữa, anh ấy sẽ đã làm việc cho công ty này được mười năm."\n(A) worked: "Worked" là thì quá khứ đơn, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trong tương lai.\n(C) will be working: "Will be working" là thì tương lai tiếp diễn, diễn tả một hành động sẽ đang diễn ra tại một thời điểm trong tương lai, không phù hợp khi câu muốn nói về một hành động đã hoàn thành.\n(D) did work: "Did work" là thì quá khứ đơn với động từ "do," không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trong tương lai.', 'Trong hai năm nữa, anh ấy sẽ đã làm việc cho công ty này được mười năm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_001', 'zenlish_practice', 'I __________him an email before I leave the office.', 'have sent', 'am sending', 'will have sent', 'will send', 'C', 'Giải thích: "will have send" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ xảy ra trước một hành động khác trong tương lai. Cụ thể, hành động "gửi email" sẽ được hoàn thành trước khi tôi rời văn phòng.\n(A) have sent: "Have sent" là thì hiện tại hoàn thành, diễn tả một hành động đã hoàn thành trước thời điểm hiện tại, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ xảy ra trong tương lai.\n(B) am sending: "Am sending" là thì hiện tại tiếp diễn, diễn tả một hành động đang xảy ra tại thời điểm hiện tại, không phù hợp khi câu yêu cầu một hành động sẽ xảy ra trong tương lai.\n(D) will sent: "Will sent" là thì tương lai đơn, diễn tả hành động xảy ra trong tương lai, không phù hợp để mô tả một hành động xảy ra trước hành động khác.', 'Tôi sẽ gửi cho anh ấy một email trước khi tôi rời khỏi văn phòng.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_002', 'zenlish_practice', 'The manager _________ the meeting room by twelve.', 'will have been left', 'will have left', 'will leave', 'left', 'B', 'Giải thích: "Will have left" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "nhà quản lý sẽ đã rời khỏi phòng họp trước 12 giờ."\n(A) will have been left: "Will have been left" là thì tương lai hoàn thành bị động, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động chủ động của "nhà quản lý."\n(C) will leave: "Will leave" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(D) left: "Left" là thì quá khứ đơn, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trong tương lai.', 'Nhà quản lý sẽ đã rời khỏi phòng họp trước 12 giờ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_003', 'zenlish_practice', 'By Friday, they _______ the road in King Street and George Street.', 'dug up', 'will dig up', 'are digging up', 'will have dug up', 'D', 'Giải thích: "Will have dug up" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "đến thứ Sáu, họ sẽ đã đào xong con đường ở phố King và phố George."\n(A) dug up: "Dug up" là thì quá khứ đơn, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động sẽ hoàn thành trong tương lai.\n(B) will dig up: "Will dig up" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra trong tương lai nhưng không nhấn mạnh rằng hành động đó sẽ hoàn thành trước một thời điểm cụ thể.\n(C) are digging up: "Are digging up" là thì hiện tại tiếp diễn, diễn tả một hành động đang xảy ra tại thời điểm hiện tại, không phù hợp với ngữ cảnh khi câu yêu cầu một hành động sẽ hoàn thành trong tương lai.', 'Đến thứ Sáu, họ sẽ đã đào xong con đường ở phố King và phố George.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_004', 'zenlish_practice', 'Before you arrive at the station, a hotel room _______ for you.', 'will have booked', 'will have been booked', 'is booked', 'is booking', 'B', 'Giải thích: "Will have been booked" là thì tương lai hoàn thành bị động, được sử dụng để diễn tả một hành động sẽ đã hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "trước khi bạn đến ga, một phòng khách sạn sẽ đã được đặt cho bạn."\n(A) will have booked: "Will have booked" là thì tương lai hoàn thành chủ động, không phù hợp với ngữ cảnh yêu cầu diễn tả hành động bị động của việc đặt phòng.\n(C) is booked: "Is booked" là thì hiện tại đơn bị động, diễn tả một trạng thái hiện tại, không phù hợp khi câu yêu cầu một hành động sẽ đã hoàn thành trong tương lai.\n(D) is booking: "Is booking" là thì hiện tại tiếp diễn, diễn tả một hành động đang xảy ra tại thời điểm hiện tại, không phù hợp với ngữ cảnh khi câu yêu cầu một hành động sẽ đã hoàn thành trong tương lai.', 'Trước khi bạn đến ga, một phòng khách sạn sẽ đã được đặt cho bạn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_005', 'zenlish_practice', 'We ____ before we come, so we will be hungry.', 'will have eaten', 'will be eating', 'won''t have eaten', 'won''t be eating', 'C', 'Giải thích: "Won''t have eaten" là thì tương lai hoàn thành phủ định, được sử dụng để diễn tả rằng hành động chưa hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "chúng tôi sẽ chưa ăn trước khi chúng tôi đến, vì vậy chúng tôi sẽ đói."\n(A) will have eaten: "Will have eaten" là thì tương lai hoàn thành khẳng định, diễn tả rằng hành động sẽ đã hoàn thành trước một thời điểm cụ thể trong tương lai, không phù hợp với ngữ cảnh phủ định.\n(B) will be eating: "Will be eating" là thì tương lai tiếp diễn, diễn tả một hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai, không phù hợp với ngữ cảnh khi hành động chưa hoàn thành.\n(D) won''t be eating: "Won''t be eating" là thì tương lai tiếp diễn phủ định, không phù hợp khi câu yêu cầu diễn tả hành động chưa hoàn thành trước thời điểm cụ thể trong tương lai.', 'Chúng tôi sẽ chưa ăn trước khi chúng tôi đến, vì vậy chúng tôi sẽ đói.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_006', 'zenlish_practice', 'I will let you know your results on Friday. The papers _______________ by then.', 'will be marking', 'will have marked', 'will have been marked', 'will have been marking', 'C', 'Giải thích: "Will have been marked" là thì tương lai hoàn thành bị động, được sử dụng để diễn tả một hành động bị động sẽ đã hoàn thành trước một thời điểm cụ thể trong tương lai. Trong trường hợp này, câu muốn nói rằng "vào thứ Sáu, các bài thi sẽ đã được chấm."\n(A) will be marking: "Will be marking" là thì tương lai tiếp diễn, diễn tả hành động sẽ đang xảy ra tại một thời điểm cụ thể trong tương lai, không phù hợp khi cần diễn tả hành động đã hoàn thành.\n(B) will have marked: "Will have marked" là thì tương lai hoàn thành chủ động, không phù hợp với ngữ cảnh yêu cầu một hành động bị động.\n(D) will have been marking: "Will have been marking" là thì tương lai hoàn thành tiếp diễn, diễn tả một hành động sẽ đang xảy ra liên tục cho đến một thời điểm trong tương lai, không phù hợp với ngữ cảnh khi cần một hành động bị động đã hoàn thành.', 'Tôi sẽ thông báo cho bạn kết quả vào thứ Sáu. Các bài thi sẽ đã được chấm trước thời điểm đó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_007', 'zenlish_practice', 'If you don´t hurry up, the film _______________ by the time we arrive.', 'will be finished', 'will not finish', 'will have finished', 'won’t have finished', 'C', 'Giải thích: "Will have finished" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ đã hoàn thành trước một thời điểm cụ thể trong tương lai. Trong câu này, ý nghĩa là "nếu bạn không nhanh lên, bộ phim sẽ đã kết thúc trước khi chúng tôi đến."\n(A) will be finished: "Will be finished" là thì tương lai bị động, diễn tả một trạng thái bị động trong tương lai mà không nhấn mạnh sự hoàn thành trước một thời điểm cụ thể.\n(B) will not finish: "Will not finish" là thì tương lai phủ định, không phù hợp với ngữ cảnh yêu cầu diễn tả một hành động sẽ đã hoàn thành.\n(D) won’t have finished: "Won’t have finished" là thì tương lai hoàn thành phủ định, nhưng không phù hợp khi câu yêu cầu diễn tả rằng hành động sẽ đã hoàn thành.', 'Nếu bạn không nhanh lên, bộ phim sẽ đã kết thúc trước khi chúng tôi đến.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_008', 'zenlish_practice', 'By the year 2050, scientists ________________ cure for cancer.', 'have will discovered', 'will have discover', 'will have discovered', 'will discover', 'C', 'Giải thích: "Will have discovered" là thì tương lai hoàn thành, được sử dụng để diễn tả một hành động sẽ đã hoàn thành trước một thời điểm cụ thể trong tương lai. Trong câu này, ý nghĩa là "tới năm 2050, các nhà khoa học sẽ đã phát hiện ra một phương pháp chữa trị cho ung thư."\n(A) have will discovered: Đây là một sự kết hợp sai giữa các thì và không phù hợp với ngữ pháp.\n(B) will have discover: "Will have discover" là một sự kết hợp sai giữa thì tương lai hoàn thành và dạng động từ cơ bản, không phù hợp với ngữ pháp.\n(D) will discover: "Will discover" là thì tương lai đơn, không phù hợp khi cần diễn tả hành động đã hoàn thành trước một thời điểm trong tương lai.', 'Tới năm 2050, các nhà khoa học sẽ đã phát hiện ra phương pháp chữa trị cho ung thư.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_009', 'zenlish_practice', 'Sheila ________the scholarship by the time she starts school in September.', 'been have got', 'will get', 'won’t have got', 'have got', 'C', 'Giải thích: "Won’t have got" là thì tương lai hoàn thành phủ định, được sử dụng để diễn tả một hành động bị động sẽ chưa hoàn thành trước một thời điểm cụ thể trong tương lai. Trong câu này, ý nghĩa là "Sheila sẽ chưa nhận được học bổng khi cô ấy bắt đầu học vào tháng Chín."\n(A) been have got: Đây là một sự kết hợp sai giữa các thì và không phù hợp với ngữ pháp.\n(B) will get: "Will get" là thì tương lai đơn, không phù hợp khi cần diễn tả hành động chưa hoàn thành trước một thời điểm trong tương lai.\n(D) have got: "Have got" là thì hiện tại hoàn thành, không phù hợp khi câu yêu cầu một thì tương lai hoàn thành.', 'Sheila sẽ chưa nhận được học bổng khi cô ấy bắt đầu học vào tháng Chín.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0050_q_010', 'zenlish_practice', 'By the time Ms. Valspar retires, she ______ to increase the company''s market share significantly.', 'manages', 'will have managed', 'managed', 'has been managing', 'B', 'Giải thích: Câu này sử dụng thì tương lai hoàn thành "will have managed" để diễn tả một hành động sẽ được hoàn tất trước một thời điểm trong tương lai (trước khi bà Valspar nghỉ hưu). Thì tương lai hoàn thành được dùng để nhấn mạnh rằng hành động sẽ được hoàn tất trước một thời điểm cụ thể trong tương lai.\n(A) manages: Không đúng vì đây là thì hiện tại đơn, không phù hợp với ngữ cảnh diễn tả một hành động sẽ hoàn tất trong tương lai.\n(C) managed: Không đúng vì đây là thì quá khứ đơn, không phù hợp với ngữ cảnh về hành động sẽ hoàn tất trong tương lai.\n(D) has been managing: Không đúng vì đây là thì hiện tại hoàn thành tiếp diễn, không phù hợp với việc mô tả một hành động sẽ hoàn tất trước một thời điểm trong tương lai.', 'Trước khi bà Valspar nghỉ hưu, bà sẽ đã quản lý để tăng trưởng thị phần của công ty một cách đáng kể.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_001', 'zenlish_practice', 'They’ve bought a rope and they ________ the car to a garage.', 'will tow', 'are going to tow', 'was going to tow', 'towing', 'B', 'Giải thích: "Are going to tow" được sử dụng để diễn tả kế hoạch hoặc dự định trong tương lai gần. Trong câu này, ý nghĩa là "Họ đã mua một sợi dây và họ dự định kéo xe ô tô đến một gara."\n(A) will tow: "Will tow" là thì tương lai đơn, có thể đúng nhưng không nhấn mạnh sự dự định hoặc kế hoạch cụ thể đã được xác định.\n(C) was going to tow: "Was going to tow" là thì quá khứ của "going to," không phù hợp với thì hiện tại hoặc dự định tương lai.\n(D) towing: "Towing" là dạng hiện tại phân từ, không phù hợp khi câu cần một động từ chính để chỉ kế hoạch trong tương lai.', 'Họ đã mua một sợi dây và họ dự định kéo xe ô tô đến một gara.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_002', 'zenlish_practice', 'They’ve hired a bulldozer. They ______ away this rubble.', 'are going to clear', 'will clear', 'was going to clear', 'are clearing', 'A', 'Giải thích: "Are going to clear" được sử dụng để diễn tả một kế hoạch hoặc dự định trong tương lai gần. Trong câu này, ý nghĩa là "Họ đã thuê một chiếc máy ủi và họ dự định dọn dẹp đống gạch vụn này."\n(B) will clear: "Will clear" là thì tương lai đơn, có thể đúng nhưng không nhấn mạnh sự dự định cụ thể như "are going to clear."\n(C) was going to clear: "Was going to clear" là thì quá khứ của "going to," không phù hợp với thì hiện tại hoặc dự định trong tương lai.\n(D) are clearing: "Are clearing" là thì hiện tại tiếp diễn, không phù hợp khi câu cần diễn tả một kế hoạch hoặc dự định trong tương lai.', 'Họ đã thuê một chiếc máy ủi và họ dự định dọn dẹp đống gạch vụn này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_003', 'zenlish_practice', 'I’m turning this cupboard into a darkroom. I ______ my own films.', 'will develop', 'was going to develop', 'am going to develop', 'developing', 'C', 'Giải thích: "Am going to develop" được sử dụng để diễn tả kế hoạch hoặc dự định trong tương lai gần. Trong câu này, ý nghĩa là "Tôi đang biến cái tủ này thành một phòng tối. Tôi dự định sẽ tự rửa phim của mình."\n(A) will develop: "Will develop" là thì tương lai đơn, có thể đúng nhưng không nhấn mạnh sự dự định cụ thể như "am going to develop."\n(B) was going to develop: "Was going to develop" là thì quá khứ của "going to," không phù hợp với thì hiện tại hoặc dự định trong tương lai.\n(D) developing: "Developing" là dạng hiện tại phân từ, không phù hợp khi câu cần một động từ chính để chỉ kế hoạch trong tương lai.', 'Tôi đang biến cái tủ này thành một phòng tối. Tôi dự định sẽ tự rửa phim của mình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_004', 'zenlish_practice', 'I’ve just enrolled at the local technical college. I ______ pottery classes next winter.', 'will attend', 'shall attend', 'attend', 'am going to attend', 'D', 'Giải thích: "Am going to attend" được sử dụng để diễn tả một kế hoạch hoặc dự định trong tương lai gần, phù hợp với việc đã đăng ký học tại trường và dự định tham gia các lớp học gốm sứ vào mùa đông tới.\n(A) will attend: "Will attend" là thì tương lai đơn, có thể đúng nhưng không nhấn mạnh sự dự định cụ thể như "am going to attend."\n(B) shall attend: "Shall attend" là cách sử dụng "shall" trong thì tương lai, nhưng "shall" thường ít được sử dụng trong tiếng Anh hiện đại để diễn tả kế hoạch cá nhân, và cũng không nhấn mạnh sự dự định cụ thể.\n(C) attend: "Attend" là thì hiện tại, không phù hợp khi câu cần diễn tả một kế hoạch hoặc dự định trong tương lai.', 'Tôi vừa mới đăng ký học tại trường kỹ thuật địa phương. Tôi dự định sẽ tham gia các lớp học gốm sứ vào mùa đông tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_005', 'zenlish_practice', 'I haven’t bought any cigarettes because I ______ up smoking.', 'am going to give', 'was going to give', 'shall give', 'am giving', 'A', 'Giải thích: "Am going to give up" được sử dụng để diễn tả một kế hoạch hoặc quyết định trong tương lai gần. Trong câu này, người nói có ý định từ bỏ thuốc lá, vì vậy chưa mua thuốc lá. "Am going to give up" nhấn mạnh sự quyết định sắp tới về việc từ bỏ thuốc lá.\n(B) was going to give: "Was going to give" là thì quá khứ của "going to," không phù hợp với ngữ cảnh hiện tại khi người nói đang quyết định trong thời điểm hiện tại.\n(C) shall give: "Shall give" là cách sử dụng "shall" trong thì tương lai, ít được dùng trong tiếng Anh hiện đại để diễn tả kế hoạch cá nhân và không nhấn mạnh quyết định cụ thể như "am going to give."\n(D) am giving: "Am giving" là thì hiện tại tiếp diễn, không phù hợp khi câu cần diễn tả một kế hoạch hoặc quyết định trong tương lai.', 'Tôi chưa mua thuốc lá vì tôi dự định sẽ từ bỏ thuốc lá.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_006', 'zenlish_practice', 'You can borrow this calculator, I ________.', 'am not going to need it', 'won’t have been needing it', 'am not needing it', 'did not need it', 'A', 'Giải thích: "Am not going to need it" được sử dụng để diễn tả một dự định hoặc kế hoạch trong tương lai gần, nghĩa là người nói dự định không cần đến máy tính trong thời gian tới, nên có thể cho mượn.\n(B) won’t have been needing it: "Won’t have been needing it" là thì tương lai hoàn thành tiếp diễn, không phù hợp trong ngữ cảnh này vì không cần diễn tả một hành động liên tục trong tương lai.\n(C) am not needing it: "Am not needing it" là thì hiện tại tiếp diễn, không phải là cách diễn đạt phù hợp cho một dự định trong tương lai.\n(D) did not need it: "Did not need it" là thì quá khứ, không phù hợp với ngữ cảnh hiện tại khi người nói đang nói về kế hoạch cho tương lai.', 'Bạn có thể mượn máy tính này, tôi sẽ không cần đến nó.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_007', 'zenlish_practice', 'Why are you taking that big basket? - I _______ a lot of vegetables.', 'am going to buy', 'am buying', 'was buying', 'shall buy', 'A', 'Giải thích: "Am going to buy" được sử dụng để diễn tả một kế hoạch hoặc dự định trong tương lai gần. Trong câu này, người nói đang chuẩn bị để mua nhiều rau, vì vậy cần mang theo giỏ lớn.\n(B) am buying: "Am buying" là thì hiện tại tiếp diễn, diễn tả hành động đang xảy ra trong hiện tại, không phải là kế hoạch trong tương lai.\n(C) was buying: "Was buying" là thì quá khứ tiếp diễn, không phù hợp với ngữ cảnh khi người nói đang đề cập đến kế hoạch trong tương lai.\n(D) shall buy: "Shall buy" là cách sử dụng "shall" để diễn tả hành động trong tương lai, nhưng không phổ biến trong tiếng Anh hiện đại và không nhấn mạnh kế hoạch cụ thể như "am going to buy."', 'Tại sao bạn lại mang theo cái giỏ lớn đó? Tôi sắp mua nhiều rau.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_008', 'zenlish_practice', 'Why are you carrying that saw? - I ______ the legs of the dining room table.', 'am going to shorten', 'will shorten', 'was going to short', 'am shortening', 'A', 'Giải thích: "Am going to shorten" được sử dụng để diễn tả một kế hoạch hoặc dự định trong tương lai. Trong câu này, người nói có dự định sẽ cắt ngắn chân của bàn ăn, vì vậy cần mang theo cái cưa.\n(B) will shorten: "Will shorten" được sử dụng để diễn tả hành động trong tương lai, nhưng không nhấn mạnh kế hoạch cụ thể hoặc dự định như "am going to shorten."\n(C) was going to short: "Was going to short" không đúng về ngữ pháp và không phù hợp với ngữ cảnh vì thiếu động từ chính xác và không phù hợp với thì quá khứ.\n(D) am shortening: "Am shortening" là thì hiện tại tiếp diễn, diễn tả hành động đang xảy ra trong hiện tại, không phải là dự định trong tương lai.', 'Tại sao bạn lại mang theo cái cưa đó? Tôi sẽ cắt ngắn chân của bàn ăn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_009', 'zenlish_practice', 'You’ve bought a lot of paints. Are you ______ your kitchen?', 'be decorating', 'decorating', 'going to decorate', 'decorate', 'C', 'Giải thích: "Going to decorate" được sử dụng để diễn tả một dự định hoặc kế hoạch trong tương lai. Trong câu này, việc mua sơn gợi ý rằng người nói có kế hoạch sơn lại căn bếp, nên "going to decorate" là lựa chọn phù hợp để diễn tả điều đó.\n(A) be decorating: "Be decorating" không đúng về ngữ pháp khi dùng với câu hỏi như vậy và không phù hợp với dự định trong tương lai.\n(B) decorating: "Decorating" là thì hiện tại tiếp diễn, dùng để diễn tả hành động đang xảy ra trong hiện tại, không phải dự định trong tương lai.\n(D) decorate: "Decorate" là động từ nguyên mẫu, không phù hợp trong ngữ cảnh này khi hỏi về dự định trong tương lai.', 'Bạn đã mua rất nhiều sơn. Bạn có định sơn lại căn bếp của mình không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0051_q_010', 'zenlish_practice', 'Tell your brother to come indoors, because it _______ going to rain in a minute of two. A. are', 'are', 'be', 'is', 'being', 'C', 'Giải thích: "Is going to rain" được sử dụng để dự đoán thời tiết trong tương lai gần. Trong câu này, "is going to rain" là cách đúng để diễn tả rằng trời sắp mưa. "Is" là động từ to be phù hợp với chủ ngữ "it" và thì tương lai gần.\n(A) are: "Are" không phù hợp với chủ ngữ "it", vì "it" yêu cầu động từ "is".\n(B) be: "Be" không phù hợp trong ngữ cảnh này; đây là dạng động từ nguyên mẫu, không phù hợp để dự đoán thời tiết.\n(D) being: "Being" là dạng hiện tại tiếp diễn, không phù hợp trong ngữ cảnh dự đoán thời tiết.', 'Bảo em trai của bạn vào trong, vì trời sắp mưa trong một hoặc hai phút nữa.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_001', 'zenlish_practice', 'Why are you peeling that bit of garlic? I _______ it in the stew.', 'am putting', 'am going to put', 'putting', 'to put', 'B', 'Giải thích: "Am going to put" được sử dụng để diễn tả hành động sẽ xảy ra trong tương lai gần, dựa trên kế hoạch hoặc dự định. Trong câu này, "am going to put" là cách đúng để diễn tả rằng bạn dự định sẽ thêm tỏi vào món hầm.\n(A) am putting: "Am putting" là thì hiện tại tiếp diễn, không phù hợp với việc diễn tả dự định trong tương lai.\n(C) putting: "Putting" là dạng hiện tại phân từ, không phù hợp với ngữ pháp của câu khi cần một động từ đầy đủ để diễn tả hành động trong tương lai.\n(D) to put: "To put" là dạng động từ nguyên mẫu, không phù hợp trong ngữ cảnh này.', 'Tại sao bạn lại bóc lớp tỏi đó? Tôi sẽ cho nó vào món hầm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_002', 'zenlish_practice', 'I’m looking for my easel. Are you ______ someone’s portrait?', 'painting', 'paint', 'going to paint', 'be painting', 'C', 'Giải thích: "Going to paint" được sử dụng để diễn tả hành động dự định sẽ xảy ra trong tương lai gần, dựa trên kế hoạch hoặc dự định. Trong câu này, việc tìm easel có nghĩa là bạn dự định sẽ vẽ chân dung của ai đó.\n(A) painting: "Painting" là thì hiện tại tiếp diễn, không phù hợp với việc diễn tả dự định trong tương lai.\n(B) paint: "Paint" là dạng động từ nguyên mẫu, không phù hợp trong ngữ cảnh khi cần một động từ đầy đủ để diễn tả hành động trong tương lai.\n(D) be painting: "Be painting" là thì hiện tại tiếp diễn ở dạng bị động, không phù hợp với ngữ cảnh của câu.', 'Tôi đang tìm giá vẽ của mình. Bạn có phải đang vẽ chân dung của ai đó không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_003', 'zenlish_practice', 'Why is he putting the camera on a tripod? - He ______ a group photo.', 'is taking', 'is going to take', 'was going to take', 'taking', 'B', 'Giải thích: "Is going to take" được sử dụng để diễn tả một dự định hoặc kế hoạch trong tương lai. Trong câu này, việc đặt máy ảnh lên giá ba chân cho thấy anh ta có ý định chụp một bức ảnh nhóm.\n(A) is taking: "Is taking" là thì hiện tại tiếp diễn, chỉ một hành động đang xảy ra ngay lập tức, không phù hợp với việc dự đoán hoặc kế hoạch trong tương lai.\n(C) was going to take: "Was going to take" là thì quá khứ tiếp diễn, không phù hợp với ngữ cảnh hiện tại khi cần diễn tả hành động dự định trong tương lai.\n(D) taking: "Taking" là dạng động từ tiếp diễn nhưng không được sử dụng đúng cách trong ngữ cảnh này.', 'Tại sao anh ấy lại đặt máy ảnh lên giá ba chân? Anh ấy sẽ chụp một bức ảnh nhóm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_004', 'zenlish_practice', 'Why have you set your alarm to go off at five thirty? - Because I ______ up then. I’ve got a lot to do.', 'was going to get', 'would getting', 'will get', 'am going to get', 'D', 'Giải thích: "Am going to get" được sử dụng để diễn tả một kế hoạch hoặc dự định trong tương lai. Trong câu này, việc đặt báo thức cho thấy bạn có kế hoạch dậy vào lúc 5:30.\n(A) was going to get: "Was going to get" là thì quá khứ tiếp diễn, không phù hợp với việc diễn tả kế hoạch trong hiện tại.\n(B) would getting: "Would getting" không phải là dạng động từ chính xác và không phù hợp với ngữ cảnh này.\n(C) will get: "Will get" là thì tương lai đơn, nhưng không nhấn mạnh kế hoạch hoặc dự định cụ thể như "am going to get."', 'Tại sao bạn lại đặt đồng hồ báo thức vào lúc 5:30? Bởi vì tôi sẽ dậy vào lúc đó. Tôi có nhiều việc phải làm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_005', 'zenlish_practice', 'I’ve hired a type writer and I _________ to type.', 'will learn', 'am learning', 'will be learning', 'am going to learn', 'D', 'Giải thích: "Am going to learn" được sử dụng để diễn tả dự định hoặc kế hoạch trong tương lai gần. Trong câu này, bạn đã thuê một máy đánh chữ và có kế hoạch học cách sử dụng nó.\n(A) will learn: "Will learn" là thì tương lai đơn, tuy nhiên khi đã có cơ sở là "đã thuê máy đánh chữ" thì nên dùng "be going to" để thể hiện mức độ chắc chắn cao hơn\n(B) am learning: "Am learning" là thì hiện tại tiếp diễn, không phù hợp với ngữ cảnh dự định trong tương lai.\n(C) will be learning: "Will be learning" là thì tương lai tiếp diễn, diễn tả hành động đang xảy ra trong một khoảng thời gian cụ thể trong tương lai, nhưng không phải là sự dự định như "am going to learn."', 'Tôi đã thuê một máy đánh chữ và tôi sẽ học cách đánh chữ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_006', 'zenlish_practice', 'What are you going to do with that dress? - I _______ the skirt.', 'will be shortening', 'shall shorten', 'was shortening', 'am going to shorten', 'D', 'Giải thích: "Am going to shorten" được sử dụng để diễn tả kế hoạch hoặc dự định trong tương lai. Trong câu này, bạn đã có ý định sẽ rút ngắn váy, và cụm từ "am going to" thể hiện rõ sự dự định đó.\n(A) will be shortening: "Will be shortening" là thì tương lai tiếp diễn, không phù hợp để diễn tả dự định cụ thể.\n(B) shall shorten: "Shall shorten" là thì tương lai đơn, nhưng "shall" thường được sử dụng trong các tình huống trang trọng hoặc theo cách nói cổ điển hơn, không phổ biến bằng "will" hoặc "am going to" trong tiếng Anh hiện đại.\n(C) was shortening: "Was shortening" là thì quá khứ tiếp diễn, không phù hợp với ngữ cảnh dự định trong tương lai.', 'Bạn định làm gì với chiếc váy đó? Tôi sẽ rút ngắn chiếc váy.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_007', 'zenlish_practice', 'I’ve bought some blue velvet and I ________ curtains for this room.', 'am going to make', 'am making', 'was going to make', 'will be going to make', 'A', 'Giải thích: "Am going to make" được sử dụng để diễn tả kế hoạch hoặc dự định trong tương lai. Câu này cho biết bạn đã mua vải và có kế hoạch làm rèm cửa cho căn phòng, vì vậy "am going to make" là lựa chọn phù hợp để thể hiện ý định này.\n(B) am making: "Am making" là thì hiện tại tiếp diễn, thường dùng để diễn tả hành động đang xảy ra ngay bây giờ, không phải là dự định trong tương lai.\n(C) was going to make: "Was going to make" là thì quá khứ tiếp diễn, không phù hợp để diễn tả dự định hiện tại.\n(D) will be going to make: "Will be going to make" là một cấu trúc không chính xác; "will be going to" không phải là một cách diễn đạt chuẩn trong tiếng Anh.', 'Tôi đã mua một ít nhung xanh và tôi dự định làm rèm cửa cho căn phòng này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_008', 'zenlish_practice', 'Why did you buy all the eggs? Are you _______ an enormous omelets?', 'make', 'making', 'going to make', 'to making', 'C', 'Giải thích: "Going to make" được sử dụng để diễn tả kế hoạch hoặc dự định trong tương lai. Câu hỏi này đang hỏi lý do bạn mua nhiều trứng, và "going to make" thể hiện rằng bạn có ý định làm một món ăn lớn trong tương lai.\n(B) making: "Making" là thì hiện tại tiếp diễn, dùng để diễn tả hành động đang xảy ra tại thời điểm hiện tại, không phải là dự định trong tương lai.\n(A) make: "Make" không phù hợp ở đây vì không đủ thông tin về thời gian hoặc dự định.\n(D) to making: "To making" là cấu trúc không chính xác và không được sử dụng trong tiếng Anh.', 'Sao bạn mua nhiều trứng thế? Bạn định làm một món omelet khổng lồ hả?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_009', 'zenlish_practice', 'Look! What I’ve just bought at an auction. What an extraordinary thing! Where _______ it ?', 'are you going to put', 'will be you putting', 'shall you put', 'was you putting', 'A', 'Giải thích: "Are you going to put" được sử dụng để hỏi về kế hoạch trong tương lai, liên quan đến việc đặt một món đồ nào đó. Câu hỏi này thể hiện sự quan tâm về nơi bạn dự định đặt món đồ đó sau khi mua nó tại một cuộc đấu giá.\n(B) will be you putting: Đây là dạng bị động và không đúng cấu trúc cho câu hỏi này.\n(C) shall you put: "Shall" thường được sử dụng trong các tình huống trang trọng hơn và ít phổ biến hơn trong các câu hỏi như thế này.\n(D) was you putting: Câu này không chính xác về mặt ngữ pháp vì "was" không phù hợp với chủ ngữ "you" và không dùng để hỏi về kế hoạch tương lai.', 'Nhìn kìa! Tôi vừa mua gì tại một cuộc đấu giá. Thật là một món đồ lạ thường! Bạn dự định sẽ đặt nó ở đâu?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0052_q_010', 'zenlish_practice', 'She ____________ a lot of things for the party.', 'is going to buy', 'are going to buy', 'am going to buy', 'will buy', 'A', 'Giải thích: "Is going to buy" được sử dụng để diễn tả một kế hoạch hoặc dự định trong tương lai. Đây là cấu trúc phù hợp với chủ ngữ "She" và thể hiện rằng cô ấy có kế hoạch mua nhiều thứ cho bữa tiệc.\n(B) are going to buy: "Are" không phù hợp với chủ ngữ "She", mà phải là "is".\n(C) am going to buy: "Am" không phù hợp với chủ ngữ "She", mà phải là "is".\n(D) will buy: Mặc dù cũng đúng, nhưng "is going to buy" thường dùng để chỉ sự dự định cụ thể hơn về kế hoạch trong tương lai.', 'Cô ấy sẽ mua nhiều thứ cho bữa tiệc.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_001', 'zenlish_practice', 'Are you ______ the washing up tonight? No, I think it can wait till tomorrow.', 'doing', 'do', 'does', 'going to do', 'D', 'Giải thích: "Going to do" được sử dụng để diễn tả một kế hoạch hoặc dự định trong tương lai. Trong câu hỏi này, "Are you going to do the washing up tonight?" hỏi về kế hoạch cụ thể trong tương lai gần. Các đáp án khác không phù hợp với cách diễn tả dự định hoặc kế hoạch cho tương lai.\n(A) doing: Không đúng vì không phù hợp với cấu trúc câu hỏi về kế hoạch tương lai.\n(B) do: Không đúng vì không sử dụng thì hiện tại tiếp diễn để hỏi về kế hoạch.\n(C) does: Không đúng vì không phù hợp với cấu trúc câu hỏi và thì hiện tại đơn không dùng để hỏi về kế hoạch trong tương lai.', 'Bạn có định rửa chén đĩa tối nay không? Không, tôi nghĩ việc đó có thể đợi đến ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_002', 'zenlish_practice', 'She _______ to her grandfather’s house in the countryside next week.', 'are going to come', 'is going to come', 'am going to come', 'will have come', 'B', 'Giải thích: "Is going to come" được sử dụng để diễn tả kế hoạch đã được định sẵn trong tương lai gần. Cấu trúc này phù hợp với việc nói về kế hoạch cụ thể.\n(A) are going to come: Không phù hợp vì chủ ngữ là "She," nên động từ phải là "is" chứ không phải "are."\n(C) am going to come: Không phù hợp vì chủ ngữ là "She," nên động từ phải là "is" chứ không phải "am."\n(D) will have come: Không phù hợp vì đây là dạng thì tương lai hoàn thành, không phải là kế hoạch cụ thể cho tuần tới.', 'Cô ấy sẽ đến nhà ông bà ở nông thôn vào tuần tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_003', 'zenlish_practice', 'Despite the unpredictable weather, we ________ our friends in the city next month.', 'will visit', 'are going to visit', 'will have visited', 'visit', 'B', 'Giải thích: "Are going to visit" được sử dụng để diễn tả kế hoạch hoặc dự định đã được xác định trong tương lai, bất chấp những yếu tố không thể đoán trước như thời tiết.\n(A) will visit: Cũng đúng nhưng không nhấn mạnh kế hoạch hoặc dự định cụ thể như "are going to visit."\n(C) will have visited: Không phù hợp vì đây là thì tương lai hoàn thành, dùng để diễn tả hành động sẽ hoàn tất trước một thời điểm cụ thể trong tương lai, không phải là kế hoạch dự định.\n(D) visit: Không đúng vì thiếu từ "will" hoặc "are going to" để diễn tả hành động ở thì tương lai.', 'Mặc dù thời tiết không thể đoán trước, chúng tôi sẽ thăm bạn bè ở thành phố vào tháng tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_004', 'zenlish_practice', 'As soon as he finishes his own assignments, he ________ you with your homework.', 'will help', 'is going to help', 'are going to help', 'will be helping', 'A', 'Giải thích: Trong câu điều kiện loại 1 (câu điều kiện với "as soon as"), chúng ta sử dụng thì tương lai đơn "will help" để diễn tả một hành động sẽ xảy ra ngay sau khi điều kiện được thỏa mãn (khi anh ấy hoàn thành bài tập của mình). "Will help" là lựa chọn phù hợp để thể hiện hành động sẽ xảy ra trong tương lai.\n(B) is going to help: Câu này có thể đúng trong nhiều trường hợp, nhưng trong cấu trúc câu điều kiện loại 1, thì tương lai đơn "will help" thường được ưu tiên hơn.\n(C) are going to help: Không đúng vì "are" không phù hợp với chủ ngữ "he" (anh ấy).\n(D) will be helping: Tương lai tiếp diễn không cần thiết trong ngữ cảnh này, vì không cần nhấn mạnh sự kéo dài của hành động.', 'Ngay khi anh ấy hoàn thành các nhiệm vụ của mình, anh ấy sẽ giúp bạn với bài tập của bạn.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_005', 'zenlish_practice', 'I ________ how to play the piano this year.', 'am going to think', 'am going to attend', 'am going to learn', 'am going to lecture', 'C', 'Giải thích: "Am going to learn" được sử dụng để diễn tả kế hoạch hoặc dự định của người nói trong tương lai, trong trường hợp này là học cách chơi piano.\n(A) am going to think: Không phù hợp vì "think" không liên quan đến việc học chơi piano.\n(B) am going to attend: Có thể đúng trong trường hợp bạn dự định tham gia một lớp học piano, nhưng không trực tiếp liên quan đến việc học chơi piano.\n(D) am going to lecture: Không phù hợp vì "lecture" có nghĩa là giảng bài, không liên quan đến việc học piano.', 'Tôi dự định sẽ học cách chơi piano trong năm nay.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_006', 'zenlish_practice', 'They ________ the conference to gain insights into the industry.', 'are going to attend', 'will attend', 'are going to partake', 'will partake', 'A', 'Giải thích: "Are going to attend" được sử dụng để diễn tả dự định hoặc kế hoạch trong tương lai. Trong câu này, việc tham gia hội nghị để thu thập thông tin về ngành là một kế hoạch đã được xác định trước.\n(B) will attend: Cũng đúng, nhưng "are going to attend" có thể nhấn mạnh hơn về kế hoạch đã được xác định.\n(C) are going to partake: "Partake" (tham gia) thường dùng với hoạt động ăn uống, tiệc hơn là hội nghị\n(D) will partake: Tương tự như (C), "partake" không thường được sử dụng trong ngữ cảnh tham gia hội nghị.', 'Họ dự định sẽ tham gia hội nghị để có thêm hiểu biết về ngành.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_007', 'zenlish_practice', 'They________ a professional for the job, as an expert ________ how best to approach the problem.', 'will hire – is going to know', 'are going to hire – know', 'will hire – will know', 'are going to hire – will know', 'D', 'Giải thích: "Are going to hire" được sử dụng để diễn tả một kế hoạch hoặc dự định đã được quyết định. "Will know" được sử dụng để dự đoán về khả năng của một người trong tương lai, thể hiện rằng chuyên gia sẽ biết cách tiếp cận vấn đề.\n(A) will hire – is going to know: Không chính xác vì "is going to know" không phù hợp với dự đoán trong ngữ cảnh này.\n(B) are going to hire – know: "Know" không phù hợp với dự đoán về khả năng trong tương lai.\n(C) will hire – will know: "Will hire" có thể đúng, nhưng "are going to hire" nhấn mạnh kế hoạch rõ ràng hơn.', 'Họ dự định sẽ tuyển một chuyên gia cho công việc này, vì chuyên gia sẽ biết cách tốt nhất để tiếp cận vấn đề.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_008', 'zenlish_practice', 'They ________ a puppy from the local animal shelter.', 'are going to adopt', 'adopting', 'will have adopted', 'adopt', 'A', 'Giải thích: Câu này đang sử dụng thì tương lai gần (be going to) để diễn tả một hành động đã được lên kế hoạch trước và sẽ xảy ra trong tương lai gần. "Are going to adopt" là cấu trúc đúng, nghĩa là "sẽ nhận nuôi," diễn tả ý định hoặc kế hoạch nhận nuôi một chú chó con từ trại động vật.\n(B) adopting (gerund): "adopting" có nghĩa là "việc nhận nuôi." Lý do không chọn là vì đây là danh động từ, không phù hợp khi câu cần một động từ ở dạng tiếp diễn hoặc tương lai.\n(C) will have adopted (future perfect): "will have adopted" có nghĩa là "sẽ đã nhận nuôi." Lý do không chọn là vì đây là thì tương lai hoàn thành, không phù hợp với ngữ cảnh của câu khi nói về kế hoạch trong tương lai gần.\n(D) adopt (base form): "adopt" có nghĩa là "nhận nuôi." Lý do không chọn là vì đây là dạng động từ nguyên mẫu, không phù hợp khi cần một cấu trúc thời tương lai để diễn tả ý định.', 'Họ sẽ nhận nuôi một chú chó con từ trại động vật địa phương.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_009', 'zenlish_practice', 'We ________ a vegetable garden in the backyard because fresh produce ________ us a power of good.', 'will plant – is doing', 'are going to plant – will do', 'will plant – is going to do', 'are going to plant – is going to do', 'B', 'Giải thích: Câu này sử dụng thì tương lai gần (be going to) cho hành động "plant" (trồng), diễn tả một kế hoạch đã có từ trước. "Will do" được sử dụng trong mệnh đề thứ hai để diễn tả kết quả hay hiệu quả của việc trồng vườn rau. Kết hợp này diễn tả rõ ràng ý định trồng rau và kết quả tích cực từ việc đó.\n(A) will plant – is doing: "Will plant" là thì tương lai đơn, nhưng "is doing" là thì hiện tại tiếp diễn, không phù hợp khi nói về tác động trong tương lai.\n(C) will plant – is going to do: "Will plant" là thì tương lai đơn, nhưng "is going to do" sử dụng thì tương lai gần cho mệnh đề kết quả, không phù hợp với cấu trúc câu.\n(D) are going to plant – is going to do: Sử dụng cả hai thì tương lai gần cho cả hành động và kết quả, có thể đúng nhưng không tự nhiên và không cần thiết khi nói về hiệu quả trong tương lai.', 'Chúng tôi sẽ trồng một vườn rau ở sân sau vì thực phẩm tươi sẽ rất tốt cho chúng tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0053_q_010', 'zenlish_practice', 'Tom: Are you busy this evening? Adam: No, Not at all. I ________ do anything.', 'am not going to', 'will', 'am going to', 'don’t', 'A', 'Giải thích: Câu hỏi: "Tối nay bạn có bận không?" và Adam trả lời "Không, không hề." nên cần một cấu trúc phủ định. "Am not going to" là cấu trúc phủ định của "going to," dùng để diễn tả việc không có kế hoạch làm gì đó trong tương lai.\n(B) will (modal verb): "will" là trợ động từ diễn tả tương lai, nhưng không mang nghĩa phủ định.\n(C) am going to (going to future): "am going to" dùng để diễn tả kế hoạch sắp xảy ra. Lý do không chọn là vì Adam nói rằng anh ấy không có kế hoạch làm gì cả.\n(D) don’t (contraction of do not): không phù hợp vì đang nói về kế hoạch trong tương lai.', 'Tom: Bạn bận tối nay à? - Adam: Không, không hề. Tôi không có kế hoạch làm gì cả.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_001', 'zenlish_practice', 'Adam: Are you ________ go out of the town this weekend? Tom: Yes, I am. I am going to visit my grandparents.', 'will', 'going to', 'like', 'don’t', 'B', 'Giải thích: Trong câu hỏi này, Adam đang hỏi về kế hoạch hoặc dự định của Tom trong tương lai gần. "Going to" là cấu trúc phù hợp để diễn tả dự định trong tương lai gần. Câu hỏi cần một cụm từ để chỉ sự dự định, vì vậy "going to" là sự lựa chọn chính xác để hoàn thành câu hỏi. Các đáp án còn lại không đi với động từ to be "are"', 'Adam: Bạn có dự định ra ngoài thành phố vào cuối tuần này không? Tom: Có, tôi có. Tôi dự định sẽ thăm ông bà của tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_002', 'zenlish_practice', 'Adam: ________ you going to watch the soccer match tomorrow? Tom: No, I am not. I ________ be out of the town.', 'Do/ am going to', 'Will/ will', 'Are/ don’t', 'Are/ am going to', 'D', 'Giải thích: Trong câu hỏi này, câu hỏi cần một cấu trúc để hỏi về dự định trong tương lai và câu trả lời cần phản ánh trạng thái hiện tại của việc có kế hoạch ra ngoài thành phố. Cấu trúc đúng là "Are you going to" để hỏi về dự định và "am going to" để thể hiện kế hoạch ra ngoài thành phố. Vì vậy,\n(D) là lựa chọn chính xác.\n(A) Do/ am going to: "Do" không phù hợp để hỏi về dự định trong tương lai; cấu trúc này không đúng về ngữ pháp cho câu hỏi về kế hoạch.\n(B) Will/ will: "Will" không phù hợp để hỏi về dự định trong tương lai khi cần cấu trúc "going to" để thể hiện kế hoạch cụ thể.\n(C) Are/ don’t: "Don’t" không phù hợp trong câu trả lời vì không phản ánh trạng thái hiện tại về dự định.', 'Adam: Bạn có dự định xem trận đấu bóng đá vào ngày mai không? Tom: Không, tôi không có. Tôi sẽ ra ngoài thành phố.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_003', 'zenlish_practice', 'Tom: Would you like to come over tomorrow? Adam: I’d like to, but I am going to ________ for my English exam.', 'studying', 'studied', 'study', 'studies', 'C', 'Giải thích: be going to + V bare\n(A) studying (v. - gerund): "Studying" là dạng danh động từ và không phù hợp với cấu trúc "am going to" trong câu này, vì cần một động từ ở dạng nguyên mẫu.\n(B) studied (v. - past): "Studied" là thì quá khứ của động từ "study" và không phù hợp khi câu cần diễn tả hành động dự định trong tương lai.\n(D) studies (v. - present): "Studies" là thì hiện tại đơn cho ngôi thứ ba số ít và không phù hợp với cấu trúc "am going to" khi cần một động từ nguyên mẫu.', 'Tom: Bạn có muốn đến chơi vào ngày mai không? Adam: Tôi muốn lắm, nhưng tôi sẽ phải ôn bài cho kỳ thi tiếng Anh của tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_004', 'zenlish_practice', 'Adam: I ________ have a party at my place on Tuesday. Would you like ________? Tom: I’d like to. Thank you for inviting me.', 'am going to/ to come', 'will/ coming', 'am going to/ coming', 'will/ to come', 'A', 'Giải thích: Trong câu này, Adam đang thông báo về kế hoạch trong tương lai và mời Tom tham gia. "Am going to" là cấu trúc phù hợp để diễn tả kế hoạch trong tương lai. Câu sau sử dụng cấu trúc câu mời "Would you like to V?"\n(B) will/ coming: "Will" có thể dùng để diễn tả sự kiện trong tương lai, nhưng không chính xác bằng "am going to" khi nói về kế hoạch cụ thể. "Coming" là dạng danh động từ và không phù hợp sau "would like."\n(C) am going to/ coming: "Am going to" là đúng cho kế hoạch trong tương lai, nhưng "coming" không phù hợp sau "would like" trong câu mời.\n(D) will/ to come: "Will" không chính xác như "am going to" để nói về kế hoạch. "To come" là chính xác cho hành động mong muốn, nhưng toàn bộ cấu trúc không hoàn chỉnh.', 'Adam: Tôi dự định sẽ tổ chức một bữa tiệc tại nhà vào thứ Ba. Bạn có muốn đến không? Tom: Tôi muốn đến. Cảm ơn bạn đã mời tôi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_005', 'zenlish_practice', 'Tom: Are you going to join Kevin’s birthday party? Adam: ________ I am going to visit my relatives.', 'Yes, I can', 'No, I don’t', 'Yes, I will', 'No, I am not', 'D', 'Giải thích: Trong câu này, Adam đang trả lời câu hỏi về việc tham gia bữa tiệc sinh nhật của Kevin. Vì Adam không tham gia bữa tiệc, câu trả lời cần phải phủ định. "No, I am not" là cách trả lời phù hợp nhất để xác nhận việc không tham gia sự kiện.\n(A) Yes, I can: "Yes, I can" có nghĩa là "Có, tôi có thể," không phù hợp với việc từ chối tham gia.\n(B) No, I don’t: "No, I don’t" không phù hợp với cấu trúc câu khi cần phủ định với cấu trúc "am going to."\n(C) Yes, I will: "Yes, I will" có nghĩa là "Có, tôi sẽ," phù hợp cho việc đồng ý tham gia, nhưng không phải là cách trả lời phù hợp trong trường hợp từ chối.', 'Tom: Bạn có dự định tham gia bữa tiệc sinh nhật của Kevin không? Adam: Không, tôi không. Tôi sẽ đi thăm bà con của mình.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_006', 'zenlish_practice', 'Would you like to join my tea party? I am sure you ________ have great fun.', 'will going to', 'are going to', 'going to', 'go to', 'B', 'Giải thích: Trong câu này, người nói đang mời và chắc chắn rằng người được mời sẽ có khoảng thời gian vui vẻ. Để diễn tả sự chắc chắn về hành động trong tương lai, "are going to" là cấu trúc chính xác để dùng. Câu này cần một động từ để thể hiện sự chắc chắn về sự vui vẻ trong tương lai, vì vậy "are going to" là lựa chọn đúng.\n(A) will going to: "Will going to" không phải là cấu trúc ngữ pháp hợp lệ trong tiếng Anh; cần phải chọn giữa "will" hoặc "going to."\n(C) going to: "Going to" không đủ để hoàn thành câu vì thiếu động từ "are" để chỉ dự định hoặc kế hoạch.\n(D) go to: "Go to" không phù hợp để thể hiện sự chắc chắn trong tương lai như yêu cầu của câu này.', 'Bạn có muốn tham gia bữa tiệc trà của tôi không? Tôi chắc chắn rằng bạn sẽ có khoảng thời gian vui vẻ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_007', 'zenlish_practice', 'Adam: Our school is organizing a tennis competition on Friday afternoon. It is ________ in the City Sports Center. Would you like to join? Tom: It would be great.', 'will be', 'be', 'going to be', 'will going to be', 'C', 'Giải thích: Trong câu này, Adam đang thông báo về một sự kiện sẽ diễn ra vào cuối tuần và cần một cấu trúc để chỉ rõ nơi tổ chức sự kiện. "Going to be" là cấu trúc chính xác để diễn tả sự kiện sẽ xảy ra trong tương lai gần và địa điểm tổ chức sự kiện. Đây là cách sử dụng phù hợp để thông báo về sự kiện và địa điểm cụ thể. Các đáp án còn lại không thể đứng sau "is"', 'Adam: Trường của chúng tôi đang tổ chức một giải quần vợt vào chiều thứ Sáu. Sự kiện sẽ được tổ chức tại Trung tâm Thể thao Thành phố. Bạn có muốn tham gia không? Tom: Thật tuyệt.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_008', 'zenlish_practice', 'We are ________ have a barbecue with friends on Saturday. Would you like to join us?', 'going to', 'will', 'don''t', 'not', 'A', 'Giải thích: Trong câu này, người nói đang thông báo về kế hoạch cụ thể cho cuối tuần. "Going to" là cấu trúc chính xác để diễn tả một kế hoạch đã được lên lịch cho tương lai gần. Câu này cần cấu trúc "going to" để hoàn thành ý định về việc tổ chức bữa tiệc nướng với bạn bè.\n(B) will: không đi sau "are"\n(C) don’t: không đi sau "are"\n(D) not: "are not" không thể đứng trước "have"', 'Chúng tôi dự định sẽ tổ chức một bữa tiệc nướng với bạn bè vào thứ Bảy. Bạn có muốn tham gia không?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_009', 'zenlish_practice', 'Tom: What a nice day! Do you want to take a walk with me? Adam: Sorry, but ________', 'I will be there on time', 'I am not going to do anything else', 'I will come with you', 'I am going to help my mother to clean the house', 'D', 'Giải thích: Trong câu này, Adam đang từ chối lời mời của Tom vì đã có kế hoạch khác. "I am going to help my mother to clean the house" là cách chính xác để thông báo rằng Adam có kế hoạch làm việc khác vào thời điểm đó, cụ thể là giúp mẹ dọn dẹp nhà cửa.\n(A) I will be there on time: "I will be there on time" có nghĩa là "Tôi sẽ đến đúng giờ," không phải là lý do từ chối vì không liên quan đến việc có kế hoạch khác.\n(B) I am not going to do anything else: "I am not going to do anything else" có nghĩa là "Tôi không có kế hoạch làm gì khác," không phải là cách từ chối phù hợp vì Adam đã có kế hoạch cụ thể.\n(C) I will come with you: "I will come with you" có nghĩa là "Tôi sẽ đi cùng bạn," không phải là lý do từ chối mà là đồng ý với lời mời.', 'Tom: Thật là một ngày đẹp! Bạn có muốn đi dạo với tôi không? Adam: Xin lỗi, nhưng tôi sẽ giúp mẹ tôi dọn dẹp nhà cửa.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0054_q_010', 'zenlish_practice', 'It’s getting late. I think I ________ to bed soon.', 'will go', 'am going to go', 'am going', 'go', 'A', 'Giải thích: Sử dụng thì tương lai đơn (will) để diễn tả một quyết định tức thời được đưa ra ngay tại thời điểm nói. Cụm từ "I think" thường đi kèm với "will" trong trường hợp này, cho thấy đây là một ý kiến hoặc dự đoán không dựa trên kế hoạch hay bằng chứng rõ ràng đã có từ trước, mà là một quyết định bột phát khi nhận thấy trời đã khuya.\n(B) am going to go: "Be going to" dùng để diễn tả một kế hoạch đã được định trước hoặc một dự đoán có căn cứ, bằng chứng rõ ràng. Trong trường hợp này, việc đi ngủ không phải là kế hoạch đã có từ lâu, mà là phản ứng tức thời với tình trạng "trời đã khuya".\n(C) am going: Thì hiện tại tiếp diễn (present continuous) dùng để nói về một sự sắp xếp (arrangement) chắc chắn trong tương lai gần, không phù hợp để diễn đạt một quyết định tức thời.\n(D) go: Thì hiện tại đơn (present simple) dùng để diễn tả các sự thật hiển nhiên, thói quen, hoặc lịch trình cố định, không được dùng để nói về hành động sẽ xảy ra trong tương lai gần như trong câu này.', 'Trời đã muộn rồi. Tôi nghĩ tôi sẽ đi ngủ sớm.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_001', 'zenlish_practice', 'I ________ buy a new car next year.', 'will', 'am going to', 'am', 'will have been', 'B', 'Giải thích: Trong câu này, người nói đang thể hiện dự định hoặc kế hoạch cụ thể cho việc mua xe vào năm tới. Cấu trúc "am going to" được sử dụng để diễn tả một kế hoạch đã được xác định cho tương lai gần. Đây là lựa chọn chính xác để diễn tả sự dự định rõ ràng.\n(A) will: "Will" cũng có thể dùng để nói về dự định trong tương lai, nhưng "am going to" cụ thể hơn cho việc thể hiện kế hoạch đã được lên lịch.\n(C) am: "Am" chỉ đơn thuần là động từ "to be" và không đủ để diễn tả hành động dự định trong tương lai.\n(D) will have been: "Will have been" là cấu trúc thì tương lai hoàn thành, không phù hợp với ngữ cảnh cần diễn tả một dự định đơn giản.', 'Tôi dự định sẽ mua một chiếc xe mới vào năm tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_002', 'zenlish_practice', 'Look at the sky! It ________ rain soon.', 'will', 'is going to', 'is', 'will be', 'B', 'Giải thích: Trong câu này, người nói đang đưa ra dự đoán về thời tiết sắp xảy ra dựa trên dấu hiệu quan sát. "Is going to" được sử dụng để dự đoán sự việc sẽ xảy ra dựa trên bằng chứng hiện tại. Đây là cách diễn tả dự đoán có cơ sở hơn so với "will."\n(A) will: "Will" có thể dùng để dự đoán sự kiện trong tương lai, nhưng khi dự đoán dựa trên dấu hiệu hiện tại, "is going to" thường được sử dụng.\n(C) is: "Is" là động từ "to be" và không đủ để diễn tả hành động hoặc sự kiện sắp xảy ra.\n(D) will be: "Will be" phải đi kèm tính từ "rainy", không đi với động từ "rain"', 'Nhìn lên bầu trời kìa! Trời sắp mưa rồi.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_003', 'zenlish_practice', 'She ________ her driver’s license next week.', 'will get', 'gets', 'got', 'is going to get', 'D', 'Giải thích: Trong câu này, người nói đang thông báo về một sự kiện sắp xảy ra trong tương lai gần. "Is going to get" là cấu trúc chính xác để diễn tả một kế hoạch hoặc dự định cụ thể trong tương lai gần, như việc lấy bằng lái xe vào tuần tới.\n(A) will get: "Will get" cũng có thể dùng để diễn tả sự kiện trong tương lai, nhưng "is going to get" thường được sử dụng để chỉ một kế hoạch đã được lên lịch hoặc có dự định rõ ràng.\n(B) gets: "Gets" là thì hiện tại đơn, không phù hợp để nói về sự kiện trong tương lai.\n(C) got: "Got" là thì quá khứ, không phù hợp với ngữ cảnh của sự kiện sẽ xảy ra trong tương lai.', 'Cô ấy sẽ nhận bằng lái xe của mình vào tuần tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_004', 'zenlish_practice', 'They ________ to the beach this weekend.', 'will go', 'are going to go', 'go', 'will have gone', 'B', 'Giải thích: Trong câu này, người nói đang đề cập đến kế hoạch cụ thể cho cuối tuần. "Are going to go" là cấu trúc chính xác để diễn tả một kế hoạch đã được lên lịch cho tương lai gần, trong trường hợp này là chuyến đi đến bãi biển.\n(A) will go: "Will go" có thể dùng để nói về dự định trong tương lai, nhưng "are going to go" là cấu trúc rõ ràng hơn để chỉ một kế hoạch cụ thể đã được quyết định.\n(C) go: "Go" là động từ ở thì hiện tại đơn, không đủ để diễn tả kế hoạch.\n(D) will have gone: "Will have gone" là thì tương lai hoàn thành, chỉ dùng để diễn tả một hành động sẽ được hoàn thành trước một mốc thời gian trong tương lai.', 'Họ sẽ đi đến bãi biển vào cuối tuần này.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_005', 'zenlish_practice', 'I ________ a lot of money in the stock market next year.', 'will make', 'make', 'am going to make', 'made', 'C', 'Giải thích: Trong câu này, người nói đang dự đoán về việc kiếm tiền từ thị trường chứng khoán vào năm tới. "Am going to make" được sử dụng để diễn tả một dự định hoặc kế hoạch cụ thể trong tương lai gần, phù hợp với ngữ cảnh khi có kế hoạch hoặc dự đoán rõ ràng.\n(A) will make: "Will make" có thể dùng để diễn tả dự đoán trong tương lai, nhưng "am going to make" cụ thể hơn cho việc dự đoán dựa trên kế hoạch hoặc dự định hiện tại.\n(B) make: "Make" là thì hiện tại đơn, không phù hợp khi nói về sự việc xảy ra trong tương lai.\n(D) made: "Made" là thì quá khứ, không phù hợp với ngữ cảnh của dự đoán về tương lai.', 'Tôi dự định sẽ kiếm được nhiều tiền từ thị trường chứng khoán vào năm tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_006', 'zenlish_practice', '15. We ________ a picnic in the park tomorrow.', 'will have', 'are going to have', 'have', 'will be having', 'B', 'Giải thích: Trong câu này, người nói đang thông báo về một kế hoạch cụ thể cho ngày mai. "Are going to have" được sử dụng để diễn tả một kế hoạch đã được lên lịch hoặc dự định trong tương lai gần, trong trường hợp này là tổ chức một buổi dã ngoại tại công viên.\n(A) will have: "Will have" có thể dùng để nói về sự kiện trong tương lai, nhưng "are going to have" thường được sử dụng để chỉ một kế hoạch cụ thể hơn đã được quyết định.\n(C) have: "Have" là thì hiện tại đơn, không đủ để diễn tả kế hoạch hoặc sự kiện trong tương lai.\n(D) will be having: "Will be having" là thì tương lai tiếp diễn, có thể diễn tả hành động xảy ra trong tương lai, nhưng không cần thiết trong trường hợp thông báo kế hoạch cụ thể.', 'Chúng tôi dự định sẽ có một buổi dã ngoại tại công viên vào ngày mai.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_007', 'zenlish_practice', 'He ________ his parents next month.', 'is going to visit', 'will visit', 'visits', 'is visiting', 'A', 'Giải thích: Trong câu này, người nói đang thông báo về một kế hoạch cụ thể cho tháng tới. "Is going to visit" được sử dụng để diễn tả một dự định hoặc kế hoạch đã được lên lịch cho tương lai gần, trong trường hợp này là việc thăm bố mẹ.\n(B) will visit: "Will visit" cũng có thể dùng để nói về một sự kiện trong tương lai, nhưng "is going to visit" thường được sử dụng để chỉ một kế hoạch hoặc dự định cụ thể hơn.\n(C) visits: "Visits" là thì hiện tại đơn, không phù hợp khi nói về kế hoạch hoặc dự định trong tương lai.\n(D) is visiting: "Is visiting" là thì hiện tại tiếp diễn, thường dùng để diễn tả hành động đang xảy ra trong hiện tại hoặc đã được lên lịch, nhưng không phải là lựa chọn tốt nhất khi thông báo về kế hoạch cụ thể trong tương lai.', 'Anh ấy sẽ thăm bố mẹ vào tháng tới.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_008', 'zenlish_practice', 'She ________ her hair before the party tonight.', 'will wash', 'is going to wash', 'washes', 'will be washed', 'B', 'Giải thích: Cần động từ chính thể hiện ý định/ kế hoạch "sẽ gội đầu trước bữa tiệc tối nay" nên dùng thì tương lai gần.\n(A) will wash (simple future): "Will wash" cũng diễn đạt hành động trong tương lai nhưng thường dùng khi quyết định tại thời điểm nói hoặc khi không có kế hoạch rõ ràng trước đó.\n(C) washes (present simple): "Washes" là dạng hiện tại đơn, thường dùng để diễn tả thói quen hoặc sự thật chung, không phù hợp khi nói về một sự kiện cụ thể sắp xảy ra.\n(D) will be washed (future passive): "Will be washed" là cấu trúc bị động, không phù hợp trong trường hợp này vì câu này cần một hành động chủ động mà cô ấy thực hiện.', 'Cô ấy sẽ gội đầu trước bữa tiệc tối nay.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_009', 'zenlish_practice', 'He ________ his room before he goes to bed.', 'cleaning', 'is going to clean', 'clean', 'cleaned', 'B', 'Giải thích: Trong câu này, "He" là chủ ngữ và câu mô tả một hành động mà người đó dự định thực hiện trong tương lai gần, đó là dọn dẹp phòng trước khi đi ngủ. "Is going to clean" là cấu trúc "going to future," dùng để diễn tả kế hoạch hoặc ý định mà đã được quyết định trước, phù hợp nhất trong ngữ cảnh này khi có một kế hoạch cụ thể.\n(A) cleaning (gerund): "Cleaning" là dạng danh động từ, không thể làm động từ chính\n(C) clean (imperative/base form): "Clean" là dạng nguyên mẫu, chưa chia theo chủ ngữ ngôi thứ ba số ít\n(D) cleaned (past simple): "Cleaned" là dạng quá khứ đơn, không phù hợp vì before he goes to bed diễn tả hành động trong tương lai.', 'Anh ấy sẽ dọn dẹp phòng trước khi đi ngủ.', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, updated_at) VALUES ('test_0055_q_010', 'zenlish_practice', '________ you going to come to the party tonight?', 'Will', 'Did', 'Do', 'Are', 'D', 'Giải thích: Trong câu này, "Are you going to come to the party tonight?" là một cấu trúc câu hỏi dùng "going to" để diễn tả kế hoạch hoặc ý định trong tương lai. "Are" là dạng của động từ "to be" phù hợp với chủ ngữ "you" và kết hợp với "going to" để tạo thành một câu hỏi về hành động sắp xảy ra. Các đáp án còn lại sai vì trong câu hỏi bắt đầu bằng Will/ Did/ Do động từ phải ở dạng nguyên thể, không thể là "going".', 'Bạn sẽ đến dự tiệc tối nay chứ?', '2026-08-20 14:00:00') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), updated_at=VALUES(updated_at);
